APP_DIR = Path(__file__).resolve().parent

# PyInstaller keeps bundled read-only resources under ``sys._MEIPASS`` while
# the executable itself lives in the portable, user-writable application
# folder.  Keep those two locations separate so settings, tools, downloads,
# logs and the database never disappear when a one-folder build is upgraded.
BUNDLE_ROOT = Path(getattr(sys, "_MEIPASS", APP_DIR.parent)).resolve()
if getattr(sys, "frozen", False):
    CODE_ROOT = Path(sys.executable).resolve().parent
else:
    CODE_ROOT = APP_DIR.parent if APP_DIR.name.lower()=="app" else APP_DIR

def _load_path_configuration(code_root):
    """Load the single portable path map, resolving relative values beside it."""
    cursor=Path(code_root).resolve()
    for _ in range(6):
        candidate=cursor/"videohoarder.paths.json"
        if candidate.is_file():
            try:
                data=json.loads(candidate.read_text(encoding="utf-8-sig"))
                install=Path(str(data.get("install_root") or ".")).expanduser()
                if not install.is_absolute():install=candidate.parent/install
                install=install.resolve()
                resolved=dict(data);resolved["_config_file"]=str(candidate);resolved["_install_root"]=str(install)
                for key in ("source_dir","build_environment","gui_environment","python_runtime","wheelhouse","cache_root","tools_dir","library_root","video_library_dir","legacy_import_media"):
                    raw=str(data.get(key) or "").strip()
                    if raw:
                        value=Path(raw).expanduser()
                        resolved[key]=str((value if value.is_absolute() else install/value).resolve())
                return resolved
            except Exception:
                pass
        if cursor.parent==cursor:break
        cursor=cursor.parent
    return {}

PATH_CONFIGURATION=_load_path_configuration(CODE_ROOT)

def _root_db_count(root):
    db=Path(root)/"data"/"database"/"video_library.db"
    if not db.exists() or not db.is_file():
        return 0
    try:
        con=sqlite3.connect(str(db),timeout=3)
        row=con.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='videos'").fetchone()
        count=con.execute("SELECT COUNT(*) FROM videos").fetchone()[0] if row else 0
        con.close()
        return int(count or 0)
    except Exception:
        return 0

def _root_media_sample_count(root,limit=250):
    root=Path(root)
    # Legacy library roots store media in a downloads child; the portable
    # release uses the visible media directory itself as DOWNLOADS.
    d=root/"downloads" if (root/"downloads").is_dir() else root
    if not d.exists():
        return 0
    exts={".mp4",".mkv",".webm",".m4v",".mov",".avi",".mp3",".m4a",".aac",".opus"}
    count=0
    try:
        for p in d.rglob("*"):
            if p.is_file() and p.suffix.lower() in exts:
                count+=1
                if count>=limit:
                    break
    except Exception:
        pass
    return count

def _library_root_score(root,code_root):
    root=Path(root)
    if not root.exists() or not root.is_dir():
        return -1,{}
    rows=_root_db_count(root)
    media=_root_media_sample_count(root)
    db=(root/"data"/"database"/"video_library.db").exists()
    phase5=(root/"data"/"knowledge"/"phase5").exists()
    start=(root/"START.bat").exists()
    export=(root/"data"/"exports"/"video_list.csv").exists()
    score=0
    if rows>0:
        score+=1000+min(rows,100000)
    elif db:
        score+=100
    if media>0:
        score+=5000+min(media,250)*20
    if phase5: score+=500
    if export: score+=250
    if start: score+=100
    if root==code_root: score+=1
    return score,{"rows":rows,"media_sample":media,"db_exists":db,"start":start,"phase5":phase5,"export":export}

def _windows_user_data_root():
    """Writable per-user fallback for installed/frozen releases."""
    local = os.environ.get("LOCALAPPDATA")
    if local:
        return Path(local).expanduser() / "VideoHoarder"
    return Path.home() / "AppData" / "Local" / "VideoHoarder"

def _is_program_files_path(path):
    try:
        target = str(Path(path).resolve()).lower().rstrip("\\/")
    except Exception:
        target = str(path).lower()
    roots = [os.environ.get("ProgramFiles"), os.environ.get("ProgramFiles(x86)"), os.environ.get("ProgramW6432")]
    for root in roots:
        if root:
            try:
                prefix = str(Path(root).resolve()).lower().rstrip("\\/")
            except Exception:
                prefix = str(root).lower().rstrip("\\/")
            if target == prefix or target.startswith(prefix + os.sep.lower()):
                return True
    return False

def resolve_library_root(code_root):
    code_root=Path(code_root).resolve()

    # Explicit override has highest priority.
    env=os.environ.get("VLM_LIBRARY_ROOT") or os.environ.get("VIDEO_LIBRARY_ROOT")
    if env:
        p=Path(env).expanduser()
        if p.exists():
            return p.resolve(),{"source":"environment override","score":999999999,"details":{}}

    configured=str(PATH_CONFIGURATION.get("library_root") or "").strip()
    if configured:
        p=Path(configured)
        if p.exists():
            return p.resolve(),{"source":"videohoarder.paths.json","score":999999998,"details":{}}

    # Optional portable override file beside the new release.
    override_file=code_root/"library_root.txt"
    if override_file.exists():
        try:
            # utf-8-sig accepts both ordinary UTF-8 and files written with a
            # Windows/PowerShell byte-order mark.
            raw=override_file.read_text(encoding="utf-8-sig",errors="ignore").strip().strip('"')
            p=Path(raw).expanduser()
            if p.exists():
                return p.resolve(),{"source":"library_root.txt","score":999999998,"details":{}}
        except Exception:
            pass

    # Optional field in the release config.
    release_cfg=code_root/"app"/"config.json"
    bundled_cfg=BUNDLE_ROOT/"app"/"config.json"
    readable_cfg=release_cfg if release_cfg.exists() else bundled_cfg
    if readable_cfg.exists():
        try:
            cfg=json.loads(readable_cfg.read_text(encoding="utf-8"))
            raw=str(cfg.get("library_root") or "").strip()
            if raw:
                p=Path(raw).expanduser()
                if p.exists():
                    return p.resolve(),{"source":"config library_root","score":999999997,"details":{}}
        except Exception:
            pass

    candidates=[]
    def add(p):
        try:p=Path(p).resolve()
        except Exception:return
        if p not in candidates:candidates.append(p)

    # The single-file desktop release keeps the executable at the top level
    # and all writable data/tools under one clean Downloads parent folder.
    # Prefer that sibling root whenever it is a real library.
    portable_data=code_root/"Downloads"
    if portable_data.is_dir() and _root_db_count(portable_data)>0:
        return portable_data.resolve(),{"source":"portable Downloads folder","score":999999996,"details":{}}

    # An installed EXE under Program Files must never try to persist config,
    # SQLite, logs or generated artifacts beside the executable.
    if getattr(sys,"frozen",False) and _is_program_files_path(code_root):
        user_root=_windows_user_data_root()
        user_root.mkdir(parents=True,exist_ok=True)
        return user_root.resolve(),{"source":"per-user app data","score":999999995,"details":{}}

    add(code_root)
    add(code_root.parent)
    add(code_root.parent.parent)
    add(Path.cwd())
    add(Path.cwd().parent)

    # Look one sibling level around the release. This handles a new ZIP extracted
    # next to an older "11 VideoLibraryManager_MASTER" installation.
    for parent in [code_root.parent,code_root.parent.parent]:
        try:
            for child in parent.iterdir():
                if not child.is_dir():
                    continue
                name=child.name.lower().replace("_","").replace("-","").replace(" ","")
                if "videolibrarymanager" in name:
                    add(child)
        except Exception:
            pass

    ranked=[]
    for c in candidates:
        score,details=_library_root_score(c,code_root)
        ranked.append((score,c,details))
    ranked.sort(key=lambda x:x[0],reverse=True)
    best=ranked[0] if ranked else (0,code_root,{})
    source="current release root" if best[1]==code_root else "auto-detected existing library"
    return best[1],{"source":source,"score":best[0],"details":best[2],"candidates":[{"path":str(c),"score":s,"details":d} for s,c,d in ranked[:8]]}

