def find_executable(filename):
    # Prefer explicit files in either the live library root or this code release.
    stem=Path(filename).stem
    direct_candidates=[
        TOOLS/filename, TOOLS/stem/filename, TOOLS/stem/"bin"/filename,
        BASE/filename, CODE_ROOT/filename, BASE/"tools"/filename,
        CODE_ROOT/"tools"/filename,
    ]
    # Known archives use stable directory names that do not always match the
    # executable stem (for example ffprobe lives in the ffmpeg bundle).
    if filename.lower() in {"ffmpeg.exe","ffprobe.exe"}:
        direct_candidates.insert(0,TOOLS/"ffmpeg"/"bin"/filename)
    if filename.lower()=="ollama.exe":
        direct_candidates.insert(0,TOOLS/"ollama"/filename)
    for direct in direct_candidates:
        if direct.exists():
            return direct
    matches=[]
    for search_root in [CODE_ROOT,BASE]:
        try:
            matches.extend(p for p in search_root.rglob(filename) if p.is_file())
        except Exception:
            pass
    if matches:
        matches=sorted(set(matches),key=lambda p:(len(p.parts),len(str(p))))
        return matches[0]
    return CODE_ROOT / filename

