def _load_authoritative_default_config():
    """Load the shipped default schema; the in-code dict is bootstrap fallback only."""
    candidates = [
        BUNDLE_ROOT / "app" / "config.default.json",
        CODE_ROOT / "app" / "config.default.json",
        APP_DIR / "config.default.json",
    ]
    for candidate in candidates:
        try:
            if not candidate.is_file():
                continue
            value = json.loads(candidate.read_text(encoding="utf-8"))
            if isinstance(value, dict):
                return value
        except Exception:
            continue
    return None


