def console_progress(prefix=""):
    if not CFG.get("console_progress",True):
        return
    s=snapshot()
    total=s.get("total",0) or 0
    processed=s.get("processed",0) or 0
    pct=(processed*100/total) if total else 0
    stage=s.get("phase","")
    status=s.get("current_status","")
    fp=s.get("current_percent","")
    sp=s.get("current_speed","")
    eta=s.get("current_eta","")
    current=s.get("current_file") or s.get("current","")
    msg=(f"\r{prefix}{stage} | {processed}/{total} ({pct:5.1f}%)"
         f" | {status}")
    if fp:
        msg+=f" | File {fp}"
    if sp:
        msg+=f" | {sp}"
    if eta:
        msg+=f" | ETA {eta}"
    if current:
        msg+=f" | {str(current)[:70]}"
    child_id=str(getattr(WEB_JOB_CONTEXT,"video_id","") or "") if "WEB_JOB_CONTEXT" in globals() else ""
    with CONSOLE_PROGRESS_LOCK:
        if child_id:
            try:
                numeric=float(re.search(r"([0-9]+(?:\.[0-9]+)?)",str(fp or "0")).group(1))
            except Exception:
                numeric=0.0
            marker=(int(numeric//10)*10,str(status),str(stage))
            if CONSOLE_PROGRESS_LAST.get(child_id)==marker:
                return
            CONSOLE_PROGRESS_LAST[child_id]=marker
            print(f"[{child_id}] {msg.lstrip(chr(13))[:220]}",flush=True)
        else:
            print(msg[:240].ljust(240),end="",flush=True)

def console_newline():
    if CFG.get("console_progress",True):
        with CONSOLE_PROGRESS_LOCK:print()

