def is_youtube_url(url):
    return canonical_is_youtube_url(url)

def normalize_pasted_url(value):
    """
    Accept URLs pasted from ChatGPT/Markdown/email and return the real URL.
    Examples:
      [https://www.youtube.com/watch?v=ID](https://www.youtube.com/watch?v=ID)
      <https://www.youtube.com/watch?v=ID>
      "https://www.youtube.com/watch?v=ID"
    """
    s=html.unescape(str(value or "")).strip()
    if not s:
        return ""
    md=re.match(r"^\s*\[[^\]]+\]\((https?://[^)\s]+)\)\s*$",s,flags=re.I)
    if md:
        s=md.group(1)
    else:
        raw=re.search(r"https?://[^\s<>\]\)\"']+",s,flags=re.I)
        if raw:
            s=raw.group(0)
    s=s.strip().strip("<>").strip().strip('"').strip("'")
    # Remove punctuation commonly dragged in from prose, but preserve URL query syntax.
    s=re.sub(r"[),.;]+$","",s)
    return s

def log(msg):
    LOG.parent.mkdir(parents=True,exist_ok=True)
    with open(LOG,"a",encoding="utf-8") as f:
        f.write(f"[{datetime.now():%Y-%m-%d %H:%M:%S}] {msg}\n")


def set_state(**kwargs):
    with STATE_LOCK:
        STATE.update(kwargs)
        current = dict(STATE)
    try:
        job_id = getattr(WEB_JOB_CONTEXT, "job_id", None)
        if job_id:
            phase = str(current.get("phase") or "Working")
            item = str(current.get("current_file") or current.get("current") or "")
            status = str(current.get("current_status") or current.get("message") or phase)
            message = phase + " | " + status + ((" | " + item) if item else "")
            web_job_update(job_id, message=message, processed=int(current.get("processed") or 0), total=int(current.get("total") or 0), failed=int(current.get("failed") or 0), skipped=int(current.get("skipped") or 0), current_file=item, current_status=status, current_percent=str(current.get("current_percent") or ""), current_speed=str(current.get("current_speed") or ""), current_eta=str(current.get("current_eta") or ""), phase=phase)
    except Exception:
        pass

def snapshot():
    with STATE_LOCK:
        s = dict(STATE)
    if s.get("started"):
        elapsed = max(time.time() - s["started"], 0.001)
        s["elapsed_seconds"] = int(elapsed)
        s["rate"] = round(s.get("processed",0)/elapsed, 2)
    else:
        s["elapsed_seconds"] = 0
        s["rate"] = 0
    return s


def transcript_fingerprint(text):
    import hashlib
    return hashlib.sha256((text or "").encode("utf-8",errors="ignore")).hexdigest()

def ai_cache_valid(video_id, timestamped_text):
    p=temp_paths(video_id)
    stamp=p["dir"]/f"{video_id}.transcript.sha256"
    if not (p["identity"].exists() and p["chapters"].exists() and stamp.exists()):
        return False
    try:
        return stamp.read_text(encoding="utf-8").strip()==transcript_fingerprint(timestamped_text)
    except Exception:
        return False

def save_ai_fingerprint(video_id, timestamped_text):
    p=temp_paths(video_id)
    p["dir"].mkdir(parents=True,exist_ok=True)
    (p["dir"]/f"{video_id}.transcript.sha256").write_text(
        transcript_fingerprint(timestamped_text),encoding="utf-8"
    )



def support_file_path(folder,preferred_name,video_id="",fallback_suffix=""):
    """
    Return a Windows-safe path inside _data.

    Keep preferred human-readable filename when path is reasonably short.
    For long paths, use VideoID-based filename to avoid WinError 3 / MAX_PATH.
    """
    data=support_dir(folder,create=True)
    preferred=safe_name(str(preferred_name or "file"))
    candidate=data/preferred

    # Keep margin under classic Windows MAX_PATH because some stdlib/WinAPI
    # operations still fail even when Python itself can represent longer paths.
    if len(str(candidate)) <= 235:
        return candidate

    vid=safe_name(str(video_id or "video"))
    suffix=str(fallback_suffix or Path(preferred).suffix or "")
    if suffix and not suffix.startswith("."):
        suffix="."+suffix

    short_name=f"{vid}{suffix}"
    return data/short_name

def support_dir(folder,create=True):
    p=Path(folder)/"_data"
    if create:
        try:
            p.mkdir(parents=True,exist_ok=True)
        except Exception:
            pass
    return p


def find_original_title_marker(folder):
    """
    Return the existing .original-title marker regardless of filename.
    Renames must never require a title-derived marker filename.
    """
    folder=Path(folder)
    markers=sorted(folder.glob("*.original-title"))
    return markers[0] if markers else None


def read_original_title_marker(folder, fallback=""):
    marker=find_original_title_marker(folder)
    if marker and marker.exists():
        try:
            value=marker.read_text(encoding="utf-8",errors="ignore").strip()
            if value:
                return value
        except Exception:
            pass
    return str(fallback or "").strip()


def ensure_original_title_marker(folder, original_title):
    """
    Keep one .original-title marker.
    - preserve an existing marker filename
    - fill empty content from original_title
    - create support/folder path first
    - never call write_text on None
    """
    folder=Path(folder)
    folder.mkdir(parents=True,exist_ok=True)

    title=str(original_title or "").strip()
    marker=find_original_title_marker(folder)

    if marker is not None:
        try:
            current=marker.read_text(encoding="utf-8",errors="ignore").strip()
        except Exception:
            current=""
        if not current and title:
            marker.write_text(title,encoding="utf-8")
        return marker

    if not title:
        return None

    marker=find_original_title_marker(folder)
    marker.write_text(title,encoding="utf-8")
    return marker


def create_original_title_marker(folder,original_title):
    """
    Best-effort marker creation. Marker failure must never block video download.
    """
    try:
        return ensure_original_title_marker(folder,original_title)
    except Exception as ex:
        try:
            folder=Path(folder)
            folder.mkdir(parents=True,exist_ok=True)
            fallback=folder/".original-title"
            if original_title:
                fallback.write_text(str(original_title),encoding="utf-8")
            return fallback
        except Exception:
            log(f"Original-title marker warning: {type(ex).__name__}: {ex}")
            return None


def title_is_finalized(video_id):
    if not CFG.get("protect_finalized_titles",True):
        return False
    con=db_connect()
    row=con.execute(
        "SELECT COALESCE(title_finalized,0),COALESCE(chatgpt_imported,0) FROM videos WHERE video_id=?",
        (video_id,)
    ).fetchone()
    con.close()
    if not row:
        return False
    return bool(int(row[0] or 0) or int(row[1] or 0))

def safe_update_clean_title(video_id,new_title,force=False):
    if not force and title_is_finalized(video_id):
        return False
    con=db_connect()
    con.execute(
        "UPDATE videos SET clean_title=? WHERE video_id=?",
        (new_title,video_id)
    )
    con.commit()
    con.close()
    return True

def clean_source_title_no_llm(original_title):
    """
    Fast source-title cleaner used when LLM is disabled.
    Preserve the real subject of an already meaningful YouTube title.
    Do NOT rename from random transcript keyword matches.
    """
    t=html.unescape(original_title or "").strip()

    # Remove channel/promo suffixes and common social clutter.
    t=re.sub(r'(?i)\s*[-–—|]\s*(?:fit\s*tuber|official|full\s*video)\s*$', ' ', t)
    t=re.sub(r'(?<!\w)#[\w-]+', ' ', t, flags=re.UNICODE)
    t=re.sub(r'@\w+', ' ', t)
    t=re.sub(r'[🔥✨🚨🤫🌎💩❤♥★☆👉➡]+', ' ', t)
    t=re.sub(r'(?i)\b(?:must\s*watch|not\s*sponsored|watch\s*till\s*end)\b', ' ', t)

    # Remove decorative/repeated punctuation, but preserve normal words/numbers.
    t=re.sub(r'[<>:"/\\|?*]', ' ', t)
    t=re.sub(r'!{1,}|\?{1,}|\.{2,}', ' ', t)
    t=re.sub(r'\s*[-–—]\s*$', ' ', t)
    t=re.sub(r'\s+', ' ', t).strip(' .,_-–—')

    return safe_name(t or original_title or "video")

def simple_title_from_source(original_title, transcript_text=""):
    """
    No-LLM mode intentionally uses the cleaned SOURCE TITLE.
    Transcript-derived semantic naming is reserved for LLM mode because
    keyword-only inference can misname unrelated videos.
    """
    return clean_source_title_no_llm(original_title)


def simple_non_llm_chapters(timestamped_text, target_seconds=180):
    """
    Fast structured fallback without LLM. Produces non-empty time-based sections
    with headings derived from the first meaningful words in each section.
    """
    lines=[x.strip() for x in (timestamped_text or "").splitlines() if x.strip()]
    if not lines:
        return []
    time_re=re.compile(r'^\[(\d{2}:\d{2}:\d{2})\]\s*(.*)$')
    chunks=[]; cur=[]; start_ts=None; end_ts=None; bucket_start=None

    for line in lines:
        m=time_re.match(line)
        if not m: continue
        ts,body=m.group(1),m.group(2).strip()
        if not body: continue
        seconds=sec(ts)
        if bucket_start is None:
            bucket_start=seconds; start_ts=ts
        if cur and seconds-bucket_start>=target_seconds:
            chunks.append((start_ts,end_ts," ".join(cur)))
            cur=[]; bucket_start=seconds; start_ts=ts
        cur.append(body); end_ts=ts
    if cur:
        chunks.append((start_ts,end_ts," ".join(cur)))

    rows=[]
    stop={"the","a","an","and","or","to","of","in","for","with","this","that","is","are","you","your","we","it"}
    for i,(start,end,body) in enumerate(chunks,1):
        words=re.findall(r"[A-Za-z][A-Za-z'-]+",body)
        meaningful=[]
        for w in words:
            lw=w.lower()
            if lw not in stop and len(w)>2 and lw not in [x.lower() for x in meaningful]:
                meaningful.append(w)
            if len(meaningful)>=6: break
        title=" ".join(meaningful[:6]).strip()
        if not title:
            title=f"Video Section {i}"
        overview=" ".join(body.split()[:120])
        rows.append({
            "chapter_title":title,
            "start":start or "00:00:00",
            "end":end or start or "00:00:00",
            "overview":overview,
            "topics":meaningful[:6],
            "ingredients_or_entities":[],
            "instructions":[],
            "claims":[],
            "key_points":[],
            "tags":[]
        })
    return rows

def safe_name(title, fallback="video"):
    t = html.unescape(title or "").strip()
    t = re.sub(r'(?<!\w)#[\w-]+',' ',t,flags=re.UNICODE)
    t = re.sub(r'[\u200b-\u200f\u202a-\u202e\ufeff]','',t)
    t = re.sub(r'[|•●◆★☆♥❤🔥✨👉➡→←]+',' ',t)
    t = re.sub(r'[\[\(]\s*(?:full\s*video|official\s*video|hd|4k|1080p|720p|watch\s*now)\s*[\]\)]',' ',t,flags=re.I)
    t = re.sub(r'(?i)\b(full\s*video|official\s*video|watch\s*now)\b',' ',t)
    t = re.sub(r'\.{2,}|!{2,}|\?{2,}|[-–—]{2,}',' ',t)
    t = re.sub(r'[<>:"/\\|?*]',' ',t)
    t = re.sub(r'\s+',' ',t).strip(' .-_–—')
    return windows_safe_component(t, fallback=fallback, max_chars=140)


def load_youtube_api_key():
    """
    Read the YouTube Data API key from api_key.txt beside app.py.
    Blank lines are ignored. The first non-empty line is used.
    Also accepts a line written as API_KEY=<key>.
    """
    candidates=[Path(os.environ.get("VLM_API_KEY_FILE") or ""),CODE_ROOT/"api_key.txt",BASE/"api_key.txt"]
    for key_file in candidates:
        if not str(key_file) or not key_file.exists():
            continue
        try:
            for line in key_file.read_text(encoding="utf-8-sig",errors="ignore").splitlines():
                line=line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" in line and line.upper().startswith(("API_KEY=","YOUTUBE_API_KEY=")):
                    line=line.split("=",1)[1].strip()
                return line
        except Exception:
            continue
    return ""


