def migrate_legacy_root_files():
    """
    Move legacy root files into canonical folders.
    Non-destructive on name collision: keep destination and suffix migrated copy.
    """
    ensure_project_layout()

    mappings={
        BASE/"video_library.db": BASE/"data"/"database"/"video_library.db",
        BASE/"video_library.rebuilt.db": BASE/"maintenance"/"recovery"/"video_library.rebuilt.db",
        BASE/"video_list.csv": BASE/"data"/"exports"/"video_list.csv",
        BASE/"video_list_with_chatgpt_titles.csv": BASE/"data"/"exports"/"video_list_with_chatgpt_titles.csv",
        BASE/"rename_review_results.csv": BASE/"maintenance"/"audits"/"rename_review_results.csv",

        BASE/"library_health.csv": BASE/"maintenance"/"audits"/"library_health.csv",
        BASE/"library_health_summary.json": BASE/"maintenance"/"audits"/"library_health_summary.json",
        BASE/"phase0_core_audit.csv": BASE/"maintenance"/"audits"/"phase0_core_audit.csv",
        BASE/"app.log": BASE/"logs"/"app.log",
        BASE/"package_history.csv": BASE/"data"/"chatgpt"/"package_history.csv",
        BASE/"phase2_integrity_audit.csv": BASE/"maintenance"/"audits"/"phase2_integrity_audit.csv",
        BASE/"phase3_summary_quality.csv": BASE/"maintenance"/"audits"/"phase3_summary_quality.csv",
        BASE/"phase4_content_intelligence.csv": BASE/"maintenance"/"audits"/"phase4_content_intelligence.csv",
    }

    moved=0
    skipped=0
    failed=0

    for old,new in mappings.items():
        try:
            if not old.exists():
                continue
            # A migration source must never be its own destination.  Treating
            # it as a duplicate would unlink the canonical file on startup.
            if old.resolve()==new.resolve():
                continue
            new.parent.mkdir(parents=True,exist_ok=True)

            if new.exists():
                # Equal byte length is not proof of duplicate content.  Delete
                # the legacy source only after a content hash confirms equality.
                if files_equal(old, new):
                    old.unlink()
                    skipped+=1
                    continue
                alt=unique_conflict_path(new, marker="legacy")
                shutil.move(str(old),str(alt))
            else:
                shutil.move(str(old),str(new))
            moved+=1
        except Exception as ex:
            failed+=1
            print(f"Legacy file migration failed: {old.name}: {ex}")

    print(f"Root file migration: moved={moved}, skipped duplicates={skipped}, failed={failed}")
    return moved,skipped,failed

def db_connect():
    ensure_project_layout()
    DB.parent.mkdir(parents=True,exist_ok=True)
    con = sqlite3.connect(DB, timeout=30, check_same_thread=False)
    con.execute("PRAGMA journal_mode=WAL")
    con.execute("""
      CREATE TABLE IF NOT EXISTS videos(
        video_id TEXT PRIMARY KEY,
        platform TEXT,
        url TEXT,
        original_title TEXT,
        clean_title TEXT,
        channel TEXT,
        upload_date TEXT,
        category TEXT,
        subcategory TEXT,
        main_topic TEXT,
        tags TEXT,
        ai_confidence REAL,
        needs_review INTEGER DEFAULT 0,
        description TEXT,
        status TEXT DEFAULT 'active',
        downloaded INTEGER DEFAULT 0,
        downloaded_quality TEXT,
        local_folder TEXT,
        local_video TEXT,
        subtitle_file TEXT,
        transcript_original TEXT,
        transcript_clean TEXT,
        transcript_detailed TEXT,
        report_html TEXT,
        first_seen TEXT,
        last_seen TEXT,
        last_error TEXT
      )
    """)
    # Keep schema evolution centralized so app.py remains orchestration-focused.
    apply_video_schema_migrations(con)
    con.execute("CREATE INDEX IF NOT EXISTS idx_upload_date ON videos(upload_date)")
    con.execute("CREATE INDEX IF NOT EXISTS idx_url ON videos(url)")
    con.execute("""CREATE TABLE IF NOT EXISTS video_artifact_manifest(
        video_id TEXT PRIMARY KEY, manifest_json TEXT NOT NULL, scanned_at TEXT NOT NULL
    )""")
    con.execute("""CREATE TABLE IF NOT EXISTS transcript_availability(
        video_id TEXT PRIMARY KEY, status TEXT NOT NULL, source TEXT, checked_at TEXT NOT NULL,
        detail TEXT, package_preflight_id TEXT
    )""")
    con.execute("""CREATE TABLE IF NOT EXISTS chatgpt_requests(
        request_id TEXT PRIMARY KEY, package_id TEXT UNIQUE, mode TEXT, schema_version TEXT,
        prompt_version TEXT, requested_features_json TEXT, package_hash TEXT, manifest_json TEXT,
        created_at TEXT, status TEXT, result_path TEXT, result_hash TEXT, validation_status TEXT,
        applied_status TEXT, notes TEXT
    )""")
    con.execute("""CREATE TABLE IF NOT EXISTS chatgpt_request_videos(
        request_id TEXT, video_id TEXT, source_snapshot_hash TEXT, evidence_manifest_json TEXT,
        requested_features_json TEXT, PRIMARY KEY(request_id,video_id)
    )""")
    con.execute("""CREATE TABLE IF NOT EXISTS video_feature_coverage(
        video_id TEXT, feature_id TEXT, feature_version TEXT, status TEXT, source_snapshot_hash TEXT,
        package_id TEXT, result_hash TEXT, evidence_coverage TEXT, completed_at TEXT, stale_reason TEXT,
        last_error TEXT, PRIMARY KEY(video_id,feature_id,feature_version)
    )""")
    con.execute("""CREATE TABLE IF NOT EXISTS chatgpt_processed_video_locks(
        video_id TEXT NOT NULL,
        feature_set_key TEXT NOT NULL,
        package_id TEXT,
        result_hash TEXT,
        completed_at TEXT NOT NULL,
        requested_features_json TEXT,
        PRIMARY KEY(video_id,feature_set_key)
    )""")
    con.execute("""CREATE TABLE IF NOT EXISTS chatgpt_import_field_history(
        transaction_id TEXT, video_id TEXT, feature_id TEXT, field_path TEXT, previous_hash TEXT,
        proposed_hash TEXT, action TEXT, lock_state TEXT, timestamp TEXT
    )""")
    con.execute("""CREATE TABLE IF NOT EXISTS external_media(
        external_id TEXT PRIMARY KEY, source_url TEXT, title TEXT, category TEXT,
        protocol TEXT, local_path TEXT, added_at TEXT, downloaded_at TEXT,
        status TEXT, error TEXT
    )""")
    con.execute("""CREATE TABLE IF NOT EXISTS youtube_subscriptions(
        channel_key TEXT PRIMARY KEY, channel_id TEXT, handle TEXT, title TEXT,
        url TEXT, thumbnail_url TEXT, description TEXT, subscriber_text TEXT, video_count_text TEXT,
        dominant_category TEXT, selected_for_scan INTEGER DEFAULT 0,
        source TEXT, collected_at TEXT
    )""")
    # Existing libraries already have this table.  Keep the upgrade additive so
    # no collected subscriptions are lost when the new selection workflow lands.
    try:
        con.execute("ALTER TABLE youtube_subscriptions ADD COLUMN selected_for_scan INTEGER DEFAULT 0")
    except sqlite3.OperationalError:
        pass
    try:
        con.execute("ALTER TABLE youtube_subscriptions ADD COLUMN thumbnail_url TEXT")
    except sqlite3.OperationalError:
        pass
    con.execute("""CREATE TABLE IF NOT EXISTS clip_projects(
        project_id TEXT PRIMARY KEY, name TEXT, project_json TEXT, output_path TEXT,
        status TEXT, created_at TEXT, completed_at TEXT, error TEXT
    )""")
    con.commit()
    return con

