def run(args, timeout=None):
    flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
    proc=None
    try:
        proc=subprocess.Popen(
            [str(x) for x in args],
            stdout=subprocess.PIPE,stderr=subprocess.PIPE,
            text=True,encoding="utf-8",errors="replace",
            creationflags=flags
        )
        web_register_process(proc)
        max_wait=float(timeout or CFG.get("timeout_seconds",60))
        started=time.time()
        while True:
            if web_stop_requested():
                try:proc.terminate()
                except Exception:pass
                try:out,err=proc.communicate(timeout=2)
                except Exception:
                    try:proc.kill()
                    except Exception:pass
                    out,err=proc.communicate()
                return 130,out or "",(err or "")+"\nSTOPPED BY USER"
            remaining=max_wait-(time.time()-started)
            if remaining<=0:
                try:proc.terminate()
                except Exception:pass
                try:out,err=proc.communicate(timeout=2)
                except Exception:
                    try:proc.kill()
                    except Exception:pass
                    out,err=proc.communicate()
                return 124,out or "",(err or "")+"\nTIMEOUT"
            try:
                out,err=proc.communicate(timeout=min(0.35,remaining))
                return proc.returncode,out or "",err or ""
            except subprocess.TimeoutExpired:
                continue
    except Exception as ex:
        return 1,"",f"{type(ex).__name__}: {ex}"
    finally:
        web_unregister_process(proc)


def start_stage(name):
    s=snapshot()
    if s.get("stage_started_at"):
        finish_stage(s.get("phase") or "Stage")
    set_state(phase=name,stage_started_at=time.time())
    console_newline()
    print(f">> {name} started")
    console_progress()

def finish_stage(name=None):
    s=snapshot()
    started=s.get("stage_started_at")
    if not started:
        return
    elapsed=max(0,time.time()-started)
    timings=s.get("stage_timings",[])
    stage_name=name or s.get("phase") or "Stage"
    timings.append({"stage":stage_name,"seconds":round(elapsed,2)})
    set_state(stage_timings=timings,stage_started_at=None)
    console_newline()
    print(f"<< {stage_name} finished in {elapsed:.1f} sec")

def set_file_table(rows):
    """Rows: list of dicts with name, required, status, path."""
    set_state(file_table=rows)

def update_file_status(name, status, path=""):
    s=snapshot()
    rows=s.get("file_table",[])
    found=False
    for row in rows:
        if row.get("name")==name:
            row["status"]=status
            if path:
                row["path"]=path
            found=True
            break
    if not found:
        rows.append({"name":name,"required":True,"status":status,"path":path})
    set_state(file_table=rows)

def run_download_with_progress(args, display_name, file_role=None, timeout_seconds=None):
    flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
    cmd = list(args) + [
        "--newline",
        "--progress-template",
        "download:VLM_PROGRESS|%(progress._percent_str)s|%(progress._speed_str)s|%(progress._eta_str)s|%(info.filename)s"
    ]
    try:
        p = subprocess.Popen(
            cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,
            encoding="utf-8", errors="replace", bufsize=1, creationflags=flags
        )
        web_register_process(p)
        timer=None
        if timeout_seconds:
            timer=threading.Timer(float(timeout_seconds),lambda: p.poll() is None and p.terminate())
            timer.daemon=True;timer.start()
        tail = []
        full_log = []
        for line in p.stdout:
            if web_stop_requested():
                try:p.terminate()
                except Exception:pass
                break
            line = line.rstrip()
            full_log.append(line)
            if line.startswith("VLM_PROGRESS|"):
                parts = line.split("|",4)
                pct = parts[1].strip() if len(parts)>1 else ""
                speed = parts[2].strip() if len(parts)>2 else ""
                eta = parts[3].strip() if len(parts)>3 else ""
                fn = parts[4].strip() if len(parts)>4 else display_name
                set_state(current_file=fn,current_status="DOWNLOADING",current_percent=pct,
                          current_speed=speed,current_eta=eta,files_in_progress=[fn])
                try:
                    m=re.search(r"([0-9]+(?:\.[0-9]+)?)",str(pct or ""))
                    jid=getattr(WEB_JOB_CONTEXT,"job_id",None)
                    if jid and m:
                        child_id=getattr(WEB_JOB_CONTEXT,"video_id","")
                        child_title=getattr(WEB_JOB_CONTEXT,"video_title",display_name)
                        if child_id:
                            web_video_progress(child_id,title=child_title,percent=float(m.group(1)),speed=speed,eta=eta,stage="Downloading")
                        else:
                            web_job_update(jid,transfer_percent=float(m.group(1)),message=f"Downloading {fn}",stage="Downloading")
                except Exception:
                    pass
                if file_role:
                    update_file_status(file_role,"Downloading",fn)
                console_progress()
            elif line:
                tail.append(line)
                if len(tail) > 100:
                    tail = tail[-100:]
                low = line.lower()
                if "merging formats into" in low:
                    set_state(current_status="MERGING VIDEO + AUDIO")
                elif "writing video subtitles" in low:
                    set_state(current_status="DOWNLOADING SUBTITLES")
                elif "writing video description" in low:
                    set_state(current_status="SAVING DESCRIPTION")
                elif "writing video metadata as json" in low:
                    set_state(current_status="SAVING METADATA")
                elif "converting subtitles" in low:
                    set_state(current_status="CONVERTING SUBTITLES")
        rc = p.wait()
        if timer:timer.cancel()
        set_state(current_status="FINISHED" if rc==0 else "FAILED",
                  current_percent="100%" if rc==0 else snapshot().get("current_percent",""),
                  files_in_progress=[])
        try:
            jid=getattr(WEB_JOB_CONTEXT,"job_id",None)
            if jid and rc==0:
                child_id=getattr(WEB_JOB_CONTEXT,"video_id","")
                if child_id:
                    web_video_progress(child_id,title=getattr(WEB_JOB_CONTEXT,"video_title",display_name),percent=100.0,stage="Finalizing")
                else:
                    web_job_update(jid,transfer_percent=100.0,message="Download finished",stage="Finalizing")
        except Exception:
            pass
        if file_role and rc != 0:
            update_file_status(file_role,"Failed")
        return rc, "\n".join(full_log), "\n".join(tail)
    except Exception as e:
        set_state(current_status="FAILED",files_in_progress=[])
        return 1, "", str(e)
    finally:
        try:web_unregister_process(locals().get("p"))
        except Exception:pass


