def load_urls():
    path=current_urls_path()
    if not path.exists():
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_text("# Put one supported video/channel/playlist URL per line.\n",encoding="utf-8")
    return [x.strip() for x in path.read_text(encoding="utf-8-sig").splitlines()
            if x.strip() and not x.strip().startswith("#")]


def youtube_api_get(resource,params):
    key=str(CFG.get("youtube_data_api_key","")).strip() or load_youtube_api_key()
    if not key:
        raise RuntimeError("YouTube Data API key is not configured")
    p=dict(params); p["key"]=key
    url="https://www.googleapis.com/youtube/v3/"+resource+"?"+urllib.parse.urlencode(p)
    req=urllib.request.Request(url,headers={"User-Agent":"VideoLibraryManager/13"})
    with urllib.request.urlopen(req,timeout=60) as r:
        return json.loads(r.read().decode("utf-8"))

def youtube_source_descriptor(url):
    return canonical_youtube_source_descriptor(url)


def youtube_channel_uploads_playlist(kind,value):
    if kind=="channel_id": params={"part":"contentDetails,snippet,statistics","id":value}
    elif kind=="handle": params={"part":"contentDetails,snippet,statistics","forHandle":value}
    elif kind=="username": params={"part":"contentDetails,snippet,statistics","forUsername":value}
    else: return None
    data=youtube_api_get("channels",params); items=data.get("items") or []
    if not items: return None
    return items[0].get("contentDetails",{}).get("relatedPlaylists",{}).get("uploads")

def youtube_playlist_video_ids(playlist_id):
    ids=[]; token=None
    while True:
        params={"part":"contentDetails","playlistId":playlist_id,"maxResults":50}
        if token: params["pageToken"]=token
        data=youtube_api_get("playlistItems",params)
        for item in data.get("items",[]):
            vid=item.get("contentDetails",{}).get("videoId")
            if vid: ids.append(vid)
        token=data.get("nextPageToken")
        set_state(listed=len(ids),current=f"API playlist {playlist_id}")
        console_progress("YouTube API | ")
        if not token: break
    return ids

def youtube_video_ids_for_source(source):
    kind,value=youtube_source_descriptor(source)
    if kind=="video": return [value]
    if kind=="playlist": return youtube_playlist_video_ids(value)
    if kind in ("channel_id","handle","username"):
        uploads=youtube_channel_uploads_playlist(kind,value)
        return youtube_playlist_video_ids(uploads) if uploads else []
    return []


YOUTUBE_CATEGORY_CACHE={}

def youtube_category_titles(category_ids):
    ids=[str(x) for x in category_ids if str(x).strip()]
    missing=[x for x in dict.fromkeys(ids) if x not in YOUTUBE_CATEGORY_CACHE]
    if missing:
        try:
            data=youtube_api_get("videoCategories",{"part":"snippet","id":",".join(missing)})
            for item in data.get("items",[]):
                YOUTUBE_CATEGORY_CACHE[str(item.get("id") or "")]=str(item.get("snippet",{}).get("title") or "")
        except Exception as ex:
            log(f"YouTube category lookup failed: {ex}")
    return {x:YOUTUBE_CATEGORY_CACHE.get(x,"") for x in ids}

def choose_source_category(meta,custom_fallback="Entertainment"):
    name=str(meta.get("source_category") or meta.get("youtube_category_name") or "").strip()
    if name:return name
    cats=meta.get("source_categories") or []
    if isinstance(cats,str):
        try:cats=json.loads(cats)
        except Exception:cats=[cats]
    for x in cats:
        if str(x).strip():return str(x).strip()
    return str(custom_fallback or "Entertainment").strip() or "Entertainment"

def extract_single_source_metadata(url):
    base={"id":"","url":str(url),"title":"","channel":"","upload_date":"","platform":"Other"}
    args=common_args()+["--skip-download","--no-playlist","--dump-single-json",str(url)]
    timeout=max(120,int(CFG.get("timeout_seconds",60)))
    rc,out,err,_cookie_retry=run_with_browser_cookie_fallback(
        args,str(url),CFG,lambda retry_args: run(retry_args,timeout=timeout)
    )
    try:d=json.loads(out) if out.strip() else {}
    except Exception:d={}
    if d:
        vid=str(d.get("id") or "").strip() or ("GEN_"+hashlib.sha1(str(url).encode()).hexdigest()[:11])
        base.update({
            "id":vid,"url":d.get("webpage_url") or str(url),"title":d.get("title") or vid,
            "channel":d.get("channel") or d.get("uploader") or "Unknown Channel",
            "upload_date":d.get("upload_date") or "","description":d.get("description") or "",
            "platform":detect_platform(d),"youtube_tags":d.get("tags") or [],
            "source_categories":d.get("categories") or [],"source_category":((d.get("categories") or [""])[0] if isinstance(d.get("categories") or [],list) and (d.get("categories") or []) else ""),
            "thumbnail_url":d.get("thumbnail") or "","metadata_source":"yt-dlp"
        })
        sub_source,sub_lang,sub_base_lang=choose_preferred_caption(d)
        base.update({"subtitle_source":sub_source,"subtitle_lang":sub_lang,"subtitle_base_lang":sub_base_lang})
        if base["platform"]=="YouTube" and (str(CFG.get("youtube_data_api_key","")).strip() or load_youtube_api_key()):
            try:
                apirows=youtube_api_video_metadata([vid])
                if apirows:base.update(apirows[0])
            except Exception as ex:log(f"YouTube metadata enrichment failed {vid}: {ex}")
        return attach_canonical_metadata(base,raw=d),""
    return None,(err or "metadata extraction failed")[-2000:]

def youtube_api_video_metadata(video_ids):
    rows=[]; batch_size=max(1,min(50,int(CFG.get("metadata_api_batch_size",50))))
    for offset in range(0,len(video_ids),batch_size):
        batch=video_ids[offset:offset+batch_size]
        data=youtube_api_get("videos",{"part":"snippet,contentDetails,statistics,status","id":",".join(batch)})
        byid={x.get("id"):x for x in data.get("items",[])}
        cat_ids=[str(x.get("snippet",{}).get("categoryId") or "") for x in data.get("items",[])]
        catmap=youtube_category_titles(cat_ids)
        for vid in batch:
            item=byid.get(vid)
            if not item: continue
            sn=item.get("snippet",{}); stats=item.get("statistics",{}); cid=str(sn.get("categoryId") or ""); cname=catmap.get(cid,"")
            _status=item.get("status",{}) or {};_channel_id=str(sn.get("channelId") or "")
            row={"id":vid,"url":f"https://www.youtube.com/watch?v={vid}","title":sn.get("title") or "","channel":sn.get("channelTitle") or "","channel_id":_channel_id,"channel_url":f"https://www.youtube.com/channel/{_channel_id}" if _channel_id else "","upload_date":(sn.get("publishedAt") or "")[:10].replace("-",""),"description":sn.get("description") or "","availability":str(_status.get("privacyStatus") or ""),"platform":"YouTube","youtube_tags":sn.get("tags") or [],"youtube_category_id":cid,"youtube_category_name":cname,"source_category_id":cid,"source_category":cname,"source_categories":[cname] if cname else [],"thumbnail_url":((sn.get("thumbnails") or {}).get("high") or (sn.get("thumbnails") or {}).get("medium") or (sn.get("thumbnails") or {}).get("default") or {}).get("url","") if isinstance(sn.get("thumbnails"),dict) else "","duration_iso":item.get("contentDetails",{}).get("duration") or "","view_count":int(stats.get("viewCount") or 0),"like_count":int(stats.get("likeCount") or 0),"comment_count":int(stats.get("commentCount") or 0),"metadata_source":"YouTube Data API"}
            rows.append(attach_canonical_metadata(row))
        set_state(processed=min(offset+len(batch),len(video_ids)),total=len(video_ids)); console_progress("YouTube API metadata | ")
    return rows


def metadata_via_youtube_api(sources):
    if not CFG.get("use_youtube_data_api",True) or not (str(CFG.get("youtube_data_api_key","")).strip() or load_youtube_api_key()): return None
    all_ids=[]; non_api=[]
    for source in sources:
        kind,_=youtube_source_descriptor(source)
        if kind=="other": non_api.append(source); continue
        try: all_ids.extend(youtube_video_ids_for_source(source))
        except Exception as e:
            log(f"YouTube Data API listing failed {source}: {e}"); non_api.append(source)
    seen=set(); ids=[]
    for vid in all_ids:
        if vid not in seen: seen.add(vid); ids.append(vid)
    if not ids: return None
    set_state(phase="YouTube Data API Metadata",total=len(ids),processed=0,listed=len(ids))
    return youtube_api_video_metadata(ids),non_api

def flat_list(source):
    args = common_args() + ["--skip-download","--flat-playlist","--dump-json",source]
    rc,out,err = run(args,timeout=300)
    rows=[]
    for line in out.splitlines():
        try:
            d=json.loads(line)
        except Exception:
            continue
        vid=d.get("id")
        if not vid: continue
        u=d.get("webpage_url") or d.get("url") or ""
        if not str(u).startswith("http"):
            if "youtube.com" in source.lower() or "youtu.be" in source.lower():
                u=f"https://www.youtube.com/watch?v={vid}"
            else:
                u=source
        rows.append({
            "id":vid,"url":u,"title":d.get("title") or "",
            "channel":d.get("channel") or d.get("uploader") or "",
            "upload_date":d.get("upload_date") or "",
            "platform":detect_platform(d)
        })
    if rc != 0 and not rows:
        log(f"List failed {source}: {err[-1000:]}")
    return rows


def choose_preferred_caption(meta):
    """
    Choose exactly ONE caption source:
    1) manual English
    2) auto English
    3) manual Hindi
    4) auto Hindi
    """
    def pick_lang(mapping,prefs):
        if not isinstance(mapping,dict):
            return ""
        keys=list(mapping.keys())
        for p in prefs:
            if p in keys:
                return p
        for pref in prefs:
            base=pref.split("-")[0].lower()
            for k in keys:
                if str(k).lower().startswith(base):
                    return k
        return ""

    subs=meta.get("subtitles") or {}
    autos=meta.get("automatic_captions") or {}

    enprefs=["en","en-US","en-GB","en-orig"]
    hiprefs=CFG.get("fallback_transcript_languages",["hi","hi-orig"])

    lang=pick_lang(subs,enprefs)
    if lang: return "manual",lang,"en"
    lang=pick_lang(autos,enprefs)
    if lang: return "auto",lang,"en"
    lang=pick_lang(subs,hiprefs)
    if lang: return "manual",lang,"hi"
    lang=pick_lang(autos,hiprefs)
    if lang: return "auto",lang,"hi"
    return "","",""

def detail_one(item):
    err=""
    for attempt in range(int(CFG.get("max_retries",3))):
        args = common_args()+["--skip-download","--no-playlist","--dump-single-json",item["url"]]
        rc,out,err,_cookie_retry = run_with_browser_cookie_fallback(
            args,str(item["url"]),CFG,lambda retry_args: run(retry_args)
        )
        try:
            d=json.loads(out)
        except Exception:
            d=None
        if d:
            sub_source,sub_lang,sub_base_lang=choose_preferred_caption(d)
            record={
                "id":d.get("id") or item["id"],
                "url":d.get("webpage_url") or item["url"],
                "title":d.get("title") or item["title"],
                "channel":d.get("channel") or d.get("uploader") or item["channel"],
                "upload_date":d.get("upload_date") or item["upload_date"],
                "description":d.get("description") or "",
                "platform":detect_platform(d),
                "youtube_tags":d.get("tags") or [],
                "source_categories":d.get("categories") or [],
                "source_category":((d.get("categories") or [""])[0] if isinstance(d.get("categories") or [],list) and (d.get("categories") or []) else ""),
                "thumbnail_url":d.get("thumbnail") or "",
                "subtitle_source":sub_source,
                "subtitle_lang":sub_lang,
                "subtitle_base_lang":sub_base_lang
            }
            return attach_canonical_metadata(record,raw=d), ""
        time.sleep(1+attempt*2)
    return None, (err or "Unknown extraction failure")[-1000:]

def normalize_date(v):
    if not v: return ""
    try:
        return datetime.strptime(v,"%Y%m%d").strftime("%Y-%m-%d")
    except Exception:
        return v

def save_metadata(items):
    con=db_connect(); now=datetime.now().isoformat(timespec="seconds")
    for d in items:
        con.execute("""
          INSERT INTO videos(video_id,platform,url,original_title,clean_title,channel,upload_date,description,
                             first_seen,last_seen,last_error,subtitle_source,subtitle_lang,subtitle_base_lang)
          VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)
          ON CONFLICT(video_id) DO UPDATE SET
            platform=excluded.platform,url=excluded.url,original_title=excluded.original_title,
            channel=excluded.channel,upload_date=excluded.upload_date,description=excluded.description,
            last_seen=excluded.last_seen,last_error=excluded.last_error,
            subtitle_source=CASE WHEN excluded.subtitle_source<>'' THEN excluded.subtitle_source ELSE videos.subtitle_source END,
            subtitle_lang=CASE WHEN excluded.subtitle_lang<>'' THEN excluded.subtitle_lang ELSE videos.subtitle_lang END,
            subtitle_base_lang=CASE WHEN excluded.subtitle_base_lang<>'' THEN excluded.subtitle_base_lang ELSE videos.subtitle_base_lang END
        """,(
            d["id"],d.get("platform",""),d["url"],d.get("title",""),safe_name(d.get("title","")),
            d.get("channel",""),normalize_date(d.get("upload_date","")),d.get("description",""),
            now,now,d.get("error",""),d.get("subtitle_source",""),d.get("subtitle_lang",""),d.get("subtitle_base_lang","")
        ))
        if d.get("metadata_source"):
            source_categories=d.get("source_categories") or []
            if isinstance(source_categories,str): source_categories=[source_categories]
            source_category=str(d.get("source_category") or d.get("youtube_category_name") or (source_categories[0] if source_categories else ""))
            con.execute("""UPDATE videos SET youtube_tags=?,youtube_category_id=?,youtube_category_name=?,
               source_category_id=?,source_category=?,source_categories_json=?,thumbnail_url=?,duration_iso=?,
               view_count=?,like_count=?,comment_count=?,metadata_source=? WHERE video_id=?""",(
                json.dumps(d.get("youtube_tags") or [],ensure_ascii=False),d.get("youtube_category_id",""),d.get("youtube_category_name",""),
                d.get("source_category_id") or d.get("youtube_category_id","") ,source_category,json.dumps(source_categories,ensure_ascii=False),d.get("thumbnail_url",""),d.get("duration_iso",""),
                int(d.get("view_count") or 0),int(d.get("like_count") or 0),int(d.get("comment_count") or 0),d.get("metadata_source",""),d["id"]))
        persist_record_canonical_metadata(con,d)
    con.commit(); con.close()


def phase7_migrate_existing_library_metadata(dry_run=True, force=False, limit=0, fetch_missing=False):
    """Run the Phase 7 existing-library canonical metadata migration.

    The normal default is a read-only dry run.  When ``fetch_missing`` is true,
    the only online fallback used is ``extract_single_source_metadata()``, which
    invokes yt-dlp with ``--skip-download`` and therefore never downloads media.
    A real migration creates a transaction-consistent SQLite backup first and
    writes a JSON audit report under maintenance/migrations.
    """
    stamp=time.strftime("%Y%m%d-%H%M%S")
    migration_dir=BASE/"maintenance"/"migrations"
    migration_dir.mkdir(parents=True,exist_ok=True)
    backup_path=None if dry_run else migration_dir/f"video_library_pre_phase7_{stamp}.db"

    def metadata_only_fetcher(video_id,url):
        if not fetch_missing or not str(url or "").strip():
            return None
        record,err=extract_single_source_metadata(str(url))
        if not record:
            raise RuntimeError(err or f"metadata-only refresh failed for {video_id}")
        return record

    con=db_connect()
    try:
        report=run_existing_library_metadata_migration(
            con,
            dry_run=bool(dry_run),
            force=bool(force),
            limit=max(0,int(limit or 0)),
            metadata_fetcher=metadata_only_fetcher if fetch_missing else None,
            backup_path=backup_path,
        )
    finally:
        con.close()
    report_path=migration_dir/f"phase7_metadata_migration_{'dry_run' if dry_run else 'apply'}_{stamp}.json"
    report_path.write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding="utf-8")
    report["report_path"]=str(report_path)
    return report


def get_chatgpt_title_for_video(video_id):
    # Prefer canonical summary JSON by Video ID.
    folder=locate_existing_folder(video_id)
    if folder:
        p=canonical_chatgpt_summary_path(folder,video_id)
        if p.exists():
            try:
                obj=json.loads(p.read_text(encoding="utf-8"))
                title=str(
                    obj.get("meaningful_title")
                    or obj.get("imported_title")
                    or ""
                ).strip()
                if title:
                    return title
            except Exception:
                pass

    # Fallback to identity_json in SQLite.
    con=db_connect()
    row=con.execute(
        "SELECT identity_json FROM videos WHERE video_id=?",
        (video_id,)
    ).fetchone()
    con.close()
    if row and row[0]:
        try:
            ident=json.loads(row[0])
            return str(ident.get("meaningful_title") or "").strip()
        except Exception:
            pass

    return ""




