def rule_tags(title):
    t=(title or "").lower()
    found=[]
    for ent in CFG.get("known_entities",[]):
        if re.search(r'(?<!\w)'+re.escape(ent.lower())+r'(?!\w)',t):
            found.append(ent)
    return sorted(set(found))

def llm_generate(prompt,timeout=None):
    if not CFG.get("ai_enabled",True):
        return None

    if not ollama_server_ok():
        if not start_ollama_server():
            log("LLM skipped: Ollama server is not running")
            return None

    timeout = int(timeout or CFG.get("ollama_timeout_seconds",600))
    retries = max(1, int(CFG.get("ollama_retries",2)))

    payload=json.dumps({
        "model":CFG.get("ollama_model","qwen2.5:7b"),
        "prompt":prompt,
        "stream":False,
        "format":"json",
        "keep_alive":CFG.get("ollama_keep_alive","30m"),
        "options":{
            "temperature":0.1,
            "num_predict":int(CFG.get("ollama_num_predict",1400))
        }
    }).encode("utf-8")

    last_error=None
    for attempt in range(1,retries+1):
        req=urllib.request.Request(
            CFG.get("ollama_url"),
            data=payload,
            headers={"Content-Type":"application/json"}
        )
        try:
            set_state(
                current_status=f"OLLAMA PROCESSING ({attempt}/{retries})",
                message=f"Waiting for local LLM response; timeout {timeout}s"
            )
            started=time.time()
            with urllib.request.urlopen(req,timeout=timeout) as r:
                body=json.loads(r.read().decode("utf-8"))
            elapsed=time.time()-started
            log(f"LLM call completed in {elapsed:.1f}s")
            txt=body.get("response","").strip()
            return json.loads(txt)
        except Exception as e:
            last_error=e
            log(f"LLM attempt {attempt}/{retries} failed: {e}")
            set_state(
                current_status=f"OLLAMA RETRY {attempt}/{retries}",
                message=f"LLM attempt failed: {e}"
            )
            if attempt < retries:
                time.sleep(2*attempt)

    log(f"LLM exhausted retries: {last_error}")
    return None


def ai_enrich_title(title):
    rules=rule_tags(title)
    cats=", ".join(CFG.get("categories",[]))
    prompt=f"""Return only valid JSON.
Video title:
{title}

Allowed category must be exactly one of:
{cats}

Return:
{{
 "clean_title":"Natural concise ENGLISH title. If the source is Hindi, Hinglish, Punjabi or mixed language, translate it to clear English. Remove hashtags, emojis, decorative punctuation, channel/person promo suffixes, ALL-CAPS clickbait, repeated words, and claims like MUST WATCH when they add no topic meaning. Preserve the actual subject and important numbers.",
 "category":"one allowed category",
 "subcategory":"short useful subcategory",
 "main_topic":"main entity/topic",
 "tags":["specific useful tags"],
 "confidence":0.0,
 "needs_review":false
}}

The clean_title is used as the Windows folder and video filename, so it must be concise, descriptive, English and filename-safe.
Known rule-detected entities to retain as tags when relevant:
{rules}
"""
    d=llm_generate(prompt)
    if not d:
        return {
            "clean_title":safe_name(title),"category":"Other","subcategory":"",
            "main_topic":rules[0] if rules else "","tags":rules,
            "confidence":0.0,"needs_review":True
        }
    tags=d.get("tags") or []
    if isinstance(tags,str):
        tags=[x.strip() for x in tags.split(",") if x.strip()]
    tags=sorted(set([str(x).strip() for x in tags if str(x).strip()]+rules),key=str.lower)
    return {
        "clean_title":safe_name(d.get("clean_title") or title),
        "category":d.get("category") if d.get("category") in CFG.get("categories",[]) else "Other",
        "subcategory":str(d.get("subcategory") or ""),
        "main_topic":str(d.get("main_topic") or ""),
        "tags":tags,
        "confidence":float(d.get("confidence") or 0),
        "needs_review":bool(d.get("needs_review",False))
    }

def enrich_all_missing():
    """
    Option 3: AI enrichment/resume for the whole library.
    Uses cached transcripts and cached AI results whenever possible.
    """
    old_use_llm=RUNTIME.get("use_llm",True)
    old_mode=RUNTIME.get("resume_mode","smart")
    try:
        RUNTIME["use_llm"]=True
        RUNTIME["resume_mode"]="smart"

        con=db_connect()
        total=con.execute("SELECT COUNT(*) FROM videos").fetchone()[0]
        con.close()

        if total==0:
            print("\nOption 3: no videos are present in video_library.db.")
            print("Run option 2 (metadata scan) first.")
            return

        print(f"\nOption 3: AI enrichment for {total} video(s)")
        print("Cached transcripts and unchanged AI results will be reused.")
        print("Missing transcripts will be fetched first.\n")

        reset_progress_state("AI Enrichment")
        prepare_transcripts_all()
        name_videos_from_tmp_transcripts()
        export_csv()

        s=snapshot()
        console_newline()
        print("\nAI enrichment complete.")
        print(f"Processed : {s.get('processed',0)}")
        print(f"AI done   : {s.get('ai_done',0)}")
        print(f"Failed    : {s.get('failed',0)}")
        print(f"CSV       : {EXPORT}")
    finally:
        RUNTIME["use_llm"]=old_use_llm
        RUNTIME["resume_mode"]=old_mode


def parse_srt_sections(srt_text):
    """Parse standard SRT and malformed/inline SRT cues reliably."""
    txt=srt_text.replace("\r\n","\n").replace("\r","\n")

    # Standard SRT blocks first.
    standard=re.compile(
        r'(?ms)^\s*(?:\d+\s*\n)?'
        r'(\d{2}:\d{2}:\d{2}[,.]\d{3})\s*-->\s*'
        r'(\d{2}:\d{2}:\d{2}[,.]\d{3})\s*\n'
        r'(.*?)(?=\n{2,}|\Z)'
    )
    blocks=[]
    for m in standard.finditer(txt):
        body=re.sub(r'<[^>]+>',' ',m.group(3))
        body=re.sub(r'\s+',' ',html.unescape(body)).strip()
        if body:
            blocks.append((m.group(1).replace(".",","),m.group(2).replace(".",","),body))
    if blocks:
        return blocks

    # Fallback for timestamps that appear inline with transcript text.
    inline=re.compile(
        r'(?s)(?:^|\s)(?:\d+\s+)?'
        r'(\d{2}:\d{2}:\d{2}[,.]\d{3})\s*-->\s*'
        r'(\d{2}:\d{2}:\d{2}[,.]\d{3})\s*'
        r'(.*?)(?=(?:\s+\d+\s+)?\d{2}:\d{2}:\d{2}[,.]\d{3}\s*-->|$)'
    )
    for m in inline.finditer(txt):
        body=re.sub(r'<[^>]+>',' ',m.group(3))
        body=re.sub(r'\s+',' ',html.unescape(body)).strip()
        if body:
            blocks.append((m.group(1).replace(".",","),m.group(2).replace(".",","),body))
    if blocks:
        return blocks

    # Last-resort plain transcript.
    body=re.sub(r'(?m)^\s*\d+\s*$',' ',txt)
    body=re.sub(r'(?:^|\s)\d+\s+\d{2}:\d{2}:\d{2}[,.]\d{3}\s*-->\s*\d{2}:\d{2}:\d{2}[,.]\d{3}',' ',body)
    body=re.sub(r'\d{2}:\d{2}:\d{2}[,.]\d{3}\s*-->\s*\d{2}:\d{2}:\d{2}[,.]\d{3}',' ',body)
    body=re.sub(r'<[^>]+>',' ',body)
    body=re.sub(r'\s+',' ',html.unescape(body)).strip()
    return [("00:00:00,000","00:00:00,000",body)] if body else []

def subtitle_cleanup(text):
    t=text.replace("\r\n","\n").replace("\r","\n")
    t=re.sub(r'(?mi)^\s*WEBVTT.*$',' ',t)
    t=re.sub(r'(?m)^\s*\d+\s*$',' ',t)
    t=re.sub(r'(?<!\d)\d+\s+\d{1,2}:\d{2}:\d{2}[,.]\d{3}\s*-->\s*\d{1,2}:\d{2}:\d{2}[,.]\d{3}',' ',t)
    t=re.sub(r'\d{1,2}:\d{2}:\d{2}[,.]\d{3}\s*-->\s*\d{1,2}:\d{2}:\d{2}[,.]\d{3}',' ',t)
    t=re.sub(r'\d{1,2}:\d{2}[,.]\d{3}\s*-->\s*\d{1,2}:\d{2}[,.]\d{3}',' ',t)
    t=re.sub(r'<[^>]+>',' ',t)
    t=html.unescape(t)
    t=re.sub(r'\[(?:music|applause|laughter|foreign)\]',' ',t,flags=re.I)
    t=re.sub(r'\s+',' ',t).strip()
    return t

def sec(ts):
    try:
        h,m,sms=ts.replace(",",".").split(":")
        return int(h)*3600+int(m)*60+float(sms)
    except Exception: return 0

def hms(seconds):
    seconds=int(seconds)
    return f"{seconds//3600:02d}:{(seconds%3600)//60:02d}:{seconds%60:02d}"

def transcript_chunks(blocks,target_seconds=240):
    if not blocks: return []
    chunks=[]; cur=[]; start=sec(blocks[0][0]); end=start
    for b in blocks:
        bs,be=sec(b[0]),sec(b[1])
        if cur and be-start>target_seconds:
            chunks.append({"start":hms(start),"end":hms(end),"text":" ".join(x[2] for x in cur)})
            cur=[]; start=bs
        cur.append(b); end=be
    if cur:
        chunks.append({"start":hms(start),"end":hms(end),"text":" ".join(x[2] for x in cur)})
    return chunks



def deterministic_content_title(original_title, transcript_text):
    """Fallback transcript-based title using concrete foods/herbs/entities."""
    t=(transcript_text or "").lower()
    entity_map=[
        ("cumin","Cumin"),("jeera","Cumin"),("carom seeds","Carom Seeds"),
        ("carom","Carom Seeds"),("ajwain","Carom Seeds"),("fennel","Fennel"),
        ("saunf","Fennel"),("fenugreek","Fenugreek"),("methi","Fenugreek"),
        ("ceylon cinnamon","Ceylon Cinnamon"),("cinnamon","Cinnamon"),
        ("coriander","Coriander"),("dhania","Coriander"),("turmeric","Turmeric"),
        ("haldi","Turmeric"),("neem","Neem"),("tulsi","Tulsi"),
        ("holy basil","Tulsi"),("ashwagandha","Ashwagandha"),("amla","Amla"),
        ("giloy","Giloy"),("moringa","Moringa"),("kalonji","Kalonji"),
        ("nigella","Kalonji"),("kokum","Kokum"),("ginger","Ginger"),
        ("garlic","Garlic"),("lemon","Lemon"),("bitter gourd","Bitter Gourd"),
        ("karela","Bitter Gourd"),("curd","Curd"),("yogurt","Yogurt"),
        ("ghee","Ghee"),("milk","Milk"),("paneer","Paneer"),("sprouts","Sprouts"),
        ("peanut","Peanut"),("almond","Almond"),("walnut","Walnut"),
        ("chia","Chia Seeds"),("flax","Flax Seeds"),("sesame","Sesame Seeds"),
        ("apple cider vinegar","Apple Cider Vinegar")
    ]
    hits=[]
    for key,label in entity_map:
        m=re.search(r'(?<!\w)'+re.escape(key)+r'(?!\w)',t)
        if m: hits.append((m.start(),label))
    found=[]
    for _,label in sorted(hits):
        if label not in found: found.append(label)

    source=(original_title or "").lower()
    list_video=bool(re.search(r'\b\d+\s+.*\b(?:foods?|drinks?|herbs?|seeds?|products?|remedies)\b',source))
    weight=any(x in t for x in ["belly fat","weight loss","lose weight","burn fat","fat loss","obesity"])

    if found:
        names=", ".join(found[:5] if list_video else found[:4])
        if weight: return safe_name(f"{names} for Weight Management")
        return safe_name(names if list_video else f"{names} Health Guide")
    if weight: return "Foods and Remedies for Weight Management"
    return safe_name(original_title)


def ai_content_identity(original_title, transcript_text):
    """Create final English filename from actual transcript subjects."""
    sample=subtitle_cleanup((transcript_text or "")[:22000])
    prompt=f"""Return only valid JSON.

SOURCE TITLE:
{original_title}

CLEAN TRANSCRIPT EXCERPT:
{sample}

Create the FINAL ENGLISH FILE/FOLDER NAME from what the video actually discusses.

Rules:
- Do not merely rewrite/translate the source title.
- Extract concrete subjects from the transcript.
- For titles such as "5 Foods", "7 Drinks", "4 Seeds", "Best Herbs",
  "Products" or "Remedies", identify the ACTUAL named items in the transcript.
- Put the most important actual item names in meaningful_title when practical.
- Example: "5 Amazing Foods that Melt Belly Fat" should become something like
  "Cumin, Fennel, Fenugreek, Cinnamon and Amla for Weight Management" ONLY if
  those are actually the principal items discussed.
- Do not put an advertised/sponsored product in the filename unless the video
  is mainly about that product.
- Translate Hindi/Hinglish/Punjabi/other languages to natural English.
- Remove channel names, hashtags, emojis, hype, guarantees and clickbait.
- Prefer <= 120 characters.
- Never invent an item absent from the transcript.

Return:
{{
 "meaningful_title":"specific English filename using actual transcript subjects",
 "title_entities":["principal concrete names that belong in the filename"],
 "main_topic":"specific main subject",
 "summary":"2 to 4 sentence factual overview",
 "category":"broad category",
 "subcategory":"specific subcategory",
 "tags":["specific useful transcript-supported tags"]
}}
"""
    d=llm_generate(prompt)
    fallback=deterministic_content_title(original_title,transcript_text)
    if not d:
        return {"meaningful_title":fallback,"title_entities":[],"main_topic":"",
                "summary":"","category":"","subcategory":"","tags":[]}

    candidate=safe_name(d.get("meaningful_title") or "")
    source_clean=safe_name(original_title)
    entities=d.get("title_entities") or []
    if isinstance(entities,str):
        entities=[x.strip() for x in entities.split(",") if x.strip()]
    list_video=bool(re.search(r'(?i)\b\d+\s+.*\b(?:foods?|drinks?|herbs?|seeds?|products?|remedies)\b',
                              original_title or ""))
    vague=bool(re.search(r'(?i)\b(amazing|must try|shocking|surprise|melt belly fat|must watch|result will amaze)\b',
                         candidate))
    if not candidate or candidate.lower()==source_clean.lower() or vague or (list_video and not entities):
        candidate=fallback
    if len(candidate)>120:
        candidate=candidate[:120].rsplit(" ",1)[0].rstrip(" ,-_")
    d["meaningful_title"]=safe_name(candidate)
    d["title_entities"]=entities
    return d


def semantic_chapter_groups(blocks,max_seconds=None,max_chars=None):
    if not blocks:
        return []
    max_seconds=int(max_seconds or CFG.get("chapter_max_seconds",120))
    max_chars=int(max_chars or CFG.get("chapter_max_chars",3200))
    groups=[]; cur=[]; chars=0; start=sec(blocks[0][0]); end=start
    for b in blocks:
        bs,be=sec(b[0]),sec(b[1])
        cleaned=subtitle_cleanup(b[2])
        if not cleaned:
            continue
        if cur and ((be-start)>max_seconds or (chars+len(cleaned))>max_chars):
            groups.append({"start":hms(start),"end":hms(end),"text":" ".join(x[2] for x in cur)})
            cur=[]; chars=0; start=bs
        cur.append((b[0],b[1],cleaned)); chars+=len(cleaned)+1; end=be
    if cur:
        groups.append({"start":hms(start),"end":hms(end),"text":" ".join(x[2] for x in cur)})
    return groups

def ai_detailed_transcript(srt_text,title):
    blocks=parse_srt_sections(srt_text)
    groups=semantic_chapter_groups(blocks)
    chapters=[]
    for idx,c in enumerate(groups,1):
        cleaned=subtitle_cleanup(c["text"])
        prompt=f"""Return only valid JSON.

Video title:
{title}

Timestamp range:
{c['start']} to {c['end']}

Clean transcript:
{cleaned}

Create ONE coherent structured chapter.

Rules:
- Do not output raw transcript text.
- Do not use generic headings like Transcript Section, Chapter, or Section.
- Use a specific heading based on the actual topic in this range.
- Keep exact supplied timestamps.
- Treat health/scientific statements as speaker claims, not verified facts.

Return:
{{
 "chapter_title":"specific meaningful heading",
 "start":"{c['start']}",
 "end":"{c['end']}",
 "overview":"2 to 5 concise sentences",
 "topics":["specific subtopics"],
 "ingredients_or_entities":["explicit ingredients, people, products, medicines, devices or places"],
 "instructions":["explicit steps, quantities, timing or preparation instructions"],
 "claims":["important claims made by the speaker"],
 "key_points":["3 to 7 concise takeaways"],
 "tags":["specific tags"]
}}
"""
        d=llm_generate(prompt)
        if not d:
            set_state(
                current_status="LLM FALLBACK",
                message=f"LLM timed out or failed for {c['start']} - {c['end']}; using structured fallback."
            )
            words=cleaned.split()
            chapters.append({
                "chapter_title":f"Section {idx}",
                "start":c["start"],"end":c["end"],
                "overview":" ".join(words[:90]),
                "topics":[],"ingredients_or_entities":[],
                "instructions":[],"claims":[],"key_points":[],"tags":[]
            })
        else:
            d["start"]=c["start"]; d["end"]=c["end"]
            h=str(d.get("chapter_title") or "").strip()
            if not h or h.lower() in ("transcript section","chapter","section"):
                h=f"Section {idx}"
            d["chapter_title"]=h
            chapters.append(d)
    return chapters


def temp_paths(video_id):
    _short=False
    try:
        con=db_connect()
        try:
            _r=con.execute(
                "SELECT url,duration_seconds,COALESCE(platform,'') FROM videos WHERE video_id=?",
                (str(video_id),)
            ).fetchone()
        except sqlite3.OperationalError:
            # Older isolated test databases may not yet have `platform`.
            _r=con.execute(
                "SELECT url,duration_seconds FROM videos WHERE video_id=?",
                (str(video_id),)
            ).fetchone()
        con.close()
        if _r and not (len(_r)>2 and str(_r[2]).lower()=='local'):
            _short=is_short_video_record(video_id,_r[0],_r[1])
    except Exception:
        _short=False
    d=(temp_short_video_root() if _short else temp_transcript_root())/str(video_id)
    return {
        "dir":d,
        "vtt":d/f"{video_id}.en.vtt",
        "timestamped":d/f"{video_id}.timestamped.txt",
        "clean":d/f"{video_id}.clean.txt",
        "identity":d/f"{video_id}.identity.json",
        "chapters":d/f"{video_id}.chapters.json"
    }

def timestamp_to_seconds_loose(ts):
    ts=ts.strip().replace(",",".")
    parts=ts.split(":")
    try:
        if len(parts)==3:
            h,m,s=parts
            return int(h)*3600+int(m)*60+float(s)
        if len(parts)==2:
            m,s=parts
            return int(m)*60+float(s)
    except Exception:
        pass
    return 0.0

def format_hms_short(seconds):
    seconds=max(0,int(seconds))
    return f"{seconds//3600:02d}:{(seconds%3600)//60:02d}:{seconds%60:02d}"

def vtt_to_timestamped_transcript(vtt_text, marker_interval=15):
    """Convert WebVTT to clean timestamped transcript, handling YouTube cue variants."""
    t=vtt_text.replace("\r\n","\n").replace("\r","\n")
    # Remove BOM/header and NOTE/STYLE/REGION blocks.
    t=t.lstrip("\ufeff")
    lines=t.splitlines()
    cues=[]
    i=0

    # Handles HH:MM:SS.mmm and MM:SS.mmm plus optional VTT settings after end time.
    time_re=re.compile(
        r'(?P<s>(?:\d{1,2}:)?\d{1,2}:\d{2}[.,]\d{3})\s*-->\s*'
        r'(?P<e>(?:\d{1,2}:)?\d{1,2}:\d{2}[.,]\d{3})(?:\s+.*)?$'
    )

    while i < len(lines):
        line=lines[i].strip()
        if not line or line.upper()=="WEBVTT":
            i+=1; continue
        if line.startswith(("NOTE","STYLE","REGION")):
            i+=1
            while i<len(lines) and lines[i].strip():
                i+=1
            continue

        m=time_re.search(line)
        # Sometimes cue identifier precedes timestamp line.
        if not m and i+1<len(lines):
            m2=time_re.search(lines[i+1].strip())
            if m2:
                i+=1
                m=m2
                line=lines[i].strip()

        if not m:
            i+=1; continue

        start=timestamp_to_seconds_loose(m.group("s"))
        i+=1
        body=[]
        while i<len(lines):
            cur=lines[i]
            if not cur.strip():
                break
            if time_re.search(cur.strip()):
                break
            x=re.sub(r'<[^>]+>',' ',cur)
            x=re.sub(r'&nbsp;',' ',x)
            x=html.unescape(x)
            x=re.sub(r'\s+',' ',x).strip()
            if x and not re.match(r'^(?:align:|position:|line:)',x,re.I):
                body.append(x)
            i+=1

        phrase=" ".join(body).strip()
        if phrase:
            cues.append((start,phrase))
        i+=1

    # Fallback: strip timestamps and preserve text if cue parser still found nothing.
    if not cues:
        plain=[]
        for line in lines:
            x=line.strip()
            if not x or x.upper()=="WEBVTT" or time_re.search(x):
                continue
            if re.match(r'^\d+$',x):
                continue
            x=re.sub(r'<[^>]+>',' ',x)
            x=html.unescape(x)
            x=re.sub(r'\s+',' ',x).strip()
            if x:
                plain.append(x)
        if plain:
            return "[00:00:00] "+" ".join(plain)

    # Deduplicate progressive/rolling YouTube captions. Compare each cue with
    # the previous FULL cue (not with the already-emitted delta), otherwise a
    # sequence such as "Today we" -> "Today we will make" -> "Today we will
    # make oats" reintroduces duplicated words on the third cue.
    def _caption_words(value):
        return re.findall(r"\S+",re.sub(r"\s+"," ",str(value or "")).strip())
    def _norm_caption_token(value):
        return re.sub(r"^\W+|\W+$","",str(value or "")).casefold()
    def _rolling_delta(previous_full,current_full):
        prev=_caption_words(previous_full);cur=_caption_words(current_full)
        if not cur:return ""
        if not prev:return " ".join(cur)
        prev_norm=[_norm_caption_token(x) for x in prev]
        cur_norm=[_norm_caption_token(x) for x in cur]
        if cur_norm==prev_norm:return ""
        # A shorter cue that is wholly contained in the previous display is a
        # rendering reset/duplicate, not new speech.
        if len(cur_norm)<=len(prev_norm):
            for start in range(0,len(prev_norm)-len(cur_norm)+1):
                if prev_norm[start:start+len(cur_norm)]==cur_norm:
                    return ""
        overlap=0
        for size in range(min(len(prev_norm),len(cur_norm)),0,-1):
            if prev_norm[-size:]==cur_norm[:size]:
                overlap=size;break
        return " ".join(cur[overlap:]).strip()

    cleaned=[]
    previous_full=""
    for st,phrase in cues:
        full_phrase=re.sub(r'\s+',' ',phrase).strip()
        if not full_phrase:continue
        delta=_rolling_delta(previous_full,full_phrase)
        previous_full=full_phrase
        if delta:
            cleaned.append((st,delta))

    out=[]
    last_marker=-999
    for st,phrase in cleaned:
        if not out or st-last_marker>=marker_interval:
            out.append(f"[{format_hms_short(st)}] {phrase}")
            last_marker=st
        else:
            out[-1]+=" "+phrase
    return "\n".join(out).strip()

def timestamped_to_clean(timestamped):
    return re.sub(r'\[\d{2}:\d{2}:\d{2}\]\s*',' ',timestamped).replace("\n"," ").strip()


def transcript_has_useful_speech(text):
    """
    True only when a transcript/caption file contains real spoken words.
    Music/applause/noise-only captions are treated as no usable transcript.
    """
    raw=str(text or "")
    if not raw.strip():
        return False
    cleaned=timestamped_to_clean(raw)
    cleaned=re.sub(r'<[^>]+>',' ',cleaned)
    cleaned=re.sub(r'(?i)\b(webvtt|kind:|language:)\b',' ',cleaned)
    cleaned=re.sub(r'(?i)\[(music|applause|laughter|silence|noise|sound|instrumental|song|singing|cheering)\]',' ',cleaned)
    cleaned=re.sub(r'(?i)\((music|applause|laughter|silence|noise|sound|instrumental|song|singing|cheering)\)',' ',cleaned)
    words=re.findall(r"[A-Za-zÀ-ÿ\u0900-\u097F]{2,}",cleaned)
    return len(words)>=8



def _subtitle_language_family(path, video_id=""):
    """Return normalized subtitle language family from a subtitle filename."""
    name=Path(path).name.lower()
    stem=name[:-4] if name.endswith(('.vtt','.srt')) else name
    vid=str(video_id or '').lower().strip()
    if vid and stem.startswith(vid+'.'):
        suffix=stem[len(vid)+1:]
    else:
        suffix=stem
    parts=[p for p in re.split(r'[._-]+',suffix) if p]
    if any(p=='en' for p in parts) or re.search(r'(^|[._-])en(?:$|[._-])',name):
        return 'en'
    for code in (CFG.get('fallback_transcript_languages') or ['hi','hi-orig']):
        base=str(code or '').split('-')[0].lower().strip()
        if base and (base in parts or re.search(rf'(^|[._-]){re.escape(base)}(?:$|[._-])',name)):
            return base
    # Best-effort two-letter language token.
    for p in parts:
        if re.fullmatch(r'[a-z]{2}',p):
            return p
    return 'unknown'


def _vtt_candidate_score(path, video_id="", preferred_path=None):
    """Score VTT candidates by selected-source preference, language and health; never alphabetically."""
    p=Path(path)
    try:
        raw=p.read_text(encoding='utf-8',errors='replace')
        timestamped=vtt_to_timestamped_transcript(raw)
        clean=timestamped_to_clean(timestamped)
        if not transcript_has_useful_speech(clean):
            return None
        words=len(re.findall(r"[A-Za-zÀ-ÿ\u0900-\u097F]{2,}",clean))
        lang=_subtitle_language_family(p,video_id)
        name=p.name.lower()
        score=0
        if preferred_path:
            try:
                if p.resolve()==Path(preferred_path).resolve():
                    score+=100
            except Exception:
                pass
        if lang=='en':
            score+=5000
            if '.en-orig.' in name or name.endswith('.en-orig.vtt'):
                score+=350
            elif re.search(r'\.en\.vtt$',name):
                score+=300
            elif re.search(r'\.en[-_.](us|gb|ca|au|ie)\.vtt$',name):
                score+=250
        elif lang!='unknown':
            score+=2000
        # Health/content tie-breakers. Cap so verbosity cannot beat English-first language priority.
        score+=min(words,5000)/20.0
        reason_codes=[]
        grade=''
        try:
            health=chatgpt_transcript_health(timestamped,0,{}) if 'chatgpt_transcript_health' in globals() else {}
            grade=str(health.get('grade') or '')
            reason_codes=list(health.get('reason_codes') or [])
            score+= {'A':500,'B':350,'C':150,'D':-200,'F':-1000}.get(grade,0)
            penalties={
                'SEVERE_TIMESTAMP_CORRUPTION':500,
                'TIMESTAMP_PARSE_WEAK':250,
                'HIGH_DUPLICATION':250,
                'LOW_SPEECH_DENSITY':200,
                'TRANSCRIPT_TOO_SHORT':300,
                'TRANSCRIPT_MISSING':2000,
            }
            score-=sum(penalties.get(code,0) for code in reason_codes)
        except Exception:
            pass
        try: score+=min(p.stat().st_size,2_000_000)/100000.0
        except Exception: pass
        return {'path':p,'score':score,'lang':lang,'timestamped':timestamped,'clean':clean,'words':words,'grade':grade,'reason_codes':reason_codes}
    except Exception:
        return None


def select_best_vtt_candidate(paths, video_id="", preferred_path=None):
    """Select the best usable VTT without relying on filename sort order."""
    scored=[]
    seen=set()
    for candidate in paths or []:
        try:
            p=Path(candidate)
            key=str(p.resolve())
        except Exception:
            p=Path(candidate); key=str(p)
        if key in seen or not p.is_file() or p.suffix.lower()!='.vtt':
            continue
        seen.add(key)
        item=_vtt_candidate_score(p,video_id,preferred_path)
        if item:
            scored.append(item)
    if not scored:
        return None
    # Score first; health richness and mtime are deterministic tie-breakers. Filename is never a rank signal.
    scored.sort(key=lambda x:(x['score'],x['words'],x['path'].stat().st_mtime if x['path'].exists() else 0),reverse=True)
    return scored[0]


def canonicalize_video_subtitle_artifacts(folder, video_id, preferred_vtt=None, update_db=True):
    """
    Enforce the persistent per-video contract in FINAL _data:
      1 best VTT + 1 SRT + 1 transcript, all derived from the same winning VTT.

    Safety rule: inferior files are deleted only after all three canonical outputs
    are written and re-validated. On any failure, existing files are left intact.
    """
    folder=Path(folder)
    if not folder.exists():
        return {'ok':False,'changed':False,'reason':'video folder missing'}
    data=support_dir(folder,create=True)
    candidates=[]
    # Existing final-folder variants.
    for p in folder.rglob('*.vtt'):
        if p.is_file() and 'live_chat' not in p.name.lower():
            candidates.append(p)
    # The selected/temporary source may live outside the final folder.
    if preferred_vtt:
        pp=Path(preferred_vtt)
        if pp.is_file() and pp.suffix.lower()=='.vtt':
            candidates.append(pp)

    winner=select_best_vtt_candidate(candidates,video_id,preferred_vtt)
    if not winner:
        return {'ok':False,'changed':False,'reason':'no usable VTT candidate; nothing deleted'}

    lang='en' if winner['lang']=='en' else (winner['lang'] if winner['lang']!='unknown' else 'und')
    canonical_vtt=data/f"{video_id}.{lang}.vtt"
    canonical_srt=data/f"{video_id}.srt"
    canonical_transcript=data/f"{video_id}.transcript.txt"
    raw=winner['path'].read_text(encoding='utf-8',errors='replace')
    timestamped=winner['timestamped']
    # Build canonical SRT from the normalized timestamped transcript, not from
    # raw VTT display cues. This prevents progressive/rolling YouTube caption
    # repetition from surviving in the persistent SRT.
    srt_text=timestamped_txt_to_srt(timestamped)
    if not timestamped.strip() or not transcript_has_useful_speech(timestamped) or not srt_text.strip():
        return {'ok':False,'changed':False,'reason':'winner could not produce verified VTT/SRT/transcript; nothing deleted'}

    created=[]
    try:
        # Write through temporary siblings, then atomically replace canonical names.
        payloads=[(canonical_vtt,raw),(canonical_srt,srt_text),(canonical_transcript,timestamped)]
        for target,payload in payloads:
            tmp=target.with_name(target.name+f'.tmp-{uuid.uuid4().hex}')
            tmp.write_text(payload,encoding='utf-8')
            if not tmp.exists() or tmp.stat().st_size<=0:
                raise IOError(f'zero-byte canonical artifact: {target.name}')
            os.replace(str(tmp),str(target))
            created.append(target)

        # Re-open and validate all three before deleting anything.
        if not transcript_has_useful_speech(vtt_to_timestamped_transcript(canonical_vtt.read_text(encoding='utf-8',errors='replace'))):
            raise ValueError('canonical VTT failed speech validation')
        if not canonical_srt.read_text(encoding='utf-8',errors='replace').strip():
            raise ValueError('canonical SRT failed validation')
        if not transcript_has_useful_speech(canonical_transcript.read_text(encoding='utf-8',errors='replace')):
            raise ValueError('canonical transcript failed validation')

        keep={str(canonical_vtt.resolve()),str(canonical_srt.resolve()),str(canonical_transcript.resolve())}
        removed=[]
        extras=[]
        # Inferior VTT/SRT variants anywhere inside the video folder.
        for pat in ('*.vtt','*.srt'):
            for p in list(folder.rglob(pat)):
                if p.is_file() and str(p.resolve()) not in keep:
                    extras.append(p)
        # Legacy transcript TXT artifacts may exist outside _data in older
        # libraries. Enforce one persistent transcript across the whole video
        # folder while preserving comment transcripts as a separate artifact.
        for p in list(folder.rglob('*.txt')):
            low=p.name.lower()
            if (p.is_file() and 'transcript' in low and 'comments' not in low
                    and str(p.resolve()) not in keep):
                extras.append(p)

        # Deletion is transactional: first move every inferior artifact outside
        # the video folder. If any move fails, restore everything moved so far
        # and report failure instead of claiming a successful cleanup.
        dedup=[];seen_extra=set()
        for p in extras:
            key=str(p.resolve())
            if key not in seen_extra:
                seen_extra.add(key);dedup.append(p)
        extras=dedup
        quarantine=BASE/'maintenance'/'subtitle_cleanup_quarantine'/str(video_id)/uuid.uuid4().hex
        moved=[]
        try:
            if extras:
                quarantine.mkdir(parents=True,exist_ok=True)
            for idx,p in enumerate(extras):
                rel=p.relative_to(folder)
                q=quarantine/f'{idx:04d}'/rel
                q.parent.mkdir(parents=True,exist_ok=True)
                shutil.move(str(p),str(q))
                moved.append((p,q))

            # Success means the exact final contract is physically true.
            vtts=[p for p in folder.rglob('*.vtt') if p.is_file() and 'live_chat' not in p.name.lower()]
            srts=[p for p in folder.rglob('*.srt') if p.is_file()]
            transcripts=[p for p in folder.rglob('*.txt') if p.is_file() and 'transcript' in p.name.lower() and 'comments' not in p.name.lower()]
            if vtts != [canonical_vtt] or srts != [canonical_srt] or transcripts != [canonical_transcript]:
                raise RuntimeError(
                    f'final three-file contract not satisfied: vtt={len(vtts)}, srt={len(srts)}, transcript={len(transcripts)}'
                )
            removed=[str(src) for src,_ in moved]
            if quarantine.exists():
                shutil.rmtree(quarantine)
        except Exception as cleanup_ex:
            rollback_errors=[]
            for src,q in reversed(moved):
                try:
                    src.parent.mkdir(parents=True,exist_ok=True)
                    if q.exists():
                        shutil.move(str(q),str(src))
                except Exception as rb_ex:
                    rollback_errors.append(f'{src}: {rb_ex}')
            try:
                if quarantine.exists(): shutil.rmtree(quarantine)
            except Exception:
                pass
            suffix=('; rollback errors: '+' | '.join(rollback_errors)) if rollback_errors else ''
            raise RuntimeError(f'inferior subtitle/transcript cleanup failed: {cleanup_ex}{suffix}')

        audit=data/'subtitle_cleanup.audit.jsonl'
        rec={
            'timestamp':time.strftime('%Y-%m-%d %H:%M:%S'),
            'video_id':str(video_id),
            'winner_source':str(winner['path']),
            'winner_language':lang,
            'canonical_vtt':str(canonical_vtt),
            'canonical_srt':str(canonical_srt),
            'canonical_transcript':str(canonical_transcript),
            'removed':removed
        }
        with audit.open('a',encoding='utf-8') as f:
            f.write(json.dumps(rec,ensure_ascii=False)+'\n')

        if update_db:
            try:
                con=db_connect()
                con.execute(
                    'UPDATE videos SET subtitle_file=?,transcript_original=?,transcript_clean=?,subtitle_base_lang=? WHERE video_id=?',
                    (str(canonical_srt),str(canonical_transcript),str(canonical_transcript),lang,str(video_id))
                )
                con.commit();con.close()
            except Exception as ex:
                log(f'Canonical subtitle DB update warning {video_id}: {ex}')
        return {'ok':True,'changed':True,'winner':str(winner['path']),'vtt':str(canonical_vtt),'srt':str(canonical_srt),'transcript':str(canonical_transcript),'removed':removed,'language':lang}
    except Exception as ex:
        # Never delete pre-existing variants on failure. Remove only incomplete temporary canonical files we created.
        log(f'Canonical subtitle cleanup failed {video_id}: {type(ex).__name__}: {ex}')
        return {'ok':False,'changed':False,'reason':f'{type(ex).__name__}: {ex}; existing variants preserved'}


def timestamped_txt_to_srt(timestamped_text, default_duration=5):
    """Create an SRT locally from [HH:MM:SS] transcript text."""
    rows=timestamped_rows(timestamped_text)
    if not rows:
        return ""

    def fmt_srt(sec_value):
        sec_value=max(0,float(sec_value))
        h=int(sec_value//3600)
        sec_value-=h*3600
        m=int(sec_value//60)
        sec_value-=m*60
        s=int(sec_value)
        ms=int(round((sec_value-s)*1000))
        if ms>=1000:
            s+=1
            ms-=1000
        return f"{h:02d}:{m:02d}:{s:02d},{ms:03d}"

    out=[]
    for i,(start_sec,start_ts,body) in enumerate(rows,1):
        if i < len(rows):
            end_sec=max(start_sec+1,rows[i][0]-0.2)
        else:
            end_sec=start_sec+default_duration
        out.append(
            f"{i}\n{fmt_srt(start_sec)} --> {fmt_srt(end_sec)}\n{body}\n"
        )
    return "\n".join(out).strip()

def basic_vtt_to_srt(vtt_text):
    """Local conversion; no second YouTube request."""
    t=vtt_text.replace("\\r\\n","\\n").replace("\\r","\\n")
    blocks=[]
    lines=t.splitlines()
    time_re=re.compile(
        r'(?P<s>(?:\\d{1,2}:)?\\d{1,2}:\\d{2}[.]\\d{3})\\s*-->\\s*'
        r'(?P<e>(?:\\d{1,2}:)?\\d{1,2}:\\d{2}[.]\\d{3})'
    )
    i=0
    while i<len(lines):
        m=time_re.search(lines[i])
        if not m:
            i+=1; continue
        def norm(ts):
            sec=timestamp_to_seconds_loose(ts)
            h=int(sec//3600); sec-=h*3600
            mi=int(sec//60); sec-=mi*60
            return f"{h:02d}:{mi:02d}:{sec:06.3f}".replace(".",",")
        st,en=norm(m.group("s")),norm(m.group("e"))
        i+=1
        body=[]
        while i<len(lines) and lines[i].strip() and not time_re.search(lines[i]):
            x=re.sub(r'<[^>]+>','',lines[i]).strip()
            if x: body.append(x)
            i+=1
        if body: blocks.append((st,en,"\\n".join(body)))
        i+=1
    return "\\n\\n".join(f"{n}\\n{s} --> {e}\\n{b}" for n,(s,e,b) in enumerate(blocks,1))

def transcript_snippet_values(snippet):
    if isinstance(snippet,dict):
        return str(snippet.get("text") or ""),float(snippet.get("start") or 0),float(snippet.get("duration") or 0)
    return str(getattr(snippet,"text","")),float(getattr(snippet,"start",0) or 0),float(getattr(snippet,"duration",0) or 0)

def fetched_transcript_to_timestamped(fetched,marker_interval=15):
    out=[]; last_marker=-999
    for snippet in fetched:
        txt,st,_=transcript_snippet_values(snippet); txt=html.unescape(re.sub(r'\s+',' ',txt)).strip()
        if not txt: continue
        if not out or st-last_marker>=marker_interval:
            out.append(f"[{format_hms_short(st)}] {txt}"); last_marker=st
        else: out[-1]+=" "+txt
    return "\n".join(out).strip()

def _fetch_with_youtube_transcript_api_unbounded(video_id):
    if not CFG.get("use_youtube_transcript_api",True):
        return None,None,None
    mod=transcript_api_import()
    # A frozen EXE is not a Python interpreter. Never attempt pip installation
    # from the running app; use the installed module or the bounded yt-dlp fallback.
    if mod is None:
        return None,None,None

    try:
        api=mod.YouTubeTranscriptApi()
        tl=api.list(video_id)

        # 1) English first: manual then generated.
        for mode,langs in [
            ("manual",["en","en-US","en-GB","en-orig"]),
            ("generated",["en","en-US","en-GB","en-orig"])
        ]:
            try:
                tr=(tl.find_manually_created_transcript(langs)
                    if mode=="manual" else tl.find_generated_transcript(langs))
                timestamped=fetched_transcript_to_timestamped(tr.fetch())
                if timestamped:
                    return timestamped,"en","youtube-transcript-api English"
            except Exception:
                pass

        # 2) Hindi next. Prefer YouTube translation to English, else retain Hindi.
        hindi=None
        for mode in ("manual","generated"):
            try:
                hindi=(tl.find_manually_created_transcript(["hi","hi-orig"])
                       if mode=="manual" else tl.find_generated_transcript(["hi","hi-orig"]))
                if hindi: break
            except Exception:
                hindi=None

        if hindi is not None:
            try:
                if getattr(hindi,"is_translatable",False):
                    timestamped=fetched_transcript_to_timestamped(hindi.translate("en").fetch())
                    if timestamped:
                        return timestamped,"en","youtube-transcript-api Hindi to English"
            except Exception as ex:
                log(f"YouTube Hindi->English transcript translation failed {video_id}: {ex}")
            try:
                timestamped=fetched_transcript_to_timestamped(hindi.fetch())
                if timestamped:
                    return timestamped,"hi","youtube-transcript-api Hindi"
            except Exception:
                pass

        # 3) Any other available language. Prefer English translation when offered.
        try:
            available=list(tl)
        except Exception:
            available=[]

        for tr in available:
            try:
                code=str(getattr(tr,"language_code","") or "unknown")
                if code.lower().startswith(("en","hi")):
                    continue

                if getattr(tr,"is_translatable",False):
                    try:
                        timestamped=fetched_transcript_to_timestamped(tr.translate("en").fetch())
                        if timestamped:
                            return timestamped,"en",f"youtube-transcript-api {code} to English"
                    except Exception:
                        pass

                timestamped=fetched_transcript_to_timestamped(tr.fetch())
                if timestamped:
                    return timestamped,code,f"youtube-transcript-api {code}"
            except Exception:
                continue

        return None,None,None
    except Exception as e:
        log(f"youtube-transcript-api failed {video_id}: {e}")
        return None,None,None


def fetch_with_youtube_transcript_api(video_id):
    """Bound a third-party transcript request so one unavailable video cannot freeze a repair run."""
    timeout=max(5,int(CFG.get("transcript_api_timeout_seconds",20) or 20))
    result={"value":(None,None,None)}
    def worker():
        result["value"]=_fetch_with_youtube_transcript_api_unbounded(video_id)
    thread=threading.Thread(target=worker,name=f"Transcript-{video_id}",daemon=True)
    thread.start();thread.join(timeout)
    if thread.is_alive():
        log(f"youtube-transcript-api timed out after {timeout}s for {video_id}; using subtitle fallback")
        return None,None,None
    return result["value"]


def download_one_caption_to_tmp(video_id,url,source,lang):
    """Download only ONE English caption track, with conservative 429 handling."""
    p=temp_paths(video_id)
    p["dir"].mkdir(parents=True,exist_ok=True)
    if p["vtt"].exists() and p["vtt"].stat().st_size>50:
        return True,"cached"

    if not source or not lang:
        return False,"No English caption source was reported in metadata"

    args=strict_common_args()+[
        "--skip-download","--no-playlist",
        "-o",str(p["dir"]/f"{video_id}.%(ext)s"),
        "--sub-langs",str(lang),
        "--sub-format","vtt",
        "--sleep-requests",str(CFG.get("subtitle_sleep_requests",0.75)),
        "--sleep-subtitles",str(CFG.get("subtitle_sleep_seconds",5.0)),
        "-R","3",
        "--retry-sleep","http:exp=5:60"
    ]
    args += ["--write-subs" if source=="manual" else "--write-auto-subs"]
    args += [url]

    cooldowns=CFG.get("subtitle_429_cooldowns",[60,180,600])
    last_err=""
    for attempt in range(len(cooldowns)+1):
        set_state(current_status=f"TRANSCRIPT {attempt+1}/{len(cooldowns)+1}",
                  current_file=str(video_id),message=f"Downloading one English {source} caption ({lang})")
        console_progress("Transcript | ")
        rc,_,err=run_download_with_progress(args,str(video_id),"English Transcript Source")
        last_err=err or ""
        candidates=list(p["dir"].glob(f"{video_id}*.vtt"))
        if rc==0 and candidates:
            candidates[0].replace(p["vtt"]) if candidates[0]!=p["vtt"] else None
            return True,"downloaded"
        if "429" not in last_err and "Too Many Requests" not in last_err:
            break
        if attempt < len(cooldowns):
            wait=int(cooldowns[attempt])
            console_newline()
            print(f"YouTube subtitle 429. Cooling down {wait} seconds before one retry...")
            log(f"Subtitle 429 {url}; cooldown {wait}s")
            time.sleep(wait)
    return False,last_err[-2000:] or "Subtitle download failed"


def maybe_upgrade_cached_transcript_to_english(video_id):
    """
    Upgrade an older cached Hindi transcript to English using YouTube's own
    transcript translation when available. No LLM required.
    """
    if not CFG.get("auto_upgrade_cached_hindi_to_english",True):
        return False

    p=temp_paths(video_id)
    en_path=p["dir"]/f"{video_id}.timestamped.en.txt"
    if en_path.exists() and en_path.stat().st_size>0:
        return True

    con=db_connect()
    row=con.execute(
        "SELECT subtitle_base_lang,transcript_source FROM videos WHERE video_id=?",
        (video_id,)
    ).fetchone()
    con.close()

    base_lang=(row[0] if row else "") or ""
    if str(base_lang).lower().startswith("en"):
        # If English source exists but .en cache does not, copy current transcript.
        if p["timestamped"].exists() and p["timestamped"].stat().st_size>0:
            shutil.copy2(p["timestamped"],en_path)
            clean_en=p["dir"]/f"{video_id}.clean.en.txt"
            clean_en.write_text(
                timestamped_to_clean(en_path.read_text(encoding="utf-8",errors="replace")),
                encoding="utf-8"
            )
            return True
        return False

    if not str(base_lang).lower().startswith("hi"):
        return False

    timestamped,api_lang,api_source=fetch_with_youtube_transcript_api(video_id)
    if timestamped and api_lang=="en":
        p["dir"].mkdir(parents=True,exist_ok=True)
        en_path.write_text(timestamped,encoding="utf-8")
        (p["dir"]/f"{video_id}.clean.en.txt").write_text(
            timestamped_to_clean(timestamped),
            encoding="utf-8"
        )
        con=db_connect()
        con.execute(
            "UPDATE videos SET subtitle_base_lang='en',transcript_source=? WHERE video_id=?",
            (api_source+" (cache upgrade)",video_id)
        )
        con.commit(); con.close()
        return True
    return False

def _caption_lang_from_filename(path,video_id):
    name=Path(path).name
    prefix=f"{video_id}."
    if name.startswith(prefix) and name.lower().endswith(".vtt"):
        middle=name[len(prefix):-4]
        if middle:
            return middle.split(".")[0]
    return "unknown"


def download_any_caption_to_tmp(video_id,url):
    """
    yt-dlp fallback when youtube-transcript-api cannot provide a transcript.
    Priority: English -> Hindi -> any available subtitle/auto-caption.
    Returns (ok, message, language).
    """
    p=temp_paths(video_id)
    p["dir"].mkdir(parents=True,exist_ok=True)

    # Bounded language priority: English first, then configured fallback
    # languages, then any remaining YouTube subtitle/auto-caption track.
    attempts=[("English", "en.*,en,en-orig")]
    fallback_langs=[str(x).strip() for x in (CFG.get("fallback_transcript_languages") or ["hi","hi-orig"]) if str(x).strip()]
    if fallback_langs:
        patterns=[]
        for code in fallback_langs:
            base=code.split("-")[0]
            patterns.extend([f"{base}.*",code,base])
        attempts.append(("Fallback language", ",".join(dict.fromkeys(patterns))))
    attempts.append(("Any available language", "all,-live_chat"))
    last_err=""

    for label,langs in attempts:
        # Remove only temporary VTT candidates; preserve canonical transcript txt caches.
        for old in p["dir"].glob(f"{video_id}*.vtt"):
            try: old.unlink()
            except Exception: pass

        args=strict_common_args()+[
            "--skip-download","--no-playlist",
            "-o",str(p["dir"]/f"{video_id}.%(ext)s"),
            "--sub-langs",langs,
            "--sub-format","vtt",
            "--write-subs","--write-auto-subs",
            "--sleep-requests",str(CFG.get("subtitle_sleep_requests",0.75)),
            "--sleep-subtitles",str(CFG.get("subtitle_sleep_seconds",5.0)),
            "-R","2",
            "--retry-sleep","http:exp=5:30",
            url
        ]
        rc,_,err=run_download_with_progress(args,str(video_id),f"{label} Transcript Source",timeout_seconds=5)
        last_err=err or ""
        candidates=[x for x in p["dir"].glob(f"{video_id}*.vtt") if "live_chat" not in x.name.lower()]
        candidates=[x for x in candidates if x.exists() and x.stat().st_size>20]
        if rc==0 and candidates:
            # Prefer exact English/Hindi-like track in those respective passes.
            chosen=sorted(candidates,key=lambda x:x.name.lower())[0]
            lang=_caption_lang_from_filename(chosen,video_id)
            if chosen!=p["vtt"]:
                shutil.copy2(chosen,p["vtt"])
            return True,f"yt-dlp {label} caption",lang

    reason=last_err[-1500:].strip() or "YouTube reported no usable subtitles or auto-captions in any language"
    return False,reason,""

def prepare_transcript_row(row):
    try:
        vid=str(row[0] or "").strip()
    except Exception:
        vid=""
    vid,url,orig,upload_date,source,lang,base_lang=row
    p=temp_paths(vid)
    p["dir"].mkdir(parents=True,exist_ok=True)

    if p["timestamped"].exists() and p["timestamped"].stat().st_size>20 and p["clean"].exists() and p["clean"].stat().st_size>20:
        maybe_upgrade_cached_transcript_to_english(vid)
        return True,"cached"

    # Imported libraries often already contain a transcript or captions. Reuse it
    # before making any slow network request, and keep a canonical cache for AI.
    con=db_connect()
    local=con.execute("SELECT local_folder,subtitle_file,transcript_original,transcript_clean,transcript_detailed FROM videos WHERE video_id=?",(vid,)).fetchone()
    con.close()
    candidates=[]
    if local:
        folder=Path(str(local[0] or ""))
        if folder.is_dir():
            # Enforce the user's persistent contract before reuse: one winning
            # VTT + one SRT + one transcript, all from the same VTT.
            preferred_existing=Path(str(local[1])) if local[1] and Path(str(local[1])).is_file() and Path(str(local[1])).suffix.lower()==".vtt" else None
            cleanup=canonicalize_video_subtitle_artifacts(folder,vid,preferred_existing,update_db=True)
            if cleanup.get("ok") and cleanup.get("transcript"):
                candidates.append(Path(cleanup["transcript"]))
            for value in local[1:]:
                if value and Path(str(value)).is_file(): candidates.append(Path(str(value)))
            for pattern in ("*.transcript.txt","*.transcript*.txt","*.srt","*.vtt"):
                candidates.extend(x for x in folder.rglob(pattern) if x.is_file() and x.stat().st_size>20)
        else:
            for value in local[1:]:
                if value and Path(str(value)).is_file(): candidates.append(Path(str(value)))
    cached=artifact_manifest_for_video(vid)
    if cached:
        for key in ("timestamped_transcript","clean_transcript","subtitle"):
            value=cached.get(key)
            if value and Path(str(value)).is_file():candidates.insert(0,Path(str(value)))
    if candidates:
        source_file=next((x for x in candidates if x.suffix.lower()==".txt"),candidates[0])
        raw=source_file.read_text(encoding="utf-8",errors="replace")
        timestamped=vtt_to_timestamped_transcript(raw) if source_file.suffix.lower()==".vtt" else raw
        clean=timestamped_to_clean(timestamped)
        if transcript_has_useful_speech(clean):
            p["timestamped"].write_text(timestamped,encoding="utf-8")
            p["clean"].write_text(clean,encoding="utf-8")
            con=db_connect();con.execute("UPDATE videos SET transcript_temp=?,transcript_source=?,subtitle_file=COALESCE(NULLIF(subtitle_file,''),?) WHERE video_id=?",(str(p["timestamped"]),"existing local transcript",str(source_file) if source_file.suffix.lower() in {".srt",".vtt"} else "",vid));con.commit();con.close()
            return True,"existing local transcript"
        return False,"Transcript/caption file contains no usable speech, or only music/noise markers"

    # API priority: English -> Hindi -> any language.
    timestamped,api_lang,api_source=fetch_with_youtube_transcript_api(vid)
    if timestamped:
        clean=timestamped_to_clean(timestamped)
        if transcript_has_useful_speech(clean):
            p["timestamped"].write_text(timestamped,encoding="utf-8")
            p["clean"].write_text(clean,encoding="utf-8")
            con=db_connect()
            con.execute(
                "UPDATE videos SET transcript_temp=?,transcript_source=?,subtitle_base_lang=? WHERE video_id=?",
                (str(p["timestamped"]),api_source,api_lang or base_lang or "",vid)
            )
            con.commit(); con.close()
            return True,api_source
        return False,"Transcript API returned no usable speech, or only music/noise markers"

    # yt-dlp fallback: English -> Hindi -> any available language.
    ok,msg,caption_lang=download_any_caption_to_tmp(vid,url)
    if not ok:
        reason=(
            "No usable transcript/captions found. Checked English first, then Hindi, "
            "then all other available YouTube subtitle/auto-caption languages. "
            f"Last detail: {msg}"
        )
        return False,reason

    raw=p["vtt"].read_text(encoding="utf-8",errors="replace")
    timestamped=vtt_to_timestamped_transcript(raw)
    clean=timestamped_to_clean(timestamped)
    if not timestamped.strip() or not transcript_has_useful_speech(clean):
        return False,"A caption track was found, but it contains no usable speech, or only music/noise markers"

    p["timestamped"].write_text(timestamped,encoding="utf-8")
    p["clean"].write_text(clean,encoding="utf-8")
    con=db_connect()
    con.execute(
        "UPDATE videos SET transcript_temp=?,transcript_source=?,subtitle_base_lang=? WHERE video_id=?",
        (str(p["timestamped"]),msg,caption_lang or base_lang or "",vid)
    )
    con.commit(); con.close()
    try:
        if has_usable_transcript(vid):
            clear_transcript_retry(vid)
    except Exception:
        pass

    return True,msg


def prepare_transcripts_rows(rows, checkpoint=None):
    """Prepare transcript cache only for the supplied DB rows."""
    TMP_TRANSCRIPTS.mkdir(parents=True,exist_ok=True)
    rows=list(rows or [])
    set_state(phase="Transcript Availability Check",total=len(rows),processed=0,failed=0)
    start_stage("Transcript Availability Check")
    started=time.time()
    reused_count=skipped_count=failed_count=0
    for i,row in enumerate(rows,1):
        if STOP:
            break
        vid,url,orig,_,_,_,_=row
        if checkpoint and str(vid) in checkpoint.get("completed",{}):
            skipped_count+=1;set_state(processed=i,skipped=skipped_count,current_file=str(vid),current_status="Already completed in previous run",current_percent=f"{(i*100/len(rows)):.0f}%")
            continue
        if transcript_retry_count(vid)>=2 and not has_usable_transcript(vid):
            skipped_count+=1
            if checkpoint is not None:checkpoint.setdefault("completed",{})[str(vid)]={"status":"skipped","reason":"No captions after two attempts","at":time.strftime("%Y-%m-%d %H:%M:%S")}
            set_state(processed=i,skipped=skipped_count,current_file=str(vid),current_status="Skipped: no captions cooldown",current_percent=f"{(i*100/len(rows)):.0f}%")
            continue
        set_state(current=orig,current_file=str(vid),processed=i-1,current_status=f"Checking local transcript/subtitles ({i}/{len(rows)})")
        try:
            ok,msg=prepare_transcript_row(row)
            if ok and msg=="cached":
                reused_count+=1
        except Exception as e:
            ok=False
            msg=str(e)
        if not ok:
            failed_count+=1;increment_transcript_retry(vid,msg)
            log(f"Transcript availability failure {url}: {msg}")
            set_state(failed=snapshot().get("failed",0)+1)
        elapsed=max(0.01,time.time()-started);rate=i/elapsed;remaining=max(0,int((len(rows)-i)/rate))
        set_state(processed=i,current_file=str(vid),current_status=("Transcript ready" if ok else "No usable transcript"),current_percent=f"{(i*100/len(rows)):.0f}%" if rows else "100%",current_speed=f"{rate*60:.2f} videos/min" if rate else "",current_eta=f"{remaining//60:02d}:{remaining%60:02d}")
        if checkpoint is not None:
            checkpoint.setdefault("completed",{})[str(vid)]={"status":"done" if ok else "failed","reason":str(msg)[:500],"at":time.strftime("%Y-%m-%d %H:%M:%S")}
            checkpoint["updated_at"]=time.strftime("%Y-%m-%d %H:%M:%S")
            checkpoint["processed"]=i
            Path(checkpoint["path"]).write_text(json.dumps(checkpoint,ensure_ascii=False,indent=2),encoding="utf-8")
        console_progress("Transcript Check | ")
        if i < len(rows) and msg not in {"cached","existing local transcript"}:
            time.sleep(min(1.0,float(CFG.get("subtitle_sleep_seconds",5.0))))
    finish_stage("Transcript Availability Check")
    console_newline()
    print(f"Transcript cache reused: {reused_count} / {len(rows)}; skipped={skipped_count}; failed={failed_count}")
    return {"total":len(rows),"reused":reused_count,"skipped":skipped_count,"failed":failed_count}


def prepare_transcripts_all():
    """Compatibility wrapper: prepare transcript cache for every DB video."""
    con=db_connect()
    rows=con.execute("""
      SELECT video_id,url,original_title,upload_date,subtitle_source,subtitle_lang,subtitle_base_lang
      FROM videos ORDER BY upload_date DESC,rowid DESC
    """).fetchall()
    con.close()
    return prepare_transcripts_rows(rows)


def analyze_video_once(video_id, original_title, timestamped_text, source_language):
    """
    ONE Ollama call per video:
    - translate non-English transcript to English when needed
    - meaningful English filename
    - category/subcategory
    - tags/entities
    - summary
    - semantic timestamped chapters
    """
    p=temp_paths(video_id)

    # Reuse cached AI result.
    if p["identity"].exists() and p["chapters"].exists():
        try:
            identity=json.loads(p["identity"].read_text(encoding="utf-8"))
            chapters=json.loads(p["chapters"].read_text(encoding="utf-8"))
            translated_path=p["dir"]/f"{video_id}.timestamped.en.txt"
            translated=(
                translated_path.read_text(encoding="utf-8",errors="replace")
                if translated_path.exists()
                else timestamped_text
            )
            return identity,chapters,translated
        except Exception as e:
            log(f"Cached AI result read failed for {video_id}: {e}")

    # Keep a bounded transcript payload for local models.
    transcript=timestamped_text[:50000]

    prompt=f"""Return only valid JSON.

SOURCE TITLE:
{original_title}

SOURCE TRANSCRIPT LANGUAGE:
{source_language or "unknown"}

TIMESTAMPED TRANSCRIPT:
{transcript}

Do ALL tasks in this ONE response.

A) If the transcript is not English, translate it to natural English while
preserving every [HH:MM:SS] marker. If it is already English, clean it without
changing its meaning.

B) Create a concise meaningful ENGLISH filename/title based on the actual
content. For list videos such as "5 Foods", "7 Drinks", "4 Seeds", "Best Herbs",
include important actual item names when practical. Remove clickbait, channel
name, emojis, hashtags, hype and guarantees.

C) Return category, subcategory, main topic, title entities, useful tags and
a concise content summary.

D) Create semantic chapters from the timestamped transcript. Use timestamps
that actually appear in the input. Create a new chapter when the topic changes.
Do not dump the raw transcript.

Health/scientific statements must be represented as claims made by the speaker,
not as verified facts.

Return exactly:
{{
 "english_timestamped_transcript":"clean/translated English transcript preserving [HH:MM:SS] markers",
 "meaningful_title":"final English filename, preferably <=120 characters",
 "title_entities":["important concrete names"],
 "main_topic":"specific main subject",
 "category":"broad category",
 "subcategory":"specific subcategory",
 "tags":["specific useful tags"],
 "summary":"2-4 sentence content overview",
 "chapters":[
   {{
     "chapter_title":"specific heading",
     "start":"HH:MM:SS",
     "end":"HH:MM:SS",
     "overview":"2-5 concise sentences",
     "topics":["..."],
     "ingredients_or_entities":["..."],
     "instructions":["..."],
     "claims":["..."],
     "key_points":["..."],
     "tags":["..."]
   }}
 ]
}}
"""

    d=llm_generate(prompt)

    if not d:
        fallback_title=deterministic_content_title(original_title,timestamped_text)
        identity={
            "meaningful_title":fallback_title,
            "title_entities":[],
            "main_topic":"",
            "category":"",
            "subcategory":"",
            "tags":[],
            "summary":""
        }
        chapters=[]
        translated=timestamped_text
    else:
        translated=str(d.get("english_timestamped_transcript") or timestamped_text)

        candidate=safe_name(d.get("meaningful_title") or "")
        if not candidate or candidate.lower()==safe_name(original_title).lower():
            candidate=deterministic_content_title(original_title,translated)

        if len(candidate)>120:
            candidate=candidate[:120].rsplit(" ",1)[0].rstrip(" ,-_")

        title_entities=d.get("title_entities") or []
        if isinstance(title_entities,str):
            title_entities=[x.strip() for x in title_entities.split(",") if x.strip()]

        tags=d.get("tags") or []
        if isinstance(tags,str):
            tags=[x.strip() for x in tags.split(",") if x.strip()]

        identity={
            "meaningful_title":safe_name(candidate),
            "title_entities":title_entities,
            "main_topic":str(d.get("main_topic") or ""),
            "category":str(d.get("category") or ""),
            "subcategory":str(d.get("subcategory") or ""),
            "tags":tags,
            "summary":str(d.get("summary") or "")
        }

        chapters=d.get("chapters") if isinstance(d.get("chapters"),list) else []

    p["dir"].mkdir(parents=True,exist_ok=True)
    p["identity"].write_text(
        json.dumps(identity,ensure_ascii=False,indent=2),
        encoding="utf-8"
    )
    p["chapters"].write_text(
        json.dumps(chapters,ensure_ascii=False,indent=2),
        encoding="utf-8"
    )

    translated_path=p["dir"]/f"{video_id}.timestamped.en.txt"
    translated_path.write_text(translated,encoding="utf-8")
    (p["dir"]/f"{video_id}.clean.en.txt").write_text(
        timestamped_to_clean(translated),
        encoding="utf-8"
    )

    return identity,chapters,translated


def _analyze_one_video_row(row):
    vid,url,orig,old_title,upload_date,category,topic,tags,base_lang=row
    p=temp_paths(vid)
    if not p["timestamped"].exists():
        return {"video_id":vid,"ok":False,"error":"No cached transcript"}

    ts=p["timestamped"].read_text(encoding="utf-8",errors="replace")

    # Smart resume: reuse completed AI if transcript did not change.
    if RUNTIME.get("use_llm",True) and RUNTIME.get("resume_mode")=="smart" and ai_cache_valid(vid,ts):
        try:
            identity=json.loads(p["identity"].read_text(encoding="utf-8"))
            chapters=json.loads(p["chapters"].read_text(encoding="utf-8"))
            return {"video_id":vid,"ok":True,"reused":True,"identity":identity,"chapters":chapters}
        except Exception:
            pass

    # No-LLM mode: do all deterministic operations only.
    if not RUNTIME.get("use_llm",True):
        # Never reuse a semantic/title guess from an older LLM run in FAST mode.
        # FAST mode uses the cleaned Original Title deterministically.
        title=clean_source_title_no_llm(orig)
        identity={
            "meaningful_title":title,
            "title_entities":[],
            "main_topic":"",
            "category":"",
            "subcategory":"",
            "tags":[],
            "summary":""
        }
        chapters=simple_non_llm_chapters(ts)
        p["identity"].write_text(json.dumps(identity,ensure_ascii=False,indent=2),encoding="utf-8")
        p["chapters"].write_text(json.dumps(chapters,ensure_ascii=False,indent=2),encoding="utf-8")
        (p["dir"]/f"{vid}.timestamped.en.txt").write_text(ts,encoding="utf-8")
        (p["dir"]/f"{vid}.clean.en.txt").write_text(timestamped_to_clean(ts),encoding="utf-8")
        save_ai_fingerprint(vid,ts)
        return {"video_id":vid,"ok":True,"reused":False,"identity":identity,"chapters":chapters,"no_llm":True}

    # Normal AI path: one Ollama call for this video.
    identity,chapters,translated=analyze_video_once(vid,orig,ts,base_lang or "unknown")
    save_ai_fingerprint(vid,ts)
    return {"video_id":vid,"ok":True,"reused":False,"identity":identity,"chapters":chapters}

def name_videos_from_tmp_transcripts():
    """
    Smart-resume AI stage with configurable parallel Ollama workers.
    Completed AI caches are reused automatically.
    """
    con=db_connect()
    rows=con.execute("""
      SELECT video_id,url,original_title,clean_title,upload_date,category,main_topic,tags,subtitle_base_lang
      FROM videos ORDER BY upload_date DESC,rowid DESC
    """).fetchall()
    con.close()

    # Retry-failed-only option
    if RUNTIME.get("resume_mode")=="failed":
        con=db_connect()
        failed_ids={r[0] for r in con.execute(
            "SELECT video_id FROM videos WHERE COALESCE(last_error,'')<>''"
        ).fetchall()}
        con.close()
        rows=[r for r in rows if r[0] in failed_ids]

    set_state(phase="Single AI Analysis",total=len(rows),processed=0,failed=0,ai_done=0)
    start_stage("Single AI Analysis")

    workers=1
    if RUNTIME.get("use_llm",True):
        try:
            workers=max(1,min(
                int(CFG.get("ai_parallel_workers",2)),
                int(CFG.get("ai_parallel_workers_max",4))
            ))
        except Exception:
            workers=2

    print(f"AI workers: {workers}" if RUNTIME.get("use_llm",True) else "Fast No-LLM mode: AI disabled")
    reused_count=0

    def persist_result(row,res):
        nonlocal reused_count
        vid,url,orig,old_title,upload_date,category,topic,tags,base_lang=row
        if not res.get("ok"):
            log(f"AI stage failed {url}: {res.get('error','unknown')}")
            return False

        if res.get("reused"):
            reused_count+=1

        identity=res.get("identity") or {}
        new_title=safe_name(identity.get("meaningful_title") or old_title or orig,vid)
        merged_tags=", ".join(dict.fromkeys(
            [str(x) for x in (identity.get("title_entities") or []) if str(x).strip()] +
            [str(x) for x in (identity.get("tags") or []) if str(x).strip()]
        )) or tags

        con=db_connect()
        con.execute("""
          UPDATE videos SET clean_title=?,category=?,subcategory=?,main_topic=?,tags=?,
                            identity_json=?,chapters_temp=?,last_error=''
          WHERE video_id=?
        """,(
            new_title,
            str(identity.get("category") or category or ""),
            str(identity.get("subcategory") or ""),
            str(identity.get("main_topic") or topic or ""),
            merged_tags,
            json.dumps(identity,ensure_ascii=False),
            str(temp_paths(vid)["chapters"]),
            vid
        ))
        con.commit(); con.close()
        return True

    if workers==1:
        for i,row in enumerate(rows,1):
            if STOP: break
            set_state(current=row[2],current_file=str(row[0]),processed=i-1,
                      current_status="REUSE OR PROCESS")
            try:
                res=_analyze_one_video_row(row)
                ok=persist_result(row,res)
            except Exception as e:
                ok=False
                log(f"AI worker failure {row[1]}: {e}")
            s=snapshot()
            set_state(processed=i,ai_done=s.get("ai_done",0)+(1 if ok else 0),
                      failed=s.get("failed",0)+(0 if ok else 1))
            console_progress("AI | ")
    else:
        from concurrent.futures import ThreadPoolExecutor, as_completed
        with ThreadPoolExecutor(max_workers=workers) as ex:
            futs={ex.submit(_analyze_one_video_row,row):row for row in rows}
            done=0
            for fut in as_completed(futs):
                if STOP: break
                row=futs[fut]
                try:
                    res=fut.result()
                    ok=persist_result(row,res)
                except Exception as e:
                    ok=False
                    log(f"Parallel AI worker failure {row[1]}: {e}")
                done+=1
                s=snapshot()
                set_state(processed=done,current=row[2],current_file=str(row[0]),
                          ai_done=s.get("ai_done",0)+(1 if ok else 0),
                          failed=s.get("failed",0)+(0 if ok else 1))
                console_progress("Parallel AI | ")

    finish_stage("Single AI Analysis")
    export_csv()
    console_newline()
    print(f"AI cache reused: {reused_count}")

def split_timestamped_batches(text,max_chars=None):
    max_chars=int(max_chars or CFG.get("chapter_batch_max_chars",12000))
    lines=[x.strip() for x in text.splitlines() if x.strip()]
    batches=[]; cur=[]; chars=0
    for line in lines:
        if cur and chars+len(line)>max_chars:
            batches.append("\\n".join(cur)); cur=[]; chars=0
        cur.append(line); chars+=len(line)+1
    if cur: batches.append("\\n".join(cur))
    return batches

def ai_chapters_from_timestamped(timestamped,title,cache_path=None):
    if cache_path and Path(cache_path).exists():
        try: return json.loads(Path(cache_path).read_text(encoding="utf-8"))
        except Exception: pass
    all_chapters=[]
    batches=split_timestamped_batches(timestamped)
    for bi,batch in enumerate(batches,1):
        prompt=f"""Return only valid JSON.

VIDEO TITLE:
{title}

CLEAN TIMESTAMPED TRANSCRIPT BATCH {bi}/{len(batches)}:
{batch}

Create semantic chapters from this timestamped text.

Rules:
- Return MULTIPLE chapters when the subject changes.
- Use only timestamp markers that appear in the input.
- Never output the raw transcript as the overview.
- Each overview should summarize its chapter in 2-5 sentences.
- Specific chapter headings only; never "Transcript Section".
- Preserve useful ingredients, products, steps, quantities and timing.
- Treat health/scientific statements as speaker claims rather than verified facts.

Return:
{{
 "chapters":[
   {{
    "chapter_title":"specific heading",
    "start":"HH:MM:SS",
    "end":"HH:MM:SS",
    "overview":"concise structured explanation",
    "topics":["..."],
    "ingredients_or_entities":["..."],
    "instructions":["..."],
    "claims":["..."],
    "key_points":["..."],
    "tags":["..."]
   }}
 ]
}}
"""
        d=llm_generate(prompt)
        if d and isinstance(d.get("chapters"),list):
            all_chapters.extend(d["chapters"])
        else:
            # bounded fallback rather than raw transcript dump
            first=re.search(r'\\[(\\d{2}:\\d{2}:\\d{2})\\]',batch)
            markers=re.findall(r'\\[(\\d{2}:\\d{2}:\\d{2})\\]',batch)
            clean=timestamped_to_clean(batch)
            all_chapters.append({
                "chapter_title":f"Video Discussion Part {bi}",
                "start":first.group(1) if first else "00:00:00",
                "end":markers[-1] if markers else "00:00:00",
                "overview":" ".join(clean.split()[:100]),
                "topics":[],"ingredients_or_entities":[],"instructions":[],
                "claims":[],"key_points":[],"tags":[]
            })
    if cache_path:
        Path(cache_path).write_text(json.dumps(all_chapters,ensure_ascii=False,indent=2),encoding="utf-8")
    return all_chapters

def locate_existing_folder(video_id):
    """Find a previous download even when its title/folder was changed."""
    # Prefer DB path when still valid.
    con=db_connect()
    row=con.execute("SELECT local_folder FROM videos WHERE video_id=?",(video_id,)).fetchone()
    con.close()
    if row and row[0]:
        p=Path(row[0])
        if p.exists():
            return p
    if DOWNLOADS.exists():
        for marker in DOWNLOADS.rglob(".video_id"):
            try:
                if marker.read_text(encoding="utf-8",errors="ignore").strip()==str(video_id):
                    # New layout stores marker under <video folder>\_data\.video_id
                    return marker.parent.parent if marker.parent.name=="_data" else marker.parent
            except Exception:
                pass
    return None

def user_video_comments_path(video_id,create_parent=False):
    folder=locate_existing_folder(video_id)
    if not folder:return None
    data=support_dir(Path(folder),create=create_parent)
    if create_parent:data.mkdir(parents=True,exist_ok=True)
    return data/"videohoarder_user_comments.json"

def load_user_video_comments(video_id):
    vid=str(video_id or "").strip()
    if not vid:return {"ok":False,"message":"video_id is required","comments":[]}
    path=user_video_comments_path(vid,False)
    comments=[]
    if path and path.is_file():
        try:
            obj=json.loads(path.read_text(encoding="utf-8"))
            rows=obj.get("comments") if isinstance(obj,dict) else obj
            if isinstance(rows,list):
                comments=[x for x in rows if isinstance(x,dict)]
        except Exception:
            comments=[]
    return {"ok":True,"video_id":vid,"comments":comments,"count":len(comments),"path":str(path) if path else ""}

def save_user_video_comments(video_id,comments):
    vid=str(video_id or "").strip()
    if not vid:return {"ok":False,"message":"video_id is required"}
    path=user_video_comments_path(vid,True)
    if not path:return {"ok":False,"message":"Video folder not found; cannot save local notes."}
    cleaned=[]
    now=time.strftime("%Y-%m-%d %H:%M:%S")
    for item in comments or []:
        if isinstance(item,dict):text=str(item.get("text") or "").strip()
        else:text=str(item or "").strip()
        if not text:continue
        cleaned.append({"id":str(uuid.uuid4()),"text":text[:4000],"updated_at":now,"source":"user"})
    if cleaned:
        payload={"video_id":vid,"updated_at":now,"comments":cleaned}
        path.write_text(json.dumps(payload,indent=2,ensure_ascii=False),encoding="utf-8")
    elif path.exists():
        path.unlink()
    return {"ok":True,"video_id":vid,"count":len(cleaned),"path":str(path),"message":"Saved personal video notes/comments." if cleaned else "Removed personal video notes/comments."}

def find_any_media(folder):
    if not folder or not Path(folder).exists():
        return None
    folder=Path(folder)
    exts={".mp4",".mkv",".webm",".mov",".m4v",".avi",".m4a",".mp3"}
    files=[p for p in folder.iterdir() if p.is_file() and p.suffix.lower() in exts]
    # Avoid thumbnails and prefer video containers.
    order={".mp4":0,".mkv":1,".webm":2,".mov":3,".m4v":4,".avi":5,".m4a":6,".mp3":7}
    files.sort(key=lambda p:(order.get(p.suffix.lower(),99),-p.stat().st_size))
    return files[0] if files else None


def channel_folder_name(channel):
    name=safe_name(channel or "Unknown Channel").strip()
    return name or "Unknown Channel"

def channel_root(channel):
    """
    Physical storage root for one channel:
      Downloads\\<Channel>\\
    """
    if CFG.get("channel_parent_folders",True):
        root=DOWNLOADS/channel_folder_name(channel)
        root.mkdir(parents=True,exist_ok=True)
        return root
    return DOWNLOADS


def truncate_title_chars(title,max_chars=MAX_VIDEO_TITLE_CHARS):
    value=safe_name(str(title or "")).strip()
    if len(value)<=max_chars:
        return value
    cut=value[:max_chars].rstrip(" .-_")
    if " " in cut:
        prior=cut.rsplit(" ",1)[0].rstrip(" .-_")
        if len(prior)>=max_chars*0.65:
            cut=prior
    return cut or value[:max_chars]


def path_budgeted_video_title(parent,date_prefix,title,video_id="",max_chars=MAX_VIDEO_TITLE_CHARS):
    title=truncate_title_chars(title,max_chars)
    prefix=f"{date_prefix} - " if date_prefix else ""
    reserve="\\_data\\" + safe_name(str(video_id or "video")) + ".transcript_timestamped.txt"
    allowed=WINDOWS_SAFE_PATH_BUDGET-len(str(Path(parent)))-1-len(prefix)-len(reserve)
    effective=max(20,min(max_chars,allowed))
    return truncate_title_chars(title,effective)


def staging_root():
    p=DOWNLOADS/"_staging"
    p.mkdir(parents=True,exist_ok=True)
    return p


def staging_dir(video_id,create=True):
    p=staging_root()/safe_name(str(video_id))
    if create:
        p.mkdir(parents=True,exist_ok=True)
    return p


def staging_data_dir(video_id,create=True):
    p=staging_dir(video_id,create=create)/"_data"
    if create:
        p.mkdir(parents=True,exist_ok=True)
    return p


def artifact_registry_csv_path():
    p=BASE/"data"/"exports"/"video_artifact_registry.csv"
    p.parent.mkdir(parents=True,exist_ok=True)
    return p


def _nonzero_file(path):
    try:
        p=Path(path)
        return p.exists() and p.is_file() and p.stat().st_size>0
    except Exception:
        return False



def working_folder_for_video(video_id):
    final=locate_existing_folder(video_id)
    if final and Path(final).exists():
        return Path(final)
    stage=staging_dir(video_id,create=False)
    if stage.exists():
        return stage
    return None



def refresh_db_artifact_paths(video_id,folder):
    """
    Re-scan final folder after staging commit and replace stale staging paths.
    Includes v30 identity/comments references.
    """
    vid=str(video_id)
    folder=Path(folder)
    data=support_dir(folder,create=True)

    media=find_any_media(folder)
    subtitle=next((p for pat in (f"{vid}.srt",f"{vid}.*.vtt","*.srt","*.vtt") for p in data.glob(pat) if _nonzero_file(p)),None)
    canonical=next((p for p in data.glob(f"{vid}.transcript.txt") if _nonzero_file(p)),None)
    ts=canonical or next((p for p in data.glob("*.transcript_timestamped.txt") if _nonzero_file(p)),None)
    clean=canonical or next((p for p in data.glob("*.transcript_clean.txt") if _nonzero_file(p)),None)
    detailed=next((p for p in data.glob("*.transcript_detailed.json") if _nonzero_file(p)),None)
    report=next((p for p in folder.glob("*.report.html") if _nonzero_file(p)),None)
    desc=next((p for p in data.glob("*.description") if _nonzero_file(p)),None)
    identity=data/"video_identity.json"
    if not identity.exists():
        identity=next((p for p in data.glob("*video_identity*.json") if p.is_file()),None)
    comments=next((p for p in data.glob("*.comments.json") if p.is_file() and ".comments_meaningful." not in p.name),None)
    comment_all=next((p for p in data.glob("*.comments_all.txt") if p.is_file()),None)
    comment_meaningful=next((p for p in data.glob("*.comments_chatgpt.txt") if p.is_file()),None)
    comment_meaningful_json=next((p for p in data.glob("*.comments_meaningful.json") if p.is_file()),None)

    cols=video_table_columns()
    updates={
        "local_folder":str(folder),
        "local_video":str(media or ""),
        "subtitle_file":str(subtitle or ""),
        "transcript_original":str(ts or ""),
        "transcript_clean":str(clean or ""),
        "transcript_detailed":str(detailed or ""),
        "report_html":str(report or ""),
        "downloaded":1 if media else 0,
        "last_error":""
    }
    if media and "downloaded_at" in cols:
        # Keep existing timestamp when present.
        pass
    if "video_identity_file" in cols:
        updates["video_identity_file"]=str(identity or "") if identity and Path(identity).exists() else ""
    if "comments_file" in cols and comments:updates["comments_file"]=str(comments)
    if "comments_transcript_file" in cols and comment_all:updates["comments_transcript_file"]=str(comment_all)
    if "comments_meaningful_file" in cols and comment_meaningful:updates["comments_meaningful_file"]=str(comment_meaningful)
    if "comments_meaningful_json" in cols and comment_meaningful_json:updates["comments_meaningful_json"]=str(comment_meaningful_json)

    con=db_connect()
    if "downloaded_at" in cols:
        existing=con.execute("SELECT downloaded_at FROM videos WHERE video_id=?",(vid,)).fetchone()
        updates["downloaded_at"]=(existing[0] if existing and existing[0] else (time.strftime("%Y-%m-%d %H:%M:%S") if media else ""))
    set_sql=",".join(f'"{k}"=?' for k in updates)
    con.execute(f"UPDATE videos SET {set_sql} WHERE video_id=?",tuple(updates.values())+(vid,))
    con.commit()
    con.close()
    return {
        "media":media,"subtitle":subtitle,"timestamped":ts,
        "clean":clean,"detailed":detailed,"report":report,"description":desc,
        "identity":identity if identity and Path(identity).exists() else None,
        "comments":comments
    }


def artifact_inventory(video_id,folder=None):
    """
    Inventory artifacts by Video ID, independent of title/file naming.
    Looks in final library AND staging.
    """
    vid=str(video_id or "").strip()
    result={
        "video_id":vid,
        "media":None,
        "subtitle":None,
        "timestamped_transcript":None,
        "clean_transcript":None,
        "description":None,
        "thumbnail":None,
        "info_json":None,
        "canonical_metadata":False,
        "metadata_source":"",
        "html_report":None,
        "final_folder":None,
        "staging_folder":str(staging_dir(vid,create=False))
    }

    if folder is None:
        folder=locate_existing_folder(vid)

    search_roots=[]
    if folder and Path(folder).exists():
        result["final_folder"]=str(folder)
        search_roots.append(Path(folder))
    sdir=staging_dir(vid,create=False)
    if sdir.exists():
        search_roots.append(sdir)

    for root in search_roots:
        # media at root level
        for pat in ("*.mp4","*.mkv","*.webm","*.mov","*.m4v"):
            for p in root.glob(pat):
                if _nonzero_file(p):
                    result["media"]=str(p)
                    break
            if result["media"]:
                break

        data=root/"_data"
        if not data.exists():
            data=root

        patterns={
            "subtitle":["*.srt","*.vtt"],
            "timestamped_transcript":[f"{vid}.transcript.txt","*.transcript.txt","*.transcript_timestamped.txt","*.timestamped.txt"],
            "clean_transcript":[f"{vid}.transcript.txt","*.transcript.txt","*.transcript_clean.txt","*.clean.txt"],
            "description":["*.description","*.description.txt"],
            "info_json":["*.info.json"],
            "html_report":["*.report.html","*.html"],
        }

        for key,pats in patterns.items():
            if result[key]:
                continue
            for pat in pats:
                found=next((p for p in data.glob(pat) if _nonzero_file(p)),None)
                if found:
                    result[key]=str(found)
                    break

        if not result["thumbnail"]:
            for pat in ("*.jpg","*.jpeg","*.png","*.webp"):
                found=next((p for p in data.glob(pat) if _nonzero_file(p)),None)
                if found:
                    result["thumbnail"]=str(found)
                    break

    try:
        con=db_connect()
        result["canonical_metadata"]=canonical_metadata_available(con,vid)
        if result["canonical_metadata"]:
            result["metadata_source"]="sqlite"
        elif result.get("info_json"):
            result["metadata_source"]="info_json_fallback"
        con.close()
    except Exception:
        if result.get("info_json"):
            result["metadata_source"]="info_json_fallback"
    return result



def staging_audit():
    root=staging_root()
    print("")
    print("===== STAGING AUDIT =====")
    count=0
    for p in sorted(root.iterdir()):
        if not p.is_dir():
            continue
        count+=1
        vid=p.name
        inv=artifact_inventory(vid)
        print(f"{vid}")
        print(f"  Media      : {'YES' if inv['media'] else 'NO'}")
        print(f"  Transcript : {'YES' if (inv['timestamped_transcript'] or inv['clean_transcript'] or inv['subtitle']) else 'NO'}")
        print(f"  Folder     : {p}")
    if count==0:
        print("No active staging folders.")
    return count

def export_artifact_registry():
    con=db_connect()
    rows=con.execute(
        "SELECT video_id,url,original_title,clean_title,channel FROM videos WHERE COALESCE(current_present,1)=1 AND COALESCE(deleted_from_library,0)=0 ORDER BY rowid"
    ).fetchall()
    con.close()

    out=artifact_registry_csv_path()
    with open(out,"w",newline="",encoding="utf-8-sig") as f:
        fields=[
            "Video ID","URL","Title","Channel","Media","Subtitle",
            "Timestamped Transcript","Clean Transcript","Description",
            "Thumbnail","Info JSON","HTML Report","Final Folder","Staging Folder"
        ]
        w=csv.DictWriter(f,fieldnames=fields)
        w.writeheader()

        for vid,url,orig,clean,channel in rows:
            inv=artifact_inventory(vid)
            w.writerow({
                "Video ID":vid,
                "URL":url or "",
                "Title":clean or orig or "",
                "Channel":channel or "",
                "Media":inv["media"] or "",
                "Subtitle":inv["subtitle"] or "",
                "Timestamped Transcript":inv["timestamped_transcript"] or "",
                "Clean Transcript":inv["clean_transcript"] or "",
                "Description":inv["description"] or "",
                "Thumbnail":inv["thumbnail"] or "",
                "Info JSON":inv["info_json"] or "",
                "HTML Report":inv["html_report"] or "",
                "Final Folder":inv["final_folder"] or "",
                "Staging Folder":inv["staging_folder"] or "",
            })

    print(f"Artifact registry: {out}")
    return out


def missing_artifacts_for_video(video_id):
    inv=artifact_manifest_for_video(video_id) or artifact_inventory(video_id)
    missing=[]
    if not inv["media"]:
        missing.append("media")
    if not inv["subtitle"]:
        missing.append("subtitle")
    if not inv["timestamped_transcript"]:
        missing.append("timestamped_transcript")
    if not inv["clean_transcript"]:
        missing.append("clean_transcript")
    if not inv["description"]:
        missing.append("description")
    if not inv["thumbnail"]:
        missing.append("thumbnail")
    if not inv["info_json"]:
        missing.append("info_json")
    if not inv["html_report"]:
        missing.append("html_report")
    return missing,inv


def staging_media_path(video_id):
    s=staging_dir(video_id,create=False)
    for pat in ("*.mp4","*.mkv","*.webm","*.mov","*.m4v"):
        found=next((p for p in s.glob(pat) if _nonzero_file(p)),None)
        if found:
            return found
    return None


def commit_staging_to_library(video_id,upload_date,title,channel):
    """
    Transaction-style move/merge after media validation.
    """
    vid=str(video_id)
    sdir=staging_dir(vid)
    media=staging_media_path(vid)

    if not media or not _nonzero_file(media):
        raise FileNotFoundError(f"Cannot commit staging: media missing for {vid}")

    final=video_folder_path(title,upload_date,channel,vid)
    final.mkdir(parents=True,exist_ok=True)
    fdata=final/"_data"
    fdata.mkdir(parents=True,exist_ok=True)

    # Move/merge media
    for p in list(sdir.iterdir()):
        if p.name=="_data":
            continue
        if not p.is_file():
            continue
        target=final/p.name
        if target.exists():
            if files_equal(p, target):
                p.unlink()
                continue
            target=unique_conflict_path(target, marker=vid or "conflict")
        shutil.move(str(p),str(target))

    # Move/merge support files
    sdata=sdir/"_data"
    if sdata.exists():
        for p in list(sdata.iterdir()):
            if not p.is_file():
                continue
            target=fdata/p.name
            if target.exists():
                if files_equal(p, target):
                    p.unlink()
                    continue
                target=unique_conflict_path(target, marker=vid or "conflict")
            shutil.move(str(p),str(target))

    # keep staging dir only if something unresolved remains
    try:
        if sdata.exists() and not any(sdata.iterdir()):
            sdata.rmdir()
        if not any(sdir.iterdir()):
            sdir.rmdir()
    except Exception:
        pass

    media_final=find_any_media(final)
    refresh_db_artifact_paths(vid,final)
    return final




