def deleted_video_guard_history_path():
    """Minimal deleted-ID history used ONLY by the pre-download re-download guard."""
    p=BASE/"maintenance"/"deleted_video_guard_history.json"
    p.parent.mkdir(parents=True,exist_ok=True)
    return p

def _load_deleted_video_guard_history():
    p=deleted_video_guard_history_path()
    if not p.is_file():
        return {}
    try:
        obj=json.loads(p.read_text(encoding="utf-8"))
        if isinstance(obj,dict):
            return {str(k):v for k,v in obj.items() if str(k).strip() and isinstance(v,dict)}
    except Exception:
        pass
    return {}

def _save_deleted_video_guard_history(history):
    p=deleted_video_guard_history_path()
    clean={str(k):v for k,v in (history or {}).items() if str(k).strip() and isinstance(v,dict)}
    tmp=p.with_suffix(p.suffix+".tmp")
    tmp.write_text(json.dumps(clean,indent=2,ensure_ascii=False),encoding="utf-8")
    tmp.replace(p)
    return p

def remember_deleted_video_for_redownload_guard(video_id,title="",channel="",deleted_at=""):
    """Remember only minimal fields required to warn on a future re-download attempt."""
    vid=str(video_id or "").strip()
    if not vid:
        return False
    h=_load_deleted_video_guard_history()
    h[vid]={
        "title":str(title or ""),
        "channel":str(channel or ""),
        "deleted_at":str(deleted_at or time.strftime("%Y-%m-%d %H:%M:%S")),
    }
    _save_deleted_video_guard_history(h)
    return True

def forget_deleted_video_redownload_guard(video_id):
    """A successfully re-downloaded video is active again, so its deleted guard is no longer needed."""
    vid=str(video_id or "").strip()
    if not vid:
        return False
    h=_load_deleted_video_guard_history()
    if vid not in h:
        return False
    h.pop(vid,None)
    _save_deleted_video_guard_history(h)
    return True

def migrate_legacy_deleted_history_to_guard():
    """One-time compatibility migration; then remove legacy deleted references from normal state."""
    history=_load_deleted_video_guard_history()
    changed=False
    # Old delete audit CSV: import only minimal warning fields, then remove the old audit file.
    old=BASE/"maintenance"/"audits"/"delete_marker_audit.csv"
    if old.is_file():
        try:
            with old.open("r",encoding="utf-8-sig",newline="") as f:
                for r in csv.DictReader(f):
                    vid=str(r.get("Video ID") or r.get("video_id") or "").strip()
                    if vid and vid not in history:
                        history[vid]={"title":"","channel":"","deleted_at":str(r.get("Timestamp") or "")}
                        changed=True
            old.unlink()
        except Exception as ex:
            log(f"Legacy deleted-history migration warning: {ex}")
    # Old DB tombstones: capture minimal metadata for the guard, then purge every
    # ordinary DB/cache/index reference for those VIDEO_IDs.
    legacy=[]
    try:
        con=db_connect()
        cols={str(r[1]) for r in con.execute("PRAGMA table_info(videos)").fetchall()}
        if "deleted_from_library" in cols:
            legacy=con.execute("SELECT video_id,COALESCE(original_title,''),COALESCE(channel,''),COALESCE(deleted_at,'') FROM videos WHERE COALESCE(deleted_from_library,0)=1").fetchall()
        con.close()
    except Exception as ex:
        log(f"Legacy deleted tombstone scan warning: {ex}")
        legacy=[]
    for vid,title,channel,deleted_at in legacy:
        vid=str(vid or "").strip()
        if not vid:
            continue
        history[vid]={"title":str(title or ""),"channel":str(channel or ""),"deleted_at":str(deleted_at or "")}
        changed=True
        try:
            remove_video_db_records(vid)
        except Exception as ex:
            log(f"Legacy deleted DB purge warning {vid}: {ex}")
        try:
            remove_video_from_cached_indexes(vid)
        except Exception as ex:
            log(f"Legacy deleted cache purge warning {vid}: {ex}")
    if changed:
        _save_deleted_video_guard_history(history)
    return {"ok":True,"count":len(history),"path":str(deleted_video_guard_history_path())}



def find_video_id_from_folder(folder):
    folder=Path(folder)

    # Current/new layouts.
    candidates=[
        folder/".video_id",
        folder/"video_id.txt",
        folder/"_data"/".video_id",
        folder/"_data"/"video_id.txt",
    ]
    for p in candidates:
        if p.exists():
            try:
                vid=p.read_text(encoding="utf-8",errors="ignore").strip()
                if vid:
                    return vid
            except Exception:
                pass

    # Filename convention: "... [VIDEO_ID].ext"
    try:
        direct_files=[p for p in folder.iterdir() if p.is_file()]
        ids=set()
        for p in direct_files:
            m=re.search(r"\[([A-Za-z0-9_-]{6,})\](?:\.[^.]+)?$",p.name)
            if m:
                ids.add(m.group(1))
        if len(ids)==1:
            return next(iter(ids))
    except Exception:
        pass

    # DB local_folder exact match. Only resolve if exactly one video owns that folder.
    try:
        con=db_connect()
        rows=con.execute(
            "SELECT video_id FROM videos WHERE lower(COALESCE(local_folder,''))=lower(?)",
            (str(folder),)
        ).fetchall()
        con.close()
        ids=[str(r[0]) for r in rows if r and r[0]]
        if len(set(ids))==1:
            return ids[0]
    except Exception:
        pass

    # DB path columns whose parent equals this folder. Again, only if unique.
    try:
        con=db_connect()
        cols=video_table_columns()
        path_cols=[c for c in [
            "local_video","subtitle_file","transcript_original","transcript_clean",
            "transcript_detailed","report_html"
        ] if c in cols]
        found=set()
        if path_cols:
            sql="SELECT video_id,"+",".join(f'"{c}"' for c in path_cols)+" FROM videos"
            for row in con.execute(sql).fetchall():
                vid=str(row[0] or "")
                for val in row[1:]:
                    if not val:
                        continue
                    try:
                        if Path(str(val)).parent.resolve()==folder.resolve():
                            found.add(vid)
                    except Exception:
                        if str(Path(str(val)).parent).lower()==str(folder).lower():
                            found.add(vid)
        con.close()
        if len(found)==1:
            return next(iter(found))
    except Exception:
        pass

    return ""



def collect_video_related_paths(video_id):
    """
    Gather concrete filesystem artifacts belonging to one exact VIDEO_ID.

    Important:
    - a shared Channel/Category directory is NOT deleted just because local_folder
      points to it;
    - a whole directory is deleted only when it is strongly owned by VIDEO_ID
      (marker or ID in folder name);
    - exact DB file paths and files containing [VIDEO_ID] / VIDEO_ID are removed.
    """
    vid=str(video_id or "").strip()
    paths=set()
    if not vid:
        return []

    # Read exact path columns before DB deletion.
    db_paths=[]
    local_folders=[]
    try:
        con=db_connect()
        cols=video_table_columns()
        path_cols=[c for c in [
            "local_folder","local_video","subtitle_file","transcript_original",
            "transcript_clean","transcript_detailed","report_html","transcript_temp",
            "chapters_temp","comments_file","comments_transcript_file","comments_meaningful_file","comments_meaningful_json","video_identity_file","chatgpt_summary_file"
        ] if c in cols]
        if path_cols:
            row=con.execute(
                "SELECT "+",".join(f'"{c}"' for c in path_cols)+" FROM videos WHERE video_id=?",
                (vid,)
            ).fetchone()
            if row:
                for col,val in zip(path_cols,row):
                    if not val:
                        continue
                    p=Path(str(val))
                    if col=="local_folder":
                        local_folders.append(p)
                    else:
                        db_paths.append(p)
        con.close()
    except Exception:
        pass

    for p in db_paths:
        if p.exists():
            paths.add(p)

    # Strongly-owned final video folder only.
    final=locate_existing_folder(vid)
    if final:
        p=Path(final)
        if p.exists():
            owned=False
            for marker in [p/".video_id",p/"_data"/".video_id",p/"video_id.txt",p/"_data"/"video_id.txt"]:
                try:
                    if marker.exists() and marker.read_text(encoding="utf-8",errors="ignore").strip()==vid:
                        owned=True
                        break
                except Exception:
                    pass
            if vid.lower() in p.name.lower() or f"[{vid}]" in p.name:
                owned=True
            if owned:
                paths.add(p)

    # For shared Media-Only channel folders, remove exact selected-video files.
    scan_roots=set()
    for p in local_folders:
        if p.exists() and p.is_dir():
            scan_roots.add(p)
    for p in db_paths:
        try:
            if p.parent.exists():
                scan_roots.add(p.parent)
        except Exception:
            pass

    for base in scan_roots:
        try:
            for p in base.iterdir():
                if not p.is_file():
                    continue
                name=p.name.lower()
                if vid.lower() in name or f"[{vid.lower()}]" in name:
                    paths.add(p)
        except Exception:
            pass

    # Global final-library fallback by VIDEO_ID in path/filename.
    if DOWNLOADS.exists():
        try:
            for p in DOWNLOADS.rglob(f"*{vid}*"):
                if p.exists() and p.is_file():
                    paths.add(p)
        except Exception:
            pass

    # Staging/tmp/archive locations.
    for p in [
        staging_dir(vid,create=False),
        temp_transcript_root()/vid,
        temp_short_video_root()/vid,
        transcript_archive_root()/"complete"/vid,
        transcript_archive_root()/"subtitle_missing"/vid,
        transcript_archive_root()/"transcription_missing"/vid,
        transcript_archive_root()/"description_missing"/vid,
        transcript_archive_root()/"thumbnail_missing"/vid,
        transcript_archive_root()/"info_json_missing"/vid,
        transcript_archive_root()/"multiple_artifacts_missing"/vid,
        transcript_archive_root()/"resolved_tmp_duplicates"/vid,
    ]:
        if p.exists():
            paths.add(p)

    # Other per-ID files.
    for base in [
        BASE/"data"/"chatgpt",
        BASE/"data"/"summaries",
        BASE/"data"/"exports",
        BASE/"maintenance",
        BASE/"logs",
    ]:
        if not base.exists():
            continue
        try:
            for p in base.rglob(f"*{vid}*"):
                if p.exists() and p != delete_queue_marker_path(vid):
                    paths.add(p)
        except Exception:
            pass

    # If a whole owned folder is selected, child paths are redundant.
    dirs=[Path(p) for p in paths if Path(p).is_dir()]
    filtered=[]
    for p in paths:
        pp=Path(p)
        nested=False
        for d in dirs:
            if pp==d:
                continue
            try:
                if d in pp.parents:
                    nested=True
                    break
            except Exception:
                pass
        if not nested:
            filtered.append(pp)

    return sorted(set(filtered),key=lambda p:len(str(p)),reverse=True)



def remove_video_db_records(video_id):
    """
    Remove all SQLite rows tied to the selected VIDEO_ID.

    Supports current/legacy ID column names, not only a literal `video_id`.
    """
    vid=str(video_id or "").strip()
    if not vid:
        return {}
    con=db_connect()
    tables=[
        r[0] for r in con.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"
        ).fetchall()
    ]

    id_names={"video_id","videoid","youtube_video_id","youtubevideoid","source_video_id","sourcevideoid"}
    removed={}
    for table in tables:
        try:
            cols=[str(r[1]) for r in con.execute(f'PRAGMA table_info("{table}")').fetchall()]
            id_cols=[c for c in cols if c.lower() in id_names]
            if not id_cols:
                continue
            table_removed=0
            for col in id_cols:
                cur=con.execute(
                    f'DELETE FROM "{table}" WHERE CAST("{col}" AS TEXT)=?',
                    (vid,)
                )
                if cur.rowcount and cur.rowcount>0:
                    table_removed+=cur.rowcount
            if table_removed:
                removed[table]=table_removed
        except Exception as ex:
            removed[f"{table}.__error__"]=str(ex)

    con.commit()
    con.close()
    return removed


def remove_empty_channel_after_purge(trigger_folder):
    try:
        folder=Path(trigger_folder)
        channel=folder.parent
        if not channel.exists() or not channel.is_dir():
            return False
        if channel.resolve()==DOWNLOADS.resolve():
            return False
        if channel.name=="_staging":
            return False
        if any(channel.iterdir()):
            return False
        channel.rmdir()
        return True
    except Exception:
        return False



def remove_video_from_cached_indexes(video_id):
    vid=str(video_id or "").strip()
    result={}

    # Collections: remove membership, preserve collection itself.
    try:
        items=phase6_load_collections()
        changed=0
        for c in items:
            old=list(c.get("video_ids") or [])
            new=[x for x in old if str(x)!=vid]
            if len(new)!=len(old):
                c["video_ids"]=new
                changed+=len(old)-len(new)
        if changed:
            phase6_save_collections(items)
        result["collections_memberships"]=changed
    except Exception as ex:
        result["collections_error"]=str(ex)

    # Phase 5 / Phase 6 JSONL indexes.
    for label,p in [
        ("phase5_search",phase5_search_index_path()),
        ("phase6_chunks",phase6_chunk_index_path()),
    ]:
        try:
            if not p.exists():
                result[label]=0
                continue
            kept=[];removed=0
            for line in p.read_text(encoding="utf-8",errors="replace").splitlines():
                if not line.strip():
                    continue
                try:
                    obj=json.loads(line)
                    if str(obj.get("video_id") or "")==vid:
                        removed+=1
                        continue
                except Exception:
                    pass
                kept.append(line)
            p.write_text(("\n".join(kept)+("\n" if kept else "")),encoding="utf-8")
            result[label]=removed
        except Exception as ex:
            result[label+"_error"]=str(ex)

    # ChatGPT intelligence: remove matching standalone records and matching
    # video_updates/source_mapping elements while retaining unrelated content.
    try:
        p=phase6_intelligence_dir()/"library_intelligence.jsonl"
        removed=0;kept_records=[]
        if p.exists():
            for line in p.read_text(encoding="utf-8",errors="replace").splitlines():
                if not line.strip():
                    continue
                try:
                    obj=json.loads(line)
                except Exception:
                    kept_records.append(line)
                    continue
                if str(obj.get("video_id") or "")==vid:
                    removed+=1
                    continue
                if isinstance(obj.get("video_updates"),list):
                    before=len(obj["video_updates"])
                    obj["video_updates"]=[x for x in obj["video_updates"] if not (isinstance(x,dict) and str(x.get("video_id") or "")==vid)]
                    removed+=before-len(obj["video_updates"])
                if isinstance(obj.get("source_mapping"),list):
                    before=len(obj["source_mapping"])
                    obj["source_mapping"]=[x for x in obj["source_mapping"] if not (isinstance(x,dict) and str(x.get("video_id") or "")==vid)]
                    removed+=before-len(obj["source_mapping"])
                kept_records.append(json.dumps(obj,ensure_ascii=False))
            p.write_text(("\n".join(kept_records)+("\n" if kept_records else "")),encoding="utf-8")
        result["chatgpt_intelligence"]=removed
    except Exception as ex:
        result["chatgpt_intelligence_error"]=str(ex)

    # Taxonomy processed state.
    try:
        state_path=phase6_taxonomy_status_path()
        if state_path.exists():
            obj=json.loads(state_path.read_text(encoding="utf-8"))
            ids=[str(x) for x in obj.get("processed_video_ids",[]) if str(x)!=vid]
            obj["processed_video_ids"]=ids
            obj["updated_at"]=time.strftime("%Y-%m-%d %H:%M:%S")
            state_path.write_text(json.dumps(obj,indent=2),encoding="utf-8")
            result["taxonomy_processed_removed"]=1
    except Exception as ex:
        result["taxonomy_processed_error"]=str(ex)

    return result


def purge_video_everywhere(video_id,trigger_folder=""):
    """
    Purge one exact VIDEO_ID from:
      - concrete filesystem artifacts
      - all recognized SQLite VIDEO_ID tables
      - collections / Phase5 / Phase6 / ChatGPT intelligence caches
      - transcript retry and failure history
    """
    vid=str(video_id or "").strip()
    if not vid:
        raise ValueError("Video ID is required for purge")

    paths=collect_video_related_paths(vid)
    deleted=[];failed=[]

    for p in paths:
        try:
            p=Path(p)
            if not p.exists():
                continue
            if p.is_dir():
                shutil.rmtree(p)
            else:
                p.unlink()
            deleted.append(str(p))
        except Exception as ex:
            failed.append((str(p),f"{type(ex).__name__}: {ex}"))

    db_removed={}
    try:
        db_removed=remove_video_db_records(vid)
    except Exception as ex:
        failed.append(("SQLite",f"{type(ex).__name__}: {ex}"))

    cache_removed={}
    try:
        cache_removed=remove_video_from_cached_indexes(vid)
    except Exception as ex:
        failed.append(("Cached indexes",f"{type(ex).__name__}: {ex}"))

    try:
        state=load_transcript_retry_state()
        if vid in state:
            state.pop(vid,None)
            save_transcript_retry_state(state)
    except Exception:
        pass

    try:
        csv_path=failed_videos_csv_path()
        if csv_path.exists():
            with open(csv_path,"r",newline="",encoding="utf-8-sig") as f:
                rows=list(csv.DictReader(f))
            rows=[
                r for r in rows
                if str(r.get("Video ID") or r.get("video_id") or "")!=vid
            ]
            fields=[
                "Timestamp","Video ID","URL","Title","Channel","Stage",
                "Error Type","Error Message","Folder","Retry Status"
            ]
            with open(csv_path,"w",newline="",encoding="utf-8-sig") as f:
                w=csv.DictWriter(f,fieldnames=fields,extrasaction="ignore")
                w.writeheader();w.writerows(rows)
            rebuild_failure_details_txt()
            rebuild_failed_videos_txt()
    except Exception:
        pass

    try:remove_empty_channel_after_purge(trigger_folder)
    except Exception:pass

    try:export_csv()
    except Exception as ex:failed.append(("video_list.csv",f"{type(ex).__name__}: {ex}"))

    return deleted,db_removed,failed



def create_delete_marker_for_video(video_id):
    vid=str(video_id or "").strip()
    if not vid:
        return False,"Video ID is required"

    # Confirm ID exists in DB OR a strong folder/media match exists.
    folder=locate_existing_folder(vid)
    exists_db=False
    try:
        con=db_connect()
        exists_db=bool(con.execute("SELECT 1 FROM videos WHERE video_id=?",(vid,)).fetchone())
        con.close()
    except Exception:
        pass

    if not exists_db and not folder:
        return False,f"Video ID not found: {vid}"

    marker=delete_queue_marker_path(vid)
    payload={
        "video_id":vid,
        "created_at":time.strftime("%Y-%m-%d %H:%M:%S"),
        "source_folder":str(folder or ""),
        "requested_by":"browser/dashboard"
    }
    try:
        marker.write_text(json.dumps(payload,indent=2,ensure_ascii=False),encoding="utf-8")
        return True,f"Delete queued for VIDEO_ID {vid}: {marker}"
    except Exception as ex:
        return False,f"{type(ex).__name__}: {ex}"



def process_delete_markers():
    """
    Process:
      1) maintenance/delete_queue/*.delete.json (preferred; exact VIDEO_ID encoded)
      2) legacy downloads/**/.delete markers

    A request is removed only after a purge completes without filesystem/DB errors.
    """
    requests=[]

    # New safe queue.
    for marker in sorted(delete_queue_dir().glob("*.delete.json")):
        vid,obj=read_delete_queue_marker(marker)
        requests.append({
            "marker":marker,
            "video_id":vid,
            "folder":str((obj or {}).get("source_folder") or ""),
            "kind":"queue"
        })

    # Legacy .delete support.
    if DOWNLOADS.exists():
        for marker in sorted(DOWNLOADS.rglob(".delete")):
            if "_staging" in marker.parts or not marker.is_file():
                continue
            vid=""
            # If someone manually wrote the Video ID inside .delete, use it.
            try:
                txt=marker.read_text(encoding="utf-8",errors="ignore").strip()
                if txt:
                    vid=txt.splitlines()[0].strip()
            except Exception:
                pass
            if not vid:
                vid=find_video_id_from_folder(marker.parent)
            requests.append({
                "marker":marker,
                "video_id":vid,
                "folder":str(marker.parent),
                "kind":"legacy"
            })

    if not requests:
        print("No delete requests found.")
        return 0

    processed=0;skipped=0;failed_count=0
    seen=set()

    for req in requests:
        marker=Path(req["marker"])
        vid=str(req.get("video_id") or "").strip()
        folder=str(req.get("folder") or "")

        if not vid:
            print(f"SKIP: could not resolve Video ID for {folder or marker}")
            print("      Legacy empty .delete marker cannot safely identify one video.")
            skipped+=1
            continue

        # Prevent double-processing if both queue + legacy marker exist.
        if vid in seen:
            try:
                if req["kind"]=="queue" and marker.exists():
                    marker.unlink()
            except Exception:
                pass
            continue
        seen.add(vid)

        print(f"PURGE VIDEO_ID {vid}")
        guard_title="";guard_channel=""
        try:
            con=db_connect();row=con.execute("SELECT COALESCE(original_title,''),COALESCE(channel,'') FROM videos WHERE video_id=?",(vid,)).fetchone();con.close()
            if row:
                guard_title,guard_channel=str(row[0] or ""),str(row[1] or "")
        except Exception:
            pass
        deleted,db_removed,failed=purge_video_everywhere(vid,folder)
        db_rows=sum(v for v in db_removed.values() if isinstance(v,int) and v>0)
        print(f"  Deleted paths: {len(deleted)}")
        print(f"  DB rows      : {db_rows}")
        if failed:
            print(f"  Failures     : {len(failed)}")
            for p,err in failed[:10]:
                print(f"    - {p}: {err}")
            failed_count+=1
            # Keep queue request for retry.
            if req["kind"]=="queue":
                try:
                    obj=json.loads(marker.read_text(encoding="utf-8"))
                    obj["last_attempt"]=time.strftime("%Y-%m-%d %H:%M:%S")
                    obj["last_failures"]=[{"path":p,"error":e} for p,e in failed]
                    marker.write_text(json.dumps(obj,indent=2,ensure_ascii=False),encoding="utf-8")
                except Exception:
                    pass
            continue

        # Success: retain only the minimal hidden history used by the re-download guard.
        try:
            remember_deleted_video_for_redownload_guard(vid,guard_title,guard_channel)
        except Exception as ex:
            print(f"  Re-download guard history warning: {type(ex).__name__}: {ex}")
        # Remove request marker.
        try:
            if marker.exists():
                marker.unlink()
        except Exception:
            pass
        processed+=1

    print(f"Delete processing complete: success={processed}, failed={failed_count}, skipped={skipped}")
    return processed


def cleanup_empty_staging():
    root=staging_root()
    removed=0
    for p in sorted(root.iterdir()):
        if not p.is_dir():
            continue
        try:
            # remove empty nested _data
            d=p/"_data"
            if d.exists() and not any(d.iterdir()):
                d.rmdir()
            if not any(p.iterdir()):
                p.rmdir()
                removed+=1
        except Exception:
            pass
    print(f"Removed empty staging folders: {removed}")
    return removed

def remove_all_empty_library_folders():
    """
    Remove truly empty directories under downloads, deepest-first.

    Safety:
    - never removes DOWNLOADS itself;
    - does not process the _staging subtree (cleanup_empty_staging owns it);
    - skips symlinks;
    - never removes a directory containing any file/subfolder.
    """
    root=Path(DOWNLOADS)
    if not root.exists():
        print("Remove All Empty Library Folders: downloads folder does not exist.")
        return {"removed":0,"failed":0,"scanned":0,"paths":[]}

    try:
        staging=staging_root().resolve()
    except Exception:
        staging=(root/"_staging").resolve()

    candidates=[]
    try:
        for p in root.rglob("*"):
            try:
                if not p.is_dir() or p.is_symlink():
                    continue
                rp=p.resolve()
                if rp==staging or staging in rp.parents:
                    continue
                candidates.append(p)
            except Exception:
                pass
    except Exception as ex:
        print(f"Empty-library scan warning: {type(ex).__name__}: {ex}")

    candidates.sort(key=lambda p:len(p.parts),reverse=True)
    removed=[]
    failed=0
    scanned=0

    for p in candidates:
        if web_stop_requested():
            print("Remove All Empty Library Folders stopped by user.")
            break
        scanned+=1
        try:
            # Only remove if it is STILL completely empty at removal time.
            if p.exists() and p.is_dir() and not any(p.iterdir()):
                p.rmdir()
                removed.append(str(p))
                print(f"REMOVED empty library folder: {p}")
        except Exception as ex:
            failed+=1
            print(f"FAILED empty library folder {p}: {type(ex).__name__}: {ex}")

    print("")
    print("Remove All Empty Library Folders complete")
    print(f"Scanned : {scanned}")
    print(f"Removed : {len(removed)}")
    print(f"Failed  : {failed}")
    return {"removed":len(removed),"failed":failed,"scanned":scanned,"paths":removed}


def cleanup_all_empty_folders():
    """
    Combined empty-folder cleanup requested for the dashboard:
      1) Clean Empty Staging
      2) Remove Empty Legacy ChatGPT Folders
      3) Remove All Empty Library Folders

    Only truly empty folders are removed.
    """
    print("")
