def find_first(folder,patterns):
    for pat in patterns:
        xs=list(folder.glob(pat))
        if xs: return xs[0]
    return None


def structured_sections_from_timestamped(timestamped_text, max_seconds=150):
    lines=[x.strip() for x in (timestamped_text or "").splitlines() if x.strip()]
    tr=re.compile(r'^\\[(\\d{2}:\\d{2}:\\d{2})\\]\\s*(.*)$')
    chunks=[]; cur=[]; start=None; end=None; bucket=None

    for line in lines:
        m=tr.match(line)
        if not m:
            continue
        ts,body=m.group(1),m.group(2).strip()
        if not body:
            continue
        now=sec(ts)
        if bucket is None:
            bucket=now
            start=ts
        if cur and now-bucket>=max_seconds:
            chunks.append((start,end," ".join(cur)))
            cur=[]; bucket=now; start=ts
        cur.append(body)
        end=ts
    if cur:
        chunks.append((start,end," ".join(cur)))

    stop={"this","that","with","from","your","have","will","into","about","they",
          "their","there","then","when","what","which","just","also","because",
          "video","speaker","today","friends","these","those","them","some"}

    result=[]
    for i,(st,en,body) in enumerate(chunks,1):
        words=re.findall(r"[A-Za-z][A-Za-z'-]+",body)
        key=[]; seen=set()
        for w in words:
            lw=w.lower()
            if len(w)>=4 and lw not in stop and lw not in seen:
                key.append(w)
                seen.add(lw)
            if len(key)>=5:
                break
        title=" ".join(key) if key else f"Section {i}"
        sentences=re.split(r'(?<=[.!?])\\s+',body)
        overview=" ".join(sentences[:4]).strip() or " ".join(body.split()[:100])
        result.append({
            "chapter_title":title,
            "start":st or "00:00:00",
            "end":en or st or "00:00:00",
            "overview":overview,
            "source_text":body,
            "detailed_summary":extractive_detailed_summary(body),
            "topics":key,
            "ingredients_or_entities":[],
            "instructions":[],
            "claims":[],
            "key_points":[],
            "tags":[]
        })
    return result

def chapters_are_useful(sections):
    if not sections:
        return False

    generic_words={"discussion","section","chapter","video","part","introduction","overview"}
    for item in sections:
        title=str(item.get("chapter_title") or item.get("title") or "").strip()
        overview=str(item.get("overview") or item.get("detailed_summary") or "").strip()
        if not title or len(overview)<=40:
            return False

        low=title.lower().strip()
        if re.fullmatch(r'(discussion|section|chapter|video discussion|video section|part)\s*\d*',low):
            return False

        tokens=[x.lower() for x in re.findall(r"[A-Za-z][A-Za-z'-]+",title)]
        if tokens and all(t in generic_words for t in tokens):
            return False

        # Reject headings with no overlap to section source text when source exists.
        source=str(item.get("source_text") or "").lower()
        if source and tokens:
            meaningful=[t for t in tokens if t not in generic_words and len(t)>3]
            if meaningful and not any(t in source for t in meaningful):
                return False

    return True


def rebuild_sections_for_report(video_id, original_title, use_llm):
    p=temp_paths(video_id)
    candidates=[
        p["dir"]/f"{video_id}.timestamped.en.txt",
        p["timestamped"]
    ]
    ts_path=next((x for x in candidates if x.exists() and x.stat().st_size>0),None)
    if not ts_path:
        return []

    ts=ts_path.read_text(encoding="utf-8",errors="replace")

    if p["chapters"].exists():
        try:
            cached=json.loads(p["chapters"].read_text(encoding="utf-8"))
            if chapters_are_useful(cached):
                return cached
        except Exception:
            pass

    if use_llm:
        try:
            identity,chapters,translated=analyze_video_once(video_id,original_title,ts,"en")
            if chapters_are_useful(chapters):
                p["chapters"].write_text(
                    json.dumps(chapters,ensure_ascii=False,indent=2),
                    encoding="utf-8"
                )
                return chapters
        except Exception as ex:
            log(f"Semantic chapter rebuild failed {video_id}: {ex}")

    chapters=structured_sections_from_timestamped(ts)
    if chapters:
        p["chapters"].write_text(
            json.dumps(chapters,ensure_ascii=False,indent=2),
            encoding="utf-8"
        )
    return chapters



def htmlify_description(desc):
    raw=(desc or "").strip()
    if not raw:
        return "<p>No description available.</p>"

    def linkify_line(line):
        escaped=html.escape(line)

        # http / https
        escaped=re.sub(
            r'(https?://[^\s<>"\']+)',
            r'<a href="\1" target="_blank" rel="noopener noreferrer">\1</a>',
            escaped,
            flags=re.I
        )

        # www without protocol
        escaped=re.sub(
            r'(?<!["/>])(www\.[A-Za-z0-9.-]+\.[A-Za-z]{2,}(?:/[^\s<>"\']*)?)',
            r'<a href="https://\1" target="_blank" rel="noopener noreferrer">\1</a>',
            escaped,
            flags=re.I
        )
        return escaped

    paras=[]
    for block in re.split(r'\n\s*\n',raw):
        block=block.strip()
        if not block:
            continue
        rendered="<br>".join(linkify_line(line) for line in block.splitlines())
        paras.append(f"<p>{rendered}</p>")

    return "".join(paras) or "<p>No description available.</p>"


def timestamped_rows(timestamped_text):
    rows=[]
    rx=re.compile(r'^\[(\d{2}:\d{2}:\d{2})\]\s*(.*)$')
    for line in (timestamped_text or "").splitlines():
        m=rx.match(line.strip())
        if m and m.group(2).strip():
            rows.append((sec(m.group(1)),m.group(1),m.group(2).strip()))
    return rows

def section_source_text(timestamped_text,start,end):
    rows=timestamped_rows(timestamped_text)
    if not rows:
        return ""
    start_s=sec(start or "00:00:00")
    end_s=sec(end or "99:59:59")
    return " ".join(
        body for seconds,_,body in rows
        if start_s <= seconds <= end_s
    ).strip()

def attach_source_text_to_sections(video_id,sections):
    """
    Attach transcript text strictly bounded by each section's start/end timestamps.
    Always refresh source_text so stale cached ranges cannot leak across chapters.
    """
    if not sections:
        return sections

    p=temp_paths(video_id)
    candidates=[
        p["dir"]/f"{video_id}.timestamped.en.txt",
        p["timestamped"]
    ]
    ts_path=next((x for x in candidates if x.exists() and x.stat().st_size>0),None)
    if not ts_path:
        return sections

    timestamped=ts_path.read_text(encoding="utf-8",errors="replace")

    for item in sections:
        start=item.get("start","00:00:00")
        end=item.get("end","99:59:59")
        item["source_text"]=section_source_text(timestamped,start,end)

        enrich=section_enrichment_from_source(item)
        item["main_idea"]=enrich["main_idea"]
        item["derived_keywords"]=enrich["keywords"]
        if not item.get("instructions"):
            item["instructions"]=enrich["instructions"]
        if not item.get("claims"):
            item["claims"]=enrich["claims"]
        item["relevance"]=enrich["relevance"]
        item["observations"]=enrich["observations"]
        item["takeaways"]=enrich["takeaways"]

        # Keep a true detailed summary for display.

    return sections


def extractive_detailed_summary(source_text,max_sentences=8,max_chars=1800):
    src=re.sub(r'\s+',' ',source_text or "").strip()
    if not src:
        return ""

    sentences=[
        x.strip() for x in re.split(r'(?<=[.!?])\s+',src)
        if x.strip()
    ]
    if not sentences:
        return src[:max_chars]

    unique=[]
    seen=set()
    for sentence in sentences:
        key=re.sub(r'[^a-z0-9]+',' ',sentence.lower()).strip()
        if key and key not in seen:
            seen.add(key)
            unique.append(sentence)

    if len(unique)<=max_sentences:
        selected=unique
    else:
        mid=max(4,len(unique)//2)
        selected=unique[:4] + unique[mid:mid+2] + unique[-2:]

    out=" ".join(selected).strip()
    if len(out)>max_chars:
        out=out[:max_chars].rsplit(" ",1)[0].rstrip(" ,;:-")+"."
    return out




def meaningful_section_summary(section,max_chars=2200):
    """
    Build a readable section summary from this section's own timestamp-bounded
    source_text. This is not a line-by-line transcript dump.
    """
    source=re.sub(r'\s+',' ',str(section.get("source_text") or "")).strip()
    overview=str(section.get("overview") or "").strip()
    direct=str(section.get("detailed_summary") or "").strip()

    # Prefer a genuine LLM summary if it is meaningfully different from overview.
    if direct and direct != overview and len(direct) > 100:
        return direct

    if not source:
        return direct or overview or "No summary available for this section."

    sentences=[x.strip() for x in re.split(r'(?<=[.!?])\s+',source) if x.strip()]
    unique=[]
    seen=set()
    for sentence in sentences:
        key=re.sub(r'[^a-z0-9]+',' ',sentence.lower()).strip()
        if not key or key in seen:
            continue
        seen.add(key)
        unique.append(sentence)

    if not unique:
        return source[:max_chars]

    # Build a coherent representative summary: beginning + middle + ending.
    if len(unique) <= 6:
        selected=unique
    else:
        mid=len(unique)//2
        selected=unique[:3] + unique[mid:mid+2] + unique[-2:]

    summary=" ".join(selected).strip()
    if len(summary) > max_chars:
        summary=summary[:max_chars].rsplit(" ",1)[0].rstrip(" ,;:-")+"."
    return summary

def detailed_summary_bullets(section,max_points=10):
    """
    Bullet-point detailed summary using only this section's source_text.
    It does not pull information from outside the start/end time range.
    """
    source=re.sub(r'\s+',' ',str(section.get("source_text") or "")).strip()
    if not source:
        overview=str(section.get("overview") or "").strip()
        return [overview] if overview else []

    sentences=[x.strip() for x in re.split(r'(?<=[.!?])\s+',source) if x.strip()]

    unique=[]
    seen=set()
    for sentence in sentences:
        key=re.sub(r'[^a-z0-9]+',' ',sentence.lower()).strip()
        if not key or key in seen:
            continue
        seen.add(key)
        unique.append(sentence)

    if len(unique)<=max_points:
        return unique

    # Representative coverage from the whole section.
    positions=[
        0,1,2,
        len(unique)//3,
        len(unique)//2,
        (2*len(unique))//3,
        len(unique)-3,
        len(unique)-2,
        len(unique)-1
    ]
    selected=[]
    for pos in positions:
        if 0 <= pos < len(unique):
            sentence=unique[pos]
            if sentence not in selected:
                selected.append(sentence)
        if len(selected)>=max_points:
            break
    return selected[:max_points]

def section_enrichment_from_source(section):
    """
    Build a richer mini-report strictly from this section's timestamp-bounded
    source_text. No information from outside the section is introduced.
    """
    source=re.sub(r'\s+',' ',str(section.get("source_text") or "")).strip()
    overview=str(section.get("overview") or "").strip()

    # Basic sentence segmentation.
    sentences=[x.strip() for x in re.split(r'(?<=[.!?])\s+',source) if x.strip()]

    # Lightweight entity extraction from existing transcript words.
    words=re.findall(r"[A-Za-z][A-Za-z'-]+",source)
    stop={
        "this","that","with","from","your","have","will","into","about","they","their",
        "there","then","when","what","which","just","also","because","video","speaker",
        "today","friends","these","those","them","some","very","more","been","being",
        "were","would","could","should","than","where","while","such","only","first"
    }
    freq={}
    original_case={}
    for w in words:
        lw=w.lower()
        if len(w)>=4 and lw not in stop:
            freq[lw]=freq.get(lw,0)+1
            original_case.setdefault(lw,w)
    keywords=[original_case[k] for k,_ in sorted(freq.items(),key=lambda x:(-x[1],x[0]))[:10]]

    # Instructions / process phrases strictly from source.
    instructions=[]
    instruction_markers=(
        "first ","then ","next ","after that ","step ","take ","add ","mix ",
        "harvest ","wash ","cut ","place ","pour ","keep ","leave ","store ",
        "apply ","boil ","roast ","grind ","soak ","dry ","plant ","water "
    )
    for sent in sentences:
        low=sent.lower()
        if any(m in low for m in instruction_markers):
            instructions.append(sent)
        if len(instructions)>=8:
            break

    # Claims / observations from source.
    claims=[]
    claim_markers=(
        "helps ","can ","may ","supports ","improves ","reduces ","increases ",
        "works ","best ","better ","suitable ","used to ","gives ","allows "
    )
    for sent in sentences:
        low=sent.lower()
        if any(m in low for m in claim_markers):
            claims.append(sent)
        if len(claims)>=8:
            break

    # Who/why relevance.
    relevance=[]
    relevance_markers=("beginner","cooler climate","gardener","soap","hair","fabric","wool",
                       "Canada","Britain","northern","home","garden")
    for sent in sentences:
        if any(m.lower() in sent.lower() for m in relevance_markers):
            relevance.append(sent)
        if len(relevance)>=5:
            break

    # Important observations.
    observations=[]
    for sent in sentences[:12]:
        if sent not in instructions and sent not in claims:
            observations.append(sent)
        if len(observations)>=6:
            break

    # Key takeaways: representative statements from beginning/middle/end.
    takeaways=[]
    if sentences:
        positions=[0]
        if len(sentences)>2:
            positions.append(len(sentences)//2)
        if len(sentences)>1:
            positions.append(len(sentences)-1)
        seen=set()
        for pos in positions:
            sent=sentences[pos]
            if sent not in seen:
                seen.add(sent)
                takeaways.append(sent)

    detailed=extractive_detailed_summary(source,max_sentences=10,max_chars=2200)

    return {
        "main_idea": overview or (sentences[0] if sentences else ""),
        "keywords": keywords,
        "instructions": instructions,
        "claims": claims,
        "relevance": relevance,
        "observations": observations,
        "takeaways": takeaways,
        "detailed_summary": detailed,
    }

def detailed_summary_for_section(section):
    direct=str(section.get("detailed_summary") or "").strip()
    overview=str(section.get("overview") or "").strip()

    if direct and (not overview or direct != overview) and len(direct)>80:
        return direct

    source=str(section.get("source_text") or "").strip()
    extracted=extractive_detailed_summary(source)
    if extracted:
        return extracted

    parts=[]
    if overview:
        parts.append(overview)

    key_points=[
        str(x).strip() for x in (section.get("key_points") or [])
        if str(x).strip()
    ]
    if key_points:
        parts.append("Key details include " + "; ".join(key_points[:8]) + ".")

    instructions=[
        str(x).strip() for x in (section.get("instructions") or [])
        if str(x).strip()
    ]
    if instructions:
        parts.append(
            "Steps or instructions mentioned: "
            + "; ".join(instructions[:8]) + "."
        )

    claims=[
        str(x).strip() for x in (section.get("claims") or [])
        if str(x).strip()
    ]
    if claims:
        parts.append(
            "Claims made in this section: "
            + "; ".join(claims[:6]) + "."
        )

    entities=[
        str(x).strip() for x in (section.get("ingredients_or_entities") or [])
        if str(x).strip()
    ]
    if entities:
        parts.append(
            "Important entities or ingredients: "
            + ", ".join(entities[:12]) + "."
        )

    return " ".join(parts).strip() or "No detailed section text was available."



def cleanup_obsolete_reports(folder,current_report_name):
    if not CFG.get("remove_obsolete_reports",True):
        return
    folder=Path(folder)
    for old in folder.glob("*.report.html"):
        if old.name!=current_report_name:
            try:
                old.unlink()
                log(f"Removed obsolete report: {old}")
            except Exception as e:
                log(f"Could not remove obsolete report {old}: {e}")


def ordered_video_neighbors(video_id):
    """
    Return previous and next videos in library order.
    Uses upload_date DESC, then rowid DESC for deterministic navigation.
    """
    vid=str(video_id or "")
    con=db_connect()
    rows=con.execute(
        """
        SELECT video_id,clean_title,original_title,local_folder,report_html,upload_date
        FROM videos
        WHERE downloaded=1
        ORDER BY COALESCE(upload_date,'' ) DESC, rowid DESC
        """
    ).fetchall()
    con.close()

    ids=[r[0] for r in rows]
    if vid not in ids:
        return None,None

    i=ids.index(vid)
    prev_row=rows[i-1] if i>0 else None
    next_row=rows[i+1] if i<len(rows)-1 else None
    return prev_row,next_row


def report_nav_info(video_id):
    prev_row,next_row=ordered_video_neighbors(video_id)

    def norm(row):
        if not row:
            return None
        vid,clean,orig,folder,report,upload_date=row
        title=clean or orig or vid
        href=""
        if report and Path(report).exists():
            href=Path(report).name
        elif folder and Path(folder).exists():
            rp=next(iter(Path(folder).glob("*.report.html")),None)
            if rp:
                href=rp.name
        return {
            "video_id":vid,
            "title":title,
            "href":href,
            "upload_date":upload_date or ""
        }

    return norm(prev_row),norm(next_row)


def html_video_nav(video_id):
    prev_info,next_info=report_nav_info(video_id)

    def button(info,label,shortcut):
        if not info or not info.get("href"):
            return f'<button class="nav-btn" disabled>{label}</button>'
        title=html.escape(str(info.get("title") or ""))
        href=html.escape(str(info.get("href") or ""))
        return (
            f'<a class="nav-btn" href="{href}" title="{title}" '
            f'data-shortcut="{shortcut}">{label}</a>'
        )

    prev_btn=button(prev_info,"◀ Previous Video","ArrowLeft")
    next_btn=button(next_info,"Next Video ▶","ArrowRight")

    return f"""
<div class="video-nav">
  {prev_btn}
  {next_btn}
</div>
<script>
document.addEventListener('keydown', function(e) {{
  if (e.target && ['INPUT','TEXTAREA'].includes(e.target.tagName)) return;
  if (e.key === 'ArrowLeft') {{
    const a=document.querySelector('.nav-btn[data-shortcut="ArrowLeft"]');
    if (a) window.location.href=a.href;
  }}
  if (e.key === 'ArrowRight') {{
    const a=document.querySelector('.nav-btn[data-shortcut="ArrowRight"]');
    if (a) window.location.href=a.href;
  }}
}});
</script>
"""



def taxonomy_hash_for_video(video_id):
    tax=canonical_taxonomy_for_video(video_id)
    payload={
        "category":str(tax.get("category") or "").strip(),
        "subcategory":str(tax.get("subcategory") or "").strip(),
        "tags":sorted(str(x).strip() for x in (tax.get("tags") or []) if str(x).strip())
    }
    return hashlib.sha256(
        json.dumps(payload,ensure_ascii=False,sort_keys=True).encode("utf-8")
    ).hexdigest()


def update_taxonomy_tracking(video_id):
    vid=str(video_id or "").strip()
    if not vid:
        return
    h=taxonomy_hash_for_video(vid)
    con=db_connect()
    con.execute(
        "UPDATE videos SET taxonomy_hash=?,taxonomy_updated_at=? WHERE video_id=?",
        (h,time.strftime("%Y-%m-%d %H:%M:%S"),vid)
    )
    con.commit()
    con.close()


def backup_current_taxonomy(label="pre_import"):
    out_dir=BASE/"data"/"knowledge"/"taxonomy_backups"
    out_dir.mkdir(parents=True,exist_ok=True)
    stamp=time.strftime("%Y%m%d_%H%M%S")
    out=out_dir/f"taxonomy_{label}_{stamp}.jsonl"

    con=db_connect()
    cols=video_table_columns()
    selected=[c for c in [
        "video_id","clean_title","original_title","channel",
        "primary_category","primary_topic","topics_json",
        "taxonomy_hash","taxonomy_updated_at"
    ] if c in cols]
    rows=con.execute(
        "SELECT "+",".join(f'"{c}"' for c in selected)+" FROM videos ORDER BY rowid"
    ).fetchall()
    con.close()

    with open(out,"w",encoding="utf-8") as f:
        for row in rows:
            f.write(json.dumps(dict(zip(selected,row)),ensure_ascii=False)+"\n")
    return out


def taxonomy_audit_rows():
    docs=phase5_load_search_index()
    rows=[]
    usage=Counter()
    for d in docs:
        usage.update(d.get("topics") or [])

    seen_norm=defaultdict(list)
    for tag in usage:
        seen_norm[phase5_normalize_tag(tag)].append(tag)

    duplicate_groups={
        norm:vals for norm,vals in seen_norm.items()
        if norm and len(set(vals))>1
    }

    for d in docs:
        issues=[]
        tags=d.get("topics") or []
        category=str(d.get("category") or "").strip()
        subcategory=str(d.get("subcategory") or "").strip()

        if not category or category=="Other":
            issues.append("Missing/Other category")
        if not subcategory or subcategory=="General":
            issues.append("Missing/General subcategory")
        if not tags:
            issues.append("No tags")
        if len(tags)>12:
            issues.append("Too many tags")
        if len(tags)==1:
            issues.append("Only one tag")

        generic={"Video","YouTube","Tips","Information","General","Miscellaneous","Explained"}
        if any(t in generic for t in tags):
            issues.append("Generic tag")

        if any(phase5_contains_devanagari(t) for t in tags+[category,subcategory]):
            issues.append("Non-English taxonomy")

        normalized=[phase5_normalize_tag(t) for t in tags]
        if len(normalized)!=len(set(normalized)):
            issues.append("Duplicate/synonym tags in video")

        if issues:
            rows.append({
                "Video ID":d.get("video_id",""),
                "Title":d.get("title",""),
                "Category":category,
                "Subcategory":subcategory,
                "Tags":" | ".join(tags),
                "Issues":"; ".join(sorted(set(issues)))
            })
    return rows,usage,duplicate_groups


def phase5_export_taxonomy_audits():
    root=phase5_dirs()[0]
    audit_dir=root/"audits"
    audit_dir.mkdir(parents=True,exist_ok=True)

    rows,usage,duplicate_groups=taxonomy_audit_rows()

    quality=audit_dir/"taxonomy_quality_audit.csv"
    with open(quality,"w",newline="",encoding="utf-8-sig") as f:
        fields=["Video ID","Title","Category","Subcategory","Tags","Issues"]
        w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)

    tag_usage=audit_dir/"tag_usage.csv"
    with open(tag_usage,"w",newline="",encoding="utf-8-sig") as f:
        w=csv.writer(f);w.writerow(["Tag","Video Count","Rare Tag"])
        for tag,count in usage.most_common():
            w.writerow([tag,count,"YES" if count<=1 else ""])

    dup=audit_dir/"tag_duplicate_candidates.csv"
    with open(dup,"w",newline="",encoding="utf-8-sig") as f:
        w=csv.writer(f);w.writerow(["Canonical Form","Variants"])
        for norm,vals in sorted(duplicate_groups.items()):
            w.writerow([norm," | ".join(sorted(set(vals)))])

    stats=audit_dir/"taxonomy_statistics.csv"
    docs=phase5_load_search_index()
    categories=Counter(d.get("category") or "Other" for d in docs)
    subcategories=Counter(d.get("subcategory") or "General" for d in docs)
    with open(stats,"w",newline="",encoding="utf-8-sig") as f:
        w=csv.writer(f)
        w.writerow(["Metric","Value"])
        w.writerow(["Videos",len(docs)])
        w.writerow(["Categories",len(categories)])
        w.writerow(["Subcategories",len(subcategories)])
        w.writerow(["Unique Tags",len(usage)])
        w.writerow(["Videos With Taxonomy Issues",len(rows)])
        w.writerow(["Rare Tags (1 video)",sum(1 for c in usage.values() if c==1)])
        w.writerow(["Duplicate Tag Candidate Groups",len(duplicate_groups)])
        w.writerow(["Generated At",time.strftime("%Y-%m-%d %H:%M:%S")])

    return quality,tag_usage,dup,stats


def phase5_integrity_audit():
    docs=phase5_load_search_index()
    out=phase5_dirs()[0]/"audits"/"library_integrity_audit.csv"
    out.parent.mkdir(parents=True,exist_ok=True)

    rows=[]
    for d in docs:
        folder=Path(d.get("local_folder") or "")
        media_ok=False
        report_ok=False
        thumb_ok=False

        try:
            inv=artifact_inventory(d.get("video_id"),folder if folder.exists() else None)
            media_ok=bool(inv.get("media") and Path(inv.get("media")).exists())
            thumb_ok=bool(inv.get("thumbnail") and Path(inv.get("thumbnail")).exists())
        except Exception:
            pass

        try:
            report=d.get("report_html") or ""
            report_ok=bool(report and Path(report).exists())
        except Exception:
            pass

        issues=[]
        if not folder.exists(): issues.append("Missing folder")
        if not media_ok: issues.append("Missing media")
        if not report_ok: issues.append("Missing report")
        if not thumb_ok: issues.append("Missing thumbnail")

        if issues:
            rows.append([
                d.get("video_id",""),d.get("title",""),d.get("channel",""),
                str(folder),"; ".join(issues)
            ])

    with open(out,"w",newline="",encoding="utf-8-sig") as f:
        w=csv.writer(f)
        w.writerow(["Video ID","Title","Channel","Folder","Issues"])
        w.writerows(rows)

    return out,len(rows)



def embedded_taxonomy_hash_from_report(report_path):
    try:
        p=Path(report_path)
        if not p.exists():
            return ""
        content=p.read_text(encoding="utf-8",errors="replace")
        m=re.search(
            r'<meta\b[^>]*\bname=["\']video-library-taxonomy-hash["\'][^>]*\bcontent=["\']([^"\']+)["\'][^>]*>',
            content,
            re.I
        )
        if not m:
            m=re.search(
                r'<meta\b[^>]*\bcontent=["\']([^"\']+)["\'][^>]*\bname=["\']video-library-taxonomy-hash["\'][^>]*>',
                content,
                re.I
            )
        return m.group(1).strip() if m else ""
    except Exception:
        return ""


def force_rebuild_all_video_reports():
    con=db_connect()
    rows=con.execute(
        "SELECT video_id,local_folder FROM videos WHERE downloaded=1 ORDER BY rowid"
    ).fetchall()
    con.close()

    rebuilt=failed=0
    for vid,folder in rows:
        try:
            if not folder or not Path(folder).exists():
                failed+=1
                continue
            title=resolved_approved_title(vid)
            ok,message=rebuild_report_after_rename(
                vid,
                Path(folder),
                title
            )
            if not ok:
                failed+=1
                log(f"Force HTML rebuild failed {vid}: {message}")
                continue
            tax_hash=taxonomy_hash_for_video(vid)
            con=db_connect()
            con.execute(
                "UPDATE videos SET html_report_taxonomy_hash=?,html_report_updated_at=? WHERE video_id=?",
                (tax_hash,time.strftime("%Y-%m-%d %H:%M:%S"),vid)
            )
            con.commit();con.close()
            rebuilt+=1
        except Exception as ex:
            failed+=1
            log(f"Force HTML rebuild failed {vid}: {type(ex).__name__}: {ex}")

    print(f"Force HTML rebuild complete: rebuilt={rebuilt}, failed={failed}")
    return rebuilt,failed


def smart_rebuild_reports_for_taxonomy(force=False):
    con=db_connect()
    cols=video_table_columns()
    needed={
        "video_id","local_folder","report_html",
        "taxonomy_hash","html_report_taxonomy_hash"
    }
    if not needed.issubset(cols):
        con.close()
        return 0,0,0

    rows=con.execute(
        "SELECT video_id,local_folder,report_html,taxonomy_hash,html_report_taxonomy_hash "
        "FROM videos WHERE downloaded=1 ORDER BY rowid"
    ).fetchall()
    con.close()

    rebuilt=skipped=failed=0
    for vid,folder,report_html,tax_hash,stored_report_hash in rows:
        try:
            current_hash=taxonomy_hash_for_video(vid)

            if not tax_hash or tax_hash!=current_hash:
                con=db_connect()
                con.execute(
                    "UPDATE videos SET taxonomy_hash=?,taxonomy_updated_at=? WHERE video_id=?",
                    (current_hash,time.strftime("%Y-%m-%d %H:%M:%S"),vid)
                )
                con.commit();con.close()

            actual_report_hash=embedded_taxonomy_hash_from_report(report_html)

            needs_rebuild=force
            if not report_html or not Path(report_html).exists():
                needs_rebuild=True
            elif not actual_report_hash:
                needs_rebuild=True
            elif actual_report_hash!=current_hash:
                needs_rebuild=True
            elif stored_report_hash!=current_hash:
                con=db_connect()
                con.execute(
                    "UPDATE videos SET html_report_taxonomy_hash=?,html_report_updated_at=? WHERE video_id=?",
                    (current_hash,time.strftime("%Y-%m-%d %H:%M:%S"),vid)
                )
                con.commit();con.close()

            if not needs_rebuild:
                skipped+=1
                continue

            if not folder or not Path(folder).exists():
                failed+=1
                continue

            title=resolved_approved_title(vid)
            rebuild_ok,rebuild_message=rebuild_report_after_rename(
                vid,
                Path(folder),
                title
            )
            if not rebuild_ok:
                failed+=1
                log(f"Taxonomy HTML rebuild failed {vid}: {rebuild_message}")
                continue

            con=db_connect()
            row=con.execute(
                "SELECT report_html FROM videos WHERE video_id=?",
                (vid,)
            ).fetchone()
            con.close()

            final_report=row[0] if row else report_html
            final_hash=embedded_taxonomy_hash_from_report(final_report)

            if final_hash!=current_hash:
                failed+=1
                log(
                    f"Taxonomy HTML verification failed {vid}: "
                    f"expected={current_hash} actual={final_hash or 'MISSING'}"
                )
                continue

            con=db_connect()
            con.execute(
                "UPDATE videos SET html_report_taxonomy_hash=?,html_report_updated_at=? WHERE video_id=?",
                (current_hash,time.strftime("%Y-%m-%d %H:%M:%S"),vid)
            )
            con.commit();con.close()
            rebuilt+=1

        except Exception as ex:
            failed+=1
            log(f"Taxonomy smart report rebuild failed {vid}: {type(ex).__name__}: {ex}")

    return rebuilt,skipped,failed


def canonical_taxonomy_for_video(video_id):
    vid=str(video_id or "").strip()
    if not vid:
        return {"category":"","subcategory":"","tags":[]}

    cols=video_table_columns()
    selected=[c for c in ["primary_category","primary_topic","topics_json"] if c in cols]
    if not selected:
        return {"category":"","subcategory":"","tags":[]}

    con=db_connect()
    row=con.execute(
        "SELECT "+",".join(f'"{c}"' for c in selected)+" FROM videos WHERE video_id=?",
        (vid,)
    ).fetchone()
    con.close()

    if not row:
        return {"category":"","subcategory":"","tags":[]}

    rec=dict(zip(selected,row))
    tags=[]
    try:
        tags=_json_list(rec.get("topics_json") or "[]")
    except Exception:
        tags=[]

    return {
        "category":str(rec.get("primary_category") or ""),
        "subcategory":str(rec.get("primary_topic") or ""),
        "tags":phase5_canonical_topics(tags)
    }


