def transcript_archive_category(video_id):
    """
    Decide where a temp transcript belongs AFTER the video itself exists.

    tmp/transcripts is reserved for videos whose media is still not downloaded.

    Archive categories are based on local/source artifacts:
      complete
      subtitle_missing
      description_missing
      thumbnail_missing
      info_json_missing
      multiple_artifacts_missing
    """
    folder=locate_existing_folder(video_id)
    if not folder:
        return "video_not_downloaded", {"video":False}

    folder=Path(folder)
    media=find_any_media(folder)
    if not media or not media.exists() or media.stat().st_size<=0:
        return "video_not_downloaded", {"video":False}

    data=support_dir(folder)

    def nonzero(p):
        try:
            return bool(p and Path(p).exists() and Path(p).stat().st_size>0)
        except Exception:
            return False

    subtitle=None
    for pat in ("*.srt","*.vtt"):
        subtitle=next(iter(data.glob(pat)),None)
        if subtitle:
            break

    description=next(iter(data.glob("*.description")),None)
    thumbnail=None
    for pat in ("*.jpg","*.jpeg","*.png","*.webp"):
        thumbnail=next(iter(data.glob(pat)),None)
        if thumbnail:
            break
    info_json=next(iter(data.glob("*.info.json")),None)
    try:
        con=db_connect();canonical_meta=canonical_metadata_available(con,video_id);con.close()
    except Exception:
        canonical_meta=False

    transcript_canonical=next(iter(data.glob(f"{video_id}.transcript.txt")),None) or next(iter(data.glob("*.transcript.txt")),None)
    transcript_ts=transcript_canonical or next(iter(data.glob("*.transcript_timestamped.txt")),None)
    transcript_clean=transcript_canonical or next(iter(data.glob("*.transcript_clean.txt")),None)

    status={
        "video":True,
        "subtitle":nonzero(subtitle),
        "transcript_timestamped":nonzero(transcript_ts),
        "transcript_clean":nonzero(transcript_clean),
        "description":nonzero(description),
        "thumbnail":nonzero(thumbnail),
        "info_json":nonzero(info_json),
        "canonical_metadata":bool(canonical_meta),
        "metadata":bool(canonical_meta or nonzero(info_json))
    }

    # Dedicated category when BOTH subtitle and transcript are unavailable.
    if not status["subtitle"] and not status["transcript_timestamped"] and not status["transcript_clean"]:
        return "transcription_missing",status

    missing=[k for k in ("description","thumbnail","metadata") if not status[k]]

    if not missing:
        return "complete",status
    if len(missing)>1:
        return "multiple_artifacts_missing",status
    return f"{missing[0]}_missing",status



def cleanup_temp_after_success(video_id, reason="Successful video processing"):
    """
    Move successful regular/short temp data out of tmp.
    Keep temp data only when the actual media is still missing.
    """
    vid=str(video_id or "").strip()
    if not vid:
        return "SKIP","Missing Video ID",""

    candidates=[
        temp_transcript_root()/vid,
        temp_short_video_root()/vid,
    ]
    src=next((p for p in candidates if p.exists()),None)
    if src is None:
        return "SKIP","No temp folder",""

    category,status=transcript_archive_category(vid)
    if category=="video_not_downloaded":
        return "KEEP","Video media not downloaded; temp retained",str(src)

    dest=transcript_archive_root()/category/vid
    dest.parent.mkdir(parents=True,exist_ok=True)

    try:
        if dest.exists():
            for child in list(src.iterdir()):
                target=dest/child.name
                if target.exists():
                    try:
                        if child.is_file() and target.is_file() and files_equal(child, target):
                            child.unlink()
                            continue
                    except Exception:
                        pass
                    target=unique_conflict_path(target, marker="archive")
                shutil.move(str(child),str(target))
            try:
                src.rmdir()
            except Exception:
                pass
        else:
            shutil.move(str(src),str(dest))

        manifest={
            "video_id":vid,
            "category":category,
            "short_video":src.parent==temp_short_video_root(),
            "reason":reason,
            "artifact_status":status,
            "archived_at":time.strftime("%Y-%m-%d %H:%M:%S")
        }
        (dest/"archive_status.json").write_text(
            json.dumps(manifest,ensure_ascii=False,indent=2),
            encoding="utf-8"
        )
        return "MOVED",category,str(dest)
    except Exception as ex:
        return "FAILED",f"{type(ex).__name__}: {ex}",str(src)

def move_temp_transcript_out_of_tmp(video_id, reason=""):
    """
    If media exists, move tmp/transcripts/<VideoID> to a categorized archive.
    If media does not exist, leave it in tmp/transcripts.
    """
    vid=str(video_id or "").strip()
    if not vid:
        return "SKIP","Missing Video ID",""

    src=temp_transcript_root()/vid
    if not src.exists():
        return "SKIP","No temp transcript folder",""

    category,status=transcript_archive_category(vid)

    if category=="video_not_downloaded":
        return "KEEP", "Video media not downloaded; transcript remains in tmp", str(src)

    dest_root=transcript_archive_root()/category
    dest_root.mkdir(parents=True,exist_ok=True)
    dest=dest_root/vid

    # Merge safely if an old archive already exists.
    try:
        if dest.exists():
            for item in list(src.iterdir()):
                target=dest/item.name
                if target.exists():
                    # Discard only byte-identical duplicates; preserve different content.
                    try:
                        if item.is_file() and target.is_file() and files_equal(item, target):
                            item.unlink()
                            continue
                    except Exception:
                        pass

                    target=unique_conflict_path(target, marker="archive")

                shutil.move(str(item),str(target))

            try:
                src.rmdir()
            except Exception:
                pass
        else:
            shutil.move(str(src),str(dest))

        manifest={
            "video_id":vid,
            "category":category,
            "reason":reason,
            "artifact_status":status,
            "archived_at":time.strftime("%Y-%m-%d %H:%M:%S")
        }
        (dest/"archive_status.json").write_text(
            json.dumps(manifest,ensure_ascii=False,indent=2),
            encoding="utf-8"
        )
        return "MOVED",category,str(dest)

    except Exception as ex:
        return "FAILED",f"{type(ex).__name__}: {ex}",str(src)



def reconcile_existing_video_failures():
    """
    For already-downloaded videos, clear false failure status caused only by
    missing subtitles/transcripts/description/thumbnail/info/report.
    Keep failure only if media itself is missing.
    Also classify transcript-missing videos.
    """
    con=db_connect()
    rows=con.execute(
        "SELECT video_id,url,original_title,clean_title,channel,local_folder,local_video FROM videos ORDER BY rowid"
    ).fetchall()
    con.close()

    cleared=0
    kept=0
    transcript_missing=0
    details=[]

    for vid,url,orig,clean,channel,db_folder,db_video in rows:
        folder=locate_existing_folder(vid)
        if folder is None and db_folder and Path(db_folder).exists():
            folder=Path(db_folder)

        media=None
        if folder:
            media=find_any_media(folder)
        if not media and db_video and Path(db_video).exists():
            media=Path(db_video)

        if not media or not Path(media).exists() or Path(media).stat().st_size<=0:
            kept+=1
            details.append((vid,"KEEP_FAIL","Video media missing",""))
            continue

        # media exists => download itself is successful
        con=db_connect()
        con.execute(
            "UPDATE videos SET downloaded=1,current_present=1,deleted_from_library=0,deleted_at=NULL,last_error='' WHERE video_id=?",
            (vid,)
        )
        con.commit()
        con.close()
        try: forget_deleted_video_redownload_guard(vid)
        except Exception: pass
        mark_failed_video_retry_status(vid,"RESOLVED")
        cleared+=1

        category,status=transcript_archive_category(vid)
        if category=="transcription_missing":
            transcript_missing+=1

        details.append((
            vid,
            "RESOLVED",
            "Video downloaded; non-video artifact failures ignored",
            category
        ))

    rebuild_failed_videos_txt()

    out=BASE/"maintenance"/"audits"/"existing_video_failure_reconcile.csv"
    out.parent.mkdir(parents=True,exist_ok=True)
    with open(out,"w",newline="",encoding="utf-8-sig") as f:
        w=csv.writer(f)
        w.writerow(["Video ID","Action","Reason","Transcript/Artifact Category"])
        w.writerows(details)

    print("")
    print("Existing video failure reconciliation")
    print(f"Resolved because video exists : {cleared}")
    print(f"Still failed - video missing  : {kept}")
    print(f"Transcription missing         : {transcript_missing}")
    print(f"Audit                         : {out}")
    return out


def cleanup_resolved_tmp_remnants():
    actions=[]

    for root in [temp_transcript_root(),temp_short_video_root()]:
        if not root.exists():
            continue

        for item in sorted(root.iterdir()):
            if not item.is_dir():
                continue

            vid=item.name.strip()
            folder=locate_existing_folder(vid)
            media=find_any_media(folder) if folder else None

            try:
                media_ok=bool(media and Path(media).exists() and Path(media).stat().st_size>0)
            except Exception:
                media_ok=False

            if not media_ok:
                actions.append((vid,"KEEP","Video media missing",str(item),""))
                continue

            if has_usable_transcript(vid):
                dest=BASE/"maintenance"/"transcript_archive"/"resolved_tmp_duplicates"/vid
                dest.parent.mkdir(parents=True,exist_ok=True)
                try:
                    if dest.exists():
                        shutil.rmtree(dest,ignore_errors=True)
                    shutil.move(str(item),str(dest))
                    actions.append((vid,"ARCHIVE","Resolved temp duplicate",str(item),str(dest)))
                except Exception as ex:
                    actions.append((vid,"FAIL",f"{type(ex).__name__}: {ex}",str(item),""))
            else:
                dest=transcript_archive_root()/"transcription_missing"/vid
                dest.parent.mkdir(parents=True,exist_ok=True)
                try:
                    if dest.exists():
                        shutil.rmtree(dest,ignore_errors=True)
                    shutil.move(str(item),str(dest))
                    actions.append((vid,"ARCHIVE","Video exists; transcription missing",str(item),str(dest)))
                except Exception as ex:
                    actions.append((vid,"FAIL",f"{type(ex).__name__}: {ex}",str(item),""))

    out=BASE/"maintenance"/"audits"/"resolved_tmp_cleanup.csv"
    out.parent.mkdir(parents=True,exist_ok=True)
    with open(out,"w",newline="",encoding="utf-8-sig") as f:
        w=csv.writer(f)
        w.writerow(["Video ID","Action","Reason","Source","Destination"])
        w.writerows(actions)

    print("")
    print("Resolved tmp cleanup complete")
    print(f"Audit: {out}")
    return out

def cleanup_old_temp_transcripts():
    """
    Apply transcript tmp policy to all existing old transcript folders.

    Result:
      tmp/transcripts contains ONLY videos with no downloaded media.
    """
    rows=[]
    roots=[temp_transcript_root(),temp_short_video_root()]

    for root in roots:
        if not root.exists():
            continue
        for item in sorted(root.iterdir()):
            if not item.is_dir():
                continue
            vid=item.name.strip()

            # Existing transcript cleanup helper operates on tmp/transcripts.
            # For short_videos, keep undownloaded items in place; archive downloaded
            # short temp folders using the same artifact categories.
            if root==temp_transcript_root():
                action,reason,path=move_temp_transcript_out_of_tmp(
                    vid,"Old temp transcript cleanup"
                )
            else:
                category,status=transcript_archive_category(vid)
                if category=="video_not_downloaded":
                    action,reason,path="KEEP","Short video media not downloaded; remains in tmp/short_videos",str(item)
                else:
                    dest=transcript_archive_root()/category/vid
                    dest.parent.mkdir(parents=True,exist_ok=True)
                    try:
                        if dest.exists():
                            for child in list(item.iterdir()):
                                target=dest/child.name
                                if target.exists():
                                    target=unique_conflict_path(target, marker="archive")
                                shutil.move(str(child),str(target))
                            item.rmdir()
                        else:
                            shutil.move(str(item),str(dest))
                        manifest={
                            "video_id":vid,
                            "category":category,
                            "short_video":True,
                            "artifact_status":status,
                            "archived_at":time.strftime("%Y-%m-%d %H:%M:%S")
                        }
                        (dest/"archive_status.json").write_text(
                            json.dumps(manifest,ensure_ascii=False,indent=2),
                            encoding="utf-8"
                        )
                        action,reason,path="MOVED",f"short_video/{category}",str(dest)
                    except Exception as ex:
                        action,reason,path="FAILED",f"{type(ex).__name__}: {ex}",str(item)

            rows.append((vid,action,reason,path))
            print(f"{action:<6} {vid} | {reason}")
            if path:
                print(f"       {path}")

    audit=BASE/"maintenance"/"audits"/"temp_transcript_cleanup.csv"
    audit.parent.mkdir(parents=True,exist_ok=True)
    with open(audit,"w",newline="",encoding="utf-8-sig") as f:
        w=csv.writer(f)
        w.writerow(["Video ID","Action","Category/Reason","Path"])
        w.writerows(rows)

    kept=sum(1 for _,a,_,_ in rows if a=="KEEP")
    moved=sum(1 for _,a,_,_ in rows if a=="MOVED")
    failed=sum(1 for _,a,_,_ in rows if a=="FAILED")

    print("")
    print("Temp transcript cleanup complete")
    print(f"Moved out of tmp : {moved}")
    print(f"Kept in tmp      : {kept}  (video not downloaded)")
    print(f"Failed           : {failed}")
    print(f"Audit            : {audit}")


def temp_transcript_problem_queue():
    """
    Show only temp transcript folders whose media still does not exist.
    """
    root=temp_transcript_root()
    problems=[]
    for item in sorted(root.iterdir()):
        if not item.is_dir():
            continue
        vid=item.name
        category,status=transcript_archive_category(vid)
        if category=="video_not_downloaded":
            problems.append(vid)

    print("")
    print("===== TEMP TRANSCRIPT PROBLEM QUEUE =====")
    if not problems:
        print("No transcript folders remain for undownloaded videos.")
        return

    for i,vid in enumerate(problems,1):
        print(f"{i}. {vid} | Video not downloaded | {root/vid}")

    print(f"Total: {len(problems)}")

    shorts=[]
    sroot=temp_short_video_root()
    for item in sorted(sroot.iterdir()):
        if not item.is_dir():
            continue
        vid=item.name
        category,status=transcript_archive_category(vid)
        if category=="video_not_downloaded":
            shorts.append(vid)

    print("")
    print("===== SHORT VIDEO PROBLEM QUEUE =====")
    if not shorts:
        print("No undownloaded short videos in tmp/short_videos.")
    else:
        for i,vid in enumerate(shorts,1):
            print(f"{i}. {vid} | Short video not downloaded | {sroot/vid}")
        print(f"Total shorts: {len(shorts)}")


def failed_videos_txt_path():
    path=BASE/"logs"/"failed_videos.txt"
    path.parent.mkdir(parents=True,exist_ok=True)
    return path


def unresolved_failed_video_ids():
    path=failed_videos_csv_path()
    if not path.exists():
        return set()
    ids=set()
    try:
        with open(path,"r",newline="",encoding="utf-8-sig") as f:
            for row in csv.DictReader(f):
                status=str(row.get("Retry Status") or "PENDING").upper()
                vid=str(row.get("Video ID") or "").strip()
                if vid and status not in ("RESOLVED","SUCCESS"):
                    ids.add(vid)
    except Exception:
        pass
    return ids


def rebuild_failed_videos_txt():
    csv_path=failed_videos_csv_path()
    txt_path=failed_videos_txt_path()

    if not csv_path.exists():
        txt_path.write_text("No unresolved failed videos.\n",encoding="utf-8")
        return txt_path

    latest={}
    try:
        with open(csv_path,"r",newline="",encoding="utf-8-sig") as f:
            for row in csv.DictReader(f):
                vid=str(row.get("Video ID") or "").strip()
                if vid:
                    latest[vid]=row
    except Exception as ex:
        txt_path.write_text(f"Could not read failed_videos.csv: {ex}\n",encoding="utf-8")
        return txt_path

    lines=[]
    for vid,row in latest.items():
        status=str(row.get("Retry Status") or "PENDING").upper()
        if status in ("RESOLVED","SUCCESS"):
            continue
        lines.extend([
            f"Video ID: {vid}",
            f"URL: {row.get('URL','')}",
            f"Title: {row.get('Title','')}",
            f"Channel: {row.get('Channel','')}",
            f"Stage: {row.get('Stage','')}",
            f"Reason: {row.get('Error Type','')}: {row.get('Error Message','')}",
            f"Folder: {row.get('Folder','')}",
            f"Retry Status: {row.get('Retry Status','PENDING')}",
            "-"*80
        ])

    if not lines:
        lines=["No unresolved failed videos."]

    txt_path.write_text("\n".join(lines)+"\n",encoding="utf-8")
    return txt_path


