    try:
        with open(path,"r",newline="",encoding="utf-8-sig") as f:
            rows=list(csv.DictReader(f))
        changed=False
        for row in rows:
            if (
                str(row.get("Video ID") or "")==str(video_id)
                and str(row.get("Retry Status") or "PENDING").upper()
                    not in ("RESOLVED","SUCCESS")
            ):
                row["Retry Status"]="RETRYING"
                changed=True
        if changed:
            fields=[
                "Timestamp","Video ID","URL","Title","Channel","Stage",
                "Error Type","Error Message","Folder","Retry Status"
            ]
            with open(path,"w",newline="",encoding="utf-8-sig") as f:
                w=csv.DictWriter(f,fieldnames=fields)
                w.writeheader()
                w.writerows(rows)
            rebuild_failed_videos_txt()
    except Exception:
        pass

