def rename_from_reviewed_csv(csv_path=None):
    """
    Apply reviewed titles AND folder migration from the reviewed CSV.
    Writes a complete result log:
      rename_review_results.csv
    """
    path=Path(csv_path) if csv_path else reviewed_titles_csv_path()
    result_path=BASE/"maintenance"/"audits"/"rename_review_results.csv"

    results=[]

    def record(vid,status,reason,old_title="",requested_title="",old_folder="",target_folder=""):
        results.append({
            "Video ID":vid,
            "Status":status,
            "Reason":reason,
            "Current Title":old_title,
            "Requested Title":requested_title,
            "Current Folder":old_folder,
            "Target Folder":target_folder
        })

    if not path.exists():
        print(f"Reviewed CSV not found: {path}")
        print("Run option 18 first.")
        return

    try:
        with open(path,"r",encoding="utf-8-sig",newline="") as f:
            reader=csv.DictReader(f)
            rows=list(reader)
            fieldnames=reader.fieldnames or []
    except Exception as ex:
        print(f"Could not read CSV: {type(ex).__name__}: {ex}")
        return

    if not rows:
        print("Reviewed CSV has no data rows.")
        return

    headers={str(x or "").strip() for x in fieldnames}
    if "Video ID" not in headers:
        print("CSV must contain a 'Video ID' column.")
        return

    allowed=("Approved Title","ChatGPT Title","New Title")
    if not any(c in headers for c in allowed):
        print("CSV must contain Approved Title, ChatGPT Title, or New Title.")
        return

    print(f"Using reviewed CSV: {path}")
    print("Title priority: Approved Title > ChatGPT Title > New Title")
    print("Folder format: Channel\\YYYY-MM-DD - Title")
    print("HTML report/video playback will be rebuilt and verified automatically.")

    renamed=0
    migrated=0
    skipped=0
    failed=0
    seen_ids=set()

    for row in rows:
        vid=str(row.get("Video ID") or "").strip()
        if not vid:
            skipped+=1
            record("", "SKIPPED", "Blank Video ID")
            continue

        if vid in seen_ids:
            failed+=1
            record(vid,"FAILED","Duplicate Video ID in reviewed CSV")
            print(f"FAILED {vid}: duplicate Video ID in CSV")
            continue
        seen_ids.add(vid)

        approved=""
        title_source=""
        for col in allowed:
            val=str(row.get(col) or "").strip()
            if val:
                approved=val
                title_source=col
                break

        if not approved:
            skipped+=1
            record(vid,"SKIPPED","No Approved Title / ChatGPT Title / New Title")
            continue

        con=db_connect()
        cols=video_table_columns()
        upload_expr="upload_date" if "upload_date" in cols else "NULL AS upload_date"
        channel_expr="channel" if "channel" in cols else "NULL AS channel"
        folder_expr="local_folder" if "local_folder" in cols else "NULL AS local_folder"
        dbrow=con.execute(f"""
          SELECT clean_title,{upload_expr},{channel_expr},{folder_expr}
          FROM videos WHERE video_id=?
        """,(vid,)).fetchone()
        con.close()

        if not dbrow:
            failed+=1
            record(vid,"FAILED","Video ID not found in SQLite",requested_title=approved)
            print(f"FAILED {vid}: Video ID not found in SQLite")
            continue

        current_title,db_upload_date,db_channel,db_folder=dbrow
        folder=locate_existing_folder(vid)
        if folder is None and db_folder:
            p=Path(db_folder)
            if p.exists():
                folder=p

        if folder is None:
            failed+=1
            record(vid,"FAILED","Video folder not found",
                   old_title=current_title or "",requested_title=approved)
            print(f"FAILED {vid}: Video folder not found")
            continue

        folder=Path(folder)
        csv_channel=str(row.get("Channel") or "").strip()
        channel,upload_date=resolve_folder_metadata(
            vid,folder,csv_channel or db_channel,db_upload_date
        )

        if not channel:
            failed+=1
            record(vid,"FAILED","Channel could not be resolved",
                   old_title=current_title or "",requested_title=approved,
                   old_folder=str(folder))
            print(f"FAILED {vid}: channel could not be resolved")
            continue

        if not upload_date:
            failed+=1
            record(vid,"FAILED","Upload date could not be resolved",
                   old_title=current_title or "",requested_title=approved,
                   old_folder=str(folder))
            print(f"FAILED {vid}: upload date could not be resolved")
            continue

        approved_safe=safe_name(approved,vid)
        desired_folder=video_folder_path(approved_safe,upload_date,channel)
        desired_name=desired_folder.name

        title_same=(safe_name(current_title or "",vid)==approved_safe)
        folder_same=(folder.resolve()==desired_folder.resolve())

        if title_same and folder_same:
            skipped+=1
            record(
                vid,"SKIPPED",
                f"Already correct ({title_source})",
                old_title=current_title or "",
                requested_title=approved_safe,
                old_folder=str(folder),
                target_folder=str(desired_folder)
            )
            print(f"SKIP {vid}: already correct")
            continue

        ok,msg=apply_title_to_video_id(
            vid,
            approved_safe,
            channel_override=channel,
            upload_date_override=upload_date
        )

        if ok:
            if title_same and not folder_same:
                migrated+=1
                status="MIGRATED"
                print(f"MIGRATED {vid}: {msg}")
            else:
                renamed+=1
                status="RENAMED"
                print(f"RENAMED {vid}: {msg}")

            record(
                vid,status,msg,
                old_title=current_title or "",
                requested_title=approved_safe,
                old_folder=str(folder),
                target_folder=str(desired_folder)
            )
        else:
            failed+=1
            record(
                vid,"FAILED",msg,
                old_title=current_title or "",
                requested_title=approved_safe,
                old_folder=str(folder),
                target_folder=str(desired_folder)
            )
            print(f"FAILED {vid}: {msg}")

    # Save detailed review result log before refreshing CSVs.
    with open(result_path,"w",newline="",encoding="utf-8-sig") as f:
        fields=[
            "Video ID","Status","Reason","Current Title","Requested Title",
            "Current Folder","Target Folder"
        ]
        w=csv.DictWriter(f,fieldnames=fields)
        w.writeheader()
        w.writerows(results)

    export_csv()
    try:
        export_csv_with_chatgpt_titles()
    except Exception as ex:
        print(f"Warning: review CSV refresh failed: {ex}")

    print("")
    print("Reviewed CSV migration complete")
    print(f"Title renamed  : {renamed}")
    print(f"Folder migrated: {migrated}")
    print(f"Skipped        : {skipped}")
    print(f"Failed         : {failed}")
    print(f"Details        : {result_path}")


