def bilingual_index_label(value):
    raw=str(value or "").strip()
    if not raw:
        return ""
    return BILINGUAL_INDEX_ALIASES.get(raw.lower(),raw)

def _json_list(value):
    try:
        x=json.loads(value or "[]")
        return [str(v).strip() for v in x if str(v).strip()] if isinstance(x,list) else []
    except Exception:
        return []

def build_library_indexes():
    """
    Build logical HTML indexes without moving/duplicating video files.
    """
    index_root=BASE/CFG.get("logical_index_folder","indexes")
    if index_root.exists():
        shutil.rmtree(index_root)
    index_root.mkdir(parents=True,exist_ok=True)

    cols=video_table_columns()
    wanted=[
        "video_id","original_title","clean_title","channel","upload_date",
        "primary_category","primary_topic","topics_json","entities_json",
        "herbs_json","products_json","report_html","local_folder"
    ]
    sql=select_existing_video_columns(wanted)
    con=db_connect()
    rows=con.execute(f"SELECT {sql} FROM videos ORDER BY rowid").fetchall()
    con.close()

    buckets={
        "By Channel":{},
        "By Category":{},
        "By Topic":{},
        "By Entity":{},
        "By Herb":{},
        "By Product":{},
    }

    for row in rows:
        (vid,orig,clean,channel,upload_date,primary_category,primary_topic,
         topics_json,entities_json,herbs_json,products_json,report_html,local_folder)=row
        item={
            "video_id":vid or "",
            "title":clean or orig or vid,
            "original_title":orig or "",
            "channel":channel or "",
            "upload_date":upload_date or "",
            "report_html":report_html or "",
            "local_folder":local_folder or ""
        }

        def add(bucket,key):
            key=bilingual_index_label(key)
            if not key:
                return
            buckets[bucket].setdefault(key,[]).append(item)

        add("By Channel",channel)
        add("By Category",primary_category)
        add("By Topic",primary_topic)
        for x in _json_list(topics_json): add("By Topic",x)
        for x in _json_list(entities_json): add("By Entity",x)
        for x in _json_list(herbs_json): add("By Herb",x)
        for x in _json_list(products_json): add("By Product",x)

    css="""body{font-family:Segoe UI,Arial;margin:24px;background:#f6f8fb;color:#1f2937}
    h1{margin-bottom:8px}.group{background:white;border-radius:12px;padding:16px;margin:14px 0;
    box-shadow:0 1px 6px rgba(0,0,0,.08)}a{text-decoration:none;color:#1d4ed8}
    .meta{color:#64748b;font-size:.9rem}"""

    # master index
    master=["<html><head><meta charset='utf-8'><style>"+css+"</style></head><body>",
            "<h1>Video Library Indexes</h1>"]
    for section,data in buckets.items():
        secdir=index_root/safe_name(section)
        secdir.mkdir(parents=True,exist_ok=True)
        master.append(f"<div class='group'><h2>{html.escape(section)}</h2><ul>")
        for key in sorted(data,key=str.lower):
            fname=safe_name(key)+".html"
            master.append(f"<li><a href='{html.escape(safe_name(section))}/{html.escape(fname)}'>{html.escape(key)}</a> ({len(data[key])})</li>")
            page=["<html><head><meta charset='utf-8'><style>"+css+"</style></head><body>",
                  f"<h1>{html.escape(section)}: {html.escape(key)}</h1>"]
            for item in data[key]:
                title=html.escape(str(item["title"]))
                report=item["report_html"]
                link=""
                if report:
                    try:
                        rel=Path(report).resolve().as_uri()
                        link=f"<a href='{html.escape(rel)}'>{title}</a>"
                    except Exception:
                        link=title
                else:
                    link=title
                page.append(
                    "<div class='group'>"
                    f"<div><b>{link}</b></div>"
                    f"<div class='meta'>{html.escape(item['upload_date'])} · {html.escape(item['channel'])} · {html.escape(item['video_id'])}</div>"
                    "</div>"
                )
            page.append("</body></html>")
            (secdir/fname).write_text("\n".join(page),encoding="utf-8")
        master.append("</ul></div>")
    master.append("</body></html>")
    (index_root/"index.html").write_text("\n".join(master),encoding="utf-8")
    print(f"Built logical indexes: {index_root/'index.html'}")
    return index_root/"index.html"



def _read_csv_metadata_for_video(video_id):
    paths=[
        reviewed_titles_csv_path(),
        main_video_csv_path()
    ]
    for path in paths:
        if not path.exists():
            continue
        try:
            with open(path,"r",encoding="utf-8-sig",newline="") as f:
                for row in csv.DictReader(f):
                    if str(row.get("Video ID") or "").strip()==str(video_id):
                        return {
                            "channel":str(row.get("Channel") or "").strip(),
                            "upload_date":str(row.get("Upload date") or row.get("Upload Date") or "").strip()
                        }
        except Exception:
            pass
    return {}

def _read_info_json_metadata(folder):
    # Phase 8 compatibility wrapper. The shared resolver keeps .info.json as a
    # fallback but prevents legacy readers from treating it as the first source.
    obj=read_info_json_metadata_fallback(folder)
    return {
        "channel":str(obj.get("channel") or "").strip(),
        "upload_date":str(obj.get("upload_date") or "").strip(),
    } if obj else {}

def resolve_folder_metadata(video_id,folder,db_channel="",db_upload_date=""):
    channel=str(db_channel or "").strip()
    upload_date=str(db_upload_date or "").strip()

    try:
        con=db_connect();canonical=canonical_db_metadata(con,video_id);con.close()
    except Exception:
        canonical={}
    csv_meta=_read_csv_metadata_for_video(video_id)
    info_meta=_read_info_json_metadata(folder)

    if not channel:
        channel=canonical.get("channel") or csv_meta.get("channel") or info_meta.get("channel") or ""

    if not upload_date:
        upload_date=canonical.get("upload_date") or csv_meta.get("upload_date") or info_meta.get("upload_date") or ""

    # Existing folder often begins YYYY-MM-DD - ...
    if not upload_date:
        m=re.match(r"^(\d{4}-\d{2}-\d{2})\s*-\s*",Path(folder).name)
        if m:
            upload_date=m.group(1)

    return channel.strip(),upload_date.strip()



def normalize_video_folder_length(video_id,folder,upload_date,title):
    folder=Path(folder)
    if not folder.exists():
        return folder

    current_title=re.sub(
        r"^\d{4}-\d{2}-\d{2}\s+-\s+",
        "",
        folder.name
    )

    if (
        len(current_title)<=MAX_VIDEO_TITLE_CHARS
        and len(str(folder))<=WINDOWS_SAFE_PATH_BUDGET
    ):
        return folder

    target=video_folder_path(
        title,
        upload_date,
        folder.parent.name,
        video_id
    )

    if folder.resolve()==target.resolve():
        return folder

    if target.exists():
        marker=target/".video_id"
        if marker.exists():
            try:
                if marker.read_text(
                    encoding="utf-8",
                    errors="ignore"
                ).strip()==str(video_id):
                    return target
            except Exception:
                pass
        raise FileExistsError(f"Target already exists: {target}")

    folder.rename(target)

    con=db_connect()
    con.execute(
        "UPDATE videos SET local_folder=? WHERE video_id=?",
        (str(target),str(video_id))
    )
    con.commit()
    con.close()

    return target

def migrate_existing_folders_to_50_char_titles():
    """
    Rename existing managed video folders to:
      Date - <title max 50 chars>

    Updates SQLite paths and repairs HTML playback links.
    """
    con=db_connect()
    rows=con.execute(
        "SELECT video_id,upload_date,clean_title,original_title,channel,local_folder "
        "FROM videos ORDER BY rowid"
    ).fetchall()
    con.close()

    moved=skipped=failed=0
    audit=[]

    for vid,upload_date,clean,orig,channel,db_folder in rows:
        folder=locate_existing_folder(vid)
        if folder is None and db_folder and Path(db_folder).exists():
            folder=Path(db_folder)

        if folder is None or not folder.exists():
            skipped+=1
            audit.append((vid,"SKIP","Folder not found","",""))
            continue

        parent=folder.parent
        title=resolved_approved_title(vid) or clean or orig or vid
        target=video_folder_path(title,upload_date,parent.name,vid)

        if folder.resolve()==target.resolve():
            skipped+=1
            audit.append((vid,"SKIP","Already compliant",str(folder),str(target)))
            continue

        try:
            if target.exists():
                # If same Video ID folder already exists, avoid destructive overwrite.
                marker=target/".video_id"
                if not (marker.exists() and marker.read_text(encoding="utf-8",errors="ignore").strip()==vid):
                    raise FileExistsError(f"Target already exists: {target}")

            folder.rename(target)

            con=db_connect()
            con.execute(
                "UPDATE videos SET local_folder=? WHERE video_id=?",
                (str(target),vid)
            )

            # Re-detect all key files after folder rename.
            media=find_any_media(target)
            report=next(iter(target.glob("*.report.html")),None)
            data=support_dir(target,create=True)

            con.execute(
                "UPDATE videos SET local_video=?,report_html=? WHERE video_id=?",
                (str(media or ""),str(report or ""),vid)
            )
            con.commit()
            con.close()

            try:
                rebuild_report_after_rename(vid,target,resolved_approved_title(vid))
            except Exception:
                pass

            moved+=1
            audit.append((vid,"MOVED","50-char folder rule",str(folder),str(target)))

        except Exception as ex:
            failed+=1
            audit.append((vid,"FAIL",f"{type(ex).__name__}: {ex}",str(folder),str(target)))

    out=BASE/"maintenance"/"audits"/"folder_title_50char_migration.csv"
    out.parent.mkdir(parents=True,exist_ok=True)
    with open(out,"w",newline="",encoding="utf-8-sig") as f:
        w=csv.writer(f)
        w.writerow(["Video ID","Action","Reason","Old Folder","New Folder"])
        w.writerows(audit)

    print("")
    print("50-character folder migration complete")
    print(f"Moved  : {moved}")
    print(f"Skipped: {skipped}")
    print(f"Failed : {failed}")
    print(f"Audit  : {out}")
    return out

def migrate_all_existing_folders_to_channel_format():
    """
    Bulk migrate every known video folder to:
      YYYY-MM-DD - Channel - Current Title

    Metadata resolution order:
      SQLite -> reviewed/main CSV -> info.json -> existing folder date prefix

    A folder is skipped ONLY if its current name exactly equals the fully-resolved
    desired folder name.
    """
    con=db_connect()
    cols=video_table_columns()
    upload_expr="upload_date" if "upload_date" in cols else "NULL AS upload_date"
    channel_expr="channel" if "channel" in cols else "NULL AS channel"
    rows=con.execute(f"""
      SELECT video_id,original_title,clean_title,{upload_expr},{channel_expr},local_folder
      FROM videos ORDER BY rowid
    """).fetchall()
    con.close()

    migrated=0
    skipped=0
    failed=0
    unresolved=0
    migration_results=[]
    result_path=BASE/"bulk_folder_migration_results.csv"

    for vid,orig,clean,db_upload_date,db_channel,db_folder in rows:
        title=clean or orig or vid

        folder=locate_existing_folder(vid)
        if folder is None and db_folder:
            p=Path(db_folder)
            if p.exists():
                folder=p

        if folder is None:
            failed+=1
            migration_results.append([vid,"FAILED","Folder not found","",""])
            print(f"FAILED {vid}: folder not found")
            continue

        folder=Path(folder)
        channel,upload_date=resolve_folder_metadata(
            vid,folder,db_channel,db_upload_date
        )

        if not channel:
            unresolved+=1
            migration_results.append([vid,"UNRESOLVED","Channel missing",str(folder),""])
            print(f"UNRESOLVED {vid}: channel missing; folder not renamed")
            continue

        if not upload_date:
            unresolved+=1
            migration_results.append([vid,"UNRESOLVED","Upload date missing",str(folder),""])
            print(f"UNRESOLVED {vid}: upload date missing; folder not renamed")
            continue

        desired_path=video_folder_path(title,upload_date,channel)
        desired=desired_path.name

        if folder.resolve()==desired_path.resolve():
            skipped+=1
            migration_results.append([vid,"SKIPPED","Already correct",str(folder),str(desired_path)])
            print(f"SKIP {vid}: already correct -> {desired}")
            continue

        ok,msg=apply_title_to_video_id(
            vid,
            title,
            channel_override=channel,
            upload_date_override=upload_date
        )

        if ok:
            # Ensure upload_date/channel are also persisted if recovered externally.
            con=db_connect()
            existing=video_table_columns()
            sets=[]
            vals=[]
            if "channel" in existing:
                sets.append("channel=?"); vals.append(channel)
            if "upload_date" in existing:
                sets.append("upload_date=?"); vals.append(upload_date)
            if sets:
                vals.append(vid)
                con.execute(
                    f"UPDATE videos SET {', '.join(sets)} WHERE video_id=?",
                    vals
                )
                con.commit()
            con.close()

            migrated+=1
            migration_results.append([vid,"MIGRATED","OK",str(folder),str(desired_path)])
            print(f"MIGRATED {vid}: {folder.name} -> {desired}")
        else:
            failed+=1
            migration_results.append([vid,"FAILED",msg,str(folder),str(desired_path)])
            print(f"FAILED {vid}: {msg}")

    export_csv()
    try:
        export_csv_with_chatgpt_titles()
    except Exception:
        pass

    with open(result_path,"w",newline="",encoding="utf-8-sig") as f:
        w=csv.writer(f)
        w.writerow(["Video ID","Status","Reason","Current Folder","Target Folder"])
        w.writerows(migration_results)

    print("")
    print("Bulk folder migration complete")
    print(f"Migrated : {migrated}")
    print(f"Skipped  : {skipped}")
    print(f"Unresolved metadata: {unresolved}")
    print(f"Failed   : {failed}")
    print(f"Details  : {result_path}")



def library_video_complete(video_id):
    """Return True only when the real library has a non-zero media file."""
    exists,folder=library_has_video(video_id)
    if not exists or not folder:
        return False,folder
    media=find_any_media(folder)
    if media and media.exists() and media.stat().st_size>0:
        return True,Path(folder)
    return False,Path(folder)

def library_has_video(video_id):
    """
    Authoritative duplicate check for Smart Resume.

    Existing library state is determined by Video ID using:
    1. _data/.video_id lookup
    2. SQLite local_folder/local_video/report_html fallback

    TMP/cache presence is NOT treated as a reason to download.
    """
    vid=str(video_id or "").strip()
    if not vid:
        return False,None

    folder=locate_existing_folder(vid)
    if folder:
        return True,Path(folder)

    con=db_connect()
    cols=video_table_columns()
    folder_expr="local_folder" if "local_folder" in cols else "NULL AS local_folder"
    video_expr="local_video" if "local_video" in cols else "NULL AS local_video"
    report_expr="report_html" if "report_html" in cols else "NULL AS report_html"
    row=con.execute(
        f"SELECT {folder_expr},{video_expr},{report_expr} FROM videos WHERE video_id=?",
        (vid,)
    ).fetchone()
    con.close()

    if not row:
        return False,None

    local_folder,local_video,report_html=row

    if local_folder:
        p=Path(local_folder)
        if p.exists():
            return True,p

    if local_video:
        p=Path(local_video)
        if p.exists() and p.stat().st_size>0:
            return True,p.parent

    if report_html:
        p=Path(report_html)
        if p.exists():
            return True,p.parent

    return False,None


def smart_resume_duplicate_audit():
    con=db_connect()
    rows=con.execute("SELECT video_id,original_title FROM videos ORDER BY rowid").fetchall()
    con.close()

    found_library=0
    tmp_present=0

    for vid,title in rows:
        exists,folder=library_has_video(vid)
        p=temp_paths(vid)
        tmp_exists=p["dir"].exists()

        if exists:
            found_library+=1
        if tmp_exists:
            tmp_present+=1

        print(
            f"{vid} | library={'YES' if exists else 'NO'} | "
            f"tmp={'YES' if tmp_exists else 'NO'} | "
            f"{folder or ''}"
        )

    print("")
    print("Smart Resume duplicate audit")
    print(f"DB videos         : {len(rows)}")
    print(f"Found in library  : {found_library}")
    print(f"TMP cache present : {tmp_present}")
    print("Rule: library=YES means Smart Resume should skip download; TMP is cache only.")


def _phase0_read_json(path):
    try:
        return json.loads(Path(path).read_text(encoding="utf-8"))
    except Exception:
        return None

def _phase0_expected_folder_name(title,upload_date):
    return folder_name_for(title,upload_date,None)

def phase0_validate_video_record(video_id):
    """
    Validate the Phase 0 core chain for one Video ID.
    Returns list of issue dictionaries.
    """
    issues=[]
    con=db_connect()
    cols=video_table_columns()
    select_cols=[
        "video_id","original_title","clean_title","channel","upload_date",
        "local_folder","local_video","report_html","chatgpt_imported",
        "chatgpt_summary_file","final_status","failure_reason"
    ]
    sql=select_existing_video_columns(select_cols)
    row=con.execute(f"SELECT {sql} FROM videos WHERE video_id=?",(video_id,)).fetchone()
    con.close()

    if not row:
        return [{
            "Video ID":video_id,
            "Check":"SQLite",
            "Status":"FAIL",
            "Reason":"Video ID not found in SQLite"
        }]

    (
        vid,orig,clean,channel,upload_date,local_folder,local_video,report_html,
        chatgpt_imported,chatgpt_summary_file,final_status,failure_reason
    )=row

    title=clean or orig or vid
    folder=locate_existing_folder(vid)

    def add(check,status,reason=""):
        issues.append({
            "Video ID":vid,
            "Check":check,
            "Status":status,
            "Reason":reason
        })

    # Folder presence + structure
    if not folder:
        add("Folder","FAIL","Video folder not found by Video ID")
        return issues

    folder=Path(folder)
    add("Folder","PASS",str(folder))

    if CFG.get("phase0_validate_folder_structure",True):
        if channel:
            expected_parent=channel_folder_name(channel)
            if folder.parent.name!=expected_parent:
                add("Channel Parent","WARN",f"Expected parent '{expected_parent}', found '{folder.parent.name}'")
            else:
                add("Channel Parent","PASS",expected_parent)

        expected_name=_phase0_expected_folder_name(title,upload_date)
        if folder.name!=expected_name:
            add("Folder Name","WARN",f"Expected '{expected_name}', found '{folder.name}'")
        else:
            add("Folder Name","PASS",expected_name)

    # .video_id
    marker=support_dir(folder)/".video_id"
    if marker.exists():
        marker_vid=marker.read_text(encoding="utf-8",errors="ignore").strip()
        add(".video_id","PASS" if marker_vid==vid else "FAIL",
            "" if marker_vid==vid else f"Marker contains {marker_vid}")
    else:
        add(".video_id","FAIL","Missing _data\\.video_id")

    # Video file
    media=find_any_media(folder)
    if media and media.exists() and media.stat().st_size>0:
        add("Video","PASS",media.name)
    else:
        add("Video","FAIL","Missing or zero-byte media file")

    # HTML report + video src
    report=Path(report_html) if report_html else None
    if not report or not report.exists():
        reports=list(folder.glob("*.report.html"))
        report=reports[0] if reports else None

    if report and report.exists() and report.stat().st_size>0:
        add("HTML Report","PASS",report.name)

        if CFG.get("phase0_validate_html_video_link",True):
            try:
                body=report.read_text(encoding="utf-8",errors="replace")
                current_media=find_any_media(folder)
                if current_media and current_media.name in body:
                    add("HTML Video Link","PASS",current_media.name)
                else:
                    add("HTML Video Link","FAIL",
                        f"Report does not reference current media: {current_media.name if current_media else 'None'}")
            except Exception as ex:
                add("HTML Video Link","FAIL",f"{type(ex).__name__}: {ex}")
    else:
        add("HTML Report","FAIL","Missing or zero-byte report")

    # ChatGPT canonical summary
    canonical=canonical_chatgpt_summary_path(folder,vid)
    imported=int(chatgpt_imported or 0)==1
    if imported:
        if canonical.exists() and canonical.stat().st_size>0:
            add("ChatGPT Summary File","PASS",canonical.name)
            if CFG.get("phase0_validate_chatgpt_json",True):
                obj=_phase0_read_json(canonical)
                if isinstance(obj,dict):
                    file_vid=str(obj.get("video_id") or "").strip()
                    if file_vid and file_vid!=vid:
                        add("ChatGPT JSON","FAIL",f"Video ID mismatch: {file_vid}")
                    else:
                        title_ok=bool(str(obj.get("meaningful_title") or obj.get("imported_title") or "").strip())
                        sections=obj.get("sections") or []
                        add("ChatGPT JSON","PASS" if title_ok else "WARN",
                            f"Sections: {len(sections) if isinstance(sections,list) else 0}")
                else:
                    add("ChatGPT JSON","FAIL","Invalid JSON")
        else:
            add("ChatGPT Summary File","FAIL","chatgpt_imported=1 but canonical summary is missing")

    return issues

def phase0_core_audit():
    """
    Audit the entire library and write:
      phase0_core_audit.csv
    """
    con=db_connect()
    rows=con.execute("SELECT video_id FROM videos WHERE COALESCE(current_present,1)=1 AND COALESCE(deleted_from_library,0)=0 ORDER BY rowid").fetchall()
    con.close()

    all_issues=[]
    for (vid,) in rows:
        all_issues.extend(phase0_validate_video_record(vid))

    output=BASE/"maintenance"/"audits"/"phase0_core_audit.csv"
    with open(output,"w",newline="",encoding="utf-8-sig") as f:
        fields=["Video ID","Check","Status","Reason"]
        w=csv.DictWriter(f,fieldnames=fields)
        w.writeheader()
        w.writerows(all_issues)

    counts={"PASS":0,"WARN":0,"FAIL":0}
    for item in all_issues:
        status=item["Status"]
        counts[status]=counts.get(status,0)+1

    print("")
    print("===== PHASE 0 CORE AUDIT =====")
    print(f"Videos checked : {len(rows)}")
    print(f"PASS           : {counts.get('PASS',0)}")
    print(f"WARN           : {counts.get('WARN',0)}")
    print(f"FAIL           : {counts.get('FAIL',0)}")
    print(f"Details        : {output}")
    return output,counts

def phase0_repair_html_video_links():
    """
    Repair only HTML reports whose embedded local media filename is stale.
    Uses canonical ChatGPT JSON when available.
    """
    con=db_connect()
    rows=con.execute("SELECT video_id FROM videos WHERE COALESCE(current_present,1)=1 AND COALESCE(deleted_from_library,0)=0 ORDER BY rowid").fetchall()
    con.close()

    repaired=0
    skipped=0
    failed=0

    for (vid,) in rows:
        folder=locate_existing_folder(vid)
        if not folder:
            failed+=1
            continue
        folder=Path(folder)
        media=find_any_media(folder)
        if not media:
            failed+=1
            continue

        reports=list(folder.glob("*.report.html"))
        if not reports:
            skipped+=1
            continue

        report=reports[0]
        try:
            body=report.read_text(encoding="utf-8",errors="replace")
            if media.name in body:
                skipped+=1
                continue
        except Exception:
            pass

        summary_obj,summary_path=load_chatgpt_summary_for_video(vid)
        if not summary_obj:
            failed+=1
            continue

        try:
            normalized=normalize_chatgpt_result_video(summary_obj)
            sections=normalized.get("sections") or []
            sections,ts_errors,ts_warnings=validate_and_normalize_sections(sections)

            con=db_connect()
            cols=video_table_columns()
            sql=select_existing_video_columns([
                "url","original_title","clean_title","channel","upload_date",
                "platform","description"
            ])
            row=con.execute(f"SELECT {sql} FROM videos WHERE video_id=?",(vid,)).fetchone()
            con.close()
            url,orig,clean,channel,upload_date,platform,db_description=row

            base=safe_name(clean or orig or vid,vid)
            description_file=find_first(support_dir(folder),[f"{base}.description","*.description"])
            description=(description_file.read_text(encoding="utf-8",errors="replace")
                         if description_file and description_file.exists() else (db_description or ""))

            meta={
                "video_id":vid,"url":url or "","original_title":orig or "",
                "clean_title":base,"channel":channel or "",
                "upload_date":upload_date or "","platform":platform or "",
                "category":str(summary_obj.get("category") or normalized.get("category") or ""),
                "subcategory":str(summary_obj.get("subcategory") or normalized.get("subcategory") or ""),
                "main_topic":"",
                "tags":", ".join(summary_obj.get("tags") or []) if isinstance(summary_obj.get("tags"),list) else str(summary_obj.get("tags") or ""),
                "description":description,
                "content_summary":str(summary_obj.get("summary") or summary_obj.get("overall_summary") or normalized.get("summary") or ""),
                "title_entities":"",
                "chatgpt_meaningful_title":str(summary_obj.get("meaningful_title") or base),
                "chatgpt_summary_only":True
            }

            new_report=write_html_report(folder,base,meta,media,sections)
            con=db_connect()
            con.execute("UPDATE videos SET report_html=? WHERE video_id=?",(str(new_report),vid))
            con.commit(); con.close()
            repaired+=1
            print(f"REPAIRED {vid}: {new_report.name}")
        except Exception as ex:
            failed+=1
            append_video_error(folder,safe_name(vid),"PHASE0 HTML VIDEO LINK REPAIR FAILED",
                               f"{type(ex).__name__}: {ex}",traceback.format_exc())

    print("")
    print("HTML video-link repair complete")
    print(f"Repaired: {repaired}")
    print(f"Skipped : {skipped}")
    print(f"Failed  : {failed}")

