def _extract_direct_video_id(url):
    return canonical_youtube_video_id(url)


def rows_for_current_urls():
    """
    Return only DB video rows corresponding to direct URLs currently in urls.txt.
    Channel/playlist URLs are intentionally not expanded here; use normal metadata
    pipeline for those.
    """
    urls=load_urls()
    direct_ids=[]
    exact_urls=set()
    for u in urls:
        vid=_extract_direct_video_id(u)
        if vid:
            direct_ids.append(vid)
        else:
            exact_urls.add(u)

    con=db_connect()
    rows=[]
    if direct_ids:
        q=",".join("?" for _ in direct_ids)
        rows.extend(con.execute(f"""
          SELECT video_id,url,original_title,clean_title,channel,upload_date,
                 platform,category,subcategory,main_topic,tags,description
          FROM videos WHERE video_id IN ({q})
        """,direct_ids).fetchall())
    if exact_urls:
        q=",".join("?" for _ in exact_urls)
        rows.extend(con.execute(f"""
          SELECT video_id,url,original_title,clean_title,channel,upload_date,
                 platform,category,subcategory,main_topic,tags,description
          FROM videos WHERE url IN ({q})
        """,list(exact_urls)).fetchall())
    con.close()

    dedup={}
    for r in rows:
        dedup[r[0]]=r
    return list(dedup.values())

def _current_url_failure_reason(video_id,folder=None,base=""):
    if not folder:
        folder=working_folder_for_video(video_id)
    con=db_connect()
    cols=video_table_columns()
    fail_expr="failure_reason" if "failure_reason" in cols else "'' AS failure_reason"
    err_expr="last_error" if "last_error" in cols else "'' AS last_error"
    row=con.execute(
        f"SELECT {fail_expr},{err_expr} FROM videos WHERE video_id=?",
        (video_id,)
    ).fetchone()
    con.close()
    if row:
        reason=str(row[0] or row[1] or "").strip()
        if reason:
            return reason[:1000]
    if folder and base:
        reason=read_video_error_reason(folder,base)
        if reason:
            return reason[:1000]
    return "Processing failed; see logs\\failed_videos.csv and the video's _data\\*.ERROR.txt"


def download_current_urls_pipeline(use_ollama=False):
    rotate_app_log_before_run()
    """
    Complete pipeline for ONLY direct video URLs currently in urls.txt.
    Ollama is an explicit per-run choice.
    Transcript/SRT/VTT is attempted first: retry at most twice; media download
    still proceeds for direct video links even when transcript is unavailable.
    """
    print("Current urls.txt - Complete Download Pipeline")
    print(f"Ollama / Local LLM: {'ENABLED' if use_ollama else 'DISABLED'}")
    print("Transcript: English -> Hindi -> any available language, max 2 attempts; media download still proceeds")

    old_use_llm=RUNTIME.get("use_llm")
    old_resume_mode=RUNTIME.get("resume_mode")
    old_smart_resume=RUNTIME.get("smart_resume")
    RUNTIME["use_llm"]=bool(use_ollama)
    RUNTIME["resume_mode"]="smart"
    RUNTIME["smart_resume"]=True

    results=[]
    try:
        choose_download_settings()
        CFG["download_video"]=True
        metadata_scan()
        rows=rows_for_current_urls()
        if not rows:
            print("No direct video URLs from urls.txt could be matched after metadata scan.")
            return

        quality=str(CFG.get("download_quality","1080"))

        for row in rows:
            vid,url,orig,clean,channel,upload_date=row[:6]
            title=clean or orig or vid
            item={"Video ID":vid,"Title":title,"Status":"","Stage":"","Reason":""}

            # Existing complete library item.
            sr=smart_resume_artifact_status(vid)
            if sr["action"]=="COMPLETE":
                item.update(Status="SKIPPED",Stage="Smart Resume",Reason=sr["reason"])
                results.append(item)
                continue

            # Transcript preparation for THIS selected URL.
            # Media download still proceeds if no usable transcript/SRT/VTT exists.
            trrow=None
            try:
                con=db_connect()
                trrow=con.execute(
                    """SELECT video_id,url,original_title,upload_date,subtitle_source,subtitle_lang,subtitle_base_lang
                       FROM videos WHERE video_id=?""",
                    (vid,)
                ).fetchone()
                con.close()
            except Exception as _trmeta_ex:
                log(f"Transcript metadata lookup warning {vid}: {_trmeta_ex}")

            tmsg="Not attempted"
            if trrow and not has_usable_transcript(vid):
                attempts=transcript_retry_count(vid)
                if attempts < 2:
                    increment_transcript_retry(vid,"Current URL transcript preparation")
                    try:
                        tok,tmsg=prepare_transcript_row(trrow)
                    except Exception as ex:
                        tok=False
                        tmsg=f"{type(ex).__name__}: {ex}"

                    if tok:
                        clear_transcript_retry(vid)
                    else:
                        log(
                            f"Transcript unavailable for {vid} "
                            f"(attempt {attempts+1}/2): {tmsg}. "
                            "Continuing with media download."
                        )
                else:
                    tmsg="Transcript unavailable after 2 attempts; ignored for media download"
            elif has_usable_transcript(vid):
                tmsg="Existing transcript reused"

            # Full processing always runs; media is the only hard requirement.
            try:
                ok=process_download(row,quality)
            except Exception as ex:
                ok=False
                folder=working_folder_for_video(vid)
                reason=f"{type(ex).__name__}: {ex}"
                try:
                    if folder:
                        append_video_error(folder,safe_name(title,vid),"DOWNLOAD/PROCESS FAILED",reason,traceback.format_exc())
                except Exception:
                    pass
                log_failed_video(vid,url,title,channel,"Download/Process",type(ex).__name__,reason,str(folder or ""),"PENDING")

            if ok:
                mark_failed_video_retry_status(vid,"RESOLVED")
                remove_video_from_failure_logs(vid)
                item.update(Status="SUCCESS",Stage="Complete",Reason=f"Media downloaded. Transcript: {tmsg}")
            else:
                folder=working_folder_for_video(vid)
                reason=_current_url_failure_reason(vid,folder,safe_name(title,vid))
                item.update(Status="FAILED",Stage="Download/Process",Reason=reason)
                log_failed_video(vid,url,title,channel,"Download/Process","ProcessingFailed",reason,str(folder or ""),"PENDING")
            results.append(item)

        export_csv()
        console_newline()

        print("\n===== CURRENT URL RESULTS =====")
        print(f"{'STATUS':9} {'VIDEO ID':14} {'STAGE':18} TITLE / REASON")
        print("-"*110)
        for r in results:
            print(f"{r['Status'][:9]:9} {r['Video ID'][:14]:14} {r['Stage'][:18]:18} {r['Title']}")
            print(f"{'':44} {r['Reason']}")

        success=sum(1 for r in results if r['Status']=='SUCCESS')
        skipped=sum(1 for r in results if r['Status']=='SKIPPED')
        failed=sum(1 for r in results if r['Status']=='FAILED')
        print("\nSummary:")
        print(f"  Success : {success}")
        print(f"  Skipped : {skipped}")
        print(f"  Failed  : {failed}")
        if failed:
            print(f"  Failure log: {failed_videos_csv_path()}")
            print(f"  App log    : {LOG}")

    finally:
        if old_use_llm is None: RUNTIME.pop("use_llm",None)
        else: RUNTIME["use_llm"]=old_use_llm
        if old_resume_mode is None: RUNTIME.pop("resume_mode",None)
        else: RUNTIME["resume_mode"]=old_resume_mode
        if old_smart_resume is None: RUNTIME.pop("smart_resume",None)
        else: RUNTIME["smart_resume"]=old_smart_resume



