def package_is_fully_complete(package_id):
    """
    A package is archive-eligible only when EVERY expected Video ID is:
      - represented in SQLite
      - chatgpt_imported=1
      - has a canonical summary file
      - has a valid report path/file
    and no manifest Video ID is missing.
    """
    manifest_path=phase2_find_manifest(package_id)
    if not manifest_path:
        return False,["Manifest not found"]

    try:
        manifest=json.loads(Path(manifest_path).read_text(encoding="utf-8"))
    except Exception as ex:
        return False,[f"Manifest unreadable: {ex}"]

    expected=[str(x) for x in (manifest.get("expected_video_ids") or []) if str(x).strip()]
    if not expected:
        return False,["Manifest has no expected Video IDs"]

    con=db_connect()
    q=",".join("?" for _ in expected)
    rows=con.execute(
        f"""SELECT video_id,chatgpt_imported,chatgpt_summary_file,report_html
            FROM videos WHERE video_id IN ({q})""",
        expected
    ).fetchall()
    con.close()

    found={r[0]:r for r in rows}
    problems=[]

    for vid in expected:
        row=found.get(vid)
        if not row:
            problems.append(f"{vid}: missing from SQLite")
            continue

        _,imported,summary_file,report_html=row

        if int(imported or 0)!=1:
            problems.append(f"{vid}: not imported")
            continue

        if not summary_file or not Path(summary_file).exists():
            problems.append(f"{vid}: canonical summary missing")

        if not report_html or not Path(report_html).exists():
            problems.append(f"{vid}: report missing")

    return len(problems)==0,problems


def phase2_package_problem_status(package_id):
    """
    Return current package-level unresolved problems for archive/retry decisions.
    """
    rows=phase2_package_status_rows(package_id)
    problems=[]
    for r in rows:
        if r["status"]!="IMPORTED":
            problems.append(f"{r['video_id']}: {r['reason']}")
    return problems

def auto_post_chatgpt_pipeline_for_videos(package_id, video_ids):
    """
    Run the post-ChatGPT chain only for the supplied Video IDs.

    Per-video flow:
      imported summary
      -> Phase 3 validation
      -> classify PASS/WARN/FAIL
      -> Phase 4 content intelligence
      -> report regenerate/verify
      -> DB/CSV refresh

    One failed video does not stop the others.
    """
    results=[]
    fail_ids=[]
    warn_ids=[]
    pass_ids=[]

    for vid in video_ids:
        row={
            "Video ID":vid,
            "Phase 3":"SKIPPED",
            "Phase 3 Score":"",
            "Phase 4":"SKIPPED",
            "Report":"SKIPPED",
            "Final":"UNKNOWN",
            "Reason":""
        }

        # Phase 3
        if CFG.get("auto_phase3_after_import",True):
            try:
                qreport,qerr=phase3_validate_video(vid)
                if qerr:
                    row["Phase 3"]="FAIL"
                    row["Final"]="FAIL"
                    row["Reason"]=qerr.get("fatal","Phase 3 validation failed")
                    fail_ids.append(vid)
                    results.append(row)
                    continue

                phase3_write_video_report(vid,qreport)
                q=qreport["quality"]
                row["Phase 3"]=q["status"]
                row["Phase 3 Score"]=q["score"]

                if q["status"]=="FAIL":
                    fail_ids.append(vid)
                elif q["status"]=="WARN":
                    warn_ids.append(vid)
                else:
                    pass_ids.append(vid)

            except Exception as ex:
                row["Phase 3"]="FAIL"
                row["Final"]="FAIL"
                row["Reason"]=f"Phase 3 exception: {type(ex).__name__}: {ex}"
                fail_ids.append(vid)
                results.append(row)
                continue

        # Phase 4 runs for PASS and WARN, but not hard FAIL.
        if vid not in fail_ids and CFG.get("auto_phase4_after_import",True):
            try:
                intel,ierr=phase4_extract_video(vid)
                if ierr:
                    row["Phase 4"]="FAIL"
                    row["Final"]="FAIL"
                    row["Reason"]=ierr.get("fatal","Phase 4 extraction failed")
                    fail_ids.append(vid)
                    if vid in pass_ids: pass_ids.remove(vid)
                    if vid in warn_ids: warn_ids.remove(vid)
                    results.append(row)
                    continue
                phase4_write_video_intelligence(vid,intel)
                row["Phase 4"]="PASS"
            except Exception as ex:
                row["Phase 4"]="FAIL"
                row["Final"]="FAIL"
                row["Reason"]=f"Phase 4 exception: {type(ex).__name__}: {ex}"
                fail_ids.append(vid)
                if vid in pass_ids: pass_ids.remove(vid)
                if vid in warn_ids: warn_ids.remove(vid)
                results.append(row)
                continue

        # Report regeneration / playback verification
        if vid not in fail_ids and CFG.get("auto_regenerate_report_after_import",True):
            try:
                folder=locate_existing_folder(vid)
                if not folder:
                    raise RuntimeError("Video folder not found")
                title=resolved_approved_title(vid)
                ok,msg=rebuild_report_after_rename(vid,folder,title)
                if not ok:
                    raise RuntimeError(msg)
                vok,vmsg=verify_report_video_playback_link(vid,folder)
                if not vok:
                    raise RuntimeError(vmsg)
                row["Report"]="PASS"
            except Exception as ex:
                row["Report"]="FAIL"
                row["Final"]="FAIL"
                row["Reason"]=f"Report rebuild/verify failed: {type(ex).__name__}: {ex}"
                fail_ids.append(vid)
                if vid in pass_ids: pass_ids.remove(vid)
                if vid in warn_ids: warn_ids.remove(vid)
                results.append(row)
                continue

        if row["Final"]=="UNKNOWN":
            if row["Phase 3"]=="WARN":
                row["Final"]="WARN"
            else:
                row["Final"]="PASS"

        results.append(row)

    # Refresh exports once, not per video.
    if CFG.get("auto_refresh_exports_after_import",True):
        try:
            export_csv()
        except Exception as ex:
            print(f"Warning: video_list export refresh failed: {ex}")
        try:
            export_csv_with_chatgpt_titles()
        except Exception as ex:
            print(f"Warning: reviewed-title export refresh failed: {ex}")

    # Write orchestration audit.
    audit_dir=BASE/"maintenance"/"audits"
    audit_dir.mkdir(parents=True,exist_ok=True)
    out=audit_dir/f"{package_id}_post_chatgpt_pipeline.csv"
    with open(out,"w",newline="",encoding="utf-8-sig") as f:
        fields=["Video ID","Phase 3","Phase 3 Score","Phase 4","Report","Final","Reason"]
        w=csv.DictWriter(f,fieldnames=fields)
        w.writeheader()
        w.writerows(results)

    # Retry package only for actual hard failures.
    unique_fail=sorted(set(fail_ids))
    if unique_fail and CFG.get("auto_retry_on_phase3_fail",True):
        reason_map={r["Video ID"]:r["Reason"] for r in results if r["Video ID"] in unique_fail}
        reason_text=" | ".join(f"{vid}: {reason_map.get(vid,'Post-ChatGPT pipeline failure')}" for vid in unique_fail)
        try:
            phase2_create_retry_package(package_id,unique_fail,reason_text)
        except Exception as ex:
            print(f"Retry package creation warning: {ex}")

    # Archive ONLY when the entire manifest is complete.
    if not unique_fail and CFG.get("auto_archive_clean_package",True):
        try:
            complete,archive_problems=package_is_fully_complete(package_id)
            if complete:
                phase2_archive_package(package_id)
            else:
                print("Package not archived; unresolved package-level problems:")
                for problem in archive_problems:
                    print(f"  {problem}")
        except Exception as ex:
            print(f"Archive eligibility warning: {ex}")

    print("")
    print("===== AUTOMATIC POST-CHATGPT PIPELINE =====")
    print(f"Package : {package_id}")
    print(f"Videos  : {len(video_ids)}")
    print(f"PASS    : {sum(1 for r in results if r['Final']=='PASS')}")
    print(f"WARN    : {sum(1 for r in results if r['Final']=='WARN')}")
    print(f"FAIL    : {sum(1 for r in results if r['Final']=='FAIL')}")
    print(f"Details : {out}")

    for r in results:
        if r["Final"]!="PASS":
            print(f"  {r['Video ID']} | {r['Final']} | {r['Reason']}")

    return results,out


def auto_post_chatgpt_pipeline_for_package(package_id):
    """
    Run automatic post-processing for all currently imported videos in a package.
    Useful for re-running the orchestration on older imports.
    """
    manifest=phase2_find_manifest(package_id)
    if not manifest:
        print(f"Manifest not found for {package_id}")
        return None

    obj=json.loads(Path(manifest).read_text(encoding="utf-8"))
    expected=[str(x) for x in (obj.get("expected_video_ids") or [])]

    con=db_connect()
    if expected:
        q=",".join("?" for _ in expected)
        rows=con.execute(
            f"SELECT video_id FROM videos WHERE chatgpt_imported=1 AND video_id IN ({q})",
            expected
        ).fetchall()
    else:
        rows=[]
    con.close()

    ids=[r[0] for r in rows]
    if not ids:
        print("No imported videos found for this package.")
        return None

    return auto_post_chatgpt_pipeline_for_videos(package_id,ids)


def log_youtube_api_status(video_id="",url="",used=False,reason=""):
    path=BASE/"logs"/"youtube_api_status.log"
    path.parent.mkdir(parents=True,exist_ok=True)
    line=(
        f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] "
        f"VideoID={video_id} URL={url} "
        f"API_USED={'YES' if used else 'NO'} "
        f"Reason={reason}\n"
    )
    with open(path,"a",encoding="utf-8") as f:
        f.write(line)


def youtube_api_key_status_reason():
    keyfile=BASE/"api_key.txt"
    if not keyfile.exists():
        return False,"api_key.txt not found"
    try:
        key=keyfile.read_text(encoding="utf-8",errors="ignore").strip()
    except Exception as ex:
        return False,f"Could not read api_key.txt: {ex}"
    if not key:
        return False,"api_key.txt is empty"
    return True,"API key available"

def metadata_scan():
    _api_available,_api_reason=youtube_api_key_status_reason()
    log_youtube_api_status(used=_api_available,reason=_api_reason)
    global STOP
    if web_current_job_context() is None:
        STOP=False
    if CFG.get("clear_progress_on_run_start",True): reset_progress_state("Metadata Scan")
    urls=load_urls()
    if not urls: print("No URLs in urls.txt"); return
    set_state(phase="Metadata Scan",started=time.time(),message="Scanning URLs",processed=0,failed=0,listed=0,total=0)
    results=[]; fallback_sources=list(urls)
    try: api_result=metadata_via_youtube_api(urls)
    except Exception as e:
        api_result=None; log(f"YouTube Data API metadata path failed: {e}")
    if api_result:
        api_rows,fallback_sources=api_result; results.extend(api_rows); print(f"\nYouTube Data API returned {len(api_rows)} videos.")
    if fallback_sources:
        set_state(phase="yt-dlp Metadata Fallback",processed=0,total=len(fallback_sources)); all_items=[]
        parent_ctx=web_current_job_context();parent_job_id=getattr(WEB_JOB_CONTEXT,"job_id",None)
        metadata_workers=max(1,min(5,int(CFG.get("parallel_videos",2) or 2)))
        source_rows=[None]*len(fallback_sources)
        def _list_source(index,source):
            WEB_JOB_CONTEXT.context=parent_ctx;WEB_JOB_CONTEXT.job_id=parent_job_id
            if web_stop_requested():return index,[]
            return index,flat_list(source)
        with ThreadPoolExecutor(max_workers=metadata_workers,thread_name_prefix="VLM-Metadata") as ex:
            futures={ex.submit(_list_source,index,source):(index,source) for index,source in enumerate(fallback_sources)}
            for completed,future in enumerate(as_completed(futures),1):
                index,source=futures[future]
                try:_,listed_rows=future.result()
                except Exception as list_ex:
                    listed_rows=[];log(f"Metadata source listing failed {source}: {list_ex}")
                source_rows[index]=listed_rows
                set_state(processed=completed,current=source,listed=len(results)+sum(len(x or []) for x in source_rows))
                web_job_progress(f"Resolved metadata source {completed}/{len(fallback_sources)}",completed,len(fallback_sources),"Metadata")
        for listed_rows in source_rows:
            all_items.extend(listed_rows or [])
        dedup={}
        for x in all_items: dedup[x["id"]]=x
        all_items=list(dedup.values()); set_state(total=len(all_items),processed=0)
        detail_rows=[None]*len(all_items)
        def _detail_item(index,item):
            WEB_JOB_CONTEXT.context=parent_ctx;WEB_JOB_CONTEXT.job_id=parent_job_id
            return index,detail_one(item)
        with ThreadPoolExecutor(max_workers=max(metadata_workers,min(8,int(CFG.get("workers",12) or 12)))) as ex:
            futs={ex.submit(_detail_item,index,x):(index,x) for index,x in enumerate(all_items)}
            for i,f in enumerate(as_completed(futs),1):
                index,item=futs[f]
                try: _,(r,err)=f.result()
                except Exception as e2: r,err=None,str(e2)
                if r:
                    r["metadata_source"]="yt-dlp";detail_rows[index]=r
                else:
                    item["description"]=""; item["error"]=err; item["metadata_source"]="yt-dlp";detail_rows[index]=item; set_state(failed=snapshot()["failed"]+1)
                set_state(processed=i,current=item.get("title") or item["url"]); console_progress("Metadata fallback | ")
        results.extend(row for row in detail_rows if row)
    unique={}
    for r in results:
        if r["id"] not in unique or unique[r["id"]].get("metadata_source")!="YouTube Data API": unique[r["id"]]=r
    results=list(unique.values()); save_metadata(results); export_csv(); console_newline()
    set_state(phase="Metadata complete",message=f"Saved {len(results)} videos",processed=len(results),total=len(results))


def normalize_no_llm_titles():
    if RUNTIME.get("use_llm",True):
        return

    con=db_connect()
    rows=con.execute("SELECT video_id,original_title FROM videos").fetchall()
    con.close()

    changed=0
    skipped=0
    for vid,orig in rows:
        title=clean_source_title_no_llm(orig)
        if safe_update_clean_title(vid,title):
            changed+=1
        else:
            skipped+=1

    export_csv()
    print(f"No-LLM titles reset: {changed}; protected/finalized skipped: {skipped}")


def download_stage():
    rotate_app_log_before_run()
    smart_queue_ids={x["video_id"] for x in smart_resume_queue_items()} if RUNTIME.get("smart_resume",False) else set()
    failed_only_ids=smart_queue_ids if RUNTIME.get("smart_resume",False) else set()
    normalize_no_llm_titles()
    if CFG.get("clear_progress_on_run_start",True):
        reset_progress_state("Transcript Availability")

    con=db_connect()
    rows=con.execute("""
      SELECT video_id,url,original_title,clean_title,channel,upload_date,platform,category,subcategory,main_topic,tags,description
      FROM videos ORDER BY upload_date DESC,rowid DESC
    """).fetchall()
    con.close()

    if CFG.get("transcript_first",True):
        # Prepare transcript only for rows that are not already fully complete
        # when Smart Resume is active. This avoids rechecking thousands of old videos.
        transcript_rows=[]
        for row in rows:
            vid,url,orig,clean,channel,upload_date,platform,category,subcategory,topic,tags,desc=row
            if RUNTIME.get("smart_resume",False):
                sr=smart_resume_artifact_status(vid)
                if sr.get("action")=="SKIP":
                    continue
            con=db_connect()
            trrow=con.execute(
                """SELECT video_id,url,original_title,upload_date,subtitle_source,subtitle_lang,subtitle_base_lang
                   FROM videos WHERE video_id=?""",
                (vid,)
            ).fetchone()
            con.close()
            if trrow:
                transcript_rows.append(trrow)
        prepare_transcripts_rows(transcript_rows)
        name_videos_from_tmp_transcripts()
    quality=str(CFG.get("download_quality","1080"))
    download_rows=[]
    for row in rows:
        vid=row[0]
        if RUNTIME.get("smart_resume",False):
            status=smart_resume_artifact_status(vid)
            if status["action"]=="COMPLETE":
                continue
            if status["action"]=="RETRY":
                print(f"SMART RESUME TRANSCRIPT RETRY {vid}: {status['reason']}")
                increment_transcript_retry(vid,status["reason"])
            else:
                print(f"SMART RESUME DOWNLOAD {vid}: {status['reason']}")
        download_rows.append(row)
    rows=download_rows
    set_state(started=time.time(),phase="Download queue",total=len(rows),processed=0,downloaded=0,failed=0,
              stage_timings=[],stage_started_at=None)
    parent_ctx=web_current_job_context();parent_job_id=getattr(WEB_JOB_CONTEXT,"job_id",None)
    legacy_options=DownloadOptions.from_values(
        action="full_download",quality=quality,use_ollama=RUNTIME.get("use_llm",False),
        save_srt=RUNTIME.get("save_srt",CFG.get("save_srt_default",False)),
        vtt=CFG.get("download_subtitles",True),smart_resume=RUNTIME.get("smart_resume",False),
        parallel_videos=CFG.get("parallel_videos",2),concurrent_fragments=CFG.get("concurrent_fragments",4),
    )
    def _legacy_download_task(row):
        vid=str(row[0]);title=str(row[3] or row[2] or row[0])
        WEB_JOB_CONTEXT.context=web_child_context(parent_job_id,vid,legacy_options);WEB_JOB_CONTEXT.job_id=parent_job_id
        WEB_JOB_CONTEXT.video_id=vid;WEB_JOB_CONTEXT.video_title=title
        if web_stop_requested():
            status,_reason=web_child_stop_state()
            web_video_progress(vid,title=title,stage=status.title(),status=status)
            return False
        return process_download(row,quality,options=legacy_options)
    workers=max(1,min(5,int(legacy_options.parallel_videos)))
    web_seed_video_progress(rows)
    for row in rows:web_child_context(parent_job_id,row[0],legacy_options)
    executor=ThreadPoolExecutor(max_workers=workers,thread_name_prefix="VLM-Legacy-Download")
    futures=[executor.submit(_legacy_download_task,row) for row in rows]
    for i,(row,future) in enumerate(zip(rows,futures),1):
        if STOP: break
        try:
            try:
                _sr_vid = row["video_id"] if isinstance(row,dict) else row[0]
            except Exception:
                _sr_vid = None
            if False and RUNTIME.get("smart_resume",False) and _sr_vid:
                _sr_status=smart_resume_artifact_status(_sr_vid)
                if _sr_status["action"]=="COMPLETE":
                    # Completed videos are not part of Smart Resume output/queue.
                    continue
                elif _sr_status["action"]=="RETRY":
                    print(f"SMART RESUME TRANSCRIPT RETRY {_sr_vid}: {_sr_status['reason']}")
                    increment_transcript_retry(_sr_vid,_sr_status["reason"])
                else:
                    print(f"SMART RESUME DOWNLOAD {_sr_vid}: {_sr_status['reason']}")
            ok=future.result()
        except Exception as e:
            ok=False
            vid,url,orig,clean,channel,upload_date,platform,category,subcategory,topic,tags,desc=row
            err_text=traceback.format_exc()
            log(f"Download/process failure {url}: {e}\n{err_text}")

            # Try to locate the actual existing video folder first.
            folder=locate_existing_folder(vid)
            if folder is None:
                base=safe_name(clean or clean_source_title_no_llm(orig) or orig,vid)
                folder=video_folder_path(base,upload_date,channel,vid)
                folder.mkdir(parents=True,exist_ok=True)
                try:
                    (support_dir(folder)/".video_id").write_text(str(vid),encoding="utf-8")
                except Exception:
                    pass
            else:
                base=safe_name(clean or orig,vid)

            # Error destinations must exist even when failure occurs very early.
            try:
                support_dir(folder).mkdir(parents=True,exist_ok=True)
            except Exception:
                pass

            try:
                log_failed_video(
                    video_id=vid,
                    url=url,
                    title=clean or orig,
                    channel=channel,
                    stage="Download/Process",
                    error_type=type(e).__name__,
                    error_message=str(e),
                    folder=str(folder),
                    retry_status="PENDING"
                )
            except Exception as failed_log_err:
                log(f"Could not append failed_videos.csv for {url}: {failed_log_err}")

            try:
                error_path=support_dir(folder)/f"{base}.ERROR.txt"
                error_path.write_text(
                    "===== UNHANDLED DOWNLOAD/PROCESS ERROR =====\n"
                    f"Video ID: {vid}\n"
                    f"URL: {url}\n"
                    f"Original Title: {orig}\n\n"
                    f"{err_text}\n",
                    encoding="utf-8"
                )
                print(f"\nERROR file written: {error_path}")
            except Exception as write_err:
                log(f"Could not write ERROR.txt for {url}: {write_err}")

        if not ok:
            print(f"\nFAILED VIDEO: {row[1]}")
            print("See the video's _data\\*.ERROR.txt for full diagnostics.")

        s=snapshot()
        set_state(processed=i,
                  downloaded=s["downloaded"]+(1 if ok else 0),
                  failed=s["failed"]+(0 if ok else 1))
    executor.shutdown(wait=True,cancel_futures=web_stop_requested())
    set_state(phase="Download complete",message="Download/subtitle/transcript/report stage finished")
    try:
        registry=export_artifact_registry()
        print(f"Artifact registry refreshed after download/resume: {registry}")
    except Exception as ex:
        print(f"Artifact registry refresh warning: {type(ex).__name__}: {ex}")




def best_transcript_for_video(video_id):
    p=temp_paths(video_id)
    en=p["dir"]/f"{video_id}.timestamped.en.txt"
    src=p["timestamped"]
    if en.exists() and en.stat().st_size>0:
        return en.read_text(encoding="utf-8",errors="replace"),"en"
    if src.exists() and src.stat().st_size>0:
        con=db_connect()
        row=con.execute(
            "SELECT subtitle_base_lang FROM videos WHERE video_id=?",
            (video_id,)
        ).fetchone()
        con.close()
        lang=((row[0] if row else "") or "unknown").split("-")[0].lower()
        return src.read_text(encoding="utf-8",errors="replace"),lang
    return "",""

def build_chatgpt_summary_packages():
    """
    Export compact ChatGPT packages.
    English transcript is preferred. If source transcript is Hindi/other language,
    ChatGPT MUST translate/normalize the returned summary into English.
    """
    con=db_connect()
    rows=con.execute("""
      SELECT video_id,url,original_title,clean_title,channel,upload_date
      FROM videos
      ORDER BY upload_date DESC,rowid DESC
    """).fetchall()
    con.close()

    candidates=[]
    for vid,url,orig,clean,channel,upload_date in rows:
        transcript,lang=best_transcript_for_video(vid)
        if not transcript:
            continue
        candidates.append({
            "video_id":vid,
            "url":url,
            "original_title":orig,
            "current_title":clean or orig,
            "channel":channel or "",
            "upload_date":upload_date or "",
            "transcript_language":lang or "unknown",
            "transcript":transcript
        })

    if not candidates:
        print("No cached transcripts available to package.")
        return []

    max_v=max(1,int(CFG.get("chatgpt_batch_max_videos",15)))
    min_v=max(1,int(CFG.get("chatgpt_batch_min_videos",5)))
    max_chars=max(10000,int(CFG.get("chatgpt_batch_max_chars",120000)))

    batches=[]
    cur=[]
    chars=0

    def flush():
        nonlocal cur,chars
        if cur:
            batches.append(cur)
            cur=[]
            chars=0

    for item in candidates:
        size=len(item["transcript"])

        # If one transcript alone exceeds the package target, isolate it in
        # its own one-video package instead of mixing it with other videos.
        if size > max_chars:
            flush()
            batches.append([item])
            print(
                f"Oversized transcript isolated into one-video package: "
                f"{item['video_id']} ({size:,} chars)"
            )
            continue

        if cur and len(cur)>=min_v and (len(cur)>=max_v or chars+size>max_chars):
            flush()

        cur.append(item)
        chars+=size

        if len(cur)>=max_v:
            flush()

    flush()

    created=[]
    for i,batch in enumerate(batches,1):
        package_id=f"chatgpt_package_{i:03d}"

        payload={
            "package_format_version":"2.0",
            "minimum_importer_version":"20.7",
            "package_id":package_id,
            "instructions":{
                "task":"Create a detailed English summary for every video independently.",
                "match_key":"video_id",
                "return_format":"JSON",
                "language_rules":[
                    "ALL returned titles, summaries, section headings, bullet points, recommendations, warnings, and instructions MUST be in English.",
                    "If the provided transcript is Hindi or another language, translate its meaning into natural English before summarizing.",
                    "Do not return Hindi or mixed-language summary text except unavoidable proper nouns, product names, herb names, or quoted names.",
                    "Do not translate or modify video_id."
                ],
                "content_rules":[
                    "Use only information supported by that video's transcript.",
                    "Keep every timestamped point inside its correct time range.",
                    "Overlapping time ranges are allowed when one item is a subtopic, explanation, recommendation, safety note, or insight contained within a broader section.",
                    "Do not move information from a later part of the video into an earlier timestamp.",
                    "Create a concise overall summary for the full video.",
                    "Return one primary_category and one primary_topic, plus secondary topics/entities. Do not over-tag.",
                    "For health/gardening videos, extract relevant herbs, ingredients, products, people, and locations when explicitly supported.",
                    "Create standardized structured cards only when supported by the transcript: health/remedy cards, recipe cards, or how-to cards.",
                    "For remedy cards capture ingredients, quantities, preparation, amount/dosage stated by the speaker, timing, frequency, duration, warnings, and claimed benefit when explicitly stated.",
                    "For how-to cards capture requirements/materials, ordered steps, tips, problems, and expected result when explicitly stated.",
                    "Extract comparison tables, ranked lists, named sources/organizations, glossary terms, Q&A, and safety notes only when present. Do not invent missing values.",
                    "Then organize the important content into meaningful named groups such as Main Topics, Remedies, Methods, Recommendations, Tips, Safety Guidelines, Warnings, Comparisons, Ingredients, Products, or other categories that fit the video.",
                    "Do not force every group to exist. Only include groups that are actually supported by the transcript.",
                    "Within each group, create clear items with title, start time, end time, and a meaningful English summary.",
                    "If a real process or recipe exists, include exact steps, quantities, timing, dosage, ratios, ingredients, or sequence only when stated in the transcript.",
                    "Safety/warning content should be separated when present.",
                    "Avoid transcript-dump wording. Summarize clearly and professionally."
                ],
                "example_style":{
                    "overall_summary":"This video features Dr. Saleem Zaidi discussing five science-backed homemade remedies and an Ayurvedic supplement to help burn body fat and improve metabolism.",
                    "overall_start":"00:00:00",
                    "overall_end":"00:09:34",
                    "groups":[
                        {
                            "group_title":"Five Homemade Weight Loss Remedies",
                            "items":[
                                {
                                    "title":"Cumin, Ajwain, and Fennel Blend",
                                    "start":"00:00:30",
                                    "end":"00:01:36",
                                    "summary":"Combine equal parts cumin, ajwain, and fennel, lightly roast, grind, and take one teaspoon with warm water 15–20 minutes before meals twice daily.",
                                    "steps":[
                                        "Combine the three ingredients in equal quantities.",
                                        "Lightly roast them.",
                                        "Grind into a fine powder.",
                                        "Take one teaspoon with warm water 15–20 minutes before meals, twice daily."
                                    ]
                                }
                            ]
                        },
                        {
                            "group_title":"Additional Recommendations & Tips",
                            "items":[]
                        },
                        {
                            "group_title":"Safety Guidelines",
                            "items":[]
                        }
                    ]
                },
                "expected_result_schema":{
                    "result_format_version":"2.0",
                    "package_id":"same package_id",
                    "videos":[{
                        "video_id":"exact input video_id",
                        "meaningful_title":"meaningful English title",
                        "category":"broad English category",
                        "primary_category":"single broad home category",
                        "primary_topic":"single main topic for this video",
                        "topics":["secondary topics"],
                        "entities":["important named entities"],
                        "ingredients":["ingredients/foods/materials"],
                        "herbs":["herbs/plants"],
                        "products":["products/brands"],
                        "people":["people"],
                        "locations":["locations"],
                        "summary_language":"en",
                        "content_types":["health_remedy|cooking_recipe|gardening_diy|technology|comparison|ranked_list|qa_interview|generic"],
                        "remedy_cards":[],
                        "recipe_cards":[],
                        "how_to_cards":[],
                        "comparisons":[],
                        "rankings":[],
                        "safety_notes":[],
                        "sources":[],
                        "organizations":[],
                        "glossary":[],
                        "qa":[],
                        "subcategory":"specific English category",
                        "tags":["English tags"],
                        "overall_summary":"English overall summary for the whole video",
                        "overall_start":"HH:MM:SS",
                        "overall_end":"HH:MM:SS",
                        "groups":[{
                            "group_title":"Meaningful English group heading",
                            "items":[{
                                "title":"Meaningful English item title",
                                "start":"HH:MM:SS",
                                "end":"HH:MM:SS",
                                "summary":"Meaningful English summary for this exact time range",
                                "steps":["optional real steps only"]
                            }]
                        }]
                    }]
                }
            },
            "videos":batch
        }

        out=CHATGPT_PACKAGES/f"{package_id}.json"
        out.write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding="utf-8")
        created.append(out)

    print(f"Created {len(created)} package(s) in: {CHATGPT_PACKAGES}")
    for p in created:
        print(" ",p.name)

    # Phase 2 canonical sync MUST happen before returning.
    try:
        synced,manifests_created=phase2_sync_legacy_packages()
        print(f"Phase 2 sync: {synced} package(s) copied, {manifests_created} manifest(s) created.")
        print(f"Canonical Phase 2 package folder: {phase2_chatgpt_dirs()[0]}")
    except Exception as ex:
        print(f"Phase 2 package sync warning: {type(ex).__name__}: {ex}")

    return created


def canonical_chatgpt_summary_path(folder, video_id):
    # Stable filename independent of current/new/old title.
    return support_dir(folder)/f"{video_id}.chatgpt_summary.json"

def canonical_chatgpt_summary_txt_path(folder, video_id):
    return support_dir(folder)/f"{video_id}.chatgpt_summary.txt"

def cleanup_stale_chatgpt_files(folder, video_id):
    if not CFG.get("cleanup_stale_chatgpt_files",True):
        return
    data=support_dir(folder)
    keep_json=canonical_chatgpt_summary_path(folder,video_id)
    keep_txt=canonical_chatgpt_summary_txt_path(folder,video_id)

    for p in data.glob("*.chatgpt_summary.json"):
        if p != keep_json:
            try: p.unlink()
            except Exception: pass

    for pattern in ("*.chatgpt-summary.txt","*.chatgpt_summary.txt"):
        for p in data.glob(pattern):
            if p != keep_txt:
                try: p.unlink()
                except Exception: pass

def cleanup_stale_reports(folder, keep_report):
    if not CFG.get("single_canonical_report_file",True):
        return
    for p in Path(folder).glob("*.report.html"):
        if Path(p) != Path(keep_report):
            try: p.unlink()
            except Exception: pass

def locate_chatgpt_summary_file(video_id):
    """
    Locate imported ChatGPT summary strictly by Video ID.
    New canonical path is:
      _data\\<video_id>.chatgpt_summary.json
    Legacy title-based files are supported only as migration fallback.
    """
    folder=locate_existing_folder(video_id)
    if folder:
        canonical=canonical_chatgpt_summary_path(folder,video_id)
        if canonical.exists():
            return canonical

    con=db_connect()
    row=con.execute(
        "SELECT chatgpt_summary_file,local_folder FROM videos WHERE video_id=?",
        (video_id,)
    ).fetchone()
    con.close()

    if row and row[0]:
        p=Path(row[0])
        if p.exists():
            return p

    if folder:
        data=support_dir(folder)
        for p in sorted(data.glob("*.chatgpt_summary.json")):
            try:
                obj=json.loads(p.read_text(encoding="utf-8"))
                if str(obj.get("video_id") or "").strip()==str(video_id):
                    # Migrate legacy title-based file to canonical Video-ID filename.
                    canonical=canonical_chatgpt_summary_path(folder,video_id)
                    shutil.copy2(p,canonical)
                    cleanup_stale_chatgpt_files(folder,video_id)
                    return canonical
            except Exception:
                pass

    return None


def load_chatgpt_summary_for_video(video_id):
    p=locate_chatgpt_summary_file(video_id)
    if not p:
        return None,None
    try:
        return json.loads(p.read_text(encoding="utf-8")),p
    except Exception:
        return None,p

def normalize_chatgpt_result_video(item):
    """
    Accept the rich grouped ChatGPT schema and flatten it into normal report sections,
    while preserving group headings for HTML rendering.
    """
    sections=[]

    # Canonical imported summary files already contain flattened sections.
    canonical_sections=item.get("sections") or []
    if canonical_sections and isinstance(canonical_sections,list):
        for secn in canonical_sections:
            sections.append({
                "group_title":str(secn.get("group_title") or ""),
                "chapter_title":str(secn.get("chapter_title") or secn.get("title") or "Section"),
                "start":str(secn.get("start") or "00:00:00"),
                "end":str(secn.get("end") or secn.get("start") or "00:00:00"),
                "overview":str(secn.get("overview") or secn.get("detailed_summary") or secn.get("summary") or ""),
                "detailed_summary":str(secn.get("detailed_summary") or secn.get("overview") or secn.get("summary") or ""),
                "instructions":[str(x) for x in (secn.get("instructions") or secn.get("steps") or []) if str(x).strip()],
                "topics":secn.get("topics") or [],
                "ingredients_or_entities":secn.get("ingredients_or_entities") or [],
                "claims":secn.get("claims") or [],
                "key_points":secn.get("key_points") or [],
                "tags":secn.get("tags") or []
            })

    groups=item.get("groups") or []
    if groups and not sections:
        for group in groups:
            group_title=str(group.get("group_title") or "").strip()
            for entry in group.get("items") or []:
                sections.append({
                    "group_title":group_title,
                    "chapter_title":str(entry.get("title") or "Section"),
                    "start":str(entry.get("start") or "00:00:00"),
                    "end":str(entry.get("end") or entry.get("start") or "00:00:00"),
                    "overview":str(entry.get("summary") or ""),
                    "detailed_summary":str(entry.get("summary") or ""),
                    "instructions":[str(x) for x in (entry.get("steps") or entry.get("instructions") or []) if str(x).strip()],
                    "topics":[],
                    "ingredients_or_entities":[],
                    "claims":[],
                    "key_points":[],
                    "tags":[]
                })
    elif not sections:
        # Backward compatibility with older result schema.
        for secn in item.get("sections") or []:
            sections.append({
                "group_title":"",
                "chapter_title":str(secn.get("title") or secn.get("chapter_title") or "Section"),
                "start":str(secn.get("start") or "00:00:00"),
                "end":str(secn.get("end") or secn.get("start") or "00:00:00"),
                "overview":str(secn.get("detailed_summary") or secn.get("summary") or ""),
                "detailed_summary":str(secn.get("detailed_summary") or secn.get("summary") or ""),
                "instructions":[str(x) for x in (secn.get("instructions") or []) if str(x).strip()],
                "topics":[],
                "ingredients_or_entities":[],
                "claims":[],
                "key_points":[],
                "tags":[]
            })

    return {
        "meaningful_title":str(item.get("meaningful_title") or ""),
        "category":str(item.get("category") or item.get("primary_category") or ""),
        "primary_category":str(item.get("primary_category") or item.get("category") or ""),
        "primary_topic":str(item.get("primary_topic") or ""),
        "topics":[str(x) for x in (item.get("topics") or []) if str(x).strip()],
        "entities":[str(x) for x in (item.get("entities") or []) if str(x).strip()],
        "ingredients":[str(x) for x in (item.get("ingredients") or []) if str(x).strip()],
        "herbs":[str(x) for x in (item.get("herbs") or []) if str(x).strip()],
        "products":[str(x) for x in (item.get("products") or []) if str(x).strip()],
        "people":[str(x) for x in (item.get("people") or []) if str(x).strip()],
        "locations":[str(x) for x in (item.get("locations") or []) if str(x).strip()],
        "summary_language":str(item.get("summary_language") or "en"),
        "subcategory":str(item.get("subcategory") or ""),
        "tags":[str(x) for x in (item.get("tags") or []) if str(x).strip()],
        "summary":str(item.get("overall_summary") or item.get("summary") or ""),
        "overall_start":str(item.get("overall_start") or "00:00:00"),
        "overall_end":str(item.get("overall_end") or ""),
        "sections":sections
    }


def import_chatgpt_summary_results(result_path=None):
    files=[Path(result_path)] if result_path else sorted(
        p for p in CHATGPT_RESULTS.glob("*.json")
        if p.parent==CHATGPT_RESULTS
    )
    if not files:
        print(f"No JSON result files found in {CHATGPT_RESULTS}")
        return 0

    imported=0
    rejected=0

    for result_file in files:
        try:
            raw_text=result_file.read_text(encoding="utf-8")
            data=json.loads(raw_text)
        except Exception as ex:
            print(f"Invalid JSON {result_file.name}: {ex}")
            rejected+=1
            try: shutil.move(str(result_file),str(CHATGPT_REJECTED/result_file.name))
            except Exception: pass
            continue

        package_id=str(data.get("package_id") or "").strip()
        expected_ids=expected_package_video_ids(package_id)
        returned=data.get("videos") or []
        returned_ids=[str(v.get("video_id") or "").strip() for v in returned if str(v.get("video_id") or "").strip()]

        # Reject duplicate IDs.
        duplicates={vid for vid in returned_ids if returned_ids.count(vid)>1}
        if duplicates:
            print(f"Rejected {result_file.name}: duplicate Video IDs {sorted(duplicates)}")
            rejected+=1
            try: shutil.move(str(result_file),str(CHATGPT_REJECTED/result_file.name))
            except Exception: pass
            continue

        if expected_ids is not None:
            returned_set=set(returned_ids)
            missing=expected_ids-returned_set
            extra=returned_set-expected_ids
            if missing or extra:
                print(f"Rejected {result_file.name}: package/video-id mismatch.")
                if missing: print(" Missing:",sorted(missing))
                if extra: print(" Extra:",sorted(extra))
                rejected+=1
                try: shutil.move(str(result_file),str(CHATGPT_REJECTED/result_file.name))
                except Exception: pass
                continue
        elif package_id:
            print(f"Warning: exported package not found for package_id={package_id}")

        file_ok=True

        for raw in returned:
            vid=str(raw.get("video_id") or "").strip()
            if not vid:
                file_ok=False
                continue

            if CFG.get("chatgpt_require_english_output",True):
                if contains_substantial_devanagari(chatgpt_result_text(raw)):
                    print(f"Rejected video {vid}: ChatGPT result is not sufficiently English.")
                    file_ok=False
                    continue

            norm=normalize_chatgpt_result_video(raw)
            norm["sections"],timestamp_errors,timestamp_warnings=validate_and_normalize_sections(norm["sections"])

            if timestamp_errors and CFG.get("chatgpt_timestamp_validation",True):
                print(f"Rejected video {vid}: invalid timestamp data:")
                for err in timestamp_errors:
                    print(" ",err)
                file_ok=False
                continue

            if timestamp_warnings:
                print(f"Timestamp warnings for {vid} (allowed):")
                for warn in timestamp_warnings:
                    print(" ",warn)

            con=db_connect()
            row=con.execute("""
              SELECT original_title,clean_title,upload_date,channel,local_folder
              FROM videos WHERE video_id=?
            """,(vid,)).fetchone()
            con.close()

            if not row:
                print(f"Video ID not found: {vid}")
                file_ok=False
                continue

            orig,clean,upload_date,channel,local_folder=row
            folder=locate_existing_folder(vid)

            if folder is None and local_folder:
                candidate=Path(local_folder)
                if candidate.exists():
                    folder=candidate

            if folder is None:
                base=safe_name(clean or orig,vid)
                folder=video_folder_path(base,upload_date,channel,vid)
                folder.mkdir(parents=True,exist_ok=True)
                support_dir(folder)

            base=safe_name(clean or orig,vid)

            payload={
                "summary_format_version":"2.0",
                "source_result_format_version":str(data.get("result_format_version") or data.get("package_format_version") or ""),
                "video_id":vid,
                "source":"ChatGPT imported summary",
                "meaningful_title":norm["meaningful_title"],
                "imported_title":norm["meaningful_title"],
                "category":norm["category"],
                "primary_category":norm.get("primary_category") or norm["category"],
                "primary_topic":norm.get("primary_topic") or "",
                "topics":norm.get("topics") or [],
                "entities":norm.get("entities") or [],
                "ingredients":norm.get("ingredients") or [],
                "herbs":norm.get("herbs") or [],
                "products":norm.get("products") or [],
                "people":norm.get("people") or [],
                "locations":norm.get("locations") or [],
                "summary_language":norm.get("summary_language") or "en",
                "subcategory":norm["subcategory"],
                "tags":norm["tags"],
                "summary":norm["summary"],
                "sections":norm["sections"]
            }

            result_hash=short_hash(json.dumps(payload,ensure_ascii=False,sort_keys=True))

            summary_file=canonical_chatgpt_summary_path(folder,vid)
            summary_file.write_text(
                json.dumps(payload,ensure_ascii=False,indent=2),
                encoding="utf-8"
            )

            if CFG.get("copy_chatgpt_summary_into_video_folder",True):
                txt=canonical_chatgpt_summary_txt_path(folder,vid)
                lines=[
                    f"Video ID: {vid}",
                    f"Title: {norm['meaningful_title'] or clean or orig}",
                    "",
                    "Overall Summary:",
                    norm["summary"],
                    ""
                ]
                last_group=None
                for secn in norm["sections"]:
                    group_title=str(secn.get("group_title") or "").strip()
                    if group_title and group_title!=last_group:
                        lines.append(group_title)
                        lines.append("-"*len(group_title))
                        last_group=group_title
                    lines.append(f"{secn['start']} - {secn['end']} | {secn['chapter_title']}")
                    lines.append(secn["detailed_summary"])
                    if secn["instructions"]:
                        lines.append("Steps:")
                        lines.extend(f"- {x}" for x in secn["instructions"])
                    lines.append("")
                txt.write_text("\n".join(lines),encoding="utf-8")

            cleanup_stale_chatgpt_files(folder,vid)

            p=temp_paths(vid)
            p["dir"].mkdir(parents=True,exist_ok=True)
            p["chapters"].write_text(
                json.dumps(norm["sections"],ensure_ascii=False,indent=2),
                encoding="utf-8"
            )

            identity={
                "meaningful_title":norm["meaningful_title"] or clean or orig,
                "category":norm["category"],
                "subcategory":norm["subcategory"],
                "tags":norm["tags"],
                "summary":norm["summary"],
                "title_entities":[],
                "main_topic":""
            }
            p["identity"].write_text(
                json.dumps(identity,ensure_ascii=False,indent=2),
                encoding="utf-8"
            )

            con=db_connect()
            con.execute("""
              UPDATE videos
              SET category=?,subcategory=?,tags=?,
                  primary_category=?,primary_topic=?,
                  topics_json=?,entities_json=?,ingredients_json=?,herbs_json=?,
                  products_json=?,people_json=?,locations_json=?,summary_language=?,
                  identity_json=?,chapters_temp=?,
                  chatgpt_summary_file=?,chatgpt_imported=1,
                  chatgpt_result_hash=?,title_finalized=1
              WHERE video_id=?
            """,(
                norm["category"],
                norm["subcategory"],
                ", ".join(norm["tags"]),
                norm.get("primary_category") or norm["category"],
                norm.get("primary_topic") or "",
                json.dumps(norm.get("topics") or [],ensure_ascii=False),
                json.dumps(norm.get("entities") or [],ensure_ascii=False),
                json.dumps(norm.get("ingredients") or [],ensure_ascii=False),
                json.dumps(norm.get("herbs") or [],ensure_ascii=False),
                json.dumps(norm.get("products") or [],ensure_ascii=False),
                json.dumps(norm.get("people") or [],ensure_ascii=False),
                json.dumps(norm.get("locations") or [],ensure_ascii=False),
                norm.get("summary_language") or "en",
                json.dumps(identity,ensure_ascii=False),
                str(p["chapters"]),
                str(summary_file),
                result_hash,
                vid
            ))
            con.commit()
            con.close()
            imported+=1

        if file_ok:
            try:
                target=CHATGPT_PROCESSED/result_file.name
                if target.exists():
                    target.unlink()
                shutil.move(str(result_file),str(target))
            except Exception as ex:
                print(f"Warning: could not archive processed result {result_file.name}: {ex}")
        else:
            rejected+=1
            try:
                target=CHATGPT_REJECTED/result_file.name
                if target.exists():
                    target.unlink()
                shutil.move(str(result_file),str(target))
            except Exception:
                pass

    export_csv()
    print(f"Imported ChatGPT summaries for {imported} video(s). Rejected result files: {rejected}.")
    return imported


def regenerate_reports_from_chatgpt(force_all=False):
    """
    Regenerate HTML reports using ONLY the canonical imported ChatGPT summary JSON
    for all semantic/report text fields.

    Source of truth for:
      - ChatGPT English title
      - Overall summary
      - Category / subcategory
      - Tags
      - Chapter titles
      - Chapter timestamps
      - Detailed summaries
      - Steps / instructions

    Existing local files are used ONLY for:
      - video playback
      - original YouTube description
      - technical metadata / thumbnail if needed by report

    The original/source-language transcript is NOT used to rewrite or enrich the
    ChatGPT-generated English summary content.
    """
    con=db_connect()
    rows=con.execute("""
      SELECT video_id,url,original_title,clean_title,channel,upload_date,platform,
             description,chatgpt_result_hash,chatgpt_report_hash
      FROM videos
      WHERE chatgpt_imported=1
      ORDER BY upload_date DESC,rowid DESC
    """).fetchall()
    con.close()

    if not rows:
        print("No imported ChatGPT summaries found.")
        return

    count=0
    skipped=0
    failed=0

    for row in rows:
        (vid,url,orig,clean,channel,upload_date,platform,
         db_description,result_hash,report_hash)=row

        expected_report_hash=chatgpt_report_fingerprint(result_hash)

        if (CFG.get("chatgpt_incremental_report_regen",True)
                and not force_all
                and result_hash
                and report_hash==expected_report_hash):
            skipped+=1
            continue

        folder=locate_existing_folder(vid)
        if folder is None:
            set_video_final_status(
                vid,"FAIL",
                "Video folder not found for ChatGPT report regeneration."
            )
            failed+=1
            continue

        base=safe_name(clean or orig,vid)

        # Canonical source of truth: _data\<video_id>.chatgpt_summary.json
        summary_path=canonical_chatgpt_summary_path(folder,vid)
        if not summary_path.exists():
            # migration fallback by Video ID, never by title
            located=locate_chatgpt_summary_file(vid)
            if located and Path(located).exists():
                try:
                    shutil.copy2(located,summary_path)
                except Exception:
                    pass

        if not summary_path.exists():
            append_video_error(
                folder,base,"CHATGPT SUMMARY FILE MISSING",
                "Canonical ChatGPT summary JSON was not found.",
                f"Expected: {summary_path}\nVideo ID: {vid}"
            )
            set_video_final_status(
                vid,"FAIL",
                "Canonical ChatGPT summary JSON missing."
            )
            failed+=1
            continue

        try:
            summary_obj=json.loads(
                summary_path.read_text(encoding="utf-8")
            )
        except Exception as ex:
            append_video_error(
                folder,base,"CHATGPT SUMMARY JSON INVALID",
                f"{type(ex).__name__}: {ex}",
                traceback.format_exc()
            )
            set_video_final_status(
                vid,"FAIL",
                "Canonical ChatGPT summary JSON is invalid."
            )
            failed+=1
            continue

        # Validate Video ID match.
        file_vid=str(summary_obj.get("video_id") or "").strip()
        if file_vid and file_vid!=str(vid):
            append_video_error(
                folder,base,"CHATGPT SUMMARY VIDEO ID MISMATCH",
                f"Expected Video ID {vid}, found {file_vid}.",
                str(summary_path)
            )
            set_video_final_status(
                vid,"FAIL",
                "ChatGPT summary Video ID mismatch."
            )
            failed+=1
            continue

        # Normalize canonical JSON only. Do NOT attach/re-enrich from transcript.
        normalized=normalize_chatgpt_result_video(summary_obj)
        sections=normalized.get("sections") or []

        sections,timestamp_errors,timestamp_warnings=validate_and_normalize_sections(
            sections
        )
        if timestamp_errors:
            append_video_error(
                folder,base,"CHATGPT REPORT TIMESTAMP ERROR",
                "Imported summary has invalid timestamps.",
                "\n".join(timestamp_errors)
            )
            set_video_final_status(
                vid,"FAIL",
                "Invalid timestamps in canonical ChatGPT summary."
            )
            failed+=1
            continue

        # IMPORTANT:
        # Do NOT call attach_source_text_to_sections() here.
        # That function can pull source-language transcript text into report data.
        # Option 16 must remain ChatGPT-summary-only for semantic content.

        meaningful_title=str(
            summary_obj.get("meaningful_title")
            or summary_obj.get("imported_title")
            or normalized.get("meaningful_title")
            or clean
            or orig
            or vid
        ).strip()

        overall_summary=str(
            summary_obj.get("summary")
            or summary_obj.get("overall_summary")
            or normalized.get("summary")
            or ""
        ).strip()

        category=str(
            summary_obj.get("category")
            or normalized.get("category")
            or ""
        ).strip()

        subcategory=str(
            summary_obj.get("subcategory")
            or normalized.get("subcategory")
            or ""
        ).strip()

        tags_obj=summary_obj.get("tags")
        if isinstance(tags_obj,list):
            tags_text=", ".join(str(x) for x in tags_obj if str(x).strip())
        else:
            tags_text=str(tags_obj or ", ".join(normalized.get("tags") or []))

        # Existing description only; this is not summary content.
        description_file=find_first(
            support_dir(folder),
            [f"{base}.description","*.description"]
        )
        description=(
            description_file.read_text(encoding="utf-8",errors="replace")
            if description_file and description_file.exists()
            else (db_description or "")
        )

        video=find_any_media(folder)

        meta={
            "video_id":vid,
            "url":url,
            "original_title":orig,
            "clean_title":base,
            "channel":channel,
            "upload_date":upload_date,
            "platform":platform,
            "category":category,
            "subcategory":subcategory,
            "main_topic":"",
            "tags":tags_text,
            "description":description,
            "content_summary":overall_summary,
            "title_entities":"",
            "chatgpt_meaningful_title":meaningful_title,
            "chatgpt_summary_only":True
        }

        try:
            report=write_html_report(
                folder,base,meta,video,sections
            )
            cleanup_stale_reports(folder,report)
            cleanup_stale_chatgpt_files(folder,vid)

            con=db_connect()
            con.execute(
                """UPDATE videos
                   SET category=?,
                       subcategory=?,
                       tags=?,
                       chatgpt_report_hash=?,
                       report_html=?,
                       chatgpt_summary_file=?,
                       final_status='PASS',
                       failure_reason=''
                   WHERE video_id=?""",
                (
                    category,
                    subcategory,
                    tags_text,
                    expected_report_hash,
                    str(report),
                    str(summary_path),
                    vid
                )
            )
            con.commit()
            con.close()

            count+=1
            print(f"Regenerated from canonical ChatGPT JSON: {report.name}")

        except Exception as ex:
            append_video_error(
                folder,base,"CHATGPT REPORT REGENERATION FAILED",
                f"{type(ex).__name__}: {ex}",
                traceback.format_exc()
            )
            set_video_final_status(
                vid,"FAIL",
                f"ChatGPT report regeneration failed: {ex}"
            )
            failed+=1
            print(f"FAILED report regeneration for {vid}: {ex}")

    print(
        f"Regenerated {count} ChatGPT-based report(s). "
        f"Skipped unchanged: {skipped}. Failed: {failed}."
    )



def _rename_if_exists(src,dst):
    src=Path(src)
    dst=Path(dst)
    if not src.exists():
        return None
    if src.resolve()==dst.resolve():
        return dst
    dst.parent.mkdir(parents=True,exist_ok=True)
    if dst.exists():
        raise FileExistsError(f"Target already exists: {dst}")
    src.rename(dst)
    return dst

def _best_physical_base(folder, fallback):
    media=find_any_media(folder)
    if media:
        return media.stem
    reports=list(Path(folder).glob("*.report.html"))
    if reports:
        return reports[0].name[:-len(".report.html")]
    return safe_name(fallback)



def resolved_approved_title(video_id, preferred_title=None):
    """
    Resolve the title to apply during rename.

    Priority:
    1. Explicit preferred_title supplied by reviewed CSV
    2. Approved Title / ChatGPT Title already stored in canonical summary
    3. identity_json meaningful_title
    4. current clean_title
    5. original_title
    """
    vid=str(video_id or "").strip()
    if preferred_title:
        return safe_name(str(preferred_title).strip(),vid)

    folder=locate_existing_folder(vid)
    if folder:
        summary=canonical_chatgpt_summary_path(folder,vid)
        if summary.exists():
            try:
                obj=json.loads(summary.read_text(encoding="utf-8"))
                title=str(
                    obj.get("meaningful_title")
                    or obj.get("imported_title")
                    or ""
                ).strip()
                if title:
                    return safe_name(title,vid)
            except Exception:
                pass

    con=db_connect()
    cols=video_table_columns()
    identity_expr="identity_json" if "identity_json" in cols else "NULL AS identity_json"
    row=con.execute(
        f"SELECT {identity_expr},clean_title,original_title FROM videos WHERE video_id=?",
        (vid,)
    ).fetchone()
    con.close()

    if row:
        identity_json,clean,orig=row
        if identity_json:
            try:
                identity=json.loads(identity_json or "{}")
                title=str(identity.get("meaningful_title") or "").strip()
                if title:
                    return safe_name(title,vid)
            except Exception:
                pass
        return safe_name(clean or orig or vid,vid)

    return safe_name(vid or "Video")


def rebuild_report_after_rename(video_id, folder, applied_title):
    try:
        _approved_title=resolved_approved_title(video_id)
    except Exception:
        _approved_title=''
    """
    Rebuild the report after any physical rename so the HTML video player
    references the CURRENT local media filename.
    """
    vid=str(video_id)
    folder=Path(folder)
    current_media=find_any_media(folder)
    if not current_media:
        return False,"Current media file not found after rename"

    summary_obj,summary_path=load_chatgpt_summary_for_video(vid)

    con=db_connect()
    cols=video_table_columns()
    sql=select_existing_video_columns([
        "url","original_title","clean_title","channel","upload_date",
        "platform","description","category","subcategory","tags"
    ])
    row=con.execute(f"SELECT {sql} FROM videos WHERE video_id=?",(vid,)).fetchone()
    con.close()

    if not row:
        return False,"Video ID not found in SQLite after rename"

    (
        url,orig,clean,channel,upload_date,platform,db_description,
        db_category,db_subcategory,db_tags
    )=row

    description_file=find_first(
        support_dir(folder),
        [f"{applied_title}.description","*.description"]
    )
    description=(
        description_file.read_text(encoding="utf-8",errors="replace")
        if description_file and description_file.exists()
        else (db_description or "")
    )

    if summary_obj:
        normalized=normalize_chatgpt_result_video(summary_obj)
        sections=normalized.get("sections") or []
        sections,ts_errors,ts_warnings=validate_and_normalize_sections(sections)
        if ts_errors:
            return False,"Invalid timestamps in canonical ChatGPT summary: "+"; ".join(ts_errors)

        category=str(summary_obj.get("category") or normalized.get("category") or db_category or "")
        subcategory=str(summary_obj.get("subcategory") or normalized.get("subcategory") or db_subcategory or "")
        tags_obj=summary_obj.get("tags")
        if isinstance(tags_obj,list):
            tags_text=", ".join(str(x) for x in tags_obj if str(x).strip())
        else:
            tags_text=str(tags_obj or db_tags or "")
        overall_summary=str(
            summary_obj.get("summary")
            or summary_obj.get("overall_summary")
            or normalized.get("summary")
            or ""
        )
        meaningful_title=str(
            summary_obj.get("meaningful_title")
            or summary_obj.get("imported_title")
            or applied_title
        )
    else:
        # Fallback: keep report valid using available local sections/cache.
        try:
            p=temp_paths(vid)
            sections=json.loads(p["chapters"].read_text(encoding="utf-8")) if p["chapters"].exists() else []
            if not isinstance(sections,list):
                sections=[]
        except Exception:
            sections=[]
        category=db_category or ""
        subcategory=db_subcategory or ""
        tags_text=db_tags or ""
        overall_summary=""
        meaningful_title=applied_title

    meta={
        "video_id":vid,
        "url":url or "",
        "original_title":orig or "",
        "clean_title":applied_title,
        "channel":channel or "",
        "upload_date":upload_date or "",
        "platform":platform or "",
        "category":category,
        "subcategory":subcategory,
        "main_topic":"",
        "tags":tags_text,
        "description":description,
        "content_summary":overall_summary,
        "title_entities":"",
        "chatgpt_meaningful_title":meaningful_title,
        "chatgpt_summary_only":bool(summary_obj)
    }

    report=write_html_report(
        folder,
        applied_title,
        meta,
        current_media,
        sections
    )
    cleanup_stale_reports(folder,report)

    con=db_connect()
    con.execute(
        "UPDATE videos SET report_html=?,local_video=? WHERE video_id=?",
        (str(report),str(current_media),vid)
    )
    con.commit()
    con.close()

    return True,str(report)


def verify_report_video_playback_link(video_id, folder):
    """
    Verify that the generated report references the current media filename.
    """
    vid=str(video_id)
    folder=Path(folder)
    media=find_any_media(folder)
    reports=list(folder.glob("*.report.html"))

    if not media:
        return False,"No media file found"
    if not reports:
        return False,"No HTML report found"

    report=reports[0]
    try:
        body=report.read_text(encoding="utf-8",errors="replace")
    except Exception as ex:
        return False,f"Cannot read report: {ex}"

    if media.name not in body:
        return False,f"Report does not reference current media '{media.name}'"

    return True,f"{report.name} -> {media.name}"

def apply_title_to_video_id(video_id,new_title=None,channel_override=None,upload_date_override=None):
    """
    One-step safe rename workflow.

    Applies approved/ChatGPT title and takes care of:
      - media filename
      - report filename
      - .original-title marker filename
      - Date - Title video folder
      - Channel parent folder
      - SQLite paths/title
      - regenerated HTML report with current MP4 filename
      - report playback-link verification
    """
    vid=str(video_id or "").strip()
    if not vid:
        return False,"Missing Video ID"

    approved_title=resolved_approved_title(vid,new_title)
    if not approved_title:
        return False,"No approved/ChatGPT title could be resolved"

    con=db_connect()
    cols=video_table_columns()
    sql=select_existing_video_columns([
        "original_title","clean_title","upload_date","channel",
        "local_folder","local_video","report_html"
    ])
    row=con.execute(f"SELECT {sql} FROM videos WHERE video_id=?",(vid,)).fetchone()
    con.close()

    if not row:
        return False,"Video ID not found in SQLite"

    orig,clean,db_upload_date,db_channel,db_folder,db_video,db_report=row
    channel=str(channel_override or db_channel or "").strip()
    upload_date=str(upload_date_override or db_upload_date or "").strip()

    folder=locate_existing_folder(vid)
    if folder is None and db_folder:
        candidate=Path(db_folder)
        if candidate.exists():
            folder=candidate

    if folder is None:
        return False,"Video folder not found"

    folder=Path(folder)

    # Recover missing metadata before target path calculation.
    if not channel or not upload_date:
        resolved_channel,resolved_date=resolve_folder_metadata(
            vid,folder,channel,upload_date
        )
        channel=channel or resolved_channel
        upload_date=upload_date or resolved_date

    if not channel:
        return False,"Channel could not be resolved"
    if not upload_date:
        return False,"Upload date could not be resolved"

    old_base=_best_physical_base(folder,clean or orig or vid)
    desired_folder=video_folder_path(approved_title,upload_date,channel)
    desired_folder.parent.mkdir(parents=True,exist_ok=True)

    try:
        # Rename media.
        media=find_any_media(folder)
        if media:
            media_target=folder/f"{approved_title}{media.suffix.lower()}"
            if media.name!=media_target.name:
                if media_target.exists() and media_target.resolve()!=media.resolve():
                    return False,f"Target media already exists: {media_target.name}"
                media.rename(media_target)

        # Rename report filename first; content rebuilt after final folder move.
        reports=list(folder.glob("*.report.html"))
        if reports:
            report_target=folder/f"{approved_title}.report.html"
            preferred=None
            if db_report:
                rp=Path(db_report)
                if rp.exists() and rp.parent==folder:
                    preferred=rp
            src_report=preferred or reports[0]
            if src_report.name!=report_target.name:
                if report_target.exists() and report_target.resolve()!=src_report.resolve():
                    report_target.unlink()
                src_report.rename(report_target)
            for extra in folder.glob("*.report.html"):
                if extra!=report_target:
                    try: extra.unlink()
                    except Exception: pass

        # Keep .original-title filename and content unchanged.

        # Preserve canonical Video-ID data files.
        cleanup_stale_chatgpt_files(folder,vid)

        # Move folder into Channel parent / Date - Title.
        final_folder=folder
        if folder.resolve()!=desired_folder.resolve():
            if desired_folder.exists():
                marker=desired_folder/"_data"/".video_id"
                existing_vid=""
                if marker.exists():
                    try:
                        existing_vid=marker.read_text(
                            encoding="utf-8",errors="ignore"
                        ).strip()
                    except Exception:
                        existing_vid=""
                if existing_vid==vid:
                    # Prefer existing correct target only when current source folder is empty-ish.
                    return False,f"Target folder for same Video ID already exists: {desired_folder}"
                return False,f"Target folder already exists: {desired_folder}"

            try:
                folder.rename(desired_folder)
            except PermissionError:
                # Windows fallback.
                shutil.move(str(folder),str(desired_folder))
            final_folder=desired_folder

        final_media=find_any_media(final_folder)

        # Update title/path before report regeneration.
        con=db_connect()
        con.execute("""
          UPDATE videos
          SET clean_title=?,
              local_folder=?,
              local_video=?,
              title_finalized=1
          WHERE video_id=?
        """,(
            approved_title,
            str(final_folder),
            str(final_media) if final_media else "",
            vid
        ))
        con.commit()
        con.close()

        # Regenerate report after ALL rename/move operations.
        rebuilt,msg=rebuild_report_after_rename(
            vid,
            final_folder,
            approved_title
        )
        if not rebuilt:
            return False,f"Rename succeeded, but report rebuild failed: {msg}"

        valid,verify_msg=verify_report_video_playback_link(
            vid,
            final_folder
        )
        if not valid:
            return False,f"Rename succeeded, but playback verification failed: {verify_msg}"

        return True,(
            f"{old_base} -> {approved_title}; "
            f"folder -> {final_folder}; "
            f"playback OK"
        )

    except Exception as ex:
        return False,f"{type(ex).__name__}: {ex}"


def apply_chatgpt_titles_and_rename():
    """
    Apply imported ChatGPT meaningful titles to physical folder/file names.
    Matching is always by video_id.
    """
    con=db_connect()
    rows=con.execute("""
      SELECT video_id,original_title,clean_title,upload_date,channel,local_folder,
             chatgpt_imported,identity_json
      FROM videos
      WHERE COALESCE(chatgpt_imported,0)=1
      ORDER BY rowid
    """).fetchall()
    con.close()

    if not rows:
        print("No imported ChatGPT titles found.")
        return

    changed=0
    skipped=0
    failed=0

    for vid,orig,clean,upload_date,channel,local_folder,chatgpt_imported,identity_json in rows:
        try:
            try:
                identity=json.loads(identity_json or "{}")
            except Exception:
                identity={}

            new_title=safe_name(identity.get("meaningful_title") or clean or orig,vid)
            if not new_title:
                skipped+=1
                continue

            folder=locate_existing_folder(vid)
            if folder is None:
                print(f"SKIP {vid}: folder not found")
                skipped+=1
                continue

            folder=Path(folder)
            old_base=_best_physical_base(folder,clean or orig or vid)
            desired_folder_name=folder_name_for(new_title,upload_date,channel)
            desired_folder=folder.parent/desired_folder_name

            media=find_any_media(folder)
            if media:
                media_target=folder/f"{new_title}{media.suffix.lower()}"
                if media.name != media_target.name:
                    _rename_if_exists(media,media_target)
                    media=media_target

            report_candidates=list(folder.glob("*.report.html"))
            report_target=folder/f"{new_title}.report.html"
            if report_candidates:
                src_report=report_candidates[0]
                if src_report.name != report_target.name:
                    if report_target.exists():
                        report_target.unlink()
                    src_report.rename(report_target)
                for extra in folder.glob("*.report.html"):
                    if extra != report_target:
                        try: extra.unlink()
                        except Exception: pass

            for marker_file in list(folder.glob("*.original-title")):
                marker_target=find_original_title_marker(folder)
                if marker_file != marker_target:
                    if marker_target.exists():
                        marker_target.unlink()
                    marker_file.rename(marker_target)

            summary_path=canonical_chatgpt_summary_path(folder,vid)
            if summary_path.exists():
                cleanup_stale_chatgpt_files(folder,vid)

            final_folder=folder
            if folder.name != desired_folder_name:
                if desired_folder.exists():
                    raise FileExistsError(
                        f"Cannot rename folder because target already exists: {desired_folder}"
                    )
                folder.rename(desired_folder)
                final_folder=desired_folder

            final_media=find_any_media(final_folder)
            final_report=final_folder/f"{new_title}.report.html"

            con=db_connect()
            con.execute("""
              UPDATE videos
              SET clean_title=?,
                  local_folder=?,
                  local_video=?,
                  report_html=?,
                  title_finalized=1
              WHERE video_id=?
            """,(
                new_title,
                str(final_folder),
                str(final_media) if final_media else "",
                str(final_report) if final_report.exists() else "",
                vid
            ))
            con.commit()
            con.close()

            print(f"RENAMED {vid}: {old_base} -> {new_title}")
            changed+=1

        except Exception as ex:
            failed+=1
            try:
                current_folder=locate_existing_folder(vid)
                if current_folder:
                    append_video_error(
                        current_folder,
                        safe_name(clean or orig or vid),
                        "APPLY CHATGPT TITLE / RENAME FAILED",
                        f"{type(ex).__name__}: {ex}",
                        traceback.format_exc()
                    )
            except Exception:
                pass
            print(f"FAILED {vid}: {ex}")

    export_csv()

    print("")
    print("Apply ChatGPT Titles complete")
    print(f"Renamed: {changed}")
    print(f"Skipped: {skipped}")
    print(f"Failed : {failed}")
    print("video_list.csv updated from SQLite.")

def organize_existing_library():
    """Move legacy support files from video-folder root into _data."""
    if not DOWNLOADS.exists():
        print("Downloads folder does not exist yet.")
        return

    moved=0
    skipped=0
    for folder in [p for p in DOWNLOADS.iterdir() if p.is_dir()]:
        data=support_dir(folder)

        for fp in list(folder.iterdir()):
            if not fp.is_file():
                continue

            # User-facing files remain at top level.
            if fp.suffix.lower() in {".mp4",".mkv",".webm",".mov",".m4v",".avi",".m4a",".mp3"}:
                skipped+=1
                continue
            if fp.name.endswith(".report.html") or fp.name.endswith(".original-title"):
                skipped+=1
                continue

            # Move known support files.
            support=(
                fp.name==".video_id"
                or ".transcript_" in fp.name
                or fp.name.endswith(".en.srt")
                or fp.name.endswith(".description")
                or fp.name.endswith(".info.json")
                or fp.name.endswith(".ERROR.txt")
                or fp.suffix.lower() in {".jpg",".jpeg",".png",".webp"}
            )
            if not support:
                continue

            target=data/fp.name
            try:
                if target.exists():
                    if files_equal(fp, target):
                        fp.unlink()
                    else:
                        target=unique_conflict_path(target, marker="legacy")
                        shutil.move(str(fp),str(target))
                else:
                    shutil.move(str(fp),str(target))
                moved+=1
            except Exception as e:
                log(f"Organize failed {fp}: {e}")

    print(f"Library organization complete. Moved: {moved}, left top-level: {skipped}")

def refresh_reports():
    """Refresh HTML sources after a user manually renames a local video file."""
    con=db_connect()
    rows=con.execute("""
      SELECT video_id,url,original_title,clean_title,channel,upload_date,platform,
             category,subcategory,main_topic,tags,description
      FROM videos ORDER BY upload_date DESC,rowid DESC
    """).fetchall()
    con.close()
    print(f"Refreshing reports for {len(rows)} library records...")
    for i,row in enumerate(rows,1):
        vid,url,orig,clean,channel,upload_date,platform,category,subcategory,topic,tags,desc=row
        folder=locate_existing_folder(vid)
        if not folder:
            continue
        video=find_any_media(folder)
        p=temp_paths(vid)
        sections=[]
        if p["chapters"].exists():
            try: sections=json.loads(p["chapters"].read_text(encoding="utf-8"))
            except Exception: sections=[]
        if not chapters_are_useful(sections):
            try:
                sections=rebuild_sections_for_report(vid,orig,RUNTIME.get("use_llm",True))
            except Exception as ex:
                log(f"Report chapter rebuild failed {vid}: {ex}")
                sections=[]
        identity=None
        if p["identity"].exists():
            try: identity=json.loads(p["identity"].read_text(encoding="utf-8"))
            except Exception: identity=None
        base=safe_name(clean or orig,vid)
        meta={"video_id":vid,"url":url,"original_title":orig,"clean_title":base,
              "channel":channel,"upload_date":upload_date,"platform":platform,
              "category":category or "","subcategory":subcategory or "",
              "main_topic":topic or "","tags":tags or "","description":desc or "",
              "content_summary":str(identity.get("summary") or "") if identity else "",
              "title_entities":", ".join(str(x) for x in (identity.get("title_entities") or [])) if identity else ""}
        sections=attach_source_text_to_sections(vid,sections)
        report=write_html_report(folder,base,meta,video,sections)
        con=db_connect()
        con.execute("UPDATE videos SET local_video=?,local_folder=?,report_html=? WHERE video_id=?",
                    (str(video or ""),str(folder),str(report),vid))
        con.commit(); con.close()
        print(f"{i}/{len(rows)} refreshed: {base}")
    export_csv()
    print("Report refresh complete.")



WEB_JOBS={}
WEB_JOB_TASKS={}
WEB_JOB_CONTEXTS={}
WEB_JOB_LOCK=threading.RLock()
WEB_JOB_QUEUE=queue.Queue()
WEB_QUEUE_PAUSED=False
WEB_WORKER_STARTED=False
WEB_JOBS_RESTORED=False
WEB_JOB_PERSIST_LAST=0.0

def web_job_state_path():
    path=BASE/"data"/"database"/"job_queue_state.json"
    path.parent.mkdir(parents=True,exist_ok=True)
    return path

def web_persist_job_state(force=False):
    """Persist a compact queue snapshot without slowing high-frequency progress updates."""
    global WEB_JOB_PERSIST_LAST
    now=time.monotonic()
    if not force and now-WEB_JOB_PERSIST_LAST<1.0:
        return False
    with WEB_JOB_LOCK:
        payload=queue_payload(WEB_JOBS,WEB_JOB_TASKS,limit=100)
    try:
        write_job_state(web_job_state_path(),payload)
        WEB_JOB_PERSIST_LAST=now
        return True
    except Exception as ex:
        log(f"Queue-state persistence warning: {type(ex).__name__}: {ex}")
        return False

def web_restore_persisted_jobs(force=False):
    """Restore prior jobs once; unfinished work becomes explicit INTERRUPTED rows."""
    global WEB_JOBS_RESTORED
    with WEB_JOB_LOCK:
        if WEB_JOBS_RESTORED and not force:
            return {"restored":0,"interrupted":0}
        if force:
            WEB_JOBS.clear();WEB_JOB_TASKS.clear();WEB_JOB_CONTEXTS.clear()
        payload=load_job_state(web_job_state_path())
        restored=interrupted=0
        tasks=dict(payload.get("tasks") or {}) if isinstance(payload,dict) else {}
        for raw in list(payload.get("jobs") or []) if isinstance(payload,dict) else []:
            if not isinstance(raw,dict):continue
            row=interrupted_copy(raw)
            jid=str(row.get("job_id") or "").strip()
            if not jid:continue
            if str(row.get("status") or "").upper()=="INTERRUPTED":interrupted+=1
            WEB_JOBS[jid]=row;restored+=1
            spec=tasks.get(jid)
            if isinstance(spec,dict):
                func=globals().get(str(spec.get("name") or ""))
                args=spec.get("args") or []
                kwargs=spec.get("kwargs") or {}
                if callable(func) and isinstance(args,list) and isinstance(kwargs,dict):
                    WEB_JOB_TASKS[jid]=(func,tuple(args),dict(kwargs))
                    WEB_JOB_CONTEXTS[jid]=JobContext(jid,options=_download_options_for_task(func,tuple(args),dict(kwargs)))
        WEB_JOBS_RESTORED=True
    if restored:
        web_persist_job_state(force=True)
    return {"restored":restored,"interrupted":interrupted}

# Browser emergency-stop / progress infrastructure.
WEB_STOP_EVENT=threading.Event()
WEB_PROCESS_LOCK=threading.RLock()
WEB_ACTIVE_PROCESSES=set()
WEB_DRIVER_LOCK=threading.RLock()
WEB_ACTIVE_DRIVERS=set()
WEB_JOB_CONTEXT=threading.local()
WEB_VIDEO_PROGRESS_LOCK=threading.RLock()
WEB_VIDEO_PROGRESS={}
WEB_CHILD_CONTEXTS={}

def web_reset_video_progress():
    with WEB_VIDEO_PROGRESS_LOCK:
        WEB_VIDEO_PROGRESS.clear()

def web_video_progress(video_id,*,title="",percent=None,speed="",eta="",stage="Downloading",status="RUNNING"):
    """Persist independent child-video transfer state and aggregate parent percent."""
    key=str(video_id or "").strip()
    if not key:return
    with WEB_VIDEO_PROGRESS_LOCK:
        row=WEB_VIDEO_PROGRESS.setdefault(key,{"video_id":key,"percent":0.0})
        if title:row["title"]=str(title)
        if percent is not None:
            try:row["percent"]=max(0.0,min(100.0,float(percent)))
            except Exception:pass
        if speed:row["speed"]=str(speed)
        if eta:row["eta"]=str(eta)
        row["stage"]=str(stage or "Downloading")
        row["status"]=str(status or "RUNNING").upper()
        row["updated_at"]=time.time()
        snapshot_rows=[dict(value) for value in WEB_VIDEO_PROGRESS.values()]
        aggregate=(sum(float(value.get("percent") or 0) for value in snapshot_rows)/len(snapshot_rows)) if snapshot_rows else 0.0
    jid=getattr(WEB_JOB_CONTEXT,"job_id",None)
    if jid:
        web_job_update(jid,transfer_percent=aggregate,active_videos=snapshot_rows)
        web_job_log(jid,"video_progress",video_id=key,title=title,percent=percent,speed=speed,eta=eta,stage=stage,status=status)

def web_seed_video_progress(items):
    """Create queued child rows before executors start, without one write per row."""
    parent_job_id=getattr(WEB_JOB_CONTEXT,"job_id",None)
    with WEB_VIDEO_PROGRESS_LOCK:
        WEB_VIDEO_PROGRESS.clear()
        for item in items:
            if isinstance(item,dict):
                video_id=item.get("video_id") or item.get("id")
                title=item.get("title") or video_id
            else:
                video_id=item[0] if len(item)>0 else ""
                title=(item[3] or item[2] or video_id) if len(item)>3 else video_id
                source_url=item[1] if len(item)>1 else ""
            if video_id:
                WEB_VIDEO_PROGRESS[str(video_id)]={"video_id":str(video_id),"title":str(title or video_id),"source_url":str((item.get("source_url") or item.get("url") or "") if isinstance(item,dict) else source_url),"log_path":str(web_child_log_path(parent_job_id,video_id)) if parent_job_id else "","percent":0.0,"speed":"","eta":"","stage":"Queued","status":"QUEUED","updated_at":time.time()}
        rows=[dict(value) for value in WEB_VIDEO_PROGRESS.values()]
    jid=getattr(WEB_JOB_CONTEXT,"job_id",None)
    if jid:web_job_update(jid,active_videos=rows,transfer_percent=0.0)

def web_job_log_path(job_id):
    folder=BASE/"logs"/"runs";folder.mkdir(parents=True,exist_ok=True)
    return folder/(safe_name(str(job_id),"job")+".jsonl")

def web_child_log_path(job_id,video_id):
    folder=BASE/"logs"/"runs"/safe_name(str(job_id),"job")
    folder.mkdir(parents=True,exist_ok=True)
    return folder/(safe_name(str(video_id),"video")+".jsonl")

def web_job_log(job_id,event,**data):
    """Persistent per-run diagnostics. Retained until a reviewed manual purge."""
    if not str(job_id or "").strip():
        return
    try:
        row={"at":time.strftime("%Y-%m-%d %H:%M:%S"),"event":str(event),**web_json_safe(data)}
        with open(web_job_log_path(job_id),"a",encoding="utf-8") as f:f.write(json.dumps(row,ensure_ascii=False)+"\n")
        video_id=str(data.get("video_id") or "").strip()
        if video_id:
            with open(web_child_log_path(job_id,video_id),"a",encoding="utf-8") as f:f.write(json.dumps(row,ensure_ascii=False)+"\n")
    except Exception:pass

def web_job_video_log(job_id,video_id="",limit=200):
    """Return recent readable run-log lines, optionally restricted to one child video."""
    path=web_child_log_path(job_id,video_id) if str(video_id or "").strip() else web_job_log_path(job_id)
    if not path.is_file():return []
    wanted=str(video_id or "").strip()
    rows=[]
    try:
        for raw in path.read_text(encoding="utf-8",errors="replace").splitlines():
            try:item=json.loads(raw)
            except Exception:continue
            row_video=str(item.get("video_id") or "")
            if wanted and row_video!=wanted:continue
            event=str(item.get("event") or "event")
            at=str(item.get("at") or "")
            message=str(item.get("message") or item.get("stage") or item.get("status") or "")
            progress=""
            if item.get("percent") is not None:
                progress=f" {item.get('percent')}%"
            speed=f" {item.get('speed')}" if item.get("speed") else ""
            identity=f" [{row_video}]" if row_video else ""
            rows.append(f"{at}{identity} {event}{progress}{speed}{(': '+message) if message else ''}".strip())
    except Exception as ex:
        return [f"Could not read log: {type(ex).__name__}: {ex}"]
    return rows[-max(1,min(1000,int(limit or 200))):]

def purge_reviewed_run_logs():
    """Remove retained diagnostic run logs only when no task is active."""
    state=web_queue_state()
    if state.get("running") or state.get("queued"):
        return {"ok":False,"message":"Wait for all tasks to finish before purging reviewed logs."}
    folder=BASE/"logs"/"runs"
    removed=0
    if folder.is_dir():
        for path in folder.glob("*.jsonl"):
            try:path.unlink();removed+=1
            except Exception:pass
    return {"ok":True,"message":f"Purged {removed} reviewed run log(s).","removed":removed}


def web_job_snapshot(job_id=None, limit=60):
    with WEB_JOB_LOCK:
        if job_id:
            d=dict(WEB_JOBS.get(job_id) or {})
            if d:
                d["log_path"]=str(web_job_log_path(job_id))
                if d.get("error"):
                    d["error_summary"]=str(d.get("error") or "")[-4000:]
            return d
        items=sorted(WEB_JOBS.values(),key=lambda x:x.get("created_at",0),reverse=True)
        compact=[]
        visible_items = items if limit is None else items[:max(0, int(limit or 0))]
        for x in visible_items:
            d=dict(x)
            jid=str(d.get("job_id") or "")
            if jid:
                d["log_path"]=str(web_job_log_path(jid))
            result=d.pop("result",None)
            error=d.pop("error",None)
            if result is not None:
                d["has_result"]=True
                if isinstance(result,dict):
                    d["result_summary"]={
                        str(k):web_json_safe(v)
                        for k,v in list(result.items())[:12]
                        if k not in {"items","records","rows","details","checks","messages","files"}
                    }
            if error:
                d["has_error"]=True
                d["error_summary"]=str(error)[-4000:]
            compact.append(d)
        return compact

def web_failed_job_rows(limit=25):
    """Return failed/warn/cancelled queue jobs, including persisted run-log failures."""
    rows=[];seen=set()
    with WEB_JOB_LOCK:
        jobs=sorted(WEB_JOBS.values(),key=lambda x:x.get("finished_at") or x.get("created_at") or 0,reverse=True)
        for x in jobs:
            status=str(x.get("status") or "").upper()
            if status not in {"FAILED","WARN","CANCELLED"}:
                continue
            d=dict(x);jid=str(d.get("job_id") or "")
            d["log_path"]=str(web_job_log_path(jid)) if jid else ""
            if d.get("error"):d["error_summary"]=str(d.get("error") or "")[-4000:]
            rows.append(web_json_safe(d));seen.add(jid)
    folder=BASE/"logs"/"runs"
    if folder.is_dir():
        for path in sorted(folder.glob("*.jsonl"),key=lambda p:p.stat().st_mtime,reverse=True):
            jid=path.stem
            if jid in seen:
                continue
            label="";status="";message="";error="";created=path.stat().st_mtime;finished=path.stat().st_mtime
            try:
                for line in path.read_text(encoding="utf-8",errors="replace").splitlines():
                    try:row=json.loads(line)
                    except Exception:continue
                    event=str(row.get("event") or "")
                    if event=="queued":
                        label=str(row.get("label") or label)
                    if row.get("status"):
                        status=str(row.get("status") or status).upper()
                        message=str(row.get("message") or message)
                        if row.get("finished_at"):finished=float(row.get("finished_at") or finished)
                    if row.get("error"):
                        error=str(row.get("error") or error)
            except Exception as ex:
                error=f"{type(ex).__name__}: {ex}"
            if status in {"FAILED","WARN","CANCELLED"} or error:
                rows.append({"job_id":jid,"label":label or "Background job","status":status or "FAILED","created_at":created,"finished_at":finished,"message":message or (error.splitlines()[-1] if error else "See run log"),"has_error":bool(error),"error_summary":error[-4000:] if error else "","log_path":str(path)})
            if len(rows)>=int(limit or 25):
                break
    return rows[:int(limit or 25)]


def web_job_update(job_id,**kwargs):
    with WEB_JOB_LOCK:
        if job_id in WEB_JOBS:WEB_JOBS[job_id].update(kwargs)
    status=str(kwargs.get("status") or "").upper()
    if status in {"RUNNING","SUCCESS","WARN","FAILED","CANCELLED","INTERRUPTED"}:
        web_job_log(job_id,"status",**kwargs)
    web_persist_job_state(force=status in {"QUEUED","RUNNING","SUCCESS","WARN","FAILED","CANCELLED","INTERRUPTED"})

def web_update_current_job_media(title="",thumbnail_url="",thumbnail_path="",video_id="",source_url="",local_folder="",local_video=""):
    """Attach presentation metadata to the currently running queue job."""
    job_id=getattr(WEB_JOB_CONTEXT,"job_id",None)
    if not job_id:
        return
    fields=metadata_job_fields(
        title=title,thumbnail_url=thumbnail_url,thumbnail_path=thumbnail_path,
        video_id=video_id,source_url=source_url
    )
    if local_folder:
        fields["local_folder"]=str(local_folder)
        fields["destination"]=str(local_folder)
    if local_video:
        fields["local_video"]=str(local_video)
        fields["output_path"]=str(local_video)
    web_job_update(job_id,**fields)

def web_current_job_context():
    ctx=getattr(WEB_JOB_CONTEXT,"context",None)
    return ctx if isinstance(ctx,JobContext) else None

def web_child_context(parent_job_id,video_id,options=None):
    key=(str(parent_job_id or ""),str(video_id or ""))
    with WEB_JOB_LOCK:
        ctx=WEB_CHILD_CONTEXTS.get(key)
        if ctx is None:
            ctx=JobContext(f"{key[0]}:{key[1]}",options=options)
            WEB_CHILD_CONTEXTS[key]=ctx
        return ctx

def web_child_stop_state(ctx=None):
    ctx=ctx or web_current_job_context()
    reason=str(getattr(ctx,"cancel_reason","") or "Cancelled by user")
    paused="pause" in reason.lower()
    return ("PAUSED" if paused else "CANCELLED"),reason

def _update_child_row(parent_job_id,video_id,**fields):
    parent=str(parent_job_id or "");wanted=str(video_id or "")
    with WEB_JOB_LOCK:
        job=WEB_JOBS.get(parent)
        if not job:return False
        rows=[];found=False
        for raw in list(job.get("active_videos") or []):
            row=dict(raw)
            if str(row.get("video_id") or "")==wanted:
                row.update(fields);row["updated_at"]=time.time();found=True
            rows.append(row)
        if found:job["active_videos"]=rows
    if found:web_persist_job_state(force=True)
    return found

def web_pause_child_job(parent_job_id,video_id):
    ctx=WEB_CHILD_CONTEXTS.get((str(parent_job_id),str(video_id)))
    if not ctx:return False,"Video child is not active"
    ctx.request_cancel("Paused by user",terminate=True)
    _update_child_row(parent_job_id,video_id,status="PAUSING",stage="Pausing")
    web_job_log(parent_job_id,"child_pause_requested",video_id=str(video_id),reason="Paused by user")
    return True,"Video pause requested; partial files are retained for resume."

def web_cancel_child_job(parent_job_id,video_id):
    ctx=WEB_CHILD_CONTEXTS.get((str(parent_job_id),str(video_id)))
    if not ctx:return False,"Video child is not active"
    ctx.request_cancel("Cancelled by user",terminate=True)
    _update_child_row(parent_job_id,video_id,status="CANCELLING",stage="Cancelling")
    web_job_log(parent_job_id,"child_cancel_requested",video_id=str(video_id),reason="Cancelled by user")
    return True,"Video cancellation requested; sibling downloads continue."

def web_retry_child_job(parent_job_id,video_id):
    parent=web_job_snapshot(str(parent_job_id))
    child=next((dict(row) for row in parent.get("active_videos") or [] if str(row.get("video_id") or "")==str(video_id)),None)
    if not child:return False,"Video child was not found",None
    url=str(child.get("source_url") or "").strip()
    if not url:return False,"Video child has no source URL",None
    options=dict(parent.get("download_options") or {})
    action=str(options.get("action") or "full_download")
    jid=web_start_job(
        f"Resume: {child.get('title') or video_id}",web_download_workflow,[url],
        action=action,quality=options.get("quality","1080"),use_ollama=options.get("use_ollama",False),
        save_srt=options.get("save_srt",False),prefix_upload_date=options.get("prefix_upload_date",False),
        download_comments=options.get("download_comments",False),category=options.get("category","Entertainment"),
        vtt=options.get("vtt",True),category_mode=options.get("category_mode","source"),smart_resume=True,
    )
    web_job_update(jid,parent_job_id=str(parent_job_id),retry_of_video_id=str(video_id))
    _update_child_row(parent_job_id,video_id,status="RETRY_QUEUED",stage="Retry queued",retry_job_id=jid)
    web_job_log(parent_job_id,"child_retry_queued",video_id=str(video_id),retry_job_id=jid)
    return True,"Video resume/retry queued",jid

def web_register_process(proc):
    if proc is None:return
    try:
        with WEB_PROCESS_LOCK:WEB_ACTIVE_PROCESSES.add(proc)
    except Exception:pass
    ctx=web_current_job_context()
    if ctx:
        try:ctx.register_process(proc)
        except Exception:pass

def web_unregister_process(proc):
    if proc is None:return
    try:
        with WEB_PROCESS_LOCK:WEB_ACTIVE_PROCESSES.discard(proc)
    except Exception:pass
    ctx=web_current_job_context()
    if ctx:
        try:ctx.unregister_process(proc)
        except Exception:pass

def web_register_driver(driver):
    if driver is None:return
    try:
        with WEB_DRIVER_LOCK:WEB_ACTIVE_DRIVERS.add(driver)
    except Exception:pass
    ctx=web_current_job_context()
    if ctx:
        try:ctx.register_driver(driver)
        except Exception:pass

def web_unregister_driver(driver):
    if driver is None:return
    try:
        with WEB_DRIVER_LOCK:WEB_ACTIVE_DRIVERS.discard(driver)
    except Exception:pass
    ctx=web_current_job_context()
    if ctx:
        try:ctx.unregister_driver(driver)
        except Exception:pass

def web_global_stop_requested():
    return bool(WEB_STOP_EVENT.is_set() or globals().get("STOP",False))

def web_stop_requested():
    ctx=web_current_job_context()
    return bool(web_global_stop_requested() or (ctx.cancelled() if ctx else False))

def web_job_progress(message,processed=None,total=None,phase=None,transfer_percent=None):
    """Update global state plus separate job batch/stage/transfer fields."""
    msg=str(message or "")
    jid=getattr(WEB_JOB_CONTEXT,"job_id",None)
    if jid:
        kw={"message":msg}
        if processed is not None:
            kw["processed"]=int(processed);kw["batch_processed"]=int(processed)
        if total is not None:
            kw["total"]=int(total);kw["batch_total"]=int(total)
        if phase is not None:kw["stage"]=str(phase)
        if transfer_percent is not None:
            try:kw["transfer_percent"]=max(0.0,min(100.0,float(transfer_percent)))
            except Exception:pass
        web_job_update(jid,**kw)
        web_job_log(jid,"progress",message=msg,processed=processed,total=total,phase=phase,transfer_percent=transfer_percent)
    state_kw={"message":msg,"current_status":msg}
    if phase:state_kw["phase"]=str(phase)
    if processed is not None:state_kw["processed"]=int(processed)
    if total is not None:state_kw["total"]=int(total)
    if transfer_percent is not None:state_kw["current_percent"]=transfer_percent
    try:set_state(**state_kw)
    except Exception:pass
    if msg:
        print(msg,flush=True)

def selenium_status():
    try:
        import selenium
        return {"ok":True,"installed":True,"version":str(getattr(selenium,"__version__","unknown")),"message":"Selenium is installed"}
    except Exception as ex:
        return {"ok":True,"installed":False,"version":"","message":f"Selenium is not installed: {type(ex).__name__}: {ex}"}

def ensure_selenium_installed(auto_install=True):
    """
    No-admin Selenium setup.
    First installs into the app's portable tools/python_packages directory.
    If that fails, tries --user as a secondary fallback.
    """
    st=selenium_status()
    if st.get("installed") or not auto_install:
        return st
    if getattr(sys,"frozen",False):
        return {"ok":False,"installed":False,"version":"",
                "message":"Selenium is missing from this packaged release. Reinstall/rebuild VideoHoarder; the frozen EXE cannot run pip."}

    PY_PACKAGES.mkdir(parents=True,exist_ok=True)
    attempts=[
        [sys.executable,"-m","pip","install","--upgrade","--target",str(PY_PACKAGES),"selenium"],
        [sys.executable,"-m","pip","install","--user","selenium"],
    ]
    last=""
    for idx,cmd in enumerate(attempts,1):
        if web_stop_requested():
            return {"ok":False,"installed":False,"version":"","message":"Selenium installation stopped by user."}
        web_job_progress(
            f"[SELENIUM] Not installed. Installation attempt {idx}/{len(attempts)}: {' '.join(str(x) for x in cmd[2:])}",
            phase="Selenium Setup"
        )
        proc=None
        timer=None
        try:
            flags=(subprocess.CREATE_NO_WINDOW if os.name=="nt" else 0)
            proc=subprocess.Popen(
                cmd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,
                encoding="utf-8",errors="replace",bufsize=1,creationflags=flags
            )
            web_register_process(proc)

            def _timeout_install():
                try:
                    if proc and proc.poll() is None:
                        proc.terminate()
                except Exception:pass
            timer=threading.Timer(300,_timeout_install);timer.daemon=True;timer.start()

            if proc.stdout:
                for line in proc.stdout:
                    line=line.rstrip()
                    if line:
                        print("[SELENIUM INSTALL] "+line,flush=True)
                    if web_stop_requested():
                        try:proc.terminate()
                        except Exception:pass
                        break
            rc=proc.wait()
            last=f"exit code {rc}"
            if rc==0:
                if str(PY_PACKAGES) not in sys.path:
                    sys.path.insert(0,str(PY_PACKAGES))
                import importlib as _importlib
                _importlib.invalidate_caches()
                st=selenium_status()
                if st.get("installed"):
                    web_job_progress(f"[SELENIUM] READY — version {st.get('version')}",phase="Selenium Setup")
                    return st
        except Exception as ex:
            last=f"{type(ex).__name__}: {ex}"
        finally:
            try:
                if timer:timer.cancel()
            except Exception:pass
            web_unregister_process(proc)

    return {"ok":False,"installed":False,"version":"","message":f"Automatic Selenium installation failed: {last}"}

def web_stop_everything():
    """Emergency stop for all current and queued work.

    Per-job cancellation is used for ordinary Cancel this job.  This function
    is intentionally the only path that sets the process-wide stop primitive.
    """
    global STOP
    STOP=True
    WEB_STOP_EVENT.set()
    stopped=[]
    errors=[]

    try:
        with WEB_JOB_LOCK:
            contexts=list(WEB_JOB_CONTEXTS.items())
            for jid,j in WEB_JOBS.items():
                status=str(j.get("status") or "").upper()
                ctx=WEB_JOB_CONTEXTS.get(jid)
                if ctx:
                    ctx.request_cancel("Cancelled by STOP EVERYTHING",terminate=False)
                if status=="QUEUED":
                    j.update(status="CANCELLED",message="Cancelled by STOP EVERYTHING",finished_at=time.time())
                    stopped.append(str(jid))
                elif status in {"RUNNING","CANCELLING"}:
                    j.update(status="CANCELLING",message="STOP EVERYTHING requested")
        for _jid,ctx in contexts:
            try:
                ctx.terminate_owned_processes();ctx.close_owned_drivers()
            except Exception as ex:
                errors.append(f"job context {_jid}: {type(ex).__name__}: {ex}")
    except Exception as ex:
        errors.append(f"jobs: {type(ex).__name__}: {ex}")

    try:
        with WEB_PROCESS_LOCK:
            procs=list(WEB_ACTIVE_PROCESSES)
        for proc in procs:
            try:
                if proc.poll() is None:
                    proc.terminate()
                    try:proc.wait(timeout=2)
                    except Exception:
                        try:proc.kill()
                        except Exception:pass
                    stopped.append(f"PID {getattr(proc,'pid','?')}")
            except Exception as ex:
                errors.append(f"process {getattr(proc,'pid','?')}: {type(ex).__name__}: {ex}")
    except Exception as ex:
        errors.append(f"process registry: {type(ex).__name__}: {ex}")

    try:
        with WEB_DRIVER_LOCK:
            drivers=list(WEB_ACTIVE_DRIVERS)
        for d in drivers:
            try:
                threading.Thread(target=lambda drv=d: drv.quit(),daemon=True).start()
                stopped.append("Selenium WebDriver")
            except Exception as ex:
                errors.append(f"webdriver: {type(ex).__name__}: {ex}")
    except Exception as ex:
        errors.append(f"driver registry: {type(ex).__name__}: {ex}")

    try:
        set_state(phase="STOPPED",current_status="STOP EVERYTHING requested",message="STOP EVERYTHING requested")
    except Exception:pass
    print("\n"+"!"*76)
    print("STOP EVERYTHING REQUESTED — queued work cancelled; child processes/drivers terminating.")
    print("!"*76,flush=True)
    return {"ok":not errors,"message":"STOP EVERYTHING requested","stopped":stopped,"errors":errors}

def web_queue_state():
    with WEB_JOB_LOCK:
        return {
            "paused":bool(WEB_QUEUE_PAUSED),
            "running":sum(1 for x in WEB_JOBS.values() if x.get("status")=="RUNNING"),
            "queued":sum(1 for x in WEB_JOBS.values() if x.get("status")=="QUEUED"),
            "failed":sum(1 for x in WEB_JOBS.values() if x.get("status")=="FAILED"),
            "warn":sum(1 for x in WEB_JOBS.values() if x.get("status")=="WARN"),
            "stop_requested":web_stop_requested()
        }



def cmd_result_summary(result,max_len=700):
    try:
        if result is None:return ""
        if isinstance(result,Path):return str(result)
        if isinstance(result,(str,int,float,bool)):s=str(result)
        elif isinstance(result,dict):
            parts=[]
            for key in ["message","path","file","csv","count","processed","total","applied","updated","created","repaired","deleted","moved","failed","source"]:
                if key in result and result.get(key) not in (None,"",[],{}):
                    parts.append(f"{key}={result.get(key)}")
            s=" | ".join(parts) if parts else json.dumps(web_json_safe(result),ensure_ascii=False)
        elif isinstance(result,(list,tuple,set)):s=f"{type(result).__name__} items={len(result)}"
        else:s=str(result)
        s=re.sub(r"\s+"," ",s).strip()
        return s if len(s)<=max_len else s[:max_len-3]+"..."
    except Exception:return ""


def web_result_outcome(result,http_status=None):
    """Return truthful terminal dashboard status: SUCCESS, WARN or FAILED."""
    if http_status is not None:
        try:
            if int(http_status)>=400:
                return "FAILED"
        except Exception:
            pass
    if not isinstance(result,dict):
        return "SUCCESS"

    status_text=" ".join(
        str(result.get(k) or "")
        for k in ("status","final_status","overall_status","result_status","state")
    ).upper()

    if any(t in status_text for t in ("FAILED","FAIL","ERROR","FATAL")):
        return "FAILED"

    warning_tokens=("WARN","WARNING","PARTIAL","ACTION REQUIRED","ATTENTION","INCOMPLETE")
    if any(t in status_text for t in warning_tokens):
        return "WARN"

    if result.get("ok") is False:
        return "FAILED"

    for key in ("failed","failures","errors","warnings","warn","unresolved","incomplete"):
        val=result.get(key)
        try:
            if isinstance(val,(int,float)) and val>0:
                return "WARN"
            if isinstance(val,(list,tuple,set,dict)) and len(val)>0:
                return "WARN"
        except Exception:
            pass

    steps=result.get("steps")
    if isinstance(steps,list):
        for step in steps:
            if not isinstance(step,dict):
                continue
            ss=str(step.get("status") or "").upper()
            if step.get("ok") is False or any(t in ss for t in warning_tokens) or any(t in ss for t in ("FAILED","FAIL","ERROR")):
                return "WARN"

    return "SUCCESS"

def cmd_dashboard_banner(status,label,job_id="",duration=None,result=None,error=""):
    state=str(status or "").upper();width=78
    if state in {"SUCCESS","COMPLETED"}:heading="DASHBOARD COMMAND COMPLETED SUCCESSFULLY";mark="="
    elif state in {"WARN","WARNING","PARTIAL"}:heading="DASHBOARD COMMAND COMPLETED WITH WARNINGS / ACTION REQUIRED";mark="!"
    elif state in {"FAILED","ERROR"}:heading="DASHBOARD COMMAND FAILED";mark="!"
    elif state in {"CANCELLED","CANCELED","STOPPED"}:heading="DASHBOARD COMMAND CANCELLED / STOPPED";mark="!"
    elif state=="STARTED":heading="DASHBOARD COMMAND STARTED";mark="-"
    elif state=="QUEUED":heading="DASHBOARD COMMAND QUEUED";mark="-"
    else:heading=f"DASHBOARD COMMAND {state or 'STATUS'}";mark="-"
    print("\n"+mark*width)
    print(heading)
    print(f"Command : {label or 'Dashboard command'}")
    if job_id:print(f"Job ID  : {job_id}")
    if duration is not None:
        try:print(f"Duration: {float(duration):.2f} seconds")
        except Exception:pass
    summary=cmd_result_summary(result)
    if summary:print(f"Result  : {summary}")
    if error:
        one=re.sub(r"\s+"," ",str(error)).strip()
        if len(one)>1200:one=one[:1197]+"..."
        print(f"Error   : {one}")
    print(mark*width,flush=True)

