def web_library_stats():
    con=db_connect();cols=video_table_columns()
    arch="COALESCE(archived,0)=0 AND COALESCE(current_present,1)=1" if "archived" in cols else "1=1"
    total=con.execute(f"SELECT COUNT(*) FROM videos WHERE {arch}").fetchone()[0]
    downloaded=con.execute(f"SELECT COUNT(*) FROM videos WHERE {arch} AND ((local_video IS NOT NULL AND local_video<>'') OR COALESCE(downloaded,0)=1)").fetchone()[0]
    failed=0
    fav=con.execute(f"SELECT COUNT(*) FROM videos WHERE {arch} AND COALESCE(favorite,0)=1").fetchone()[0] if "favorite" in cols else 0
    watched=con.execute(f"SELECT COUNT(*) FROM videos WHERE {arch} AND COALESCE(watched,0)=1").fetchone()[0] if "watched" in cols else 0
    latest=0
    if "downloaded_at" in cols:
        try:latest=con.execute(f"SELECT COUNT(*) FROM videos WHERE {arch} AND downloaded_at>=?",((datetime.now()-timedelta(days=7)).strftime("%Y-%m-%d %H:%M:%S"),)).fetchone()[0]
        except Exception:pass
    path_rows=[]
    if "local_folder" in cols:
        try:
            path_rows=con.execute(f"SELECT local_folder,local_video,downloaded,COALESCE(downloaded_at,'') FROM videos WHERE {arch}").fetchall()
        except Exception:
            path_rows=[]
    con.close()
    # Current unresolved failures are authoritative for the dashboard. Historical
    # failed jobs remain available in run logs but do not inflate this count.
    try:failed=web_current_failure_count()
    except Exception:failed=0

    db_total=int(total or 0)
    stat_source="SQLite database"
    recovery_needed=False
    available_downloaded=0
    missing_local_folders=0
    for local_folder,local_video,downloaded_flag,_downloaded_at in path_rows:
        folder_exists=bool(local_folder and Path(str(local_folder)).is_dir())
        if physical_media_available(local_folder,local_video,downloaded_flag):
            available_downloaded+=1
        elif int(downloaded_flag or 0) and local_folder and not folder_exists:
            missing_local_folders+=1
    try:
        downloaded_today=physical_downloaded_today_count(path_rows, finder=find_any_media)
    except Exception:
        downloaded_today=0

    fs_media=0;fs_latest=0
    exts={".mp4",".mkv",".webm",".m4v",".mov",".avi",".mp3",".m4a",".aac",".opus"}
    if DOWNLOADS.exists():
        cutoff=time.time()-7*86400
        try:
            for p in DOWNLOADS.rglob("*"):
                if not p.is_file() or p.suffix.lower() not in exts:
                    continue
                fs_media+=1
                try:
                    if p.stat().st_mtime>=cutoff:fs_latest+=1
                except Exception:pass
        except Exception:pass

    if db_total==0 and fs_media>0:
        # Do not hide the existing library just because SQLite is empty. These
        # counts are filesystem-derived until the recovery DB/index is rebuilt.
        total=fs_media
        downloaded=fs_media
        available_downloaded=fs_media
        if not latest:latest=fs_latest
        watched=0
        fav=0
        stat_source="Filesystem fallback — SQLite has 0 video rows"
        recovery_needed=True
    elif db_total>0 and latest==0 and fs_latest>0:
        # Older rows may not have downloaded_at populated.
        latest=fs_latest

    return {
        "total":int(total or 0),"downloaded":int(downloaded or 0),"failed":int(failed or 0),
        "available_downloaded_videos":int(available_downloaded or 0),
        "missing_local_folders":int(missing_local_folders or 0),
        "favorites":int(fav or 0),"unwatched":max(0,int(total or 0)-int(watched or 0)),"latest7":int(latest or 0),
        "database_rows":db_total,"filesystem_media":fs_media,"downloaded_today":int(downloaded_today or 0),"source":stat_source,
        "recovery_needed":recovery_needed,"library_root":str(DOWNLOADS),"database_path":str(DB),
        "root_source":str(BASE_RESOLUTION.get("source") or "")
    }

def refresh_dashboard_figures(full_rebuild=False):
    """Refresh and return the canonical figures used by Dashboard and workflows.

    ``full_rebuild=True`` runs the physical-library reconciliation/report export
    first.  Other callers can use the quick default to get fresh counts, current
    failures and queue state without starting the heavier scan.
    """
    rebuild_result=None
    if full_rebuild:
        rebuild_result=rebuild_database_and_library_exports()
    stats=web_library_stats()
    failures=web_current_failure_rows()
    payload={
        "ok":True,
        "rebuilt":bool(full_rebuild),
        "rebuild_result":web_json_safe(rebuild_result) if rebuild_result is not None else None,
        "stats":stats,
        "failure_count":len(failures),
        "failure_summary":summarize_current_failures(failures),
        "queue":web_queue_state(),
        "refreshed_at":time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    return payload


