def chatgpt_exchange_dir():
    p=BASE/"data"/"chatgpt"/"exchange"
    (p/"outgoing").mkdir(parents=True,exist_ok=True)
    (p/"incoming").mkdir(parents=True,exist_ok=True)
    return p

def chatgpt_exchange_save(filename,b64data,direction="outgoing"):
    safe=safe_name(Path(str(filename or "file.bin")).name) or "file.bin"
    folder=chatgpt_exchange_dir()/("incoming" if direction=="incoming" else "outgoing")
    data=base64.b64decode(b64data.encode("ascii"),validate=False)
    if len(data)>100*1024*1024:
        raise ValueError("File exceeds 100 MB browser exchange limit")
    p=folder/safe
    if p.exists():
        p=folder/(p.stem+"_"+time.strftime("%Y%m%d_%H%M%S")+p.suffix)
    p.write_bytes(data)
    return p


def chatgpt_detect_file_type(path):
    p=Path(path)
    if p.suffix.lower() not in {".json",".jsonl"}:return {"type":"Text/Binary File","videos":0,"valid_updates":0}
    try:records=phase6_read_result_records(p)
    except Exception:return {"type":"Invalid JSON","videos":0,"valid_updates":0}
    updates=[]
    for r in records:updates.extend(phase6_extract_video_updates(r))
    if updates:return {"type":"Video Taxonomy / Library Intelligence","videos":len(updates),"valid_updates":len([x for x in updates if x.get("video_id")])}
    keys=set()
    for r in records:
        if isinstance(r,dict):keys.update(r.keys())
    if {"canonical_tags","source_mapping","questions_answered","search_phrases"} & keys:return {"type":"Library Intelligence","videos":0,"valid_updates":0}
    if any("tag" in str(k).lower() for k in keys):return {"type":"Tag Cleanup / Taxonomy","videos":0,"valid_updates":0}
    return {"type":"Unknown JSON","videos":0,"valid_updates":0}

def chatgpt_exchange_read(path):
    p=Path(path)
    if not p.exists():return {"ok":False,"message":"File not found"}
    det=chatgpt_detect_file_type(p)
    if p.stat().st_size>20*1024*1024:return {"ok":True,"name":p.name,"path":str(p),"preview":"Preview skipped: file >20 MB","detected":det}
    if p.suffix.lower() in {".json",".jsonl",".txt",".md",".csv",".html",".srt",".vtt",".py",".log"}:
        return {"ok":True,"name":p.name,"path":str(p),"preview":p.read_text(encoding="utf-8",errors="replace")[:200000],"detected":det}
    return {"ok":True,"name":p.name,"path":str(p),"preview":"Binary file staged successfully.","detected":det}



def chatgpt_exchange_list():
    base=chatgpt_exchange_dir();out=[]
    for direction in ["outgoing","incoming"]:
        for p in sorted((base/direction).glob("*"),key=lambda x:x.stat().st_mtime,reverse=True)[:150]:
            if p.is_file():
                d=chatgpt_detect_file_type(p);out.append({"direction":direction,"name":p.name,"path":str(p),"size":p.stat().st_size,"modified":time.strftime("%Y-%m-%d %H:%M:%S",time.localtime(p.stat().st_mtime)),"detected_type":d.get("type"),"videos":d.get("videos",0)})
    return out



def _phase5_search_scores(query):
    """Return all Phase-5 ranked video IDs for paged Library search."""
    query=str(query or "").strip()
    if not query:
        return {}
    try:
        docs=phase5_load_search_index()
        limit=max(1,len(docs)+1)
        return {str(d.get("video_id") or ""):float(score or 0.0) for score,d in phase5_search(query,limit=limit) if str(d.get("video_id") or "").strip()}
    except Exception:
        return {}

