def parse_time_seconds(value):
    s=str(value or "").strip()
    if not s:return 0.0
    try:return float(s)
    except Exception:pass
    parts=s.split(":")
    try:
        nums=[float(x) for x in parts]
        if len(nums)==3:return nums[0]*3600+nums[1]*60+nums[2]
        if len(nums)==2:return nums[0]*60+nums[1]
    except Exception:pass
    raise ValueError(f"Invalid time: {value}")

def clip_studio_root():
    p=BASE/"studio"/"clip_projects";p.mkdir(parents=True,exist_ok=True);return p

def web_merge_clips(clips,project_name="Merged Project"):
    if not FFMPEG.exists():return {"ok":False,"message":f"ffmpeg not found: {FFMPEG}"}
    clips=[x for x in (clips or []) if isinstance(x,dict)]
    if not clips:return {"ok":False,"message":"No clips supplied"}
    project_id="CLIP_"+time.strftime("%Y%m%d_%H%M%S")+"_"+uuid.uuid4().hex[:5]
    proj=clip_studio_root()/project_id;parts=proj/"parts";parts.mkdir(parents=True,exist_ok=True);normalized=[];manifest=[]
    for i,c in enumerate(clips,1):
        source=str(c.get("source") or c.get("video_id") or c.get("url") or '').strip();start=parse_time_seconds(c.get("start"));end=parse_time_seconds(c.get("end"))
        if end<=start:raise ValueError(f"Clip {i}: end must be greater than start")
        local=None;url=None
        con=db_connect();row=con.execute("SELECT local_video,url,clean_title,original_title FROM videos WHERE video_id=?",(source,)).fetchone();con.close()
        if row and row[0] and Path(row[0]).exists():local=Path(row[0]);url=row[1]
        elif source.startswith(('http://','https://')):url=source
        else:raise RuntimeError(f"Clip {i}: source not found: {source}")
        input_path=local;clip_start=start;clip_end=end
        if not input_path:
            raw=parts/f"remote_{i}.%(ext)s";section=f"*{start}-{end}"
            args=strict_common_args()+["--no-playlist","--download-sections",section,"--force-keyframes-at-cuts","-f","bv*+ba/b","--merge-output-format","mp4","-o",str(raw),url]
            rc,out,err=run(args,timeout=1800)
            files=sorted([p for p in parts.glob(f"remote_{i}.*") if p.is_file() and p.suffix.lower() in {'.mp4','.mkv','.webm','.m4v'}],key=lambda p:p.stat().st_mtime,reverse=True)
            if rc!=0 or not files:raise RuntimeError(f"Clip {i}: remote section download failed: {(err or out)[-1200:]}")
            input_path=files[0];clip_start=0;clip_end=end-start
        outp=parts/f"clip_{i:03d}.mp4";duration=max(.1,clip_end-clip_start)
        vf="scale=1280:720:force_original_aspect_ratio=decrease,pad=1280:720:(ow-iw)/2:(oh-ih)/2,setsar=1,fps=30"
        cmd=[str(FFMPEG),"-y","-ss",str(clip_start),"-t",str(duration),"-i",str(input_path),"-vf",vf,"-c:v","libx264","-preset","veryfast","-crf","21","-c:a","aac","-ar","48000","-ac","2","-movflags","+faststart",str(outp)]
        rc,so,se=run(cmd,timeout=1800)
        if rc!=0 or not outp.exists():raise RuntimeError(f"Clip {i}: ffmpeg failed: {(se or so)[-1500:]}")
        normalized.append(outp);manifest.append({"order":i,"source":source,"resolved":str(input_path),"start":start,"end":end,"clip":str(outp)})
    concat=proj/"concat.txt";concat.write_text("\n".join("file '"+p.resolve().as_posix().replace("'","'\\''")+"'" for p in normalized),encoding="utf-8")
    final=proj/(safe_name(project_name,"Merged_Project")+".mp4");cmd=[str(FFMPEG),"-y","-f","concat","-safe","0","-i",str(concat),"-c","copy",str(final)];rc,so,se=run(cmd,timeout=1800)
    if rc!=0 or not final.exists():raise RuntimeError(f"Final merge failed: {(se or so)[-1500:]}")
    obj={"project_id":project_id,"name":project_name,"created_at":time.strftime("%Y-%m-%d %H:%M:%S"),"clips":manifest,"output":str(final)};(proj/"project.json").write_text(json.dumps(obj,indent=2,ensure_ascii=False),encoding="utf-8")
    con=db_connect();con.execute("INSERT OR REPLACE INTO clip_projects(project_id,name,project_json,output_path,status,created_at,completed_at,error) VALUES(?,?,?,?,?,?,?,?)",(project_id,project_name,json.dumps(obj,ensure_ascii=False),str(final),"SUCCESS",obj["created_at"],time.strftime("%Y-%m-%d %H:%M:%S"),""));con.commit();con.close()
    return {"ok":True,"project_id":project_id,"output":str(final),"folder":str(proj),"clips":len(normalized)}

