def chatgpt_master_modular_sequential_prompt():
    try:
        if CHATGPT_MASTER_PROMPT_PATH.is_file():
            return CHATGPT_MASTER_PROMPT_PATH.read_text(encoding="utf-8-sig",errors="replace")
    except Exception:
        pass
    return "VIDEO LIBRARY — CHATGPT TRANSCRIPT INTELLIGENCE PROCESSOR. Process each supplied video transcript independently and sequentially. Preserve VIDEO_ID and original_title exactly. Use transcript evidence as authority for actual content. Do not use description or viewer comments for transcript analysis. Exclude sponsor/ad/affiliate/promotional content. Return valid JSON according to the supplied schema."

# Field-level contracts prevent different ChatGPT runs from inventing incompatible
# shapes for the same feature ID.  These contracts are embedded in every upload.
CHATGPT_FEATURE_CONTRACTS={
    "title_en.v1":{"fields":{"title":"string","short_title":"string","reason":"string"},"rules":["Natural English; retain the actual subject","For list/ranking/recommendation videos, include the key named items in the title when transcript or metadata evidence clearly identifies them, e.g. Dinner Foods to Avoid: Leafy Vegetables, Salads, Sprouts, Curd, Fruits, Juices and Heavy Foods","Prefer readable specific titles over vague titles; title may exceed 14 words when needed to include clearly evidenced list items","short_title stays compact at 3-8 words","Do not invent listed items from title alone; if item names are not evidenced, use a general title"]},
    "taxonomy.v3":{"fields":{"primary_topic":"string","secondary_topics":"string[]","category":"string","subcategory":"string","keywords":"string[]","canonical_tags":"string[]","search_queries":"string[]"},"rules":["Use the supplied VideoHoarder categories when one clearly fits; otherwise Other","Prefer specific subjects over generic labels","Return approximately 4-12 meaningful deduplicated canonical tags"]},
    "executive_summary.v2":{"fields":{"summary":"string","key_takeaways":"string[]","source_basis":"string[]"},"rules":["80-160 words","3-7 non-duplicative takeaways","State the source's position without presenting it as independently verified"]},
    "detailed_summary.v3":{"fields":{"overview":"string","sections":"object[]","practical_details":"string[]","limitations":"string[]","source_basis":"string[]"},"rules":["Cover the complete substantive video evidence with video-specific semantic synthesis; never use reusable/template filler","Each section has heading, summary and segment_ids that actually support that section when canonical segments exist","Preserve important quantities, steps, dates, qualifications, recommendations, examples, comparisons and cautions only when actually stated; never manufacture a category because the schema supports it","Represent what the video says faithfully; external fact-checking is outside this workflow"]},
    "chapters.v1":{"fields":{"chapters":"object[]"},"rules":["Canonical topic boundaries used by the detailed summary","Each chapter has chapter_no, chapter_title, start_timestamp, end_timestamp, start_seconds, end_seconds and segment_ids","Chronological, non-overlapping, start < end, and within authoritative duration when available","Render as responsive cards, not a table"]},
    "timeline_sections.v3":{"fields":{"sections":"object[]"},"rules":["Legacy compatibility only; new V3.3.4 packages use chapters.v1","Each section has start_timestamp, end_timestamp, title, summary and segment_ids","Chronological, non-overlapping and within supplied transcript duration","Prefer 4-12 meaningful sections; do not create filler sections"]},
    "entities.v2":{"fields":{"entities":"object[]"},"rules":["Each entity has name, type, context, confidence and segment_ids","Allowed types: person, organization, place, product, work, event, concept, law, study, other","Merge aliases and omit generic nouns"]},
    "claims_warnings.v2":{"fields":{"claims":"object[]","warnings":"object[]","overall_risk":"none|low|medium|high|unknown"},"rules":["Each claim has text, claim_type, verification_status, severity, confidence and segment_ids","verification_status: source_claim_only, supported_by_supplied_evidence, contradicted_in_source, or needs_external_verification","severity: informational, low, medium, high, critical","Never label a claim externally verified unless external evidence is supplied"]},
    "viewer_comment_intelligence.v2":{"fields":{"total_comments":"integer","included_comments":"integer","sampling_method":"string","themes":"object[]","agreements":"string[]","disagreements":"string[]","questions":"string[]","useful_corrections":"string[]","sentiment":"object","limitations":"string[]"},"rules":["Copy total_comments, included_comments and sampling_method from supplied structured comment evidence","Analyze only supplied comment records","Cluster semantically similar comments and report approximate counts","Separate popularity from factual reliability","Quote no more than a short phrase when needed; otherwise paraphrase"]},
    "same_topic_clip_plan.v1":{"fields":{"clips":"object[]","selection_rationale":"string","total_selected_duration_seconds":"number"},"rules":["Each clip has start_timestamp, end_timestamp, duration_seconds, title, purpose, segment_ids and include","Prefer self-contained 30-180 second clips; allow exceptions only with explanation","No overlaps, timestamps within evidence, and clips are suggestions only"]},
    "evidence_assessment.v1":{"fields":{"grade":"A|B|C|D|E","completeness":"complete|usable|partial|none","source_consistency":"consistent|minor_conflict|major_conflict|insufficient_evidence","conflicts":"string[]","limitations":"string[]"},"rules":["Use the supplied evidence assessment as the baseline","Explain downgrades and conflicts"]},
    "video_intake.v1":{"fields":{"actual_subject":"string","strongest_takeaway":"string","strengths":"string[]","weaknesses":"string[]","worth_keeping":"yes|no|unknown","worth_rewatching":"yes|no|unknown","reason":"string"},"rules":["Judge usefulness from supplied evidence only","Do not confuse production popularity with information quality"]},
    "editorial_assessment.v1":{"fields":{"chatgpt_take":"string","bottom_line":"string","what_is_new_or_distinctive":"string[]","practical_value":"object","credibility_assessment":"object","evidence_strength":"high|medium|low|insufficient","possible_bias_or_agenda":"string[]","important_missing_context":"string[]","who_should_watch":"string[]","who_can_skip":"string[]","recommended_actions":"string[]","questions_left_unanswered":"string[]","contradictions_or_doubts":"string[]","comparison_opportunities":"string[]","overall_score":"object","keep_priority":"high|medium|low|unknown|not_available","rewatch_sections":"object[]","interpretation_limits":"string"},"rules":["This is a distinct synthesis, not another summary","overall_score contains score_0_to_100 and explanation","Rewatch sections contain valid timestamps, reason and segment_ids","Separate interpretation from factual verification"]},
    "quality_validation.v1":{"fields":{"status":"PASS|PASS_WITH_WARNINGS|REPROCESS_RECOMMENDED|SOURCE_INSUFFICIENT","warnings":"string[]","cross_feature_consistency":"string","repair_attempts":"integer"},"rules":["Check IDs, provenance, timestamps, contradictions, missing fields and unsupported certainty","Use REPROCESS_RECOMMENDED or SOURCE_INSUFFICIENT rather than fabricating required content"]},
    "recipes.v1":{"fields":{"recipes":"object[]","no_recipe_reason":"string"},"rules":["Extract only real recipes/procedures supported by transcript evidence","Each recipe should include name, ingredients, quantities when stated, steps, timings, serving/use notes and segment_ids","Do not invent missing quantities or steps"]},
    "references.v1":{"fields":{"references":"object[]","limitations":"string[]"},"rules":["Capture meaningful referenced studies, books, people, tools, products, links or resources only when present","Each reference should include name, type, context, timestamp or segment_ids when available","Do not turn generic words into references"]},
    "qa.v1":{"fields":{"questions":"object[]"},"rules":["List genuinely useful video-specific retrieval questions answered by the supplied evidence; avoid repetitive generic main-point templates","Each item should include question, answer, confidence and segment_ids that support the answer when canonical segments exist","Use uncertainty when the transcript only implies an answer; do not fact-check the speaker"]},
    "playlist_series.v1":{"fields":{"series_signals":"object[]","recommended_library_group":"string","follow_up_topics":"string[]"},"rules":["Identify if the video belongs with a series, playlist, recurring topic or natural research group","Use supplied evidence only"]},
    "technical_intelligence.v1":{"fields":{"methods":"object[]","tools":"object[]","settings_or_parameters":"object[]","implementation_notes":"string[]"},"rules":["For technical/process videos, capture concrete tools, steps, parameters and workflows","For non-technical videos, return empty arrays with brief limitation"]},
    "named_items.v1":{"fields":{"items":"object[]"},"rules":["Render this last in HTML/report views","Include concrete identifiable foods, ingredients, herbs, medicines, supplements, products, people, places, tools, books, studies, organizations, software, technologies, exercises, techniques, treatments or other named resources actually discussed","Do not mechanically promote title words, frequent tokens or broad abstract topic concepts into Named Items; empty is better than invented","Each item should include name, type, context and segment_ids that support the item when canonical segments exist"]}
}

def chatgpt_feature_contracts_for(requested,compact=False):
    """Return the exact contracts to embed/validate for this package."""
    contracts={}
    for fid in requested:
        if fid not in CHATGPT_FEATURE_CONTRACTS:continue
        contracts[fid]=json.loads(json.dumps(CHATGPT_FEATURE_CONTRACTS[fid],ensure_ascii=False))
    return contracts

def _chatgpt_contract_json_type(type_name):
    value=str(type_name or "")
    if value.endswith("[]"):return {"type":"array","items":{"type":"object" if value=="object[]" else "string"}}
    if value in {"integer","number","string","object"}:return {"type":value}
    if "|" in value:return {"type":"string","enum":value.split("|")}
    return {"type":"string"}

