    if "editorial_assessment.v1" in feature_properties:
        feature_properties["editorial_assessment.v1"]["properties"]["overall_score"]={"type":"object","required":["score_0_to_100","explanation"],"properties":{"score_0_to_100":{"type":"number","minimum":0,"maximum":100},"explanation":{"type":"string"}},"additionalProperties":False}
