def chatgpt_source_snapshot(row,evidence):
    raw=json.dumps({"row":row,"evidence":evidence},ensure_ascii=False,sort_keys=True,default=str)
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()

TRANSCRIPT_HEALTH_ANALYZER_VERSION="1.0"
TRANSCRIPT_HEALTH_HARD_FAILURES={
    "TRANSCRIPT_MISSING","EMPTY_TRANSCRIPT","NO_USABLE_TEXT",
    "CONFIRMED_MISSING_SPOKEN_CONTENT","SOURCE_POLICY_FAILURE"
}

def chatgpt_transcript_fingerprint(transcript, manifest=None):
    raw=json.dumps({"transcript":str(transcript or ""),"manifest":manifest or {}},ensure_ascii=False,sort_keys=True,default=str)
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()

def chatgpt_transcript_health(transcript, video_duration=0, manifest=None):
    """Mechanical V3.3.4 transcript-health analysis. No semantic intelligence."""
    transcript=str(transcript or "")
    now=time.strftime("%Y-%m-%d %H:%M:%S")
    fp=chatgpt_transcript_fingerprint(transcript,manifest)
    text_plain=re.sub(r"<[^>]+>"," ",html.unescape(transcript))
    text_plain=re.sub(r"\d{1,3}:\d{2}(?::\d{2}(?:[.,]\d+)?)?"," ",text_plain)
    text_plain=re.sub(r"\s+"," ",text_plain).strip()
    words=re.findall(r"\b[\w'-]+\b",text_plain)
    fragments=_chatgpt_caption_fragments(transcript,video_duration)
    signals={
        "timestamp_parse_rate":None,"timestamp_monotonicity":None,"start_coverage":None,
        "end_coverage":None,"duration_coverage":None,"text_density":None,
        "unsubtitled_tail_seconds":None,"unsubtitled_tail_ratio":None,
        "large_gap_ratio":None,"duplicate_ratio":None,"fragmentation_ratio":None,
        "noise_ratio":None
    }
    reason_codes=[];warnings=[];score=100
    if not transcript.strip():
        reason_codes.append("TRANSCRIPT_MISSING");warnings.append("No transcript/SRT/VTT text supplied.");score=0
    elif not text_plain:
        reason_codes.append("EMPTY_TRANSCRIPT");warnings.append("Transcript exists but has no usable text after cleanup.");score=0
    elif not transcript_has_useful_speech(transcript):
        reason_codes.append("NO_USABLE_TEXT");warnings.append("Transcript appears to contain no usable speech text.");score=0
    if transcript.strip():
        raw_timestamp_count=len(_chatgpt_timestamp_matches(transcript))
        signals["timestamp_parse_rate"]=(len(fragments)/raw_timestamp_count) if raw_timestamp_count else None
        if raw_timestamp_count and len(fragments)<max(1,raw_timestamp_count//3):
            reason_codes.append("TIMESTAMP_PARSE_WEAK");warnings.append("Many apparent timestamps could not be parsed.");score-=15
        if fragments:
            starts=[float(x[0] or 0) for x in fragments];ends=[float(x[1] or x[0] or 0) for x in fragments]
            monotonic=all(a<=b for a,b in zip(starts,starts[1:]))
            signals["timestamp_monotonicity"]=1.0 if monotonic else 0.0
            if not monotonic:
                reason_codes.append("SEVERE_TIMESTAMP_CORRUPTION");warnings.append("Transcript timestamps are not monotonic.");score-=45
            invalid=sum(1 for a,b in zip(starts,ends) if b<a)
            overlaps=sum(1 for prev_end,next_start in zip(ends,starts[1:]) if next_start<prev_end-0.25)
            if invalid or overlaps>max(3,len(fragments)*0.15):
                reason_codes.append("TIMESTAMP_CORRUPTION");warnings.append("Invalid or overlapping timestamp ranges detected.");score-=25
            gaps=[max(0.0,b-a) for a,b in zip(ends,starts[1:])]
            large_gaps=[g for g in gaps if g>=30]
            signals["large_gap_ratio"]=len(large_gaps)/max(1,len(gaps))
            if large_gaps:
                reason_codes.append("LARGE_TIMESTAMP_GAPS");warnings.append(f"{len(large_gaps)} unusually large transcript gap(s) detected.");score-=min(25,5+len(large_gaps)*2)
            represented=max(0.0,(max(ends)-min(starts)) if ends else 0)
            signals["start_coverage"]=min(starts) if starts else None
            signals["end_coverage"]=max(ends) if ends else None
            if video_duration:
                duration=float(video_duration)
                signals["duration_coverage"]=represented/max(1.0,duration)
                tail=max(0.0,duration-max(ends))
                signals["unsubtitled_tail_seconds"]=tail
                signals["unsubtitled_tail_ratio"]=tail/max(1.0,duration)
                # Video duration is not speech duration. A long tail may be
                # silence/music/visual-only demonstration/credits, so duration
                # alone can only create a coverage-uncertainty signal.
                if duration>180 and tail>max(60.0,duration*0.35):
                    reason_codes.extend(["LARGE_UNSUBTITLED_TAIL","END_COVERAGE_UNCERTAIN"])
                    warnings.append("Transcript ends well before video duration; later speech is unknown, not proven missing.")
                    score-=6
                elif duration>180 and tail>max(45.0,duration*0.15):
                    reason_codes.append("END_COVERAGE_UNCERTAIN")
                    warnings.append("Transcript ends before video duration; the remaining media may legitimately contain no speech.")
                    score-=3
            if starts and min(starts)>60:
                reason_codes.append("BEGIN_COVERAGE_UNCERTAIN");warnings.append("Transcript starts unusually late; earlier speech coverage is uncertain.");score-=8
            coverage_meta=manifest or {}
            confirmed_missing=bool(
                coverage_meta.get("confirmed_missing_spoken_content")
                or coverage_meta.get("speech_continues_after_transcript")
                or (isinstance(coverage_meta.get("coverage"),dict) and coverage_meta["coverage"].get("confirmed_missing_spoken_content"))
            )
            if confirmed_missing:
                reason_codes.append("CONFIRMED_MISSING_SPOKEN_CONTENT")
                warnings.append("Independent source evidence confirms meaningful spoken content is missing from the selected transcript.")
                score-=45
            signals["text_density"]=len(words)/max(1.0,represented)
        else:
            reason_codes.append("UNTIMESTAMPED_OR_UNPARSEABLE");warnings.append("No parseable timestamped caption fragments found.");score-=20
    normalized_lines=[re.sub(r"\s+"," ",re.sub(r"<[^>]+>"," ",line)).strip().lower() for line in transcript.splitlines()]
    normalized_lines=[x for x in normalized_lines if x and "-->" not in x and not x.isdigit()]
    if normalized_lines:
        counts=Counter(normalized_lines);dupes=sum(c-1 for c in counts.values() if c>1)
        signals["duplicate_ratio"]=dupes/max(1,len(normalized_lines))
        if signals["duplicate_ratio"] and signals["duplicate_ratio"]>0.25:
            reason_codes.append("DUPLICATED_CAPTIONS");warnings.append("High repeated-caption ratio detected.");score-=20
    if words:
        short_words=sum(1 for w in words if len(w)<=2)
        signals["fragmentation_ratio"]=short_words/max(1,len(words))
        if signals["fragmentation_ratio"]>0.45:
            reason_codes.append("EXTREME_FRAGMENTATION");warnings.append("Transcript text appears highly fragmented.");score-=15
    noise_markers=len(re.findall(r"\[(?:music|applause|laughter|silence|noise)\]|\((?:music|applause|laughter|silence|noise)\)",transcript,re.I))
    signals["noise_ratio"]=noise_markers/max(1,len(normalized_lines) or len(words))
    if noise_markers and signals["noise_ratio"]>0.18:
        reason_codes.append("HIGH_NOISE_MARKER_RATIO");warnings.append("Transcript contains many non-speech/noise markers.");score-=20
    hard_failure=any(code in TRANSCRIPT_HEALTH_HARD_FAILURES for code in reason_codes)
    score=max(0,min(100,int(round(score))))
    if hard_failure:grade="F";routing="REPAIR_REQUIRED"
    elif score>=90:grade="A";routing="NORMAL"
    elif score>=75:grade="B";routing="NORMAL"
    elif score>=55:grade="C";routing="CAUTION"
    elif score>=35:grade="D";routing="REPAIR_RECOMMENDED"
    else:grade="F";routing="REPAIR_REQUIRED"
    # Bad/missing timestamps alone must not discard otherwise usable speech text.
    # Such videos remain packageable as untimestamped semantic evidence.
    timestamp_only_codes={
        "TIMESTAMP_PARSE_WEAK","UNTIMESTAMPED_OR_UNPARSEABLE",
        "SEVERE_TIMESTAMP_CORRUPTION","TIMESTAMP_CORRUPTION",
        "LARGE_TIMESTAMP_GAPS","BEGIN_COVERAGE_UNCERTAIN",
        "END_COVERAGE_UNCERTAIN","LARGE_UNSUBTITLED_TAIL"
    }
    non_timestamp_codes=[c for c in reason_codes if c not in timestamp_only_codes]
    if transcript_has_useful_speech(transcript) and not hard_failure and not non_timestamp_codes and routing in {"REPAIR_RECOMMENDED","REPAIR_REQUIRED"}:
        grade="C";routing="CAUTION";score=max(score,55)
        warnings.append("Timestamp quality is poor, but usable speech text remains packageable as untimestamped semantic evidence.")
    return {"analyzer_version":TRANSCRIPT_HEALTH_ANALYZER_VERSION,"transcript_fingerprint":fp,"score":score,"grade":grade,"routing_class":routing,"hard_failure":bool(hard_failure or grade=="F"),"signals":signals,"reason_codes":list(dict.fromkeys(reason_codes)),"warnings":warnings,"analyzed_at":now}

def _chatgpt_format_seconds(value):
    value=max(0.0,float(value or 0));hours=int(value//3600);minutes=int((value%3600)//60);seconds=value%60
    return f"{hours:02d}:{minutes:02d}:{seconds:06.3f}"

# One shared timestamp-token detector for transcript parsing, health analysis,
# canonical evidence accounting, and package fail-fast guards. It accepts
# bracketed or plain MM:SS / H:MM:SS / HH:MM:SS plus optional .mmm/,mmm.
CHATGPT_TIMESTAMP_TOKEN_RE=re.compile(
    r"(?<![\d:])(?:\[(?P<bracket>\d{1,3}:\d{2}(?::\d{2})?(?:[.,]\d+)?)\]|(?P<plain>\d{1,3}:\d{2}(?::\d{2})?(?:[.,]\d+)?))(?![\d:])"
)

def _chatgpt_timestamp_matches(text):
    """Return ordered (start_pos, end_pos, normalized_token) timestamp markers."""
    matches=[]
    for match in CHATGPT_TIMESTAMP_TOKEN_RE.finditer(str(text or "")):
        token=(match.group("bracket") or match.group("plain") or "").replace(",",".")
        if _chatgpt_timestamp_seconds(token) is not None:
            matches.append((match.start(),match.end(),token))
    return matches

def _chatgpt_caption_fragments(transcript, video_duration=0):
    """Parse SRT/VTT-like text or inline [HH:MM:SS] markers into ordered canonical fragments.

    V3.3.4 normalization rule: timestamp markers embedded inside one flattened line
    must be split into real segments before transcript-health analysis. The final
    segment end is used only when authoritative duration is available; otherwise
    it remains a zero-length terminal boundary rather than inventing time.
    """
    transcript=str(transcript or "");rows=[]
    if "-->" in transcript:
        for start,end,text_value in parse_srt_sections(transcript):
            a=_chatgpt_timestamp_seconds(start.replace(",","."));b=_chatgpt_timestamp_seconds(end.replace(",","."))
            if a is not None and b is not None and b>=a and text_value.strip():rows.append([a,b,re.sub(r"\s+"," ",text_value).strip()])
        if rows:return rows

    # Flattened transcripts may place many timestamp markers on one physical
    # line, with or without brackets. Use the same detector as health/guards.
    markers=_chatgpt_timestamp_matches(transcript)
    if markers:
        # A single plain timestamp may simply be a clock time inside prose; line
        # fallback below handles genuine one-marker transcript lines. Multiple
        # markers, or any bracketed marker, are strong transcript-timeline signals.
        has_bracketed=any(transcript[start:end].lstrip().startswith("[") for start,end,_ in markers)
        if len(markers)>=2 or has_bracketed:
            for index,(marker_start,marker_end,token) in enumerate(markers):
                start=_chatgpt_timestamp_seconds(token)
                if start is None:continue
                text_start=marker_end;text_end=markers[index+1][0] if index+1<len(markers) else len(transcript)
                text_value=html.unescape(transcript[text_start:text_end])
                text_value=re.sub(r"<[^>]+>"," ",text_value)
                text_value=re.sub(r"\s+"," ",text_value).strip(" -–—:\t\r\n")
                if not text_value:continue
                if index+1<len(markers):
                    end=_chatgpt_timestamp_seconds(markers[index+1][2])
                else:
                    # The last source marker identifies when its text begins; video
                    # duration does not prove that speech continues to media end.
                    end=start
                if end is None or end<start:end=start
                rows.append([start,end,text_value])
            if rows:return rows

    # Fallback for genuinely line-oriented timestamped text.
    for line in transcript.splitlines():
        line=re.sub(r"<[^>]+>"," ",html.unescape(line)).strip()
        if not line:continue
        match=re.match(r"^\[?(\d{1,3}:\d{2}(?::\d{2}(?:[.,]\d+)?)?)\]?\s*[-–—:]?\s*(.*)$",line)
        if not match:continue
        start=_chatgpt_timestamp_seconds(match.group(1).replace(",","."));text_value=re.sub(r"\s+"," ",match.group(2)).strip()
        if start is not None and text_value:rows.append([start,None,text_value])
    for index,row in enumerate(rows):
        if row[1] is None:
            if index+1<len(rows):row[1]=rows[index+1][0]
            else:row[1]=row[0]
    return rows

def _chatgpt_merge_caption_sentences(fragments,video_duration=0):
    """Merge short caption fragments into complete, timestamp-bounded sentences."""
    merged=[];current=None
    for start,end,text_value in fragments:
        text_value=re.sub(r"\s+"," ",str(text_value)).strip()
        if not text_value:continue
        if current is None:current=[start,end,text_value]
        else:
            gap=max(0,start-current[1]);ends_sentence=bool(re.search(r"[.!?][\"')\]]?$",current[2]))
            if ends_sentence or gap>3 or len(current[2])+len(text_value)>420:
                merged.append(current);current=[start,end,text_value]
            else:current[1]=max(current[1],end);current[2]=(current[2]+" "+text_value).strip()
        if current and re.search(r"[.!?][\"')\]]?$",current[2]) and len(current[2])>=45:
            merged.append(current);current=None
    if current:merged.append(current)
    duration=float(video_duration or 0)
    for index,row in enumerate(merged):
        next_start=merged[index+1][0] if index+1<len(merged) else (duration or row[1])
        row[1]=max(row[0],min(row[1] or next_start,next_start,duration or next_start))
    return merged

def _chatgpt_structured_comments(raw_comments,max_records=100):
    """Normalize supplied comments and use deterministic head/tail sampling."""
    raw=str(raw_comments or "");records=[]
    try:
        data=json.loads(raw)
        values=data if isinstance(data,list) else (data.get("comments") or data.get("items") or []) if isinstance(data,dict) else []
        for index,item in enumerate(values,1):
            if isinstance(item,dict):text_value=str(item.get("text") or item.get("comment") or item.get("content") or "").strip();author=str(item.get("author") or item.get("user") or "");likes=item.get("likes")
            else:text_value=str(item).strip();author="";likes=None
            if text_value:records.append({"comment_id":f"c{index:05d}","author":author,"text":text_value,"likes":likes})
    except Exception:pass
    if not records:
        for index,line in enumerate(raw.splitlines(),1):
            text_value=re.sub(r"\s+"," ",line).strip()
            if text_value:records.append({"comment_id":f"c{index:05d}","author":"","text":text_value,"likes":None})
    total=len(records)
    if total>max_records:
        half=max_records//2;included=records[:half]+records[-(max_records-half):];method="deterministic_head_tail"
    else:included=records;method="all_supplied_comments"
    return {"total_comments":total,"included_comments":len(included),"sampling_method":method,"records":included}

def _chatgpt_timestamp_hints(transcript,max_hints=200,excerpt_chars=180):
    """Preserve source-provided timestamp clues compactly when canonical timing is unreliable.

    Hints are source markers only, not authoritative normalized timeline data.
    They let the semantic model retain rough navigation context without duplicating
    the full raw transcript or spending reasoning effort on timestamp repair.
    """
    text=str(transcript or "")
    hints=[]
    matches=_chatgpt_timestamp_matches(text)
    for index,(start,end,token) in enumerate(matches[:max_hints]):
        next_start=matches[index+1][0] if index+1<len(matches) else len(text)
        excerpt=html.unescape(text[end:min(next_start,end+excerpt_chars)])
        excerpt=re.sub(r"<[^>]+>"," ",excerpt)
        excerpt=re.sub(r"\s+"," ",excerpt).strip(" -–—:\t\r\n")
        seconds=_chatgpt_timestamp_seconds(token)
        hints.append({"source_timestamp":token,"source_seconds":round(seconds,3) if seconds is not None else None,"text_excerpt":excerpt,"reliability":"approximate_source_hint"})
    return {"available":bool(hints),"reliable":False,"total_detected":len(matches),"included_count":len(hints),"hints":hints}

def _chatgpt_timing_reliable(health, fragments, segment_rows, monotonic):
    """Return True only when normalized timing is safe to expose as authoritative.

    Transcript Health is mechanical context, but its timing-corruption signals
    must gate *navigation authority*. Usable speech still remains FULL_INTELLIGENCE
    evidence when this returns False.
    """
    if not fragments or not segment_rows or not monotonic:
        return False
    reason_codes={str(x) for x in ((health or {}).get("reason_codes") or [])}
    disqualifying={
        "SEVERE_TIMESTAMP_CORRUPTION",
        "TIMESTAMP_CORRUPTION",
        "TIMESTAMP_PARSE_WEAK",
        "UNTIMESTAMPED_OR_UNPARSEABLE",
    }
    if reason_codes & disqualifying:
        return False
    # Final deterministic sanity check over canonical segment ordering/ranges.
    previous_end=None
    for row in segment_rows:
        try:
            start=float(row.get("start_seconds"))
            end=float(row.get("end_seconds"))
        except Exception:
            return False
        if end < start:
            return False
        if previous_end is not None and start < previous_end - 0.25:
            return False
        previous_end=end
    return True

def _chatgpt_untimestamped_fallback_text(transcript):
    """Return usable speech text while preserving timestamp clues separately."""
    text=str(transcript or "")
    if not text.strip():return ""
    # Remove standard SRT/VTT timing arrows and sequence-only lines.
    text=re.sub(r"(?m)^\s*\d+\s*$", " ", text)
    text=re.sub(r"(?m)^\s*\d{1,3}:\d{2}(?::\d{2})?(?:[.,]\d+)?\s*-->\s*\d{1,3}:\d{2}(?::\d{2})?(?:[.,]\d+)?(?:\s+.*)?$", " ", text)
    # Remove timestamp tokens recognized by the shared detector. They are not
    # semantic content and ChatGPT must not spend time reconstructing them.
    spans=_chatgpt_timestamp_matches(text)
    if spans:
        out=[];last=0
        for start,end,_token in spans:
            out.append(text[last:start]);out.append(" ");last=end
        out.append(text[last:]);text="".join(out)
    text=html.unescape(text)
    text=re.sub(r"<[^>]+>"," ",text)
    text=re.sub(r"\s+"," ",text).strip()
    return text

def _chatgpt_transcript_completeness(transcript,health,video_duration=0,manifest=None):
    """Return spoken-content completeness without equating video time with speech time."""
    transcript=str(transcript or "");manifest=manifest or {};health=health or {}
    if not transcript_has_useful_speech(transcript):
        return "NONE"
    explicit=str(manifest.get("transcript_completeness") or "").strip().upper()
    if explicit in {"COMPLETE","LIKELY_COMPLETE","PARTIAL","UNKNOWN","NONE"}:
        return explicit
    if manifest.get("transcript_complete") is True:
        return "COMPLETE"
    codes={str(x) for x in (health.get("reason_codes") or [])}
    if "CONFIRMED_MISSING_SPOKEN_CONTENT" in codes or manifest.get("confirmed_missing_spoken_content") is True:
        return "PARTIAL"
    fragments=_chatgpt_caption_fragments(transcript,float(video_duration or 0))
    if not fragments or not video_duration:
        return "UNKNOWN"
    starts=[float(x[0] or 0) for x in fragments]
    ends=[float(x[1] or x[0] or 0) for x in fragments]
    duration=float(video_duration)
    head=min(starts) if starts else 0.0
    tail=max(0.0,duration-(max(ends) if ends else 0.0))
    # Near-edge timing can support LIKELY_COMPLETE, never absolute COMPLETE,
    # because subtitles track speech rather than every second of media.
    if head<=max(10.0,duration*0.03) and tail<=max(20.0,duration*0.08):
        return "LIKELY_COMPLETE"
    return "UNKNOWN"

def chatgpt_canonical_evidence(video_id,metadata,manifest,transcript,language,comments):
    """Build one evidence record used by every requested intelligence feature."""
    manifest=manifest or {};transcript=str(transcript or "");comments=str(comments or "")
    health=chatgpt_transcript_health(transcript,float(metadata.get("duration_seconds") or 0),manifest)
    source="no_transcript"
    source_candidates=[
        ("existing_srt",manifest.get("srt")),("existing_vtt",manifest.get("vtt") or manifest.get("subtitle")),
        ("existing_transcript",manifest.get("timestamped_transcript") or manifest.get("clean_transcript")),
    ]
    for label,value in source_candidates:
        if value:source=label;break
    video_duration=float(metadata.get("duration_seconds") or 0);fragments=_chatgpt_caption_fragments(transcript,video_duration)
    if transcript.strip() and source=="no_transcript":
        source="timestamped_transcript" if fragments else "untimestamped_transcript"
    merged=_chatgpt_merge_caption_sentences(fragments,video_duration)
    stamps=[]
    for _start,_end,token in _chatgpt_timestamp_matches(transcript):
        seconds=_chatgpt_timestamp_seconds(token)
        if seconds is not None:stamps.append(seconds)
    monotonic=all(a<=b for a,b in zip(stamps,stamps[1:]))
    chars=len(transcript.strip());words=len(re.findall(r"\b\w+\b",transcript))
    if not chars:quality="failed"
    elif chars<1000:quality="partial"
    elif stamps and not monotonic:quality="low"
    elif chars<5000:quality="medium"
    else:quality="high"
    completeness=_chatgpt_transcript_completeness(transcript,health,video_duration,manifest)
    # Phase 5 evidence isolation: transcript grade/consistency must never depend
    # on description, clean/display title, source tags, source chapters or comments.
    # Source identity metadata may still travel separately for operational use.
    conflicts=[]
    consistency="consistent" if transcript else "insufficient_evidence"
    segment_rows=[{"segment_id":f"s{number:05d}","start_timestamp":_chatgpt_format_seconds(start),"end_timestamp":_chatgpt_format_seconds(end),"start_seconds":round(start,3),"end_seconds":round(end,3),"text":text_value} for number,(start,end,text_value) in enumerate(merged[:2500],1)]
    speech_usable=transcript_has_useful_speech(transcript)
    # V3.3.4 authoritative timing gate: parseable segments are not automatically
    # reliable. Severe/non-monotonic/corrupt timing must be demoted to approximate
    # source hints while preserving the speech text for FULL_INTELLIGENCE.
    timestamps_available=_chatgpt_timing_reliable(health,fragments,segment_rows,monotonic)
    if not timestamps_available:
        segment_rows=[]
    untimestamped_text="" if timestamps_available else _chatgpt_untimestamped_fallback_text(transcript)
    timestamp_hint_data={"available":False,"reliable":False,"total_detected":0,"included_count":0,"hints":[]} if timestamps_available else _chatgpt_timestamp_hints(transcript)
    actual_available=bool(speech_usable and (segment_rows or untimestamped_text))
    comments_payload=_chatgpt_structured_comments(comments)
    grade=evidence_grade_from_transcript_health(health,transcript_available=actual_available)
    if not actual_available:
        segment_rows=[];untimestamped_text="";quality="failed";completeness="NONE";grade="F"
    elif not timestamps_available:
        # Timestamp failure is a navigation limitation, not loss of semantic text.
        source="untimestamped_transcript"
        if quality=="failed":quality="partial"
        if completeness=="NONE":completeness="UNKNOWN"
        timing_codes={str(x) for x in (health.get("reason_codes") or [])}
        if timing_codes & {"SEVERE_TIMESTAMP_CORRUPTION","TIMESTAMP_CORRUPTION","TIMESTAMP_PARSE_WEAK","UNTIMESTAMPED_OR_UNPARSEABLE"}:
            conflicts.append("Normalized timing failed the authoritative reliability gate; semantic processing uses untimestamped speech text and source timestamp markers only as approximate hints.")
    inferred_duration=max([x["end_seconds"] for x in segment_rows],default=0);canonical_duration=video_duration or inferred_duration
    normalization_status="NORMALIZED_TIMESTAMPED" if timestamps_available else ("UNTIMESTAMPED_FALLBACK" if actual_available else "NO_TRANSCRIPT")
    timestamp_status="available" if timestamps_available else ("unavailable_or_unreliable" if actual_available else "none")
    return {"video_id":str(video_id),"transcript_available":actual_available,"transcript_source":source,"transcript_language":language or "unknown","transcript_quality":quality,"transcript_usability":("USABLE" if actual_available else "NONE"),"transcript_completeness":completeness,"timestamp_reliability":("RELIABLE" if timestamps_available else ("UNRELIABLE_OR_UNAVAILABLE" if actual_available else "NONE")),"timestamp_count":len(stamps),"canonical_segment_count":len(segment_rows),"timestamps_available":timestamps_available,"timestamp_status":timestamp_status,"timestamp_hints_available":bool(timestamp_hint_data.get("available")),"timestamp_hints_reliable":False,"timestamps_monotonic":monotonic,"normalization_status":normalization_status,"video_duration_seconds":round(canonical_duration,3),"transcript_characters":chars,"transcript_words":words,"transcript_health":health,"comments_available":bool(comments_payload["included_comments"]),"metadata_available":True,"description_available":bool(metadata.get("description")),"evidence_grade":grade,"source_consistency":consistency,"source_conflicts":conflicts,"canonical_transcript":{"source":source,"language":language or "unknown","quality":quality,"usability":("USABLE" if actual_available else "NONE"),"completeness":completeness,"timestamp_reliability":("RELIABLE" if timestamps_available else ("UNRELIABLE_OR_UNAVAILABLE" if actual_available else "NONE")),"normalization_status":normalization_status,"timestamps_available":timestamps_available,"timestamp_status":timestamp_status,"timestamp_hints_available":bool(timestamp_hint_data.get("available")),"timestamp_hints_reliable":False,"timestamp_hint_count":int(timestamp_hint_data.get("total_detected") or 0),"timestamp_hints":timestamp_hint_data.get("hints") or [],"timestamp_instruction":"Use normalized segment timestamps only when timestamps_available=true. When false, process untimestamped_text directly. If timestamp_hints_available=true, preserve the supplied hints as approximate navigation clues only; do not repair, reconstruct, interpolate, validate, or present them as exact timestamps, and never invent missing timestamps.","video_duration_seconds":round(canonical_duration,3),"transcript_health":health,"segments":segment_rows,"untimestamped_text":untimestamped_text},"comments":comments_payload}

def chatgpt_recommended_transcript_batch_size(video_ids):
    lengths=[]
    for video_id in video_ids:
        transcript,_=best_transcript_for_video(str(video_id));lengths.append(len(transcript))
    average=sum(lengths)/max(1,len(lengths))
    if average>=30000:return 4
    if average>=20000:return 6
    if average>=12000:return 8
    return 25

CHATGPT_TARGET_PACKAGE_VIDEOS=25
CHATGPT_MAX_PACKAGE_VIDEOS=30
CHATGPT_TARGET_TRANSCRIPT_CHARS=150000
CHATGPT_SOFT_MIN_TRANSCRIPT_CHARS=60000
CHATGPT_HARD_TRANSCRIPT_CHARS=250000


CHATGPT_PACKAGE_QUALITY_ANALYZER_VERSION="1.0"
CHATGPT_PACKAGE_GRADE_POINTS={"A":100,"B":85,"C":65,"D":40,"F":15}
CHATGPT_SEVERE_HEALTH_REASON_CODES={
    "SEVERE_TIMESTAMP_CORRUPTION","TIMESTAMP_CORRUPTION","TIMESTAMP_PARSE_WEAK",
    "UNTIMESTAMPED_OR_UNPARSEABLE","MISSING_TRANSCRIPT","EMPTY_TRANSCRIPT",
    "NO_USABLE_SPEECH_TEXT","HARD_FAILURE"
}

def chatgpt_package_quality(video_rows, transcript_characters=0):
    """Mechanical INPUT-evidence quality only; never semantic truth or output quality."""
    rows=list(video_rows or [])
    n=len(rows)
    distribution={g:0 for g in "ABCDF"}
    reliable=0; fallback=0; severe_videos=0; usable=0
    points=[]
    for row in rows:
        assessment=(row.get("evidence") or {}).get("assessment") or {}
        health=assessment.get("transcript_health") or {}
        grade=str(health.get("grade") or "F").upper()
        if grade not in CHATGPT_PACKAGE_GRADE_POINTS: grade="F"
        distribution[grade]+=1; points.append(CHATGPT_PACKAGE_GRADE_POINTS[grade])
        if assessment.get("transcript_available"): usable+=1
        if assessment.get("timestamps_available"): reliable+=1
        elif assessment.get("transcript_available"): fallback+=1
        reasons={str(x).upper() for x in (health.get("reason_codes") or [])}
        hard=bool(health.get("hard_failure"))
        severe=hard or bool(reasons & CHATGPT_SEVERE_HEALTH_REASON_CODES) or any(x.startswith("SEVERE_") for x in reasons)
        if severe: severe_videos+=1
    if n:
        base=sum(points)/n
        score=round(base - 5*(fallback/n) - 5*(severe_videos/n))
    else: score=0
    score=max(0,min(100,int(score)))
    grade="A" if score>=90 else "B" if score>=80 else "C" if score>=65 else "D" if score>=45 else "F"
    reasons=[]
    if n and (distribution["A"]+distribution["B"])/n>=0.80: reasons.append("HIGH_QUALITY_TRANSCRIPT_MAJORITY")
    if n and fallback/n<=0.10: reasons.append("LOW_TIMESTAMP_FALLBACK_RATIO")
    if fallback: reasons.append("TIMESTAMP_FALLBACK_PRESENT")
    if severe_videos: reasons.append("SEVERE_MECHANICAL_SIGNAL_PRESENT")
    chars=max(0,int(transcript_characters or 0))
    workload_class="LOW" if chars<=CHATGPT_TARGET_TRANSCRIPT_CHARS//2 else "MEDIUM" if chars<=CHATGPT_TARGET_TRANSCRIPT_CHARS else "HIGH"
    return {
        "package_quality":{"analyzer_version":CHATGPT_PACKAGE_QUALITY_ANALYZER_VERSION,"score":score,"grade":grade,"processing_priority":None,
            "transcript_grade_distribution":distribution,"usable_transcripts":usable,"timestamp_reliable":reliable,
            "timestamp_fallback":fallback,"severe_signal_count":severe_videos,"reason_codes":reasons},
        "workload":{"class":workload_class,"transcript_characters":chars}
    }

def chatgpt_assign_package_priorities(entries):
    """Assign stable 1-based priorities without changing package IDs or membership."""
    def key(e):
        q=e.get("package_quality") or {}; n=max(1,int(e.get("video_count") or 0))
        reliable=float(q.get("timestamp_reliable") or 0)/n
        severe=float(q.get("severe_signal_count") or 0)/n
        return (-int(q.get("score") or 0),-reliable,severe,str(e.get("package_id") or ""))
    ordered=sorted(entries,key=key)
    for priority,e in enumerate(ordered,1):
        (e.setdefault("package_quality",{}))["processing_priority"]=priority
    return entries

def chatgpt_transcript_lengths(video_ids):
    lengths={}
    for video_id in video_ids:
        transcript,_=best_transcript_for_video(str(video_id))
        lengths[str(video_id)]=len(transcript or "")
    return lengths

def chatgpt_adaptive_package_chunks(group_name, video_ids, transcript_lengths=None, restricted=False):
    """Legacy affinity chunker; hard cap follows CHATGPT_MAX_PACKAGE_VIDEOS (30). Final V3.3.4 package boundaries are owned by the global optimizer."""
    ids=[str(x).strip() for x in (video_ids or []) if str(x).strip()]
    if not ids:return []
    lengths=transcript_lengths or chatgpt_transcript_lengths(ids)
    max_videos=CHATGPT_MAX_PACKAGE_VIDEOS
    # Legacy sizing hints only. V3.3.4 final package creation uses the global optimizer;
    # there is no minimum package size or small-package exception contract.
    preferred_min=5 if restricted else 12
    preferred_max=8 if restricted else CHATGPT_TARGET_PACKAGE_VIDEOS
    target_chars=100000 if restricted else CHATGPT_TARGET_TRANSCRIPT_CHARS
    chunks=[];cur=[];cur_chars=0
    def flush(reason):
        nonlocal cur,cur_chars
        if cur:
            chunks.append({"group_name":group_name,"video_ids":cur,"transcript_chars":cur_chars,"split_reason":reason})
            cur=[];cur_chars=0
    for vid in ids:
        chars=int(lengths.get(vid) or 0)
        if chars>=200000:
            flush("before_unusually_large_video")
            chunks.append({"group_name":group_name,"video_ids":[vid],"transcript_chars":chars,"split_reason":"single_video_unusually_large_transcript"})
            continue
        would_count=len(cur)+1
        would_chars=cur_chars+chars
        if cur and (would_count>max_videos or would_chars>CHATGPT_HARD_TRANSCRIPT_CHARS):
            flush("max_video_or_hard_transcript_limit")
        elif cur and would_chars>target_chars and len(cur)>=preferred_min:
            flush("target_transcript_chars_reached")
        elif cur and len(cur)>=preferred_max and cur_chars>=CHATGPT_SOFT_MIN_TRANSCRIPT_CHARS:
            flush("preferred_video_count_reached")
        cur.append(vid);cur_chars+=chars
    flush("remaining_videos")
    # Avoid tiny trailing chunks when they can safely fit into the previous
    # related chunk without crossing max videos or hard transcript characters.
    if len(chunks)>=2:
        last=chunks[-1];prev=chunks[-2]
        if len(last["video_ids"])<=2 and len(prev["video_ids"])+len(last["video_ids"])<=max_videos and prev["transcript_chars"]+last["transcript_chars"]<=CHATGPT_HARD_TRANSCRIPT_CHARS:
            prev["video_ids"].extend(last["video_ids"])
            prev["transcript_chars"]+=last["transcript_chars"]
            prev["split_reason"]="merged_small_tail"
            chunks.pop()
    return [(c["group_name"],c["video_ids"],c["transcript_chars"],c["split_reason"]) for c in chunks]

def chatgpt_processing_overview():
    con=db_connect()
    requests=con.execute("SELECT status,COUNT(*) FROM chatgpt_requests GROUP BY status").fetchall()
    coverage=con.execute("SELECT status,COUNT(*) FROM video_feature_coverage GROUP BY status").fetchall()
    request_rows=con.execute("SELECT package_id,mode,manifest_json,status FROM chatgpt_requests").fetchall()
    feature_updates=con.execute("SELECT COUNT(*) FROM video_feature_coverage").fetchone()[0]
    intelligence_videos=con.execute("SELECT COUNT(DISTINCT video_id) FROM video_feature_coverage").fetchone()[0]
    videos=con.execute("SELECT COUNT(*) FROM videos WHERE COALESCE(archived,0)=0 AND COALESCE(current_present,1)=1").fetchone()[0]
    con.close()
    package_sets=set();planner_sets=set()
    for package_id,mode,manifest_json,status in request_rows:
        try:
            manifest=json.loads(manifest_json or "{}")
        except Exception:
            manifest={}
        batch_context=manifest.get("batch_context") if isinstance(manifest,dict) else {}
        master_set_id=(batch_context or {}).get("master_set_id") if isinstance(batch_context,dict) else ""
        if str(mode or "").upper()=="BATCH_PLANNING":
            planner_sets.add(str(manifest.get("package_id") or package_id or "").strip())
            continue
        package_sets.add(str(master_set_id or package_id or "").strip())
    package_sets.discard("")
    planner_sets.discard("")
    counters={
        "package_sets":len(package_sets),
        "planner_sets":len(planner_sets),
        "package_files":len(request_rows),
        "videos_with_intelligence":int(intelligence_videos or 0),
        "feature_updates":int(feature_updates or 0),
    }
    return {"manual_exchange_only":True,"active_videos":videos,"requests":dict(requests),"coverage":dict(coverage),"counters":counters,"features":CHATGPT_FEATURES}

def chatgpt_feature_set_key(features):
    return hashlib.sha256(json.dumps(sorted(str(x) for x in (features or []) if str(x)),ensure_ascii=False).encode("utf-8")).hexdigest()[:16]

def chatgpt_completion_marker_path(video_id,features,create=False):
    vid=str(video_id or "").strip()
    if not vid:return None
    con=db_connect();row=con.execute("SELECT local_folder FROM videos WHERE video_id=?",(vid,)).fetchone();con.close()
    folder=Path(str(row[0] or "")) if row and row[0] else working_folder_for_video(vid)
    if not folder:return None
    data=support_dir(folder,create=create)
    return data/f"chatgpt_package_complete_{chatgpt_feature_set_key(features)}.json"

def write_chatgpt_completion_marker(video_id,features,package_id,result_hash):
    marker=chatgpt_completion_marker_path(video_id,features,create=True)
    if not marker:return ""
    payload={"video_id":str(video_id),"feature_set_key":chatgpt_feature_set_key(features),"package_id":package_id,"result_hash":result_hash,"completed_at":time.strftime("%Y-%m-%d %H:%M:%S"),"requested_features":features,"purpose":"VideoHoarder skips this video for the same ChatGPT package feature set while this marker exists. Delete this marker or enable recreate to package again."}
    marker.write_text(json.dumps(payload,indent=2,ensure_ascii=False),encoding="utf-8")
    return str(marker)

def chatgpt_completion_marker_exists(video_id,features):
    marker=chatgpt_completion_marker_path(video_id,features,create=False)
    return bool(marker and marker.is_file())

def chatgpt_processed_locked_ids(video_ids,features):
    ids=[str(x).strip() for x in (video_ids or []) if str(x).strip()]
    if not ids:return set()
    key=chatgpt_feature_set_key(features)
    con=db_connect();qmarks=",".join("?" for _ in ids)
    con.execute("""CREATE TABLE IF NOT EXISTS chatgpt_processed_video_locks(
        video_id TEXT NOT NULL,
        feature_set_key TEXT NOT NULL,
        package_id TEXT,
        result_hash TEXT,
        completed_at TEXT NOT NULL,
        requested_features_json TEXT,
        PRIMARY KEY(video_id,feature_set_key)
    )""")
    rows=con.execute(f"SELECT video_id FROM chatgpt_processed_video_locks WHERE feature_set_key=? AND video_id IN ({qmarks})",[key,*ids]).fetchall()
    con.close()
    # The physical _data marker is the user-visible authority. If it is missing,
    # the video is eligible again even if an old DB lock still exists.
    return {str(r[0]) for r in rows if chatgpt_completion_marker_exists(str(r[0]),features)}

def chatgpt_filter_recreate_locked_ids(video_ids,features,allow_recreate=False):
    ids=list(dict.fromkeys(str(x).strip() for x in (video_ids or []) if str(x).strip()))
    if allow_recreate:return ids,[]
    locked=chatgpt_processed_locked_ids(ids,features)
    return [x for x in ids if x not in locked],sorted(locked)

def reset_chatgpt_processed_locks(video_ids=None,features=None):
    """
    Forget ChatGPT completed-package locks so package creation can include videos again.
    This does not delete downloaded videos, imported result JSON files, or saved intelligence.
    """
    ids=list(dict.fromkeys(str(x).strip() for x in (video_ids or []) if str(x).strip()))
    feature_key=chatgpt_feature_set_key(features or []) if features else ""
    removed_db=0;removed_markers=0;failed=[]
    con=db_connect()
    con.execute("""CREATE TABLE IF NOT EXISTS chatgpt_processed_video_locks(
        video_id TEXT NOT NULL,
        feature_set_key TEXT NOT NULL,
        package_id TEXT,
        result_hash TEXT,
        completed_at TEXT NOT NULL,
        requested_features_json TEXT,
        PRIMARY KEY(video_id,feature_set_key)
    )""")
    if ids and feature_key:
        qmarks=",".join("?" for _ in ids)
        removed_db=con.execute(f"DELETE FROM chatgpt_processed_video_locks WHERE feature_set_key=? AND video_id IN ({qmarks})",[feature_key,*ids]).rowcount or 0
    elif ids:
        qmarks=",".join("?" for _ in ids)
        removed_db=con.execute(f"DELETE FROM chatgpt_processed_video_locks WHERE video_id IN ({qmarks})",ids).rowcount or 0
    elif feature_key:
        removed_db=con.execute("DELETE FROM chatgpt_processed_video_locks WHERE feature_set_key=?",(feature_key,)).rowcount or 0
    else:
        removed_db=con.execute("DELETE FROM chatgpt_processed_video_locks").rowcount or 0
    if ids:
        for vid in ids:
            try:
                folder=locate_existing_folder(vid)
                if not folder:continue
                data=support_dir(Path(folder))
                patterns=[f"chatgpt_package_complete_{feature_key}.json"] if feature_key else ["chatgpt_package_complete_*.json"]
                for pat in patterns:
                    for marker in data.glob(pat):
                        try:
                            marker.unlink();removed_markers+=1
                        except Exception as ex:
                            failed.append(f"{marker}: {ex}")
            except Exception as ex:
                failed.append(f"{vid}: {ex}")
    con.commit();con.close()
    return {"ok":not failed,"removed_db_locks":int(removed_db),"removed_marker_files":removed_markers,"failed":failed[:50]}

def chatgpt_processing_selectors():
    """Return safe, local selector values for the package builder."""
    con=db_connect()
    def vals(column):
        rows=con.execute(f"SELECT DISTINCT {column} FROM videos WHERE COALESCE(archived,0)=0 AND COALESCE(current_present,1)=1 AND COALESCE({column},'')<>'' ORDER BY {column} LIMIT 500").fetchall()
        return [str(r[0]) for r in rows]
    out={"folders":vals("local_folder"),"categories":vals("category"),"topics":vals("main_topic"),"channels":vals("channel"),"collections":[str(x.get("name") or "") for x in phase6_load_collections() if str(x.get("name") or "").strip()]}
    con.close();return out

def chatgpt_git_executable():
    """Find git.exe even when the packaged EXE does not inherit the developer PATH."""
    for candidate in (TOOLS/"git"/"cmd"/"git.exe", TOOLS/"git"/"bin"/"git.exe", TOOLS/"git.exe"):
        if candidate.is_file():return str(candidate)
    found=shutil.which("git")
    if found:return found
    roots=[os.environ.get("ProgramFiles"),os.environ.get("ProgramFiles(x86)"),os.environ.get("LocalAppData"),os.environ.get("USERPROFILE")]
    candidates=[]
    for root in roots:
        if not root:continue
        base=Path(root)
        candidates.extend([
            base/"Git"/"cmd"/"git.exe",
            base/"Git"/"bin"/"git.exe",
            base/"Programs"/"Git"/"cmd"/"git.exe",
            base/"Programs"/"Git"/"bin"/"git.exe",
            base/".cache"/"codex-runtimes"/"codex-primary-runtime"/"dependencies"/"native"/"git"/"cmd"/"git.exe",
            base/".cache"/"codex-runtimes"/"codex-primary-runtime"/"dependencies"/"native"/"git"/"bin"/"git.exe",
        ])
    seen=set()
    for candidate in candidates:
        text=str(candidate)
        if text in seen:continue
        seen.add(text)
        if candidate.is_file():return text
    raise RuntimeError("GitHub upload needs git.exe, but VideoHoarder could not find Git. Install Git for Windows or add git.exe to PATH, then try upload again. The local package is still created before upload starts.")

def _chatgpt_git(args, cwd=None, timeout=180):
    git_exe=chatgpt_git_executable()
    env=os.environ.copy();env["GIT_TERMINAL_PROMPT"]="0"
    git_dir=str(Path(git_exe).parent)
    env["PATH"]=git_dir+os.pathsep+env.get("PATH","")
    try:
        result=subprocess.run([git_exe,*args],cwd=str(cwd) if cwd else None,env=env,
                              capture_output=True,text=True,timeout=timeout,creationflags=getattr(subprocess,"CREATE_NO_WINDOW",0))
    except FileNotFoundError as exc:
        raise RuntimeError("GitHub upload could not start git.exe. Install Git for Windows or add git.exe to PATH, then try upload again. The local package is still created before upload starts.") from exc
    if result.returncode:
        detail=(result.stderr or result.stdout or "Git command failed").strip()
        raise RuntimeError(detail)
    return result.stdout.strip()

def chatgpt_github_mirror_path():
    # Keep even short-lived GitHub transfer data on the configured library
    # drive.  tempfile's default is normally the user's C: profile on Windows,
    # which violates the portable D-drive layout and can leave large clones on
    # the system disk after an interrupted run.
    runtime_root=chatgpt_exchange_dir()/"runtime"
    runtime_root.mkdir(parents=True,exist_ok=True)
    return Path(tempfile.mkdtemp(prefix="github_",dir=runtime_root)).resolve()/"VideoHoarder"

def ensure_chatgpt_github_mirror(pull=True):
    mirror=chatgpt_github_mirror_path();mirror.parent.mkdir(parents=True,exist_ok=True)
    set_state(phase="Publishing to GitHub",current_file="GitHub clone",current_status="Cloning authorized repository on D drive",current_percent="")
    _chatgpt_git(["clone","--branch",CHATGPT_GITHUB_BRANCH,"--single-branch",CHATGPT_GITHUB_REPO_URL,str(mirror)],timeout=300)
    actual=_chatgpt_git(["remote","get-url","origin"],mirror)
    normalized=lambda s:s.rstrip("/").removesuffix(".git").lower()
    if normalized(actual)!=normalized(CHATGPT_GITHUB_REPO_URL): raise RuntimeError("Existing mirror points to a different GitHub repository; stopped to protect it.")
    if _chatgpt_git(["status","--porcelain"],mirror): raise RuntimeError("GitHub mirror has uncommitted files; stopped to protect them.")
    _chatgpt_git(["checkout",CHATGPT_GITHUB_BRANCH],mirror)
    if pull:
        set_state(phase="Publishing to GitHub",current_file="GitHub pull",current_status="Updating local temporary clone",current_percent="")
        _chatgpt_git(["pull","--ff-only","origin",CHATGPT_GITHUB_BRANCH],mirror,300)
    return mirror

def publish_chatgpt_exchange_to_github(local_root, remote_relative, label="package"):
    """Publish a curated package view to the one explicitly authorized public repository."""
    source=Path(local_root).resolve()
    outgoing=(BASE/"data"/"chatgpt"/"exchange"/"outgoing").resolve()
    try: source.relative_to(outgoing)
    except ValueError: raise ValueError("GitHub publishing is restricted to VideoHoarder outgoing package folders.")
    remote_path=str(remote_relative).replace("\\","/").strip("/")
    if not remote_path.startswith(CHATGPT_GITHUB_ALLOWED_PREFIX) or ".." in Path(remote_path).parts:
        raise ValueError("GitHub destination must remain under exchange/outgoing in the authorized repository.")
    if not source.is_dir(): raise FileNotFoundError(f"Package folder not found: {source}")
    selected=[]
    for item in source.rglob("*"):
        if not item.is_file(): continue
        if item.name not in CHATGPT_GITHUB_PUBLIC_FILES and not (item.name.startswith("PLANNER_PACKAGE_") and item.suffix.lower()==".json"):
            continue
        if item.stat().st_size>95*1024*1024: raise ValueError(f"File exceeds GitHub safety limit: {item.name}")
        selected.append(item)
    if not selected: raise ValueError("No approved package files were found to publish.")
    set_state(phase="Publishing to GitHub",current_file=remote_path,current_status=f"Preparing {len(selected)} approved public file(s)",current_percent="")
    mirror=Path(ensure_chatgpt_github_mirror(pull=True)).resolve()
    try:
        destination=(mirror/Path(remote_path)).resolve()
        try: destination.relative_to(mirror)
        except ValueError: raise ValueError("Invalid GitHub destination path.")
        if destination.exists() and any(destination.iterdir()): raise RuntimeError(f"GitHub package destination already exists: {remote_path}")
        published=[]
        set_state(phase="Publishing to GitHub",current_file=remote_path,current_status="Copying approved package files into temporary clone",current_percent="")
        for item in selected:
            rel=item.relative_to(source);target=destination/rel;target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(item,target);published.append((rel,target))
        set_state(phase="Publishing to GitHub",current_file=remote_path,current_status="Staging files",current_percent="")
        _chatgpt_git(["add","--",remote_path],mirror)
        if not _chatgpt_git(["diff","--cached","--name-only"],mirror): raise RuntimeError("No new GitHub package files were staged.")
        set_state(phase="Publishing to GitHub",current_file=remote_path,current_status="Committing package",current_percent="")
        _chatgpt_git(["commit","-m",f"Publish VideoHoarder {label}"],mirror)
        set_state(phase="Publishing to GitHub",current_file=remote_path,current_status="Pushing package to GitHub",current_percent="")
        _chatgpt_git(["push","origin",CHATGPT_GITHUB_BRANCH],mirror,300)
        sha=_chatgpt_git(["rev-parse","HEAD"],mirror)
        quoted="/".join(urllib.parse.quote(x,safe="") for x in remote_path.split("/"))
        folder_url=f"{CHATGPT_GITHUB_WEB_URL}/tree/{CHATGPT_GITHUB_BRANCH}/{quoted}"
        file_urls=[f"{CHATGPT_GITHUB_WEB_URL}/blob/{sha}/{quoted}/"+"/".join(urllib.parse.quote(x,safe="") for x in rel.parts) for rel,_ in published]
        set_state(phase="GitHub upload complete",current_file=remote_path,current_status=f"Published {len(published)} file(s)",current_percent="100%")
        return {"ok":True,"public_repository":True,"repository":CHATGPT_GITHUB_WEB_URL,"branch":CHATGPT_GITHUB_BRANCH,
                "repository_path":remote_path,"folder_url":folder_url,"commit":sha,
                "commit_url":f"{CHATGPT_GITHUB_WEB_URL}/commit/{sha}","file_urls":file_urls,
                "published_files":len(published),"local_clone_removed":True}
    finally:
        shutil.rmtree(mirror.parent,ignore_errors=True)

def publish_latest_chatgpt_exchange_folder(kind="planner"):
    """Publish the newest already-created ChatGPT exchange folder when the user forgot the GitHub checkbox."""
    kind=str(kind or "planner").lower().strip()
    exchange=BASE/"data"/"chatgpt"/"exchange"/"outgoing"
    if kind in {"planner","planners","group_planner"}:
        root=exchange/"group_similar"/"planners";remote_base="exchange/outgoing/group_similar/planners";label="latest planner"
    elif kind in {"grouped","group_batches","batches"}:
        root=exchange/"group_similar"/"batches";remote_base="exchange/outgoing/group_similar/batches";label="latest grouped package set"
    elif kind in {"batch","batch_videos"}:
        root=exchange/"batch_videos";remote_base="exchange/outgoing/batch_videos";label="latest batch package set"
    else:
        raise ValueError("Unknown package type. Use planner, grouped, or batch.")
    if not root.is_dir():raise FileNotFoundError(f"No local package folder exists yet: {root}")
    folders=[p for p in root.iterdir() if p.is_dir()]
    if not folders:raise FileNotFoundError(f"No local package folders found in: {root}")
    latest=max(folders,key=lambda p:p.stat().st_mtime)
    set_state(phase="Publishing latest package to GitHub",current_file=latest.name,current_status=f"Selected newest local folder from {root}",current_percent="")
    result=publish_chatgpt_exchange_to_github(latest,f"{remote_base}/{latest.name}",latest.name)
    result["local_package_folder"]=str(latest)
    result["package_kind"]=kind
    result["selected_by"]="latest_modified_folder"
    return result

def chatgpt_short_package_id(mode):
    """Short, unique package id to avoid Windows MAX_PATH failures in nested package folders."""
    aliases={
        "FULL_INTELLIGENCE":"fi",
        "RESTRICTED_INTELLIGENCE":"ri",
        "NO_TRANSCRIPT_METADATA":"nt",
        "SMART_QUALITY":"sq",
        "BATCH_PLANNING":"bp",
        "MASTER":"ma",
    }
    code=aliases.get(str(mode or "").upper(),re.sub(r"[^a-z0-9]+","",str(mode or "pkg").lower())[:4] or "pkg")
    return f"vh_{code}_{time.strftime('%y%m%d%H%M%S')}_{uuid.uuid4().hex[:6]}"

def chatgpt_processing_history(limit=100):
    con=db_connect();rows=con.execute("SELECT request_id,package_id,mode,schema_version,prompt_version,requested_features_json,package_hash,created_at,status,result_path,validation_status,applied_status FROM chatgpt_requests ORDER BY created_at DESC LIMIT ?",(int(limit),)).fetchall();con.close()
    keys=["request_id","package_id","mode","schema_version","prompt_version","requested_features","package_hash","created_at","status","result_path","validation_status","applied_status"]
    return [dict(zip(keys,list(r[:5])+[json.loads(r[5] or "[]")]+list(r[6:]))) for r in rows]

def chatgpt_processing_coverage(feature_id="",status="",limit=500):
    con=db_connect();where=[];args=[]
    if feature_id:where.append("c.feature_id=?");args.append(feature_id)
    if status:where.append("c.status=?");args.append(status)
    sql="SELECT c.video_id,c.feature_id,c.feature_version,c.status,c.package_id,c.completed_at,c.last_error,v.clean_title,v.channel FROM video_feature_coverage c LEFT JOIN videos v ON v.video_id=c.video_id"+(" WHERE "+" AND ".join(where) if where else "")+" ORDER BY c.completed_at DESC LIMIT ?";args.append(int(limit))
    rows=con.execute(sql,args).fetchall();con.close();keys=["video_id","feature_id","feature_version","status","package_id","completed_at","last_error","title","channel"]
    return [dict(zip(keys,r)) for r in rows]

def chatgpt_package_transcript_preflight(video_ids, fetch_missing=False, package_preflight_id=""):
    """Persist local/fetched transcript availability before package routing. No video media is downloaded."""
    ids=list(dict.fromkeys(str(x).strip() for x in (video_ids or []) if str(x).strip()))
    if not ids:return {"total":0,"available":0,"unavailable":0,"checked":False}
    con=db_connect();q=','.join('?' for _ in ids)
    rows=con.execute(f"SELECT video_id,url,original_title,upload_date,subtitle_source,subtitle_lang,subtitle_base_lang,COALESCE(duration_seconds,0),COALESCE(platform,'') FROM videos WHERE video_id IN ({q})",ids).fetchall();con.close()
    if fetch_missing:
        # Local hard-drive imports are never passed into yt-dlp/YouTube caption
        # discovery (their IDs and empty URLs are not YouTube resources).
        missing=[r[:7] for r in rows if str(r[8]).lower()!='local' and not has_usable_transcript(str(r[0]))]
        if missing: prepare_transcripts_rows(missing)
    build_video_artifact_manifest([str(r[0]) for r in rows])
    stamp=time.strftime("%Y-%m-%d %H:%M:%S");con=db_connect();available=[];unavailable=[]
    for row in rows:
        vid=str(row[0]);manifest=artifact_manifest_for_video(vid) or {};transcript,lang=best_transcript_for_video(vid);assessment=chatgpt_canonical_evidence(vid,{"original_title":row[2],"duration_seconds":row[7]},manifest,transcript,lang,"");ready=bool(assessment["transcript_available"])
        source=assessment["transcript_source"] if ready else "not_available"
        if ready and assessment.get("timestamps_available"):
            detail=f"{assessment['canonical_segment_count']} canonical timestamped segment(s), {assessment['transcript_words']} words"
        elif ready:
            detail=f"Usable untimestamped transcript fallback, {assessment['transcript_words']} words; timestamp-dependent outputs disabled"
        else:
            detail="No usable transcript speech text found after check"
        con.execute("INSERT OR REPLACE INTO transcript_availability(video_id,status,source,checked_at,detail,package_preflight_id) VALUES(?,?,?,?,?,?)",(vid,"AVAILABLE" if ready else "UNAVAILABLE",source,stamp,detail,package_preflight_id))
        (available if ready else unavailable).append(vid)
    con.commit();con.close()
    return {"total":len(rows),"available":len(available),"unavailable":len(unavailable),"available_ids":available,"unavailable_ids":unavailable,"checked":bool(fetch_missing)}

def create_manual_chatgpt_processing_package(options):
    """Create files only. The user manually uploads them to ChatGPT."""
    options=options or {};mode=str(options.get("mode") or "MASTER").upper();compact_mode=bool(options.get("compact_chatgpt_package"))
    if compact_mode:
        requested=[x for x in options.get("features") or list(CHATGPT_FEATURES) if x in CHATGPT_FEATURES and x!="viewer_comment_intelligence.v2"]
    else:
        requested=[x for x in options.get("features") or ["title_en.v1","taxonomy.v3","chapters.v1","detailed_summary.v3","recipes.v1","references.v1","qa.v1","playlist_series.v1","technical_intelligence.v1","named_items.v1"] if x in CHATGPT_FEATURES]
    raw=str(options.get("video_ids") or "");ids=list(dict.fromkeys(x for x in re.split(r"[\s,;]+",raw) if x))
    con=db_connect()
    if not ids:
        q="SELECT video_id FROM videos WHERE COALESCE(archived,0)=0 AND COALESCE(current_present,1)=1";sel_args=[]
        selector_map={"folderScope":"local_folder","topicScope":"main_topic","categoryScope":"category"}
        for key,column in selector_map.items():
            value=str(options.get(key) or "").strip()
            if value:q+=f" AND {column}=?";sel_args.append(value)
        if mode=="FEATURE_ENRICHMENT" and requested:
            first_feature=requested[0].split('.',1)[0]
            q+=" AND video_id NOT IN (SELECT video_id FROM video_feature_coverage WHERE feature_id=? AND status='COMPLETE')";sel_args.append(first_feature)
        ids=[str(r[0]) for r in con.execute(q,tuple(sel_args)).fetchall()]
    ids,recreate_skipped=chatgpt_filter_recreate_locked_ids(ids,requested,bool(options.get("allow_recreate_processed")))
    if not ids:con.close();raise ValueError("No eligible videos selected for this manual package.")
    if options.get("verify_transcript_availability"):
        # For a single package this records the state; SMART_QUALITY additionally
        # uses it to route unavailable videos into the separate profile.
        chatgpt_package_transcript_preflight(ids,True,str(options.get("preflight_id") or ""))
    package_fields=["video_id","url","original_title","clean_title","channel","upload_date","description","source_category","youtube_category_name","comments_file","comments_transcript_file","local_folder","duration_seconds","availability","source_chapters_json","youtube_tags_cleaned","subtitle_source","subtitle_lang","subtitle_base_lang","transcript_source"]
    available_cols={str(r[1]) for r in con.execute("PRAGMA table_info(videos)").fetchall()}
    select_exprs=[(f'"{name}"' if name in available_cols else f'NULL AS "{name}"') for name in package_fields]
    qmarks=','.join('?' for _ in ids);rows=con.execute(f"SELECT {','.join(select_exprs)} FROM videos WHERE video_id IN ({qmarks})",ids).fetchall();con.close()
    fields=','.join(package_fields)
    stamp=time.strftime("%Y%m%d_%H%M%S");package_id=chatgpt_short_package_id(mode)
    default_parent=BASE/"data"/"chatgpt"/"exchange"/"outgoing"/"single_packages"/re.sub(r"[^a-z0-9_-]+","_",mode.lower())
    root=Path(str(options.get("package_parent") or default_parent))/package_id;root.mkdir(parents=True,exist_ok=True)
    videos=[];request_id=str(uuid.uuid4());package_source_repair=[]
    for row in rows:
        d=dict(zip(fields.split(','),row));vid=str(d["video_id"]);artifact=artifact_manifest_for_video(vid) or artifact_inventory(vid)
        transcript,_lang=best_transcript_for_video(vid)
        evidence_context={"original_title":d.get("original_title"),"duration_seconds":d.get("duration_seconds")}
        assessment=chatgpt_canonical_evidence(vid,evidence_context,artifact,transcript,_lang,"")
        assessment_grade=normalize_evidence_grade(assessment.get("evidence_grade"),allow_legacy=True)
        assessment["evidence_grade"]=assessment_grade
        if not normal_transcript_package_eligible(assessment_grade):
            health=assessment.get("transcript_health") or {}
            package_source_repair.append({
                "video_id":vid,
                "reason_code":f"TRANSCRIPT_GRADE_{assessment_grade}_EXCLUDED",
                "message":f"Transcript evidence grade {assessment_grade} is not eligible for the normal transcript-intelligence package.",
                "evidence_grade":assessment_grade,
                "routing_class":repair_routing_for_grade(assessment_grade),
                "health_score":health.get("score"),
                "health_reason_codes":health.get("reason_codes") or [],
            })
            continue
        # V3.3.4 package guard: bad timestamps must never discard usable speech text.
        # When timestamp normalization fails, canonical evidence falls back to
        # untimestamped_text and ChatGPT is explicitly forbidden from recovering time.
        inline_timestamp_count=len(_chatgpt_timestamp_matches(transcript or ""))
        if transcript.strip() and assessment.get("transcript_source")=="no_transcript":
            package_source_repair.append({"video_id":vid,"reason_code":"TRANSCRIPT_SOURCE_MISMATCH","message":"Transcript text exists but no usable canonical transcript source could be created.","inline_timestamp_count":inline_timestamp_count,"canonical_segment_count":int(assessment.get("canonical_segment_count") or 0)})
            continue
        segs=((assessment.get("canonical_transcript") or {}).get("segments") or [])
        timestamp_failed=inline_timestamp_count>=2 and (int(assessment.get("canonical_segment_count") or 0)<=1 or (segs and all(float(x.get("start_seconds") or 0)==0 and float(x.get("end_seconds") or 0)==0 for x in segs)))
        if timestamp_failed and assessment.get("transcript_available"):
            canonical=assessment.get("canonical_transcript") or {}
            fallback_text=_chatgpt_untimestamped_fallback_text(transcript)
            canonical["source"]="untimestamped_transcript"
            canonical["normalization_status"]="UNTIMESTAMPED_FALLBACK"
            canonical["timestamps_available"]=False
            canonical["timestamp_status"]="unavailable_or_unreliable"
            hint_data=_chatgpt_timestamp_hints(transcript)
            canonical["timestamp_hints_available"]=bool(hint_data.get("available"))
            canonical["timestamp_hints_reliable"]=False
            canonical["timestamp_hint_count"]=int(hint_data.get("total_detected") or 0)
            canonical["timestamp_hints"]=hint_data.get("hints") or []
            canonical["timestamp_instruction"]="Process untimestamped_text directly. Preserve supplied timestamp_hints only as approximate navigation clues when helpful. Do not repair, reconstruct, interpolate, validate, or present them as exact timestamps, and never invent missing timestamps. Do not spend significant reasoning time on timestamp recovery."
            canonical["segments"]=[]
            canonical["untimestamped_text"]=fallback_text
            assessment["canonical_transcript"]=canonical
            assessment["transcript_source"]="untimestamped_transcript"
            assessment["canonical_segment_count"]=0
            assessment["timestamps_available"]=False
            assessment["timestamp_status"]="unavailable_or_unreliable"
            assessment["timestamp_hints_available"]=bool(hint_data.get("available"))
            assessment["timestamp_hints_reliable"]=False
            assessment["normalization_status"]="UNTIMESTAMPED_FALLBACK"
            assessment.setdefault("source_conflicts",[]).append("Timestamp normalization failed; semantic processing will use untimestamped transcript text; source timestamp hints remain approximate navigation clues and exact timestamp-dependent claims are omitted.")
        elif timestamp_failed:
            package_source_repair.append({"video_id":vid,"reason_code":"TIMESTAMP_NORMALIZATION_FAILED_NO_USABLE_TEXT","message":f"{inline_timestamp_count} timestamp markers were detected, normalization failed, and no usable fallback speech text was available.","inline_timestamp_count":inline_timestamp_count,"canonical_segment_count":int(assessment.get("canonical_segment_count") or 0)})
            continue
        payload=build_video_payload(d,assessment=assessment,artifact_manifest=artifact,transcript_language=_lang,requested_features=requested)
        assert_strict_package_contract(payload)
        videos.append(payload)
    if package_source_repair:
        _atomic_write_json(root/"PACKAGE_SOURCE_REPAIR_QUEUE.json",{"package_id":package_id,"created_at":time.strftime("%Y-%m-%d %H:%M:%S"),"queue_type":"late_package_build_source_repair","videos":package_source_repair})
    if not videos:
        return {"ok":False,"package_id":package_id,"request_id":request_id,"folder":str(root),"upload_file":"","videos":0,"features":requested,"skipped_source_repair":len(package_source_repair),"skipped_source_repair_file":str(root/"PACKAGE_SOURCE_REPAIR_QUEUE.json") if package_source_repair else "","message":"No videos remained packageable after source-repair checks; repair transcript/SRT evidence and recreate."}
    package_transcript_chars=int((options.get("batch_context") or {}).get("transcript_chars") or sum(int((v.get("evidence") or {}).get("assessment",{}).get("transcript_characters") or 0) for v in videos))
    package_metrics=chatgpt_package_quality(videos,package_transcript_chars)
    # Structural response template only. Keep semantic example content empty so the
    # template cannot become a generation recipe or leak generic placeholder prose.
    response_features={
        "title_en.v1":{"title":"","short_title":"","reason":""},
        "taxonomy.v3":{"primary_topic":"","secondary_topics":[],"category":"Other","subcategory":"","keywords":[],"canonical_tags":[],"search_queries":[]},
        "detailed_summary.v3":{"overview":"","sections":[],"practical_details":[],"limitations":[],"source_basis":[]},
        "chapters.v1":{"chapters":[]},
        "recipes.v1":{"recipes":[],"no_recipe_reason":""},
        "references.v1":{"references":[],"limitations":[]},
        "qa.v1":{"questions":[]},
        "playlist_series.v1":{"series_signals":[],"recommended_library_group":"","follow_up_topics":[]},
        "technical_intelligence.v1":{"methods":[],"tools":[],"settings_or_parameters":[],"implementation_notes":[]},
        "named_items.v1":{"items":[]},
        "video_intake.v1":{"actual_subject":"","strongest_takeaway":"","strengths":[],"weaknesses":[],"worth_keeping":"unknown","worth_rewatching":"unknown","reason":""},
        "quality_validation.v1":{"status":"PASS_WITH_WARNINGS","warnings":[],"cross_feature_consistency":"","repair_attempts":0}
    }
    response_template={"package_id":package_id,"schema_version":CHATGPT_PROCESSING_SCHEMA_VERSION,"batch_validation_status":"PASS_WITH_WARNINGS","package_outcome_status":"COMPLETE_WITH_REPROCESS_LIST","video_updates":[{"video_id":"EXACT_VIDEO_ID_FROM_PACKAGE","processing_status":"PASS_WITH_WARNINGS","evidence_grade":"A","confidence":"high","evidence_references":[{"source":"canonical_transcript","segment_ids":["s00001"]}],"source_conflicts":[],"validation":{"status":"PASS_WITH_WARNINGS","warnings":[],"repair_attempts":0},"features":{fid:response_features[fid] for fid in requested if fid in response_features}}]}
    feature_contracts=chatgpt_feature_contracts_for(requested,compact_mode)
    schema={"schema_version":CHATGPT_PROCESSING_SCHEMA_VERSION,"package_id":package_id,"manual_exchange_only":True,"compact_chatgpt_package":compact_mode,"allowed_feature_ids":requested,"feature_contracts":feature_contracts,"controlled_taxonomy":{"allowed_categories":list(CFG.get("categories") or ["Other"]),"entity_types":["person","organization","place","product","work","event","concept","law","study","other"],"unknown_category":"Other","tag_rules":"lowercase canonical concepts; singular where natural; no promotional filler"},"formal_json_schema":chatgpt_formal_result_schema(package_id,requested,compact_mode),"allowed_processing_status":["PASS","PASS_WITH_WARNINGS","REPROCESS_RECOMMENDED","SOURCE_INSUFFICIENT"],"allowed_evidence_grades":["A","B","C","D","F"],"result_contract":"Return ONE JSON object only after processing every exact VIDEO_ID. video_updates must be an array. Each item must include processing_status, evidence_grade, confidence, evidence_references, source_conflicts, validation, and every requested feature using its exact field-level contract and formal_json_schema. Provenance must cite supplied segment_ids when transcript evidence is used. Treat speaker claims as unverified unless external verification is explicitly provided. Use unknown, not_available, or insufficient_evidence instead of inventing content. No automatic deletion, file movement, clipping, or upload.","response_template":response_template}
    batch_context=options.get("batch_context") or {}
