        no_transcript_chunks=[]
        for n in range(0,len(without_transcript),min(100,CHATGPT_MAX_PACKAGE_VIDEOS)):
            chunk=without_transcript[n:n+CHATGPT_MAX_PACKAGE_VIDEOS]
