            child=dict(options);child["mode"]=profile;child["video_ids"]="\n".join(chunk);child["features"]=features;child["verify_transcript_availability"]=False;child["github_publish"]=False;child["package_parent"]=str(set_root/"packages");child["skip_no_transcript_videos"]=compact_mode;child["batch_context"]={"master_set_id":master_set_id,"profile":profile,"group_name":group_name,"batch_number":number,"batch_total":len(chunks),"video_count":len(chunk),"batch_size":len(chunk),"target_package_size":CHATGPT_TARGET_PACKAGE_VIDEOS,"max_package_size":CHATGPT_MAX_PACKAGE_VIDEOS,"transcript_chars":chunk_chars,"split_reason":split_reason,"adaptive_batching":automatic_size,"compact_chatgpt_package":compact_mode}
