    if not ids:
        con=db_connect();ids=[str(r[0]) for r in con.execute("SELECT video_id FROM videos WHERE COALESCE(archived,0)=0 AND COALESCE(current_present,1)=1 ORDER BY video_id").fetchall()];con.close()
