    full,full_ids,errors=groups("transcript_groups",available,max(1,len(available)));none,none_ids,more=groups("no_transcript_groups",unavailable,max(1,len(unavailable)));errors+=more;errors+=integrity_errors
    pfull,pfull_ids,more=parent_groups("transcript_parent_groups",available);errors+=more
    pnone,pnone_ids,more=parent_groups("no_transcript_parent_groups",unavailable);errors+=more
    returned=set(full_ids+none_ids);parent_returned=set(pfull_ids+pnone_ids);missing=sorted(expected-returned);unexpected=sorted(returned-expected);parent_missing=sorted(expected-parent_returned);parent_unexpected=sorted(parent_returned-expected)
    if schema!=expected_schema:errors.append(f"Schema mismatch: expected {expected_schema}, received {schema or 'missing'}")
    if missing:errors.append(f"Missing {len(missing)} catalog VIDEO_ID(s)")
    if unexpected:errors.append("Unexpected VIDEO_IDs: "+", ".join(unexpected[:10]))
    if parent_missing:errors.append(f"Missing {len(parent_missing)} catalog VIDEO_ID(s) from parent_groups")
    if parent_unexpected:errors.append("Unexpected parent_group VIDEO_IDs: "+", ".join(parent_unexpected[:10]))
    valid=not errors
