    if not row or str(row[1])!="VALIDATED":raise ValueError("The selected planner has not been validated successfully.")
    path=Path(str(row[0] or ""));
    if not path.is_file():raise ValueError("Validated planner file is missing.")
    plan=json.loads(path.read_text(encoding="utf-8"))
    if not plan.get("valid"):raise ValueError("Validated planner contains errors and cannot create packages.")
    manifest=json.loads(row[2] or "{}");child=dict(options);child["mode"]="SMART_QUALITY";child["video_ids"]="\n".join(manifest.get("video_ids") or []);child["verify_transcript_availability"]=False
