def _chatgpt_timestamp_seconds(value):
    if value in (None,""): return None
    if isinstance(value,(int,float)): return float(value)
    text=str(value).strip()
    if not re.fullmatch(r"\d+(?::\d{1,2}){0,2}(?:\.\d+)?",text): return None
    parts=[float(x) for x in text.split(":")]
    if len(parts)==1:return parts[0]
    if len(parts)==2:return parts[0]*60+parts[1]
    return parts[0]*3600+parts[1]*60+parts[2]

def _chatgpt_walk_timestamps(value,path="$",out=None):
    out=[] if out is None else out
    if isinstance(value,dict):
        for k,v in value.items():
            p=f"{path}.{k}"
            if "timestamp" in str(k).lower() or str(k).lower() in {"start","end","start_seconds","end_seconds"}:out.append((p,v))
            _chatgpt_walk_timestamps(v,p,out)
    elif isinstance(value,list):
        for i,v in enumerate(value):_chatgpt_walk_timestamps(v,f"{path}[{i}]",out)
    return out

def _chatgpt_walk_segment_ids(value,path="$",out=None):
    out=[] if out is None else out
    if isinstance(value,dict):
        for key,item in value.items():
            current=f"{path}.{key}"
            if key=="segment_ids" and isinstance(item,list):out.extend((current,str(x)) for x in item)
            _chatgpt_walk_segment_ids(item,current,out)
    elif isinstance(value,list):
        for index,item in enumerate(value):_chatgpt_walk_segment_ids(item,f"{path}[{index}]",out)
    return out

def chatgpt_outgoing_package_folder(package_id):
    """Resolve both legacy flat packages and the new separated batch folders."""
    outgoing=BASE/"data"/"chatgpt"/"exchange"/"outgoing";package_id=str(package_id)
    direct=outgoing/package_id
    if direct.is_dir(): return direct
    try:
        matches=[p for p in outgoing.rglob(package_id) if p.is_dir()]
        if matches:return matches[0]
    except Exception:
        pass
    return direct

def refresh_chatgpt_final_batch_validation(manifest):
    context=(manifest or {}).get("batch_context") or {};master_set_id=str(context.get("master_set_id") or "")
    if not master_set_id:return {}
    outgoing=BASE/"data"/"chatgpt"/"exchange"/"outgoing";matches=[p for p in outgoing.rglob(master_set_id) if p.is_dir()]
    if not matches:return {}
    set_root=matches[0];index_path=set_root/"BATCH_SET_INDEX.json"
    try:index=json.loads(index_path.read_text(encoding="utf-8"))
    except Exception:return {}
    package_ids=[str(x.get("package_id") or "") for x in index.get("batches") or [] if x.get("package_id")]
    con=db_connect();rows=[]
    for package_id in package_ids:
        row=con.execute("SELECT status,validation_status,result_path FROM chatgpt_requests WHERE package_id=?",(package_id,)).fetchone() or ("MISSING","MISSING","")
        rows.append({"package_id":package_id,"status":row[0],"validation_status":row[1],"result_path":row[2]})
    con.close();statuses={str(x["status"] or "") for x in rows}
    if statuses&{"INVALID","FAILED","MISSING"}:overall="FAIL"
    elif statuses&{"PARTIAL"}:overall="PASS_WITH_WARNINGS"
    elif rows and all(x["status"]=="VALIDATED" for x in rows):overall="PASS"
    else:overall="AWAITING_RESULTS"
    report={"master_set_id":master_set_id,"status":overall,"expected_packages":len(package_ids),"validated_packages":sum(x["status"]=="VALIDATED" for x in rows),"updated_at":time.strftime("%Y-%m-%d %H:%M:%S"),"packages":rows}
    (set_root/"FINAL_BATCH_VALIDATION.json").write_text(json.dumps(report,indent=2,ensure_ascii=False),encoding="utf-8")
    return {"status":overall,"report":str(set_root/"FINAL_BATCH_VALIDATION.json")}

def _validate_chatgpt_package_integrity(package_id,manifest,stored_package_hash):
    errors=[];verified=[];root=chatgpt_outgoing_package_folder(package_id)
    manifest_path=root/"manifest.json"
    if not manifest_path.is_file():return ["Outgoing manifest.json is missing; package integrity cannot be verified."],verified
    if str(manifest.get("package_id") or "")!=str(package_id):errors.append("Manifest package_id does not match the imported package.")
    actual_manifest_hash=hashlib.sha256(manifest_path.read_bytes()).hexdigest()
    if stored_package_hash and actual_manifest_hash!=stored_package_hash:errors.append("Package manifest checksum mismatch.")
    for name,expected_hash in (manifest.get("hashes") or {}).items():
        p=(root/str(name)).resolve()
        try:p.relative_to(root.resolve())
        except ValueError:errors.append(f"Unsafe evidence path in manifest: {name}");continue
        if not p.is_file():errors.append(f"Evidence file missing: {name}");continue
        actual=hashlib.sha256(p.read_bytes()).hexdigest()
        if actual!=str(expected_hash):errors.append(f"Evidence checksum mismatch: {name}")
        else:verified.append(str(name))
    return errors,verified

def _chatgpt_package_evidence_index(package_id):
    """Return evidence actually present per VIDEO_ID plus transcript time coverage."""
    path=chatgpt_outgoing_package_folder(package_id)/"evidence.json"
    try:data=json.loads(path.read_text(encoding="utf-8"))
    except Exception:return {}
