    update_by_video={}
    for item in updates or []:
        if isinstance(item,dict) and str(item.get("video_id") or "").strip():
            update_by_video[str(item.get("video_id")).strip()]=item
    now=time.strftime("%Y-%m-%d %H:%M:%S")
    completed=[];reprocess=[];pass_count=warn_count=reprocess_count=insufficient_count=0;pass2_requests=[];artifact_status_seen={}
    expected_order=[str(x).strip() for x in expected_ids if str(x).strip()]
    first_unfinished=next((x for x in expected_order if x not in update_by_video),None)
    for idx,vid in enumerate(expected_order,1):
        item=update_by_video.get(vid)
