        feature_payload=record.get("features") or {}
        section_status={}
        for filename,fid in feature_map:
            section={"section_name":fid,"section_status":"PASS" if fid in feature_payload else "EMPTY_BY_DESIGN","source_fingerprint":source_manifest["source_fingerprint"],"prompt_version":source_manifest["prompt_version"],"prompt_hash":source_manifest["prompt_hash"],"generated_by":"pass_1" if item else "manual","generated_at":now,"last_modified_at":now,"validation_warnings":[],"dependency_warnings":[],"data":feature_payload.get(fid,{})}
            _atomic_write_json(intel_dir/filename,section)
