        artifact_status_by_video={x:artifact_status_seen.get(x,"JSON_COMPLETE_HTML_PENDING") for x in expected_order}
        checkpoint={"package_id":package_id,"package_size":len(expected_order),"last_completed_index":len(completed),"last_completed_video_id":completed[-1] if completed else "","next_video_id":first_unfinished,"completed_video_ids":completed,"video_processing_state_by_video":{x:("SEMANTIC_COMPLETE" if x in completed else ("INTERRUPTED" if x==first_unfinished else "PENDING")) for x in expected_order},"semantic_status_by_video":{x:(update_by_video.get(x) or {}).get("processing_status") for x in expected_order if update_by_video.get(x)},"artifact_status_by_video":artifact_status_by_video,"updated_at":now}
        _atomic_write_json(package_root/"CHECKPOINT.json",checkpoint)
