def chatgpt_incoming_results_root():
    root=BASE/"data"/"chatgpt"/"exchange"/"incoming"/"full_intelligence"
    root.mkdir(parents=True,exist_ok=True)
    return root

def chatgpt_new_incoming_session_folder(prefix="import"):
    root=chatgpt_incoming_results_root()
    folder=root/f"{safe_name(str(prefix) or 'import')}_{time.strftime('%Y%m%d_%H%M%S')}"
    i=1
    while folder.exists():
        folder=root/f"{safe_name(str(prefix) or 'import')}_{time.strftime('%Y%m%d_%H%M%S')}_{i}"
        i+=1
    folder.mkdir(parents=True,exist_ok=True)
    return folder

def chatgpt_latest_incoming_session_folder():
    root=chatgpt_incoming_results_root()
    sessions=[p for p in root.iterdir() if p.is_dir() and any(p.glob("*.json"))]
    return max(sessions,key=lambda p:p.stat().st_mtime) if sessions else root

def import_validate_manual_chatgpt_processing_result(payload):
    """Archive and validate a user-selected result.  This never writes video metadata or moves files."""
    payload=payload or {};raw=payload.get("result_json")
    if not isinstance(raw,str) or not raw.strip(): raise ValueError("Select a returned JSON file first.")
    try: result=json.loads(raw)
    except Exception as ex: raise ValueError(f"Returned file is not valid JSON: {ex}")
    if not isinstance(result,dict): raise ValueError("Returned JSON must be one object containing package_id and video_updates.")
    package_id=str(result.get("package_id") or "").strip();schema=str(result.get("schema_version") or "").strip()
    if not package_id: raise ValueError("Returned JSON is missing package_id.")
    con=db_connect();request=con.execute("SELECT request_id,schema_version,requested_features_json,manifest_json,package_hash,mode FROM chatgpt_requests WHERE package_id=?",(package_id,)).fetchone()
    if not request: con.close();raise ValueError("Unknown package_id. Import the result for a package created by this VideoHoarder library.")
    request_id,expected_schema,features,manifest_json,stored_package_hash,request_mode=request;features=json.loads(features or "[]");manifest=json.loads(manifest_json or "{}");enhanced=bool(manifest.get("evidence_grades"));strict_contracts=str(manifest.get("validation_pipeline") or "")=="canonical-semantic-1";compact_mode=bool(manifest.get("compact_chatgpt_package"))
    expected={str(r[0]) for r in con.execute("SELECT video_id FROM chatgpt_request_videos WHERE request_id=?",(request_id,)).fetchall()}
    updates=result.get("video_updates") or result.get("videos") or []
    normalized_keyed_updates=False
    # Compatibility: earlier package files did not include an exact response
    # template, so ChatGPT reasonably returned {VIDEO_ID: feature_data}. Keep
    # accepting that safe, common representation and normalize only in memory.
    if isinstance(updates,dict):
        normalized_keyed_updates=True
        updates=[{"video_id":str(video_id),"features":feature_data} for video_id,feature_data in updates.items()]
    if not isinstance(updates,list): con.close();raise ValueError("video_updates must be a JSON array, or a VIDEO_ID-keyed JSON object.")
    returned=[];unexpected=[];warnings=[];errors=[];quality_issues=[];editorial_takes=[];evidence_index=_chatgpt_package_evidence_index(package_id)
    def soft_issue(video_id,message):
        video_id=str(video_id or "").strip()
        text=f"{video_id}: {message}" if video_id else str(message)
        warnings.append(text)
        quality_issues.append({"video_id":video_id,"message":str(message),"package_id":package_id})
    integrity_errors,verified_files=_validate_chatgpt_package_integrity(package_id,manifest,stored_package_hash);errors+=integrity_errors
    for item in updates:
        if not isinstance(item,dict): warnings.append("Ignored a non-object update.");continue
        vid=str(item.get("video_id") or "").strip()
        if not vid: warnings.append("Ignored update with no video_id.");continue
        returned.append(vid)
        if vid not in expected: unexpected.append(vid)
        refs=item.get("evidence_references") or item.get("evidence") or []
        if not refs:soft_issue(vid,"no evidence reference supplied")
        if not isinstance(refs,list):soft_issue(vid,"evidence_references must be an array");refs=[]
        ref_names=[str(x.get("source") or "") if isinstance(x,dict) else str(x) for x in refs]
        allowed={"metadata","description","transcript","canonical_transcript","comments","manifest","timestamped_transcript","subtitle","existing_intelligence"}
        bad=[x for x in ref_names if x not in allowed]
        if bad:soft_issue(vid,f"unknown provenance reference(s): {', '.join(bad[:10])}")
        available=set((evidence_index.get(vid) or {}).get("sources") or [])
