            if processing_status not in {"PASS","PASS_WITH_WARNINGS","REPROCESS_RECOMMENDED","SOURCE_INSUFFICIENT"}:soft_issue(vid,"processing_status must be PASS, PASS_WITH_WARNINGS, REPROCESS_RECOMMENDED or SOURCE_INSUFFICIENT")
