def chatgpt_processing_review(package_id=""):
    con=db_connect();args=[];where=""
    if package_id: where=" WHERE package_id=?";args=[package_id]
    rows=con.execute("SELECT package_id,status,result_path,result_hash,validation_status,applied_status FROM chatgpt_requests"+where+" ORDER BY created_at DESC LIMIT 50",args).fetchall();con.close()
    out=[]
    for package_id,status,result_path,result_hash,validation,applied in rows:
        preview=BASE/"data"/"chatgpt"/"exchange"/"review"/f"{package_id}_{str(result_hash or '')[:12]}_review.json"
        preview_data={}
        if preview.is_file():
            try:preview_data=json.loads(preview.read_text(encoding="utf-8"))
            except Exception:preview_data={}
        out.append({"package_id":package_id,"status":status,"validation_status":validation,"applied_status":applied,"result_path":result_path,"review_preview":str(preview) if preview.is_file() else "","proposed_updates":preview_data.get("proposed_updates") or [],"warnings":preview_data.get("warnings") or [],"errors":preview_data.get("errors") or [],"manual_actions_only":["Review rename suggestion in existing Rename tool","Review category move in existing move preview","Review duplicate canonical choice","Review Clip Studio plan"]})
    return out

def record_chatgpt_review_decisions(payload):
    """Persist explicit field/action decisions; physical actions remain separate reviewed tools."""
    payload=payload or {};package_id=str(payload.get("package_id") or "").strip();decisions=payload.get("decisions") or []
    if not package_id:raise ValueError("package_id is required")
    if not isinstance(decisions,list) or not decisions:raise ValueError("Select at least one proposed field/action.")
    allowed={"rename","move","metadata","taxonomy","duplicate_keep","duplicate_archive","duplicate_mark_delete","clip_plan","report_refresh"}
    clean=[]
    for row in decisions:
        if not isinstance(row,dict):continue
        action=str(row.get("action") or "").strip()
        if action not in allowed:raise ValueError(f"Unsupported review action: {action}")
        clean.append({"video_id":str(row.get("video_id") or ""),"feature_id":str(row.get("feature_id") or ""),"field_path":str(row.get("field_path") or "$"),"action":action,"approved":bool(row.get("approved")),"value":row.get("value")})
    if not clean:raise ValueError("No valid review decisions supplied.")
    root=BASE/"data"/"chatgpt"/"exchange"/"review"/"decisions";root.mkdir(parents=True,exist_ok=True)
    record={"package_id":package_id,"created_at":time.strftime("%Y-%m-%d %H:%M:%S"),"decisions":clean,"physical_changes_applied":False,"next_routes":{"rename":"/app?tab=chatgpt","move":"/app?tab=chatgpt","duplicates":"/app?tab=tools&command=duplicate_audit","clips":"/app?tab=clips"}}
    path=root/f"{package_id}_{time.strftime('%Y%m%d_%H%M%S')}.json";path.write_text(json.dumps(record,indent=2,ensure_ascii=False),encoding="utf-8")
    con=db_connect();con.execute("UPDATE chatgpt_requests SET applied_status='REVIEWED_NOT_APPLIED',notes=? WHERE package_id=?",(f"Review decisions: {path}",package_id));con.commit();con.close()
    return {"ok":True,"record":str(path),"decisions":len(clean),"physical_changes_applied":False,"next_routes":record["next_routes"]}

def apply_all_validated_chatgpt_results(options=None):
    """Bulk apply every validated review preview without per-field checkbox selection."""
    options=options or {}
    include_partial=bool(options.get("include_partial",True))
    move_folders=bool(options.get("move_folders",False))
    statuses={"VALIDATED"}
    if include_partial:statuses.add("PARTIAL")
    review_dir=BASE/"data"/"chatgpt"/"exchange"/"review"
    previews=[]
    for path in sorted(review_dir.glob("*_review.json")) if review_dir.is_dir() else []:
        try:preview=json.loads(path.read_text(encoding="utf-8"))
        except Exception:continue
        if preview.get("status") in statuses:
            previews.append((path,preview))
    if not previews:
        return {"ok":False,"message":"No validated ChatGPT review previews found to apply.","applied":0,"files":0}
    stored=0;applied=0;failed_ids=[];success_ids=[];messages=[];packages=[];records_for_preview=[]
    for path,preview in previews:
        records=[{"package_id":preview.get("package_id"),"schema_version":"3.0","video_updates":preview.get("proposed_updates") or []}]
        try:
            stored+=phase6_store_intelligence_records(records)
            a,msgs,ok_ids,bad_ids=phase6_apply_chatgpt_video_updates(records,move_folders=move_folders,return_ids=True)
            applied+=a;messages.extend(msgs[:20]);success_ids.extend(ok_ids);failed_ids.extend(bad_ids);records_for_preview.extend(records)
            packages.append({"package_id":preview.get("package_id"),"status":preview.get("status"),"review_preview":str(path),"applied":a,"failed":len(bad_ids)})
            try:
                con=db_connect()
                con.execute("UPDATE chatgpt_requests SET applied_status=? WHERE package_id=?",("APPLIED_BULK" if a else "APPLY_FAILED",str(preview.get("package_id") or "")))
                con.commit();con.close()
            except Exception:pass
        except Exception as ex:
            packages.append({"package_id":preview.get("package_id"),"status":preview.get("status"),"review_preview":str(path),"applied":0,"failed":1,"message":f"{type(ex).__name__}: {ex}"})
    move_preview={}
    try:move_preview=phase6_preview_category_moves(records_for_preview)
    except Exception as ex:move_preview={"ok":False,"message":f"Move preview refresh failed: {type(ex).__name__}: {ex}"}
    try:rebuild_database_and_library_exports()
    except Exception:pass
    success_ids=list(dict.fromkeys(success_ids));failed_ids=list(dict.fromkeys(failed_ids))
    return {"ok":applied>0 and not failed_ids,"files":len(previews),"stored_records":stored,"applied":applied,"successful_video_ids":success_ids,"failed":len(failed_ids),"failed_video_ids":failed_ids,"packages":packages,"move_folders":move_folders,"move_preview":move_preview,"messages":messages[:100],"manual_folder_moves_required":not move_folders}

def record_chatgpt_duplicate_review(payload):
    """Record a reviewed duplicate group without moving or deleting media."""
    payload=payload or {};group=payload.get("group") or {};canonical=str(payload.get("canonical_video_id") or "").strip();choices=payload.get("choices") or []
    ids=[str(x).strip() for x in (group.get("video_ids") or []) if str(x).strip()]
    if len(ids)<2:raise ValueError("Duplicate review requires at least two VIDEO_IDs.")
    if canonical not in ids:raise ValueError("Canonical VIDEO_ID must belong to the duplicate group.")
    allowed={"keep","archive","mark_delete"};normalized=[]
    for row in choices:
        vid=str((row or {}).get("video_id") or "").strip();decision=str((row or {}).get("decision") or "keep").strip().lower()
        if vid not in ids:raise ValueError(f"Unknown VIDEO_ID in duplicate choice: {vid}")
        if decision not in allowed:raise ValueError(f"Unsupported duplicate decision: {decision}")
        if vid==canonical and decision!="keep":raise ValueError("The canonical video must be kept.")
        normalized.append({"video_id":vid,"decision":decision})
    decided={x["video_id"] for x in normalized}
    normalized.extend({"video_id":vid,"decision":"keep"} for vid in ids if vid not in decided)
    record={"review_id":str(uuid.uuid4()),"created_at":time.strftime("%Y-%m-%d %H:%M:%S"),"canonical_video_id":canonical,"group_name":str(group.get("group_name") or "Duplicate group"),"choices":normalized,"physical_changes_applied":False,"manual_delete_only":True}
    root=BASE/"data"/"chatgpt"/"exchange"/"review"/"duplicates";root.mkdir(parents=True,exist_ok=True);path=root/f"duplicate_{record['review_id']}.json";path.write_text(json.dumps(record,indent=2,ensure_ascii=False),encoding="utf-8")
    return {"ok":True,"record":str(path),"review":record,"duplicate_audit_route":"/app?tab=tools&command=duplicate_audit"}

def validate_chatgpt_clip_plan(payload,save=False):
    payload=payload or {};plan=payload.get("plan") if isinstance(payload.get("plan"),dict) else payload
    clips=plan.get("clips") or plan.get("merge_clip_plan") or []
    if not isinstance(clips,list) or not clips:raise ValueError("Clip plan must contain a non-empty clips array.")
    con=db_connect();normalized=[];errors=[]
    for index,clip in enumerate(clips,1):
        if not isinstance(clip,dict):errors.append(f"Clip {index}: not an object");continue
        vid=str(clip.get("video_id") or "").strip();row=con.execute("SELECT local_video,COALESCE(duration_seconds,0) FROM videos WHERE video_id=?",(vid,)).fetchone()
        if not row:errors.append(f"Clip {index}: unknown VIDEO_ID {vid}");continue
        start=_chatgpt_timestamp_seconds(clip.get("start_seconds",clip.get("start_timestamp")));end=_chatgpt_timestamp_seconds(clip.get("end_seconds",clip.get("end_timestamp")))
        if start is None or end is None:errors.append(f"Clip {index}: invalid start/end timestamp");continue
        if start<0 or end<=start:errors.append(f"Clip {index}: end must be greater than start");continue
        duration=float(row[1] or 0)
        if duration and end>duration+2:errors.append(f"Clip {index}: end {end:.1f}s exceeds video duration {duration:.1f}s");continue
        source=str(row[0] or "")
        if not source:errors.append(f"Clip {index}: video has no local media path");continue
        normalized.append({"order":index,"included":bool(clip.get("included",True)),"video_id":vid,"source":source,"start":start,"end":end,"duration":round(end-start,3),"title":str(clip.get("title") or f"Clip {index}")})
    con.close();valid=not errors and len(normalized)==len(clips);out={"ok":valid,"valid":valid,"errors":errors,"clips":normalized,"manual_handoff_only":True}
    if save and valid:
        root=BASE/"data"/"chatgpt"/"exchange"/"review"/"clip_plans";root.mkdir(parents=True,exist_ok=True);path=root/f"clip_plan_{time.strftime('%Y%m%d_%H%M%S')}.json";path.write_text(json.dumps(out,indent=2,ensure_ascii=False),encoding="utf-8");out.update({"saved":str(path),"clip_studio_route":"/app?tab=clips","executed":False})
    return out

def import_validate_many_manual_chatgpt_processing_results(payload):
    """Validate a user-selected set of result files; each remains review-only."""
    items=(payload or {}).get("results") or []
    if not isinstance(items,list) or not items: raise ValueError("Select one or more returned JSON files first.")
    if len(items)>200: raise ValueError("Select no more than 200 JSON files at once.")
    session_folder=Path(str((payload or {}).get("session_folder") or "")).resolve() if (payload or {}).get("session_folder") else chatgpt_new_incoming_session_folder("manual_batch")
    outcomes=[]
    for item in items:
        try:
            payload_item=dict(item or {})
            payload_item["session_folder"]=str(session_folder)
            outcomes.append(import_validate_manual_chatgpt_processing_result(payload_item))
        except Exception as ex: outcomes.append({"ok":False,"filename":str((item or {}).get("filename") or "unknown"),"message":f"{type(ex).__name__}: {ex}"})
    return {"ok":all(x.get("ok") for x in outcomes),"files":len(outcomes),"validated":sum(1 for x in outcomes if x.get("status")=="VALIDATED"),"partial":sum(1 for x in outcomes if x.get("status")=="PARTIAL"),"failed":sum(1 for x in outcomes if not x.get("ok")),"incoming_session_folder":str(session_folder),"outcomes":outcomes,"manual_review_required":True,"applied":False}

def import_validate_manual_chatgpt_processing_zip(payload):
    """Read result.json files from one returned ZIP without extracting arbitrary content."""
    payload=payload or {};filename=Path(str(payload.get("filename") or "returned_results.zip")).name
    encoded=payload.get("zip_base64")
    if not isinstance(encoded,str) or not encoded.strip():raise ValueError("Select a returned ZIP file first.")
    try:raw=base64.b64decode(encoded,validate=True)
    except Exception as ex:raise ValueError(f"Returned ZIP could not be decoded: {ex}")
    if len(raw)>100*1024*1024:raise ValueError("Returned ZIP exceeds the 100 MB safety limit.")
    import io
    try:z=pyzipfile.ZipFile(io.BytesIO(raw),"r")
    except Exception as ex:raise ValueError(f"Returned file is not a valid ZIP: {ex}")
    with z:
        infos=[x for x in z.infolist() if not x.is_dir()]
        if len(infos)>5000:raise ValueError("Returned ZIP contains too many files.")
        total=sum(x.file_size for x in infos)
        if total>250*1024*1024:raise ValueError("Returned ZIP expands beyond the 250 MB safety limit.")
        candidates=[];seen_packages=set();ignored=[]
        for info in infos:
            normalized=info.filename.replace("\\","/")
            if normalized.startswith("/") or "../" in f"/{normalized}":ignored.append(normalized);continue
            if Path(normalized).name.lower() not in {"result.json","chatgpt_result.json"}:continue
            if info.file_size>20*1024*1024:ignored.append(normalized);continue
            try:text=z.read(info).decode("utf-8-sig");data=json.loads(text)
            except Exception:ignored.append(normalized);continue
            package_id=str(data.get("package_id") or "") if isinstance(data,dict) else ""
            if not package_id or package_id in seen_packages:ignored.append(normalized);continue
            seen_packages.add(package_id);candidates.append({"filename":f"{filename}__{Path(normalized).parent.name}_result.json","result_json":text})
        if not candidates:raise ValueError("No valid, uniquely identified result.json files were found in the ZIP.")
        if len(candidates)>200:raise ValueError("Returned ZIP contains more than 200 result packages.")
    result=import_validate_many_manual_chatgpt_processing_results({"results":candidates})
    report_dir=BASE/"data"/"chatgpt"/"exchange"/"incoming"/"bulk_reports";report_dir.mkdir(parents=True,exist_ok=True)
    report=report_dir/f"{safe_name(Path(filename).stem)}_{time.strftime('%Y%m%d_%H%M%S')}_validation.json"
    result.update({"zip_filename":filename,"zip_entries":len(infos),"result_files_found":len(candidates),"ignored_entries":ignored[:100],"bulk_validation_report":str(report),"source_zip_was_extracted":False})
    report.write_text(json.dumps(result,indent=2,ensure_ascii=False),encoding="utf-8")
    return result

def _chatgpt_github_result_candidates(mirror):
    mirror=Path(mirror).resolve()
    candidates=[]
    for prefix in CHATGPT_GITHUB_RESULT_PREFIXES:
        root=(mirror/Path(prefix)).resolve()
        if not root.is_dir():continue
        for path in sorted(root.rglob("*")):
            if not path.is_file():continue
            if path.suffix.lower() not in {".json",".zip"}:continue
            try:rel=path.resolve().relative_to(mirror).as_posix()
            except ValueError:continue
            if "/archive/" in f"/{rel}/":continue
            candidates.append({"path":path,"repo_path":rel})
    return candidates

def _chatgpt_save_github_source_copy(source_path, repo_path):
    local_root=chatgpt_new_incoming_session_folder("github_pull")
    target=(local_root/safe_name(Path(repo_path).name)).resolve()
    try:target.relative_to(local_root.resolve())
    except ValueError:raise ValueError("Unsafe GitHub result path.")
    target.parent.mkdir(parents=True,exist_ok=True)
    if target.exists():target=target.with_name(target.stem+"_"+time.strftime("%Y%m%d_%H%M%S")+target.suffix)
    shutil.copy2(source_path,target)
    return target

def import_validate_chatgpt_results_from_github(options=None):
    """Pull returned ChatGPT result files from the authorized GitHub repo mirror, validate locally, then optionally archive processed repo copies."""
    options=options or {};archive=bool(options.get("archive_processed",True))
    mirror=Path(ensure_chatgpt_github_mirror(pull=True)).resolve()
    try:
        candidates=_chatgpt_github_result_candidates(mirror)
        if not candidates:
            return {"ok":True,"message":"No GitHub result JSON/ZIP files found under exchange/incoming.","files":0,"local_copies":[],"archived":[],"local_clone_removed":True}
        outcomes=[];archivable=[];local_copies=[];session_folder=chatgpt_new_incoming_session_folder("github_pull")
        for item in candidates[:200]:
            path=item["path"];repo_path=item["repo_path"]
            try:
                if path.suffix.lower()==".zip":
                    local_copy=(session_folder/safe_name(Path(repo_path).name)).resolve();shutil.copy2(path,local_copy)
                    outcome=import_validate_manual_chatgpt_processing_zip({"filename":path.name,"zip_base64":base64.b64encode(path.read_bytes()).decode("ascii")})
                else:
                    raw=path.read_text(encoding="utf-8")
                    try:probe=json.loads(raw)
                    except Exception:probe={}
                    if isinstance(probe,dict) and ("transcript_groups" in probe or "no_transcript_groups" in probe) and "video_updates" not in probe:
                        local_copy=(session_folder/safe_name(Path(repo_path).name)).resolve();shutil.copy2(path,local_copy)
                        outcome=import_validate_chatgpt_batch_plan({"result_json":raw})
                    else:
                        outcome=import_validate_manual_chatgpt_processing_result({"filename":path.name,"result_json":raw,"session_folder":str(session_folder)})
                        saved_result=Path(str(outcome.get("result_file") or ""))
                        local_copy=saved_result if saved_result.is_file() else (session_folder/safe_name(Path(repo_path).name)).resolve()
                        if not local_copy.exists():shutil.copy2(path,local_copy)
                if str(local_copy):local_copies.append(str(local_copy))
                outcome["github_repo_path"]=repo_path;outcome["local_source_copy"]=str(local_copy);outcomes.append(outcome)
                if outcome.get("ok"):archivable.append(item)
            except Exception as ex:
                outcomes.append({"ok":False,"github_repo_path":repo_path,"message":f"{type(ex).__name__}: {ex}"})
        archived=[];commit_url=""
        if archive and archivable:
            stamp=time.strftime("%Y%m%d_%H%M%S")
            for item in archivable:
                source=item["path"];repo_path=item["repo_path"]
                destination=(mirror/Path(CHATGPT_GITHUB_ARCHIVE_PREFIX)/stamp/Path(repo_path)).resolve()
                try:destination.relative_to(mirror)
                except ValueError:continue
                destination.parent.mkdir(parents=True,exist_ok=True)
                if destination.exists():destination=destination.with_name(destination.stem+"_"+uuid.uuid4().hex[:6]+destination.suffix)
                shutil.move(str(source),str(destination))
                archived.append({"from":repo_path,"to":destination.relative_to(mirror).as_posix()})
            if archived:
                stage_paths=[p for p in ("exchange/incoming",CHATGPT_GITHUB_ARCHIVE_PREFIX) if (mirror/Path(p)).exists()]
                if stage_paths:_chatgpt_git(["add","--",*stage_paths],mirror)
                if _chatgpt_git(["diff","--cached","--name-only"],mirror):
                    _chatgpt_git(["commit","-m",f"Archive processed VideoHoarder ChatGPT results {stamp}"],mirror)
                    _chatgpt_git(["push","origin",CHATGPT_GITHUB_BRANCH],mirror,300)
                    sha=_chatgpt_git(["rev-parse","HEAD"],mirror)
                    commit_url=f"{CHATGPT_GITHUB_WEB_URL}/commit/{sha}"
        return {"ok":all(x.get("ok") for x in outcomes),"files":len(outcomes),"validated":sum(1 for x in outcomes if x.get("status")=="VALIDATED" or x.get("valid") is True),"failed":sum(1 for x in outcomes if not x.get("ok")),"incoming_session_folder":str(session_folder),"outcomes":outcomes,"local_copies":local_copies,"archived":archived,"archive_commit_url":commit_url,"local_clone_removed":True,"message":"GitHub result files were copied locally, validated, and successful files were archived in the GitHub repository."}
    finally:
        shutil.rmtree(mirror.parent,ignore_errors=True)

def export_chatgpt_processing_review_csv():
    """Create one local, review-only CSV from validated/partial imported result previews."""
    import csv
    review_dir=BASE/"data"/"chatgpt"/"exchange"/"review";review_dir.mkdir(parents=True,exist_ok=True)
    out_dir=BASE/"data"/"chatgpt"/"exchange"/"exports";out_dir.mkdir(parents=True,exist_ok=True)
    rows=[]
    for preview_path in sorted(review_dir.glob("*_review.json")):
        try: preview=json.loads(preview_path.read_text(encoding="utf-8"))
        except Exception: continue
        if preview.get("status") not in {"VALIDATED","PARTIAL"}: continue
        for item in preview.get("proposed_updates") or []:
            if not isinstance(item,dict): continue
            video_id=str(item.get("video_id") or "")
            features=item.get("features") if isinstance(item.get("features"),dict) else {k:v for k,v in item.items() if k in CHATGPT_FEATURES}
            for feature_id,value in (features or {}).items():
                rows.append({"package_id":preview.get("package_id",""),"request_id":preview.get("request_id",""),"validation_status":preview.get("status",""),"video_id":video_id,"feature_id":feature_id,"evidence_references":json.dumps(item.get("evidence_references") or item.get("evidence") or [],ensure_ascii=False),"proposed_value_json":json.dumps(value,ensure_ascii=False),"review_preview":str(preview_path),"applied":"NO"})
    out=out_dir/f"chatgpt_review_combined_{time.strftime('%Y%m%d_%H%M%S')}.csv"
    fields=["package_id","request_id","validation_status","video_id","feature_id","evidence_references","proposed_value_json","review_preview","applied"]
    with out.open("w",encoding="utf-8-sig",newline="") as f:
        writer=csv.DictWriter(f,fieldnames=fields);writer.writeheader();writer.writerows(rows)
    return {"ok":True,"csv":str(out),"rows":len(rows),"manual_review_only":True,"applied":False}

def chatgpt_processing_unprocessed_packages():
    """Only packages with no returned/imported result may be removed from local exchange storage."""
    con=db_connect();rows=con.execute("SELECT package_id,created_at,mode,requested_features_json FROM chatgpt_requests WHERE status='AWAITING_RESULT' AND COALESCE(result_path,'')='' ORDER BY created_at DESC").fetchall();con.close()
    out=[]
    for package_id,created_at,mode,features_json in rows:
        folder=chatgpt_outgoing_package_folder(package_id)
        out.append({"package_id":package_id,"created_at":created_at,"mode":mode,"features":json.loads(features_json or '[]'),"folder":str(folder),"folder_exists":folder.is_dir()})
    return out

def delete_unprocessed_chatgpt_packages(package_ids):
    """Remove only locally-created, unprocessed package folders; retain a deletion audit row."""
    package_ids=[str(x).strip() for x in (package_ids or []) if str(x).strip()]
    if not package_ids: raise ValueError("Select at least one unprocessed package.")
    if len(package_ids)>200: raise ValueError("Select no more than 200 packages at once.")
    con=db_connect();deleted=[];skipped=[]
    for package_id in package_ids:
        row=con.execute("SELECT status,result_path FROM chatgpt_requests WHERE package_id=?",(package_id,)).fetchone()
        if not row or row[0]!="AWAITING_RESULT" or str(row[1] or ""):
            skipped.append({"package_id":package_id,"reason":"Only packages awaiting a result and never imported can be deleted."});continue
        folder=chatgpt_outgoing_package_folder(package_id)
        if folder.is_dir(): shutil.rmtree(folder)
        con.execute("UPDATE chatgpt_requests SET status='DELETED',notes=? WHERE package_id=?",(f"Outgoing package removed locally at {time.strftime('%Y-%m-%d %H:%M:%S')}",package_id))
        con.execute("DELETE FROM video_feature_coverage WHERE package_id=? AND status='REQUESTED'",(package_id,))
        deleted.append(package_id)
    con.commit();con.close()
    return {"ok":not skipped,"deleted":deleted,"skipped":skipped,"message":"Only local unprocessed package folders were removed; processed/imported packages were retained."}

def reset_chatgpt_package_history(confirm_text):
    """Reset ChatGPT dashboard history/coverage without deleting packages or applied intelligence."""
    if str(confirm_text or "").strip() != "RESET PACKAGE HISTORY":
        raise ValueError("Type RESET PACKAGE HISTORY exactly to reset the history.")
    con=db_connect()
    request_count=con.execute("SELECT COUNT(*) FROM chatgpt_requests").fetchone()[0]
    video_count=con.execute("SELECT COUNT(*) FROM chatgpt_request_videos").fetchone()[0]
    coverage_count=con.execute("SELECT COUNT(*) FROM video_feature_coverage").fetchone()[0]
    audit_dir=BASE/"data"/"chatgpt"/"exchange"/"audit";audit_dir.mkdir(parents=True,exist_ok=True)
    audit={"action":"reset_package_history","at":time.strftime("%Y-%m-%d %H:%M:%S"),"requests":request_count,"request_videos":video_count,"feature_coverage":coverage_count,"kept":"outgoing folders, imported result files and applied video intelligence"}
    (audit_dir/f"package_history_reset_{time.strftime('%Y%m%d_%H%M%S')}.json").write_text(json.dumps(audit,indent=2),encoding="utf-8")
    con.execute("DELETE FROM chatgpt_request_videos")
    con.execute("DELETE FROM chatgpt_requests")
    con.execute("DELETE FROM video_feature_coverage")
    con.commit();con.close()
    return {"ok":True,"message":"Request History, Feature Coverage and Overview package counters were reset. Outgoing folders, imported results and applied intelligence were kept.","audit":audit}

def library_exports_dir():
    root=BASE/"data"/"library"
    for child in ["csv","html","html/channels"]:
        (root/child).mkdir(parents=True,exist_ok=True)
    return root

def library_safe_filename(value,fallback="channel"):
    text=str(value or "").strip() or fallback
    text=re.sub(r"[\\/:*?\"<>|]+","_",text)
    text=re.sub(r"\s+"," ",text).strip(" ._")
    return (text[:120] or fallback)

def rebuild_database_and_library_exports():
    """Reconcile the physical library and rebuild active/missing-local reports. Deleted videos are not surfaced."""
    set_state(phase="Library rebuild",current_status="Reconciling physical library",current_percent="5%")
    reconciliation=reconcile_active_library_state()
    set_state(phase="Library rebuild",current_status="Refreshing main video CSV",current_percent="10%")
    csv_path=export_csv()
    try:
        title_csv=export_csv_with_chatgpt_titles()
    except Exception:
        title_csv=""
    root=library_exports_dir();csv_dir=root/"csv";html_dir=root/"html"
    con=db_connect()
    total=con.execute("SELECT COUNT(*) FROM videos").fetchone()[0]
    active=con.execute("SELECT COUNT(*) FROM videos WHERE COALESCE(archived,0)=0 AND COALESCE(current_present,1)=1").fetchone()[0]
    archived=con.execute("SELECT COUNT(*) FROM videos WHERE COALESCE(archived,0)=1").fetchone()[0]
    downloaded=con.execute("SELECT COUNT(*) FROM videos WHERE COALESCE(downloaded,0)=1 AND COALESCE(current_present,1)=1").fetchone()[0]
    pending_delete=0
    try:
        pending_delete=sum(1 for p in delete_queue_dir().glob("*.delete.json"))
    except Exception:
        pending_delete=0
    video_rows=con.execute("SELECT video_id,original_title,clean_title,channel,upload_date,category,subcategory,downloaded,archived,local_folder,local_video,report_html,url,thumbnail_url FROM videos ORDER BY COALESCE(upload_date,'' ) DESC, rowid DESC").fetchall()
    sub_cols={r[1] for r in con.execute("PRAGMA table_info(youtube_subscriptions)").fetchall()}
    sub_thumb_expr="COALESCE(thumbnail_url,'')" if "thumbnail_url" in sub_cols else "''"
    sub_rows=con.execute(f"SELECT channel_key,handle,title,url,{sub_thumb_expr},description,subscriber_text,video_count_text,dominant_category,selected_for_scan,source,collected_at FROM youtube_subscriptions ORDER BY dominant_category,title").fetchall()
    con.close()
