        body.extend(f"<th>{html.escape(str(h))}</th>" for h in headers);body.append("</tr></thead><tbody>")
        for row in rows:
            body.append("<tr>");body.extend(f"<td>{html.escape(str(x or ''))}</td>" for x in row);body.append("</tr>")
