        body.append(f"<div class='top'><a href='../channels_index.html'>← All channels</a><h1>{html.escape(channel_name)}</h1><p><span class='pill'>{len(rows)} available downloaded videos</span><span class='pill'>Generated {html.escape(counts['rebuilt_at'])}</span></p></div><div class='grid'>")
        for r in rows:
            vid,actual_title,clean,channel,upload_date,category,subcategory,downloaded_flag,archived_flag,local_folder,local_video,report_html,youtube_url,thumb,folder_exists,video_exists,local_available=r
