def retry_failed_chatgpt_packages(options=None):
    """Create fresh upload files only for packages whose returned result failed validation."""
    options=options or {};requested_ids={str(x) for x in options.get("package_ids") or [] if str(x)}
    con=db_connect();rows=con.execute("SELECT package_id,mode,requested_features_json,manifest_json,status FROM chatgpt_requests WHERE status IN ('INVALID','PARTIAL','FAILED') ORDER BY created_at").fetchall();con.close()
    retried=[]
    for old_package_id,mode,features_json,manifest_json,status in rows:
        if requested_ids and str(old_package_id) not in requested_ids:continue
        manifest=json.loads(manifest_json or "{}");video_ids=manifest.get("video_ids") or []
        active=set(active_library_video_ids(refresh=True));video_ids=[str(v) for v in video_ids if str(v) in active]
        if not video_ids:continue
        created=create_manual_chatgpt_processing_package({"mode":mode,"video_ids":"\n".join(video_ids),"features":json.loads(features_json or "[]"),"verify_transcript_availability":False,"package_parent":str(BASE/"data"/"chatgpt"/"exchange"/"outgoing"/"retry_failed")})
        retried.append({"previous_package_id":old_package_id,"previous_status":status,"new_package_id":created["package_id"],"upload_file":created.get("upload_file"),"folder":created["folder"]})
    return {"ok":True,"retried":len(retried),"packages":retried,"message":"Created fresh packages for failed/partial results only."}


