def _move_preview_signature(obj):
    sig=[]
    for x in (obj or {}).get('items') or []:
        sig.append((str(x.get('video_id') or ''),str(x.get('category') or ''),str(x.get('source') or ''),str(x.get('target') or ''),str(x.get('status') or '')))
    return sorted(sig)


def apply_chatgpt_updates_and_organization_moves():
    title="APPLY CHATGPT UPDATES & ORGANIZATION MOVES"
    p=phase6_move_preview_path()
    if not p.exists():
        print("No reviewed move preview exists. Run Refresh Organization Move Preview first.")
        return {"ok":False,"status":"ACTION REQUIRED","message":"Run Refresh Organization Move Preview first."}
    try: old=json.loads(p.read_text(encoding='utf-8'))
    except Exception as ex:return {"ok":False,"status":"ACTION REQUIRED","message":f"Move preview unreadable: {ex}"}
    steps=[]
    records=phase6_load_intelligence()
    steps.append(_combined_step("Reapply ChatGPT Video Updates",1,3,phase6_apply_chatgpt_video_updates,records,False))
    refreshed=phase6_preview_category_moves(records)
    same=_move_preview_signature(old)==_move_preview_signature(refreshed)
    print("[2/3] Refresh/verify move preview after reapplying updates")
    print("Preview unchanged: "+("YES" if same else "NO"))
    steps.append({"name":"Verify Move Preview","ok":same,"result":web_json_safe(refreshed)})
    if not same:
        print("Move preview changed. Review the refreshed preview, then run Apply again.")
        return _combined_finish(title,steps,{"preview_changed":True,"preview":web_json_safe(refreshed)})
    steps.append(_combined_step("Apply Organization Moves",3,3,phase6_apply_previewed_moves))
    return _combined_finish(title,steps)


