def clean_temporary_resolved_empty_files_folders():
    title="CLEAN TEMPORARY, RESOLVED & EMPTY FILES/FOLDERS"
    # Clean All Empty Folders already includes Clean Empty Staging and
    # Remove Empty Legacy ChatGPT Folders; do not run those subroutines twice.
    funcs=[
        ("Classify Old tmp",cleanup_old_temp_transcripts,()),
        ("Clean Resolved tmp",cleanup_resolved_tmp_remnants,()),
        ("Clean All Empty Folders",cleanup_all_empty_folders,()),
    ]
    steps=[_combined_step(n,i,len(funcs),f,*a) for i,(n,f,a) in enumerate(funcs,1)]
    return _combined_finish(title,steps)


def knowledge_ai_interactive_menu():
    while True:
        print("""
============================================================
 KNOWLEDGE & AI — BUILD, VERIFY, ASK & FIND
============================================================
1 = Rebuild & Verify Knowledge + AI
2 = Ask Local AI
3 = Find Timestamp
4 = Open Knowledge Center
0 = Back
""")
        c=input("Choose: ").strip()
        if c=='1': knowledge_ai_build_verify_refresh()
        elif c=='2':
            q=input("Question: ").strip()
            if q:
                mode=input("Mode [fast/deep]: ").strip().lower() or 'fast'
                r=phase6_ollama_generate(q,mode=mode if mode in {'fast','deep'} else 'fast',use_cache=True)
                print(r.get('answer') or r.get('message') or r)
        elif c=='3':
            vid=input("VIDEO_ID: ").strip();q=input("Topic / phrase: ").strip()
            hit=phase5_find_timestamp(vid,q)
            print(hit or "No timestamped match found.")
        elif c=='4': open_phase5_dashboard_server()
        elif c=='0': break
