def dashboard_help_index():
    """Return central command help keyed by command/action identifier."""
    out={}
    for group in help_command_groups_with_ui():
        for key,name,what,changes,when in group.get("items",[]):
            out[str(key)]={
                "key":str(key),
                "stage":str(group.get("stage") or ""),
                "group":str(group.get("title") or ""),
                "name":str(name),
                "what":str(what),
                "changes":str(changes),
                "when":str(when),
            }
    return out


def help_command_target(key):
    """Safe Help-page navigation target; never executes the command directly."""
    key=str(key or "").strip()
    direct={
        "control_tower":"/","knowledge_center":"/knowledge","help_page":"/help",
        "nav_home":"/app?tab=home","nav_downloads":"/app?tab=downloads",
        "nav_library":"/app?tab=library","nav_status":"/app?tab=status",
        "nav_chatgpt":"/app?tab=chatgpt","nav_collections":"/app?tab=collections",
        "nav_intelligence":"/app?tab=intelligence","nav_health":"/app?tab=health",
        "nav_diagnostics":"/app?tab=diagnostics","nav_tools":"/app?tab=tools",
        "nav_clips":"/app?tab=clips","nav_external":"/app?tab=external",
        "nav_subscriptions":"/app?tab=subscriptions",
    }
    if key in direct:return direct[key]
    tab_by_key={
        "open_config":"tools","config_save":"tools","config_reload":"tools","open_urls":"tools","open_apikey":"tools","portable_dependencies":"tools",
        "selenium_diagnostic":"subscriptions","selenium_setup":"subscriptions","subscriptions_collect":"subscriptions","subscriptions_refresh":"subscriptions",
        "metadata_scan":"downloads","full_download":"downloads","media_only":"downloads","smart_resume_master":"downloads",
        "job_pause":"downloads","job_resume":"downloads","job_cancel":"downloads","job_retry":"downloads","view_queue":"downloads",
        "external_media":"external","external_refresh":"external",
        "library_health_path_audit":"tools","original_title_integrity":"tools","migrate_modernize_library":"tools",
        "repair_refresh_library_core":"tools","quarantine_zero_byte":"tools","open_folders":"tools","process_delete_markers":"tools",
        "phase2_legacy_sync":"chatgpt","phase2_package_audit":"chatgpt","comment_intelligence":"chatgpt",
        "chatgpt_create_packages_cleanup":"chatgpt","chatgpt_workspace":"chatgpt","exchange_stage":"chatgpt",
        "chatgpt_import_validate_extract":"chatgpt","taxonomy_preview":"chatgpt","chatgpt_apply_updates_moves":"chatgpt",
        "taxonomy_undo":"chatgpt","taxonomy_audit":"chatgpt","phase4_export":"chatgpt","open_chatgpt_web":"chatgpt","exchange_refresh":"chatgpt",
        "knowledge_ai_workspace":"intelligence",
        "library_search":"library","video_details":"library","video_state":"library","repair_reports_links":"library",
        "rebuild_reports":"library","export_csv":"library","export_chatgpt_titles_csv":"library","video_play":"library",
        "report_open":"library","clip_add_from_library":"library","delete_marker":"library",
        "collection_manage":"collections","collection_export":"collections","collection_rename":"collections","collection_delete":"collections",
        "system_health_backup_repair":"health","recovery_db":"diagnostics","recover_rebuild_all":"diagnostics",
        "repair_clean_failure_history":"status","clean_temp_resolved_empty":"status",
        "merge_clips":"clips","clip_add_row":"clips","clip_remove_row":"clips","clip_refresh":"clips",
        "stop_everything":"home",
    }
    tab=tab_by_key.get(key,"tools")
    return "/app?tab="+urllib.parse.quote(tab)+"&command="+urllib.parse.quote(key)

def help_page_html():
    groups=help_command_groups_with_ui()
    command_count=sum(len(g["items"]) for g in groups)

    def impact_class(value):
        v=str(value).lower()
        if "destructive" in v:
            return "danger"
        if v.startswith("no") or "read-only" in v or "diagnostic only" in v or "audit only" in v:
            return "readonly"
        if "navigation only" in v:
            return "readonly"
        if "empty" in v and ("remove" in v or "deletes" in v):
            return "caution"
        return "write"

    sections=[]
    for g in groups:
        rows=[]
        for key,name,what,changes,when in g["items"]:
            rows.append(
                '<tr id="cmd-'+html.escape(key,quote=True)+'" class="cmdrow" data-key="'+html.escape(key)+'" '
                'data-search="'+html.escape(" ".join([g["title"],name,what,changes,when]).lower(),quote=True)+'">'
                '<td class="cmd"><a class="cmdlink" href="'+html.escape(help_command_target(key),quote=True)+'"><b>'+html.escape(name)+'</b></a><div class="key">'+html.escape(key)+'</div></td>'
                '<td>'+html.escape(what)+'</td>'
                '<td><span class="impact '+impact_class(changes)+'">'+html.escape(changes)+'</span></td>'
                '<td>'+html.escape(when)+'</td>'
                '</tr>'
            )
        sections.append(
            '<section class="flowsec" data-stage="'+html.escape(g["stage"])+'">'
            '<div class="stagehead"><div class="stagebubble">'+html.escape(g["stage"])+'</div>'
            '<div><h2>'+html.escape(g["title"])+'</h2><p>'+html.escape(g["why"])+'</p></div></div>'
            '<div class="tablewrap"><table><thead><tr>'
            '<th style="width:20%">Command</th><th style="width:34%">What it actually does</th>'
            '<th style="width:20%">Changes files/data?</th><th style="width:26%">When you need it</th>'
            '</tr></thead><tbody>'+''.join(rows)+'</tbody></table></div></section>'
        )

    stage_chips="".join(
        '<a href="#stage-'+html.escape(g["stage"])+'" onclick="jumpStage(event,\''+html.escape(g["stage"])+'\')">'
        +html.escape(g["stage"])+". "+html.escape(g["title"])+'</a>'
        for g in groups
    )

    return """<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Video Library Manager — Help / Command Guide</title>
<style>
:root{--bg:#f4f7fb;--panel:#fff;--text:#122b52;--muted:#647a9b;--line:#dce6f2;--blue:#086cf0;--navy:#071f47;--green:#087b3d;--orange:#9a6400;--red:#a82c2c;--shadow:0 8px 24px rgba(26,55,96,.08)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);font:14px/1.45 "Segoe UI",Arial,sans-serif;color:var(--text)}
.top{position:sticky;top:0;z-index:20;background:rgba(244,247,251,.96);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.topin{max-width:1500px;margin:auto;padding:12px 18px;display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.logo{width:42px;height:42px;border-radius:11px;background:linear-gradient(145deg,#0a397d,#061c3f);display:grid;place-items:center;color:#fff;font-size:20px;font-weight:900}
.title h1{font-size:20px;margin:0}.title p{margin:2px 0 0;color:var(--muted);font-size:12px}
.actions{margin-left:auto;display:flex;gap:7px}.btn{display:inline-block;border:1px solid #bfd0e7;background:#fff;color:var(--text);padding:8px 11px;border-radius:8px;text-decoration:none;font-weight:700}.btn.primary{background:var(--blue);border-color:var(--blue);color:#fff}
.wrap{max-width:1500px;margin:auto;padding:18px}
.hero{background:linear-gradient(120deg,#071f47,#0871f5);color:#fff;border-radius:16px;padding:20px 22px;box-shadow:var(--shadow)}
.hero h2{margin:0 0 5px;font-size:25px}.hero p{margin:0;color:#dbeaff}.hero .count{margin-top:10px;font-weight:800}
.toolbar{display:grid;grid-template-columns:minmax(280px,1fr) auto auto;gap:8px;margin:14px 0;position:sticky;top:68px;z-index:15;background:var(--bg);padding:8px 0}
input,select{width:100%;border:1px solid #bdcde0;border-radius:9px;background:#fff;padding:10px 12px;color:var(--text)}
.chips{display:flex;gap:6px;overflow:auto;padding:2px 0 12px}.chips a{white-space:nowrap;text-decoration:none;border:1px solid var(--line);background:#fff;padding:7px 9px;border-radius:999px;color:#24466f;font-size:11px;font-weight:700}
.flowsec{scroll-margin-top:145px;margin:0 0 18px}.stagehead{display:flex;align-items:flex-start;gap:11px;margin:12px 0 7px}.stagebubble{width:36px;height:36px;border-radius:50%;background:#0b6df0;color:white;display:grid;place-items:center;font-weight:900;flex:none}.stagehead h2{font-size:18px;margin:0}.stagehead p{margin:2px 0 0;color:var(--muted)}
.tablewrap{border:1px solid var(--line);border-radius:12px;background:#fff;overflow:auto;box-shadow:var(--shadow)}
table{width:100%;border-collapse:collapse;min-width:980px}th,td{padding:10px 11px;border-bottom:1px solid #e7eef6;text-align:left;vertical-align:top}th{background:#f7faff;color:#24466f;font-size:11px;position:sticky;top:0}tr:last-child td{border-bottom:0}tr:hover td{background:#fbfdff}
.cmd b{font-size:13px}.cmdlink{color:#0a5fd2;text-decoration:none;display:inline-flex;align-items:center;gap:5px}.cmdlink:hover{text-decoration:underline;color:#004cae}.cmdlink:after{content:'↗';font-size:10px;opacity:.65}.key{font:10px/1.3 Consolas,monospace;color:#8a9ab1;margin-top:3px}
.impact{display:inline-block;border-radius:8px;padding:5px 7px;font-size:11px;font-weight:700}.impact.readonly{background:#ebf8ef;color:#08713a}.impact.write{background:#edf4ff;color:#145eb8}.impact.caution{background:#fff5df;color:#7d5900}.impact.danger{background:#fff0f0;color:#a12626}
.hidden{display:none!important}.noresults{display:none;background:#fff;border:1px solid var(--line);border-radius:12px;padding:30px;text-align:center;color:var(--muted)}
.note{margin:14px 0;background:#fff;border-left:4px solid #0b6df0;border-radius:8px;padding:11px 13px;color:#405b7e}.cmdrow.vlmTarget td{background:#fff8d9!important;box-shadow:inset 0 1px #f2d05c,inset 0 -1px #f2d05c}
@media(max-width:800px){.actions{margin-left:0}.toolbar{grid-template-columns:1fr;top:104px}.hero h2{font-size:21px}.wrap{padding:12px}}
@media print{.top,.toolbar,.chips,.actions{display:none!important}.wrap{max-width:none}.flowsec{break-inside:avoid}.tablewrap{box-shadow:none}}
</style>
</head>
<body>
<div class="top"><div class="topin">
  <div class="logo">?</div>
  <div class="title"><h1>Help / Command Guide</h1><p>Video Library Manager · Version """+html.escape(APP_VERSION)+"""</p></div>
  <div class="actions"><a class="btn" href="/">Control Tower</a><a class="btn primary" href="/app">App Workspace</a></div>
</div></div>

<div class="wrap">
  <div class="hero">
    <h2>Every command, in the order the app normally flows</h2>
    <p>Use this page to understand what a command changes before you run it. Click any command name to open its correct App Workspace tab and highlight the command. Help-page clicks do not execute commands automatically.</p>
    <div class="count"><span id="visibleCount">"""+str(command_count)+"""</span> of """+str(command_count)+""" documented commands shown</div>
  </div>

  <div class="note"><b>Flow:</b> Setup → Download → Library structure → ChatGPT → Knowledge/AI → Library use → Health/Recovery → Failure cleanup → Delete → Specialist tools/queue.</div>

  <div class="toolbar">
    <input id="search" placeholder="Search commands, e.g. report, Smart Resume, ChatGPT, delete..." oninput="filterRows()">
    <select id="impactFilter" onchange="filterRows()">
      <option value="">All impact types</option>
      <option value="readonly">Read-only / diagnostic</option>
      <option value="write">Writes or updates data</option>
      <option value="caution">Cleanup / empty-folder removal</option>
      <option value="danger">Destructive</option>
    </select>
    <button class="btn" onclick="window.print()">Print / Save PDF</button>
  </div>

  <div class="chips">"""+stage_chips+"""</div>
  <div id="noresults" class="noresults">No commands match your search/filter.</div>
  <div id="sections">"""+''.join(
      s.replace('<section class="flowsec" data-stage="',
                '<section id="stage-'+re.search(r'data-stage="([^"]+)"',s).group(1)+'" class="flowsec" data-stage="',1)
      for s in sections
  )+"""</div>
</div>

<script>
function filterRows(){
  const q=(document.getElementById('search').value||'').trim().toLowerCase();
  const impact=document.getElementById('impactFilter').value;
  let visible=0;
  document.querySelectorAll('.flowsec').forEach(sec=>{
    let secVisible=0;
    sec.querySelectorAll('.cmdrow').forEach(row=>{
      const txt=(row.dataset.search||'');
      const badge=row.querySelector('.impact');
      const impactOk=!impact || (badge && badge.classList.contains(impact));
      const ok=(!q || txt.includes(q)) && impactOk;
      row.classList.toggle('hidden',!ok);
      if(ok){visible++;secVisible++;}
    });
    sec.classList.toggle('hidden',secVisible===0);
  });
  document.getElementById('visibleCount').textContent=visible;
  document.getElementById('noresults').style.display=visible?'none':'block';
}
function jumpStage(e,n){
  e.preventDefault();
  const el=document.getElementById('stage-'+n);
  if(el)el.scrollIntoView({behavior:'smooth',block:'start'});
}

function focusHashCommand(){
  const h=decodeURIComponent((location.hash||'').replace(/^#/,''));
  if(!h.startsWith('cmd-'))return;
  const el=document.getElementById(h);
  if(!el)return;
  document.querySelectorAll('.cmdrow.vlmTarget').forEach(x=>x.classList.remove('vlmTarget'));
  el.classList.add('vlmTarget');
  setTimeout(()=>el.scrollIntoView({behavior:'smooth',block:'center'}),50);
}
window.addEventListener('hashchange',focusHashCommand);
setTimeout(focusHashCommand,80);

</script>
</body></html>"""


