def resolve_video_report_path(video_id):
    vid=str(video_id or "").strip()
    if not vid:return None
    stored="";folder=""
    try:
        con=db_connect();cols=video_table_columns()
        wanted=[c for c in ["report_html","local_folder"] if c in cols]
        row=con.execute("SELECT "+",".join(f'"{c}"' for c in wanted)+" FROM videos WHERE video_id=?",(vid,)).fetchone() if wanted else None
        con.close()
        if row:
            d=dict(zip(wanted,row))
            stored=str(d.get("report_html") or "").strip()
            folder=str(d.get("local_folder") or "").strip()
    except Exception:pass
    if stored:
        try:
            p=Path(stored)
            if p.is_file():return p
        except Exception:pass
    if folder:
        try:
            fp=Path(folder)
            if fp.is_dir():
                candidates=sorted([p for p in fp.glob("*.report.html") if p.is_file()],key=lambda p:(vid not in p.name,len(p.name)))
                if candidates:
                    p=candidates[0]
                    try:
                        con=db_connect()
                        if "report_html" in video_table_columns():
                            con.execute("UPDATE videos SET report_html=? WHERE video_id=?",(str(p),vid));con.commit()
                        con.close()
                    except Exception:pass
                    return p
        except Exception:pass
    try:
        candidates=[p for p in DOWNLOADS.rglob("*.report.html") if vid in p.name or vid in str(p.parent)]
        if candidates:
            candidates.sort(key=lambda p:(len(p.parts),len(str(p))))
            return candidates[0]
    except Exception:pass
    return None

def resolve_video_media_path(video_id):
    vid=str(video_id or "").strip()
    if not vid:return None
    folder=""
    try:
        con=db_connect();cols=video_table_columns()
        wanted=[c for c in ["local_video","local_folder"] if c in cols]
        row=con.execute("SELECT "+",".join(f'"{c}"' for c in wanted)+" FROM videos WHERE video_id=?",(vid,)).fetchone() if wanted else None
        con.close()
        if row:
            d=dict(zip(wanted,row))
            raw=str(d.get("local_video") or "").strip()
            folder=str(d.get("local_folder") or "").strip()
            if raw:
                p=Path(raw)
                if p.is_file():return p
    except Exception:pass
    exts={".mp4",".mkv",".webm",".m4v",".mov",".avi",".mp3",".m4a",".aac",".opus"}
    if folder:
        try:
            fp=Path(folder)
            if fp.is_dir():
                files=[p for p in fp.iterdir() if p.is_file() and p.suffix.lower() in exts]
                files.sort(key=lambda p:(vid not in p.name,p.name.lower()))
                if files:return files[0]
        except Exception:pass
    return None

def video_view_html(video_id,start_seconds=0):
    vid=str(video_id or "").strip()
    try:seconds=max(0,int(float(start_seconds or 0)))
    except Exception:seconds=0
    con=db_connect();cols=video_table_columns()
    wanted=[c for c in ["original_title","clean_title","channel","url","category","subcategory"] if c in cols]
    row=con.execute("SELECT "+",".join(f'"{c}"' for c in wanted)+" FROM videos WHERE video_id=?",(vid,)).fetchone() if wanted else None
    con.close()
    if not row:return None
    d=dict(zip(wanted,row))
    title=str(d.get("clean_title") or d.get("original_title") or vid)
    channel=str(d.get("channel") or "")
    report=resolve_video_report_path(vid)
    media=resolve_video_media_path(vid)

    if report and report.is_file():
        doc=report.read_text(encoding="utf-8",errors="replace")
        media_url="/media/"+urllib.parse.quote(vid)
        # Patch both single-quoted and double-quoted source/video src attributes.
        doc=re.sub(
            r'(<(?:source|video)\b[^>]*\bsrc\s*=\s*)(["\'])([^"\']*)(["\'])',
            lambda m:m.group(1)+m.group(2)+media_url+m.group(4),
            doc,count=2,flags=re.I
        )
        toolbar=(
            "<div style=\"position:sticky;top:0;z-index:99999;background:#071a39;color:white;"
            "padding:8px 12px;font-family:Segoe UI,Arial;display:flex;gap:8px;align-items:center\">"
            "<a href=\"/knowledge\" style=\"color:white\">← Knowledge Center</a>"
            "<a href=\"/\" style=\"color:white\">Main Dashboard</a>"
            +(f"<a href=\"{media_url}\" target=\"_blank\" style=\"color:white\">Open Local Video</a>" if media else "")
            +"</div>"
        )
        doc=re.sub(r'(<body[^>]*>)',lambda m:m.group(1)+toolbar,doc,count=1,flags=re.I) if re.search(r'<body[^>]*>',doc,re.I) else toolbar+doc
        jump=f"""<script>window.addEventListener('DOMContentLoaded',()=>{{const v=document.querySelector('video');if(v){{const go=()=>{{try{{v.currentTime={seconds};}}catch(e){{}}}};if(v.readyState>=1)go();else v.addEventListener('loadedmetadata',go,{{once:true}});}}}});</script>"""
        return doc.replace("</body>",jump+"</body>",1) if "</body>" in doc else doc+jump

    if media and media.is_file():
        qvid=urllib.parse.quote(vid)
        return f"""<!doctype html><html><head><meta charset="utf-8"><title>{html.escape(title)}</title>
<style>body{{margin:0;background:#0b1220;color:#eef4ff;font-family:Segoe UI,Arial;padding:18px}}.top{{max-width:1200px;margin:auto}}video{{width:100%;max-height:78vh;background:#000;border-radius:12px}}a{{color:#fff;background:#245fc5;border-radius:8px;padding:9px 12px;text-decoration:none;display:inline-block}}.muted{{color:#aab9cf}}</style></head>
<body><div class="top"><h2>{html.escape(title)}</h2><div class="muted">{html.escape(channel)} · VIDEO_ID {html.escape(vid)}</div><p><a href="/knowledge">← Back to Knowledge Center</a></p><video id="v" controls autoplay src="/media/{qvid}"></video></div>
<script>const v=document.getElementById('v');v.addEventListener('loadedmetadata',()=>{{try{{v.currentTime={seconds};}}catch(e){{}}}},{{once:true}});</script></body></html>"""

    original=str(d.get("url") or "")
    source=(f'<p><a target="_blank" href="{html.escape(original,quote=True)}">Open original source</a></p>' if original else "")
    return f"""<!doctype html><html><head><meta charset="utf-8"><title>{html.escape(title)}</title></head><body style="font-family:Segoe UI,Arial;padding:24px"><h2>{html.escape(title)}</h2><p>Local report and media are not currently available for this VIDEO_ID.</p>{source}<p><a href="/knowledge">← Back to Knowledge Center</a></p></body></html>"""


def full_app_diagnostics():
    checks=[]
    def add(name,status,detail="",fix=""):
        checks.append({"name":name,"status":status,"detail":str(detail or ""),"fix":str(fix or "")})
    add("Library Root","PASS" if BASE.exists() else "FAIL",f"{BASE} | source={BASE_RESOLUTION.get('source','')}",
        "If this is the wrong folder, create library_root.txt beside START.bat with the correct library path.")
    try:
        con=db_connect();rows=int(con.execute("SELECT COUNT(*) FROM videos").fetchone()[0] or 0);con.close()
        add("SQLite Database","PASS",f"{DB} | videos={rows}")
    except Exception as ex:
        rows=0;add("SQLite Database","FAIL",f"{type(ex).__name__}: {ex}")
    try:
        # The portable edition keeps its application data in BASE and the
        # user-visible media collection beside the executable in DOWNLOADS.
        media=_root_media_sample_count(DOWNLOADS,limit=10000)
        add("Downloaded Media","PASS" if media or rows==0 else "WARN",f"media={media} | {DOWNLOADS}")
    except Exception as ex:add("Downloaded Media","FAIL",f"{type(ex).__name__}: {ex}")
    try:
        td=BASE/"maintenance"/"diagnostics";td.mkdir(parents=True,exist_ok=True);p=td/"write.tmp";p.write_text("ok");p.unlink()
        add("Write Access","PASS",td)
    except Exception as ex:add("Write Access","FAIL",f"{type(ex).__name__}: {ex}")
    for label,p in [("yt-dlp",YTDLP),("FFmpeg",FFMPEG),("FFprobe",FFPROBE),("Deno",DENO)]:
        add(label,"PASS" if Path(p).is_file() else "WARN",p,
            "" if Path(p).is_file() else "Tools → Install Missing Portable Core Tools")
    try:
        pdocs=phase5_load_search_index();pids={str(d.get("video_id") or "") for d in pdocs}
        con=db_connect();vids={str(r[0]) for r in con.execute("SELECT video_id FROM videos WHERE COALESCE(current_present,1)=1 AND COALESCE(deleted_from_library,0)=0").fetchall()};con.close()
        stale=len([x for x in pids if x and x not in vids]);missing=len([x for x in vids if x and x not in pids])
        add("Knowledge Center","PASS" if stale==0 and missing==0 else "WARN",
            f"DB={len(vids)} Phase5={len(pids)} stale={stale} not_enriched={missing}",
            "Knowledge Center still shows DB videos; Build Phase 5 to refresh enrichment.")
    except Exception as ex:add("Knowledge Center","FAIL",f"{type(ex).__name__}: {ex}")
    for b in ["firefox","chrome","edge"]:
        try:
            d=selenium_diagnostic(b)
            add(f"Selenium {b.title()}","PASS" if d.get("ready") else "WARN",
                f"{d.get('message')} | browser={d.get('browser_executable') or 'missing'} | profile={d.get('profile_path') or 'missing'} | driver={d.get('driver_mode')}")
        except Exception as ex:add(f"Selenium {b.title()}","WARN",f"{type(ex).__name__}: {ex}")
    try:
        q=web_queue_state();add("Job Queue","PASS",q)
    except Exception as ex:add("Job Queue","FAIL",f"{type(ex).__name__}: {ex}")
    summary={k:sum(1 for x in checks if x["status"]==k.upper()) for k in ["pass","warn","fail"]}
    return {"ok":summary["fail"]==0,"summary":summary,"checks":checks,"library_root":str(BASE),"database":str(DB),
            "root_resolution":web_json_safe(BASE_RESOLUTION),"app_version":APP_VERSION}

