def old_import_page_v2_html():
    default=LEGACY_IMPORT_MEDIA_DEFAULT
    return '''<!doctype html><html><head><meta charset="utf-8"><style>body{margin:0;background:#0b1628;color:#f5f8ff;font:16px Segoe UI,Arial,sans-serif}main{max-width:1100px;margin:36px auto;padding:0 28px}.card{background:#101e33;border:1px solid #29405f;border-radius:16px;padding:24px;margin:16px 0}p,#status{color:#aac0df;line-height:1.55}label{display:block;margin:15px 0 6px;font-weight:700}input[type=text]{width:100%;box-sizing:border-box;background:#0a1425;border:1px solid #3a5579;border-radius:9px;color:#fff;padding:12px;font-size:15px}.checks label{font-weight:400;margin:11px 0}button{border:0;border-radius:9px;padding:12px 18px;font-size:15px;font-weight:700;cursor:pointer;background:#1769ee;color:#fff}.secondary{background:#344d70}.danger{background:#9c3341}pre{white-space:pre-wrap;max-height:350px;overflow:auto;background:#091321;border:1px solid #293e5b;padding:14px;border-radius:9px;color:#c7d8f0}</style></head><body><main><h1>Old Library Import &amp; Repair</h1><p><b>Step 1:</b> run Preflight Scan. It is read-only and tells you what each legacy folder has, lacks, and can create. <b>Step 2:</b> select actions and import.</p><div class="card"><label>Old Downloads / media folder</label><input id="media" type="text" value="'''+html.escape(default,quote=True)+'''"><label>Optional old data / metadata folder</label><input id="metadata" type="text" placeholder="Leave blank unless metadata is elsewhere"><div class="checks"><label><input id="merge" type="checkbox" checked> Import metadata.info.json fields and create missing SQLite records</label><label><input id="move" type="checkbox"> Move all video folders into VideoHoarder Videos; merge folders and skip same-name files</label><label><input id="paths" type="checkbox" checked> Create `_data/.video_id` and repair paths</label><label><input id="reports" type="checkbox"> Refresh HTML reports</label><label><input id="indexes" type="checkbox" checked> Rebuild CSV, indexes &amp; Knowledge Center</label></div><button class="secondary" onclick="preflight()">1. Preflight Scan Old Library</button> <button onclick="run()">2. Run Selected Import &amp; Repair</button> <button class="danger" onclick="closeOld()">Close Previous App Sessions</button><div id="status">Run the preflight scan before moving anything.</div><pre id="report">No preflight report yet.</pre></div></main><script>const $=id=>document.getElementById(id);let jid='';async function post(u,p){const r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});return r.json()}function payload(){return{media_root:$('media').value.trim(),metadata_root:$('metadata').value.trim(),merge_metadata:$('merge').checked,move_media:$('move').checked,repair_paths:$('paths').checked,refresh_reports:$('reports').checked,rebuild_indexes:$('indexes').checked}}async function start(action,p){const x=await post('/api/job-start',{action,payload:p});jid=x.job_id||'';$('status').textContent=x.message||JSON.stringify(x);return x}async function preflight(){if(!$('media').value.trim())return alert('Choose an old Downloads folder.');await start('old_library_preflight',{media_root:$('media').value.trim()})}async function run(){if(!$('media').value.trim())return alert('Choose an old Downloads folder.');if($('move').checked&&!confirm('Merge folders and skip only same-name files?'))return;await start('old_library_import',payload())}async function closeOld(){const x=await post('/api/close-previous-sessions',{});$('status').textContent=x.message||JSON.stringify(x)}setInterval(async()=>{try{const r=await fetch('/api/jobs',{cache:'no-store'}),x=await r.json(),j=jid?(x.items||[]).find(v=>v.job_id===jid):(x.items||[])[0];if(!j)return;$('status').textContent=(j.label||'Task')+' — '+j.status+'\\nPhase: '+(j.phase||'Working')+'\\nCurrent: '+(j.current_file||'Preparing')+'\\nStatus: '+(j.current_status||j.message||'')+(j.total?'\\nOverall: '+(j.processed||0)+' / '+j.total:'')+(j.current_percent?'\\nFile: '+j.current_percent:'')+(j.current_speed?' · '+j.current_speed:'')+(j.current_eta?' · ETA '+j.current_eta:'');if(j.status!=='RUNNING'&&j.status!=='QUEUED'&&j.has_result){const d=await fetch('/api/job-detail?id='+encodeURIComponent(j.job_id)).then(q=>q.json());$('report').textContent=JSON.stringify((d.job||{}).result||d.job||{},null,2)}}catch(e){$('status').textContent='Progress error: '+e}},1000)</script></body></html>'''

def old_import_page_v3_html():
    default=LEGACY_IMPORT_MEDIA_DEFAULT
    return '''<!doctype html><html><head><meta charset="utf-8"><style>body{margin:0;background:#0b1628;color:#f5f8ff;font:16px Segoe UI,Arial,sans-serif}main{max-width:1100px;margin:36px auto;padding:0 28px}.card{background:#101e33;border:1px solid #29405f;border-radius:16px;padding:24px;margin:16px 0}.muted,#status{color:#aac0df;line-height:1.55}label{display:block;margin:14px 0 6px;font-weight:700}input,textarea{width:100%;box-sizing:border-box;background:#0a1425;border:1px solid #3a5579;border-radius:9px;color:#fff;padding:12px;font-size:15px}textarea{height:110px}.checks label{font-weight:400;margin:10px 0}button{border:0;border-radius:9px;padding:11px 15px;font-size:15px;font-weight:700;cursor:pointer;background:#1769ee;color:#fff;margin:4px}.secondary{background:#344d70}.danger{background:#9c3341}pre{white-space:pre-wrap;max-height:320px;overflow:auto;background:#091321;border:1px solid #293e5b;padding:14px;border-radius:9px;color:#c7d8f0}</style></head><body><main><h1>Old Library Import &amp; Repair</h1><p><a href="/import-local" style="color:#aacdff">Import ordinary video files from your hard drives (no YouTube ID needed) →</a></p><p class="muted">Add one or more source folders. Each line is scanned and imported separately; nothing moves until you enable the move checkbox.</p><div class="card"><label>Add source folder</label><input id="folder" value="'''+html.escape(default,quote=True)+'''"><button class="secondary" onclick="addFolder()">Add Folder</button><label>Selected folders (one per line)</label><textarea id="media"></textarea><div class="checks"><label><input id="merge" type="checkbox" checked> Import metadata.info.json fields and create missing SQLite records</label><label><input id="move" type="checkbox"> Move folders into VideoHoarder Videos; merge folders and skip same-name files</label><label><input id="paths" type="checkbox" checked> Create `_data/.video_id` and repair paths</label><label><input id="reports" type="checkbox"> Refresh HTML reports</label><label><input id="indexes" type="checkbox" checked> Rebuild CSV, indexes &amp; Knowledge Center</label></div><button class="secondary" onclick="preflight()">1. Preflight Selected Folders</button><button onclick="run()">2. Run Selected Import &amp; Repair</button><button class="danger" onclick="closeOld()">Close Previous App Sessions</button><div id="status">Add folders, run the read-only preflight, then select actions.</div><pre id="report">No preflight report yet.</pre></div></main><script>const $=id=>document.getElementById(id);let jid='';function addFolder(){const x=$('folder').value.trim();if(!x)return;$('media').value=Array.from(new Set(($('media').value.split(/\\r?\\n/).concat([x])).filter(Boolean))).join('\\n');$('folder').value=''}async function post(u,p){return await fetch(u,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)}).then(r=>r.json())}function payload(){return{media_roots:$('media').value.trim(),merge_metadata:$('merge').checked,move_media:$('move').checked,repair_paths:$('paths').checked,refresh_reports:$('reports').checked,rebuild_indexes:$('indexes').checked}}async function start(action,p){const x=await post('/api/job-start',{action,payload:p});jid=x.job_id||'';$('status').textContent=x.message||JSON.stringify(x)}async function preflight(){if(!$('media').value.trim())return alert('Add at least one source folder.');await start('old_library_preflight',{media_roots:$('media').value.trim()})}async function run(){if(!$('media').value.trim())return alert('Add at least one source folder.');if($('move').checked&&!confirm('Merge folders and skip only same-name files?'))return;await start('old_library_import',payload())}async function closeOld(){const x=await post('/api/close-previous-sessions',{});$('status').textContent=x.message||JSON.stringify(x)}setInterval(async()=>{try{const x=await fetch('/api/jobs',{cache:'no-store'}).then(r=>r.json()),j=jid?(x.items||[]).find(v=>v.job_id===jid):(x.items||[])[0];if(!j)return;$('status').textContent=(j.label||'Task')+' — '+j.status+'\\nPhase: '+(j.phase||'Working')+'\\nCurrent: '+(j.current_file||'Preparing')+'\\nStatus: '+(j.current_status||j.message||'')+(j.total?'\\nOverall: '+(j.processed||0)+' / '+j.total:'')+(j.current_percent?'\\nFile: '+j.current_percent:'')+(j.current_speed?' · '+j.current_speed:'')+(j.current_eta?' · ETA '+j.current_eta:'');if(j.status!=='RUNNING'&&j.status!=='QUEUED'&&j.has_result){const d=await fetch('/api/job-detail?id='+encodeURIComponent(j.job_id)).then(q=>q.json());$('report').textContent=JSON.stringify((d.job||{}).result||d.job||{},null,2)}}catch(e){}},1000)</script></body></html>'''

def chatgpt_processing_page_html_v2():
    features=''.join(f'<label><input type="checkbox" value="{html.escape(k)}" checked> {html.escape(k)} — {html.escape(v)}</label>' for k,v in CHATGPT_FEATURES.items())
    navigation=[('overview','Overview'),('create','Create Package'),('history','Request History'),('coverage','Feature Coverage'),('import','Import & Validate'),('review','Review & Apply'),('duplicates','Duplicates'),('clips','Clip Plans'),('maintenance','Maintenance')]
    nav=''.join(f'<button onclick="show(\'{key}\')">{label}</button>' for key,label in navigation)
    return f'''<!doctype html><html><head><meta charset="utf-8"><style>body{{margin:0;background:#081426;color:#eef5ff;font:15px Segoe UI,Arial}}.top{{padding:18px 24px;background:#0e2038;border-bottom:1px solid #294667;font-size:22px;font-weight:700}}.layout{{display:grid;grid-template-columns:220px 1fr;min-height:calc(100vh - 61px)}}nav{{background:#0b1a2d;border-right:1px solid #294667;padding:14px}}nav button{{display:block;width:100%;text-align:left;margin:5px 0;background:transparent;border:0;color:#b9cae2;padding:11px;border-radius:8px;font-size:14px}}main{{padding:22px;max-width:1250px}}.notice{{background:#13325a;border:1px solid #2f649b;padding:14px;border-radius:10px;color:#d9ecff}}.grid{{display:grid;grid-template-columns:repeat(3,minmax(180px,1fr));gap:12px;margin:15px 0}}.card{{background:#0f2036;border:1px solid #294667;border-radius:12px;padding:16px;margin:12px 0}}.count{{font-size:30px;font-weight:700;color:#fff}}.panel{{display:none}}.panel.active{{display:block}}textarea,select,input{{box-sizing:border-box;background:#071120;color:#fff;border:1px solid #315273;border-radius:7px;padding:9px}}textarea,select{{width:100%}}textarea{{height:90px}}button.primary{{background:#1670ea;color:#fff;border:0;border-radius:8px;padding:11px 14px;font-weight:700}}.features label{{display:block;color:#c8d8ed;margin:7px 0}}pre{{white-space:pre-wrap;max-height:420px;overflow:auto;background:#071120;padding:12px;border-radius:8px}}</style></head><body><div class="top">ChatGPT Processing <span style="font-size:13px;color:#9eb5d1">Manual Exchange Command Center</span></div><div class="layout"><nav>{nav}</nav><main><section id="overview" class="panel active"><div class="notice"><b>Manual exchange safety:</b> VideoHoarder creates local packages only. You upload manually to ChatGPT, then manually select returned JSON. Nothing is uploaded or applied automatically.</div><div id="counters" class="grid"></div><div class="card"><h3>Six-step manual flow</h3>Select → Review evidence → Create package → Upload manually → Import & validate → Review & apply.</div><div class="card"><h3>Quick actions</h3><button class="primary" onclick="show('create')">Create package</button> <button class="primary" onclick="show('history')">View history</button> <button class="primary" onclick="show('coverage')">Feature coverage</button></div></section><section id="create" class="panel"><h2>Create Package</h2><div class="card"><label>Mode</label><select id="mode"><option>MASTER</option><option>FOCUSED</option><option>TAXONOMY</option><option>SAME_TOPIC</option><option>FEATURE_ENRICHMENT</option></select><label>VIDEO_IDs (optional; blank selects eligible active videos)</label><textarea id="ids"></textarea><div class="features">{features}</div><button class="primary" onclick="createPackage()">Create local manual package</button><pre id="createOut"></pre></div></section><section id="history" class="panel"><h2>Request History</h2><pre id="historyOut"></pre></section><section id="coverage" class="panel"><h2>Feature Coverage</h2><button class="primary" onclick="loadCoverage()">Refresh matrix</button><pre id="coverageOut"></pre></section><section id="import" class="panel"><h2>Import & Validate</h2><div class="notice"><b>Nothing is applied here.</b> Select JSON manually saved from ChatGPT. VideoHoarder archives it locally, validates it and creates a review preview.</div><div class="card"><input id="resultFile" type="file" accept="application/json,.json"> <button class="primary" onclick="importResult()">Import & validate selected result</button><pre id="importOut"></pre></div></section><section id="review" class="panel"><h2>Review & Apply</h2><div class="notice">Review previews before using existing reviewed rename, category-move preview, metadata, taxonomy and undo tools. No physical rename, move, deletion, cut, or merge happens automatically.</div><button class="primary" onclick="loadReview()">Refresh reviewed results</button><pre id="reviewOut"></pre></section><section id="duplicates" class="panel"><h2>Duplicates</h2><div class="notice">Suggestions only. Choose a canonical video and manually keep, archive, mark delete or delete. No automatic deletion.</div></section><section id="clips" class="panel"><h2>Clip Plans</h2><div class="notice">Suggestions only. Review and manually send a valid plan to existing Clip Studio; no automatic cut or merge.</div></section><section id="maintenance" class="panel"><h2>Maintenance</h2><div class="notice">Existing integrity, comment-intelligence, legacy sync and audit tools remain local and traceable.</div></section></main></div><script>const $=x=>document.getElementById(x);async function api(u,o){{return await fetch(u,o).then(r=>r.json())}}function show(id){{document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));$(id).classList.add('active');if(id==='overview')loadOverview();if(id==='history')loadHistory();if(id==='coverage')loadCoverage();if(id==='review')loadReview()}}async function loadOverview(){{let x=await api('/api/chatgpt-processing/overview'),c=x.counters||{{}};$('counters').innerHTML=[['Package sets',c.package_sets||0],['Videos with intelligence',c.videos_with_intelligence||0],['Feature updates',c.feature_updates||0]].map(v=>`<div class="card"><div>${{v[0]}}</div><div class="count">${{v[1]}}</div></div>`).join('')}}async function createPackage(){{let f=[...document.querySelectorAll('.features input:checked')].map(x=>x.value);let x=await api('/api/chatgpt-processing/create',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{mode:$('mode').value,video_ids:$('ids').value,features:f}})}});$('createOut').textContent=JSON.stringify(x,null,2);loadOverview()}}async function loadHistory(){{$('historyOut').textContent=JSON.stringify(await api('/api/chatgpt-processing/history'),null,2)}}async function loadCoverage(){{$('coverageOut').textContent=JSON.stringify(await api('/api/chatgpt-processing/coverage'),null,2)}}async function importResult(){{let f=$('resultFile').files[0];if(!f){{$('importOut').textContent='Select the returned JSON file first.';return}}let x=await api('/api/chatgpt-processing/import',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{filename:f.name,result_json:await f.text()}})}});$('importOut').textContent=JSON.stringify(x,null,2);loadOverview()}}async function loadReview(){{$('reviewOut').textContent=JSON.stringify(await api('/api/chatgpt-processing/review'),null,2)}}loadOverview()</script></body></html>'''

def chatgpt_processing_page_html_v3():
    page=chatgpt_processing_page_html_v2()
    return page.replace('<option>MASTER</option><option>FOCUSED</option><option>TAXONOMY</option><option>SAME_TOPIC</option><option>FEATURE_ENRICHMENT</option>', '<option value="SMART_QUALITY">SMART QUALITY - 25 transcript / 50 no-transcript</option><option>MASTER</option><option>FOCUSED</option><option>TAXONOMY</option><option>SAME_TOPIC</option><option>FEATURE_ENRICHMENT</option>')

def chatgpt_processing_page_html_v4():
    page=chatgpt_processing_page_html_v3()
    page=page.replace('id="resultFile" type="file" accept="application/json,.json"', 'id="resultFiles" type="file" accept="application/json,.json" multiple> <label style="display:block;margin-top:8px">Or choose a folder of returned JSON files:</label><input id="resultFolder" type="file" accept="application/json,.json" multiple webkitdirectory directory')
    page=page.replace('Import & validate selected result', 'Import & validate selected JSON file(s) / folder')
    page=page.replace('<button class="primary" onclick="loadReview()">Refresh reviewed results</button>', '<button class="primary" onclick="loadReview()">Refresh reviewed results</button> <button class="primary" onclick="exportReviewCsv()">Create combined review CSV</button> <button class="primary" onclick="applyAllValidatedResults()">Apply all validated results</button><pre id="bulkApplyOut"></pre>')
    script='''<script>async function importMany(){let fs=[...document.getElementById('resultFiles').files,...document.getElementById('resultFolder').files].filter(f=>f.name.toLowerCase().endsWith('.json'));let seen=new Set;fs=fs.filter(f=>!seen.has(f.name)&&seen.add(f.name));if(!fs.length){document.getElementById('importOut').textContent='Select one or more returned JSON files, or choose a folder containing them.';return}document.getElementById('importOut').textContent='Reading and validating '+fs.length+' JSON file(s)...';let results=[];for(const f of fs){results.push({filename:f.name,result_json:await f.text()})}let x=await api('/api/chatgpt-processing/import-many',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({results})});document.getElementById('importOut').textContent=JSON.stringify(x,null,2);loadOverview()}async function exportReviewCsv(){let x=await api('/api/chatgpt-processing/export-review-csv',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});document.getElementById('reviewOut').textContent=JSON.stringify(x,null,2)}document.querySelector('#import button.primary').setAttribute('onclick','importMany()');</script>'''
    selectors_script='''<script>(async function(){try{const x=await api('/api/chatgpt-processing/selectors');const map={folderScope:x.folders||[],topicScope:x.topics||[],categoryScope:x.categories||[]};Object.entries(map).forEach(([id,vals])=>{const e=$(id);if(!e)return;vals.forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;e.appendChild(o)});e.addEventListener('change',()=>{const ids=$('ids');if(ids&&!ids.value)ids.placeholder='Selected '+id.replace('Scope','')+': '+e.value+' (backend scope wiring follows current package selection)'});});}catch(e){}})();</script>'''
    return page.replace('</body>',script+selectors_script+'</body>')

def chatgpt_processing_page_html_v5():
    page=chatgpt_processing_page_html_v4()
    old='<section id="maintenance" class="panel"><h2>Maintenance</h2><div class="notice">Existing integrity, comment-intelligence, legacy sync and audit tools remain local and traceable.</div></section>'
    new='<section id="maintenance" class="panel"><h2>Maintenance</h2><div class="notice">Existing integrity, comment-intelligence, legacy sync and audit tools remain local and traceable.</div><div class="card"><h3>Remove unprocessed packages</h3><p>Only local outgoing packages with no returned/imported result are listed. Processed or imported packages cannot be removed here. The request history is retained as DELETED.</p><label>Filter by batch number or package ID</label><input id="packageBatchFilter" placeholder="Example: 2 or 20260813"><button class="primary" onclick="loadUnprocessedPackages()">Refresh filtered list</button> <button class="primary" onclick="deleteSelectedUnprocessed()">Delete selected local packages</button><div id="unprocessedList"></div><pre id="maintenanceOut"></pre></div></section>'
    page=page.replace(old,new)
    script='''<script>async function loadUnprocessedPackages(){let x=await api('/api/chatgpt-processing/unprocessed-packages');let q=(document.getElementById('packageBatchFilter')?.value||'').toLowerCase();let a=(x.items||[]).filter(p=>!q||String(p.package_id||'').toLowerCase().includes(q)||String(p.batch_number||'').toLowerCase()===q);document.getElementById('unprocessedList').innerHTML=a.length?a.map(p=>`<label style="display:block;margin:8px 0"><input type="checkbox" class="unprocessedPackage" value="${p.package_id}"> <b>${p.package_id}</b> - batch ${p.batch_number||'—'} - ${p.mode} - ${p.created_at}<br><small>${p.folder}</small></label>`).join(''):'<p>No matching unprocessed packages are available for deletion.</p>'}async function deleteSelectedUnprocessed(){let ids=[...document.querySelectorAll('.unprocessedPackage:checked')].map(x=>x.value);if(!ids.length){document.getElementById('maintenanceOut').textContent='Select one or more packages first.';return}if(!confirm('Delete '+ids.length+' local unprocessed package folder(s)? Imported/processed packages are not affected.'))return;let x=await api('/api/chatgpt-processing/delete-unprocessed-packages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({package_ids:ids})});document.getElementById('maintenanceOut').textContent=JSON.stringify(x,null,2);loadUnprocessedPackages();loadOverview();if(window.loadHistory)loadHistory()}</script>'''
    review_script='''<script>(function(){function esc(v){return String(v??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}function fields(value,path,out){out=out||[];if(value&&typeof value==='object'&&!Array.isArray(value)){Object.entries(value).forEach(([k,v])=>fields(v,path?path+'.'+k:k,out))}else out.push([path,value]);return out}window.applyAllValidatedResults=async function(){if(!confirm('Apply all VALIDATED/PARTIAL ChatGPT results to the library now? This updates metadata/titles/taxonomy only. Folder moves remain preview-only.'))return;const out=document.getElementById('bulkApplyOut')||document.getElementById('reviewOut');out.textContent='Applying all validated ChatGPT results...';const x=await api('/api/chatgpt-processing/apply-all-validated',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({include_partial:true,move_folders:false})});out.textContent=JSON.stringify(x,null,2);if(window.loadOverview)loadOverview();if(window.loadCoverage)loadCoverage();};window.loadReview=async function(){const x=await api('/api/chatgpt-processing/review'),items=x.items||[],root=$('reviewOut');if(!root)return;root.outerHTML='<div id="reviewOut">'+(items.map(p=>'<div class="card"><div class="section-head"><h3>'+esc(p.package_id)+'</h3><span class="status-chip">'+esc(p.validation_status)+'</span></div>'+(p.errors||[]).map(e=>'<div class="notice">'+esc(e)+'</div>').join('')+(p.proposed_updates||[]).map(u=>'<div class="work-stat"><b>'+esc(u.video_id)+'</b>'+Object.entries(u.features||{}).flatMap(([fid,val])=>fields(val,fid)).map(([field,val])=>'<div class="review-field"><label><input class="reviewDecision" type="checkbox" data-package="'+esc(p.package_id)+'" data-video="'+esc(u.video_id)+'" data-feature="'+esc(field.split('.')[0])+'" data-field="'+esc(field)+'" data-value="'+encodeURIComponent(JSON.stringify(val))+'"> <b>'+esc(field)+'</b>: '+esc(typeof val==='object'?JSON.stringify(val):val)+'</label><select class="reviewAction"><option value="metadata">Approve metadata</option><option value="taxonomy">Approve taxonomy</option><option value="rename">Stage rename preview</option><option value="move">Stage folder-move preview</option><option value="duplicate_keep">Duplicate: keep</option><option value="duplicate_archive">Duplicate: archive</option><option value="duplicate_mark_delete">Duplicate: mark delete</option><option value="clip_plan">Stage clip plan</option><option value="report_refresh">Refresh report</option></select></div>').join('')+'</div>').join('')+'<button class="primary" onclick="saveReviewDecisions(\''+esc(p.package_id)+'\')">Save approved field decisions</button></div>').join('')||'<div class="card">No imported results are ready for review.</div>')+'</div>'};window.saveReviewDecisions=async function(packageId){const decisions=[...document.querySelectorAll('.reviewDecision:checked[data-package="'+packageId+'"]')].map(c=>({video_id:c.dataset.video,feature_id:c.dataset.feature,field_path:c.dataset.field,action:c.closest('.review-field').querySelector('.reviewAction').value,approved:true,value:JSON.parse(decodeURIComponent(c.dataset.value))}));const x=await api('/api/chatgpt-processing/review-decisions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({package_id:packageId,decisions})});alert(x.message||('Saved '+(x.decisions||0)+' reviewed field decision(s). Physical file changes were not applied.'))}})();</script>'''
    return page.replace('</body>',script+review_script+'</body>')

def chatgpt_processing_page_html_v6():
    page=chatgpt_processing_page_html_v5()
    page=page.replace('<textarea id="ids"></textarea><div class="features">', '<textarea id="ids"></textarea><label title="Checks local transcript/subtitle files first; for missing ones it makes a short YouTube transcript/caption check and records AVAILABLE or UNAVAILABLE before package routing."><input id="verifyTranscriptAvailability" type="checkbox" checked> Before packaging: check/recheck transcript availability and track unavailable videos</label><div class="features">')
    page=page.replace("video_ids:$('ids').value,features:f", "video_ids:$('ids').value,verify_transcript_availability:$('verifyTranscriptAvailability').checked,features:f")
    return page

def chatgpt_processing_page_html_v7():
    page=chatgpt_processing_page_html_v6()
    page=page.replace('</select><label>VIDEO_IDs (optional; blank selects eligible active videos)</label>', '</select><div id="modeHelp" class="notice" style="margin:10px 0"></div><label>VIDEO_IDs (optional; blank selects eligible active videos)</label>', 1)
    script='''<script>(function(){const mode=document.getElementById('mode'),help=document.getElementById('modeHelp');if(!mode||!help)return;const info={SMART_QUALITY:['Recommended for full library processing','Checks transcript availability first, then creates 25-video full-intelligence packages and separate 50-video no-transcript packages. Example: process your whole library safely.'],MASTER:['One large all-feature package','Includes all selected videos and selected features in one package. Example: a small library or a one-off master export.'],FOCUSED:['Specific selected videos','Uses only the VIDEO_IDs you paste. Example: analyse 3 videos from one channel.'],TAXONOMY:['Categories, topics and tags','Use when you primarily want classification/search labels. Example: organize unclassified videos by topic.'],SAME_TOPIC:['Related-topic research','Use to compare videos around one theme. Example: select 10 videos about nutrition.'],FEATURE_ENRICHMENT:['Fill one missing feature','Targets videos missing the selected first feature. Example: create summaries only for videos that do not have them yet.']};function update(){let x=info[mode.value]||info.MASTER;help.innerHTML='<b>'+x[0]+'</b><br>'+x[1]}mode.addEventListener('change',update);update()})();</script>'''
    return page.replace('</body>',script+'</body>')

def chatgpt_processing_page_html_v8():
    """Use the shared job queue so package creation reports live progress."""
    page=chatgpt_processing_page_html_v7()
    page=page.replace("payload={mode:$('mode').value,video_ids:$('ids').value,verify_transcript_availability:$('verifyTranscriptAvailability').checked,features:f}", "payload={mode:$('mode').value,video_ids:$('ids').value,folderScope:$('folderScope')?.value||'',topicScope:$('topicScope')?.value||'',categoryScope:$('categoryScope')?.value||'',verify_transcript_availability:$('verifyTranscriptAvailability').checked,features:f}")
    script='''<script>(function(){let createTimer=null;function out(t){const e=document.getElementById('createOut');if(e)e.textContent=t}function line(j){return (j.label||'Create ChatGPT package')+' — '+(j.status||'')+'\\nPhase: '+(j.phase||'Preparing')+'\\nCurrent video: '+(j.current_file||'Preparing')+'\\nStatus: '+(j.current_status||j.message||'')+(j.total?'\\nOverall: '+(j.processed||0)+' / '+j.total:'')+(j.current_percent?'\\nProgress: '+j.current_percent:'')+(j.current_speed?' · '+j.current_speed:'')+(j.current_eta?' · ETA '+j.current_eta:'')}async function watchCreate(jobId){if(createTimer)clearInterval(createTimer);async function tick(){try{const x=await api('/api/job-detail?id='+encodeURIComponent(jobId)),j=x.job||{};out(line(j));if(['SUCCESS','WARN','FAILED','CANCELLED'].includes(j.status)){clearInterval(createTimer);if(j.result)out(line(j)+'\\n\\n'+JSON.stringify(j.result,null,2));loadOverview()}}catch(e){out('Progress check failed: '+e)}}await tick();createTimer=setInterval(tick,1000)}window.watchCreate=watchCreate;window.createPackage=async function(){let f=[...document.querySelectorAll('.features input:checked')].map(x=>x.value),payload={mode:$('mode').value,video_ids:$('ids').value,verify_transcript_availability:$('verifyTranscriptAvailability').checked,features:f};out('Queuing package creation…');let x=await api('/api/job-start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'chatgpt_processing_create',payload:payload})});if(!x.ok){out(x.message||JSON.stringify(x));return}out(x.message+'\\nWaiting for live progress…');watchCreate(x.job_id)}})();</script>'''
    return page.replace('</body>',script+'</body>')

def chatgpt_processing_page_html_v9():
    page=chatgpt_processing_page_html_v8()
    # v5's inline quoted package id loses its Python escape while composing
    # the final page. Use a data attribute so arbitrary ids remain valid JS.
    page=page.replace("onclick=\"saveReviewDecisions(''+esc(p.package_id)+'')\"", "data-package=\"'+esc(p.package_id)+'\" onclick=\"saveReviewDecisions(this.dataset.package)\"")
    page=page.replace("VideoHoarder creates local packages only. You upload manually to ChatGPT, then manually select returned JSON. Nothing is uploaded or applied automatically.", "VideoHoarder creates local packages by default. If you explicitly select GitHub publishing, approved package files—including supplied transcripts and comments—are published to the public gbansal86/VideoHoarder repository. Nothing is applied automatically.")
    page=page.replace("VideoHoarder never uploads data to ChatGPT", "VideoHoarder never sends data directly to ChatGPT")
    # v8 renders concrete button HTML (not the source tuple used by the old
    # template), so inject against that stable visible markup.
    page=page.replace('<button onclick="show(\'overview\')">Overview</button>', '<button onclick="show(\'overview\')">Overview</button><button onclick="show(\'planner\')">Group Similar Videos</button>', 1)
    page=page.replace('<pre id="importOut"></pre></div>', '<pre id="importOut"></pre></div><div class="card"><h3>Import one returned batch ZIP</h3><p>Select a ZIP containing package <b>result.json</b> files. VideoHoarder reads them safely without extracting the archive, validates every package, creates one combined report, and applies nothing automatically.</p><input id="resultZip" type="file" accept="application/zip,.zip"> <button class="primary" onclick="importResultZip()">Validate &amp; import returned ZIP</button><pre id="zipImportOut"></pre></div><div class="card"><h3>GitHub returned results</h3><p>Pull returned JSON/ZIP files from the authorized public repository under <b>exchange/incoming</b> or <b>exchange/results</b>. Every file is copied locally before validation.</p><label><input id="githubArchiveProcessed" type="checkbox" checked> Archive successfully processed GitHub copies after validation</label> <button class="primary" onclick="importGithubResults()">Pull &amp; validate GitHub results</button><pre id="githubImportOut"></pre></div>',1)
    page=page.replace("('review','Review & Apply'),('duplicates','Duplicates'),('clips','Clip Plans'),('maintenance','Maintenance')", "('review','Review & Apply'),('advanced','ADVANCED'),('duplicates','Duplicates'),('clips','Clip Plans'),('maintenance','Maintenance')")
    page=page.replace('<button onclick="show(\'review\')">Review & Apply</button><button onclick="show(\'duplicates\')">Duplicates</button>', '<button onclick="show(\'review\')">Review & Apply</button><button class="nav-group" disabled>ADVANCED</button><button onclick="show(\'duplicates\')">Duplicates</button>')
    page=page.replace('<button onclick="show(\'advanced\')">ADVANCED</button>', '<button class="nav-group" disabled>ADVANCED</button>')
    page=page.replace("<button class=\"primary\" onclick=\"show('create')\">Create package</button>", "<button class=\"primary\" onclick=\"show('planner')\">Group similar videos</button> <button class=\"primary\" onclick=\"show('create')\">Create package</button>")
    insert='''</section><section id="planner" class="panel"><h2>Group Similar Videos</h2><div class="card"><p>Create one small manual planner package. The planner includes transcript availability, transcript size, video length and video type so ChatGPT can group all selected videos intelligently. Videos without usable transcript/SRT/VTT or music-only captions may appear in no-transcript planner groups, but they are excluded from final ChatGPT intelligence packages unless you explicitly request metadata-only packages.</p><p><b>Example:</b> group the Black Raven / Westeros videos together first, then create one planner package for that topic.</p><label><input id="skipEntertainment" type="checkbox"> Skip videos whose YouTube category is Entertainment</label><label><input id="recheckBadTranscriptsBeforeGrouping" type="checkbox" checked> Recheck missing / bad transcripts online before Group Similar</label><button onclick="recheckBadTranscripts()">Recheck Missing / Bad Transcripts Now</button><label>Optional title/channel words to skip (comma-separated)</label><input id="skipKeywords" placeholder="Example: Westeros, Black Raven"><button class="primary" onclick="previewPlannerSkips()">1. Preview categories, evidence counts and recommended batches</button> <button onclick="recheckBadTranscripts(false)">Recheck Missing / Bad Transcripts</button> <button onclick="recheckBadTranscripts(true)">Force Transcript Recheck</button> <button class="primary" onclick="createBatchPlanner()">2. Create one similarity planner package</button> <button onclick="openExchangeFolder('group_planners')">Open planner packages folder</button></div><div class="card"><h3>3. Import and validate returned planner JSON</h3><p>Topic groups are semantic organization only; actual packages are globally optimized later with no minimum size and a hard maximum of 30. No-transcript groups are planning/recheck only by default. Every active-library catalog ID must appear exactly once.</p><input id="batchPlanFile" type="file" accept="application/json,.json"> <button class="primary" onclick="importBatchPlan()">Import &amp; validate plan</button><input id="plannerPackageId" type="hidden"><label><input id="automaticBatchSize" type="checkbox" checked> Automatically optimize package count while respecting transcript workload</label><button class="primary" onclick="createFromBatchPlan()">4. Create grouped intelligence packages</button> <button onclick="openExchangeFolder('group_batches')">Open grouped batches folder</button> <button onclick="openExchangeFolder('group_incoming')">Open grouped incoming folder</button><p class="notice">Each package creates one <b>CHATGPT_PACKAGE.json</b> file for upload. The run also creates <b>BATCH_PACKAGE_SUMMARY.csv</b> with actual titles, <b>BATCH_VALIDATION_REPORT.csv</b>, and a convenience ZIP for backup/transfer.</p><pre id="batchPlanOut">Create the planner package first.</pre></div></section><section id="create" class="panel"><h2>Create Package</h2>'''
    page=page.replace("</section><section id=\"create\" class=\"panel\"><h2>Create Package</h2>", insert, 1)
    public_warning='<div class="notice"><b>Public GitHub warning:</b> Selecting either option publishes the approved package JSON/CSV—including embedded transcript and comment evidence—to <b>github.com/gbansal86/VideoHoarder</b>. Do not select it for private material.</div>'
    page=page.replace('<button class="primary" onclick="createBatchPlanner()">2. Create one similarity planner package</button>', '<div class="vh-check-stack"><label class="vh-check-row"><input id="githubPublishPlanner" type="checkbox"> <span>Publish planner package to the authorized public GitHub repository</span></label></div>'+public_warning+'<div class="action-row"><button class="primary" onclick="createBatchPlanner()">2. Create one similarity planner package</button><button onclick="publishLatestGithub(\'planner\')">Upload latest planner to GitHub</button><button onclick="openExchangeFolder(\'group_planners\')">Open planner packages folder</button></div>',1)
    page=page.replace('<label><input id="githubPublishBatches" type="checkbox"> Publish completed grouped packages to the authorized public GitHub repository</label><button class="primary" onclick="createFromBatchPlan()">4. Create grouped intelligence packages</button>', '<div class="vh-check-stack"><label class="vh-check-row"><input id="refreshLibraryBeforeGrouping" type="checkbox" checked> <span>Refresh database counts and library reports before creating grouped packages</span></label><label class="vh-check-row"><input id="automaticBatchSize" type="checkbox" checked> <span>Automatically optimize package count while respecting transcript workload</span></label><label class="vh-check-row"><input id="compactChatgptPackage" type="checkbox" checked> <span>Use master modular sequential ChatGPT prompt; exclude videos without usable transcript/SRT/VTT or music-only captions</span></label><label class="vh-check-row"><input id="allowRecreateProcessedBatches" type="checkbox"> <span>Recreate packages even for videos that already have a completed ChatGPT result</span></label><label class="vh-check-row"><input id="resetProcessedLocksBatches" type="checkbox"> <span>Reset already-processed ChatGPT counters for this selected plan before creating packages</span></label><label class="vh-check-row"><input id="githubPublishBatches" type="checkbox"> <span>Publish completed grouped packages to the authorized public GitHub repository</span></label></div><div class="action-row"><button class="primary" onclick="createFromBatchPlan()">4. Create grouped intelligence packages</button><button onclick="rebuildLibraryReports()">Refresh DB/library now</button><button onclick="publishLatestGithub(\'grouped\')">Upload latest grouped packages to GitHub</button><button onclick="openExchangeFolder(\'group_batches\')">Open grouped batches folder</button><button onclick="openExchangeFolder(\'group_incoming\')">Open grouped incoming folder</button></div>',1)
    page=page.replace('<label><input id="automaticBatchSize" type="checkbox" checked> Automatically optimize package count while respecting transcript workload</label>', '',1)
    page=page.replace('<button class="primary" onclick="createFromBatchPlan()">4. Create grouped intelligence packages</button> <button onclick="openExchangeFolder(\'group_batches\')">Open grouped batches folder</button> <button onclick="openExchangeFolder(\'group_incoming\')">Open grouped incoming folder</button>', '',1)
    page=page.replace('<button class="primary" onclick="createPackage()">Create local manual package</button>', '<div class="vh-check-stack"><label class="vh-check-row"><input id="allowRecreateProcessed" type="checkbox"> <span>Recreate package for videos that already have completed ChatGPT results</span></label><label class="vh-check-row"><input id="githubPublish" type="checkbox"> <span>Publish this package (transcripts/comments included) to the authorized public GitHub repository</span></label></div>'+public_warning+'<button class="primary" onclick="createPackage()">Create package</button>',1)
    page=page.replace('<label><input id="skipEntertainment" type="checkbox"> Skip videos whose YouTube category is Entertainment</label><label>Optional title/channel words to skip (comma-separated)</label><input id="skipKeywords" placeholder="Example: Westeros, Black Raven"><button class="primary" onclick="previewPlannerSkips()">1. Preview categories, evidence counts and recommended batches</button>', '<div class="vh-check-stack"><label class="vh-check-row"><input id="skipEntertainment" type="checkbox"> <span>Skip videos whose YouTube category is Entertainment</span></label></div><label>Optional title/channel words to skip (comma-separated)</label><input id="skipKeywords" placeholder="Example: Westeros, Black Raven"><div class="action-row"><button class="primary" onclick="previewPlannerSkips()">1. Preview categories, evidence counts and recommended batches</button></div>',1)
    page=page.replace(' <button onclick="openExchangeFolder(\'group_planners\')">Open planner packages folder</button></div><div class="card"><h3>3. Import and validate returned planner JSON</h3>', '</div><div class="card"><h3>3. Import and validate returned planner JSON</h3>',1)
    grouped_controls='<div class="vh-check-stack"><label class="vh-check-row"><input id="refreshLibraryBeforeGrouping" type="checkbox" checked> <span>Refresh database counts and library reports before creating grouped packages</span></label><label class="vh-check-row"><input id="automaticBatchSize" type="checkbox" checked> <span>Automatically optimize package count while respecting transcript workload</span></label><label class="vh-check-row"><input id="compactChatgptPackage" type="checkbox" checked> <span>Use master modular sequential ChatGPT prompt; exclude videos without usable transcript/SRT/VTT or music-only captions</span></label><label class="vh-check-row"><input id="allowRecreateProcessedBatches" type="checkbox"> <span>Recreate packages even for videos that already have a completed ChatGPT result</span></label><label class="vh-check-row"><input id="resetProcessedLocksBatches" type="checkbox"> <span>Reset already-processed ChatGPT counters for this selected plan before creating packages</span></label><label class="vh-check-row"><input id="githubPublishBatches" type="checkbox"> <span>Publish completed grouped packages to the authorized public GitHub repository</span></label></div><div class="action-row"><button class="primary" onclick="createFromBatchPlan()">4. Create grouped intelligence packages</button><button onclick="rebuildLibraryReports()">Refresh DB/library now</button><button onclick="publishLatestGithub(\'grouped\')">Upload latest grouped packages to GitHub</button><button onclick="openExchangeFolder(\'group_batches\')">Open grouped batches folder</button><button onclick="openExchangeFolder(\'group_incoming\')">Open grouped incoming folder</button></div>'
    if "Upload latest grouped packages to GitHub" not in page:
        page=page.replace('<p class="notice">Each package creates one <b>CHATGPT_PACKAGE.json</b> file for upload.', grouped_controls+'<p class="notice">Each package creates one <b>CHATGPT_PACKAGE.json</b> file for upload.',1)
    page=page.replace('<label>VIDEO_IDs (optional; blank selects eligible active videos)</label><textarea id="ids"></textarea>', '<label>Scope selectors</label><div class="selector-grid"><select id="folderScope"><option value="">All folders</option></select><select id="topicScope"><option value="">All topics</option></select><select id="collectionScope"><option value="">All collections</option></select><select id="categoryScope"><option value="">All categories</option></select></div><label>VIDEO_IDs (optional; blank selects eligible active videos)</label><textarea id="ids"></textarea><div class="notice" id="estimateBox">Estimated package size will appear after selection.</div>',1)
    page=page.replace('<section id="coverage" class="panel"><h2>Feature Coverage</h2><button class="primary" onclick="loadCoverage()">Refresh matrix</button>', '<section id="coverage" class="panel"><h2>Feature Coverage</h2><div class="selector-grid"><select id="coverageStatus"><option value="">All statuses</option><option>MISSING</option><option>REQUESTED</option><option>RESULT_AVAILABLE</option><option>NEEDS_VALIDATION</option><option>PARTIAL</option><option>FAILED</option><option>STALE</option></select></div><button class="primary" onclick="loadCoverage()">Refresh matrix</button>',1)
    page=page.replace('<section id="duplicates" class="panel"><h2>Duplicates</h2><div class="notice">Suggestions only. Choose a canonical video and manually keep, archive, mark delete or delete. No automatic deletion.</div></section>', '<section id="duplicates" class="panel"><h2>Duplicates</h2><div class="notice">Suggestions only. Paste one duplicate group, choose its canonical VIDEO_ID, then record Keep, Archive or Mark Delete per video. Nothing is deleted automatically.</div><div class="card"><label>Duplicate group JSON</label><textarea id="duplicatePlan" placeholder=\'{"group_name":"Same recording","video_ids":["ID1","ID2"]}\'></textarea><button class="primary" onclick="loadDuplicateGroup()">Preview duplicate group</button><div id="duplicateReview"></div><button class="primary" onclick="saveDuplicateReview()">Save reviewed choices</button><button onclick="location.href=\'/app?tab=tools&command=duplicate_audit\'">Open existing Duplicate Audit</button><pre id="duplicateOut"></pre></div></section>',1)
    page=page.replace('<section id="clips" class="panel"><h2>Clip Plans</h2><div class="notice">Suggestions only. Review and manually send a valid plan to existing Clip Studio; no automatic cut or merge.</div></section>', '<section id="clips" class="panel"><h2>Clip Plans</h2><div class="notice">Paste a ChatGPT clip-plan JSON. VideoHoarder validates VIDEO_IDs, timestamps, order and duration. Handoff only saves a reviewed plan; it does not cut or merge.</div><div class="card"><textarea id="clipPlanJson" placeholder=\'{"clips":[{"video_id":"...","start_timestamp":"00:10","end_timestamp":"00:30"}]}\'></textarea><button class="primary" onclick="validateClipPlan(false)">Validate clip plan</button><button class="primary" onclick="validateClipPlan(true)">Send to Clip Studio (manual)</button><pre id="clipPlanOut"></pre></div></section>',1)
    page=page.replace('<select id="coverageFeature"><option value="">All features</option>', '<select id="coverageStatus"><option value="">All statuses</option><option>MISSING</option><option>REQUESTED</option><option>RESULT_AVAILABLE</option><option>NEEDS_VALIDATION</option><option>PARTIAL</option><option>FAILED</option><option>STALE</option></select> <select id="coverageFeature"><option value="">All features</option>',1)
    page=page.replace('<div class="top">ChatGPT Processing', '<div class="top"><span class="brand-dot">●</span> ChatGPT Processing')
    page=page.replace('<main><section id="overview"', '<main><section id="overview"')
    overview_extra='''<div class="card current-work"><div class="section-head"><h3>Current Work</h3><span id="workBadge" class="badge">IDLE</span></div><div id="currentWork">No command is running.</div></div>'''
    page=page.replace('</div></section><section id="planner"', '</div>'+overview_extra+'</section><section id="planner"',1)
    reset_panel='''<div class="card"><h3>Rebuild database counts &amp; library reports</h3><p>Refreshes the main video CSV, Knowledge Center files, current video list, subscribed channel list, and count report in one folder under data/library.</p><button class="primary" onclick="rebuildLibraryReports()">Rebuild database counts &amp; library reports</button><pre id="libraryReportsOut"></pre></div><div class="card"><h3>Retry failed packages</h3><p>Creates fresh single-file uploads only for INVALID, PARTIAL or FAILED results.</p><button class="primary" onclick="retryFailedPackages()">Retry failed packages only</button><pre id="retryFailedOut"></pre></div><div class="card"><h3>Reset package history</h3><p>Clears Request History, Feature Coverage, and their Overview counters. It keeps outgoing package folders, imported result files, downloaded videos, and applied video intelligence.</p><label>Type <code>RESET PACKAGE HISTORY</code> to enable</label><input id="resetPackageHistoryText" placeholder="RESET PACKAGE HISTORY"><button class="primary" onclick="resetPackageHistory()">Reset package history</button><pre id="resetPackageHistoryOut"></pre></div>'''
    page=page.replace('<pre id="maintenanceOut"></pre></div></section>', '<pre id="maintenanceOut"></pre></div>'+reset_panel+'</section>', 1)
    css='''<style id="design1-overrides">:root{--vh-bg:#081426;--vh-panel:#0f2036;--vh-line:#294667;--vh-blue:#1670ea;--vh-muted:#9eb5d1}body{background:var(--vh-bg)!important}.top{position:sticky;top:0;z-index:3;letter-spacing:.2px}.brand-dot{color:#38d39f;margin-right:6px}nav{position:sticky;top:61px;height:calc(100vh - 61px);box-sizing:border-box}nav button{transition:background .15s,color .15s}nav button:hover{background:#193354;color:#fff}nav button[onclick*=advanced]{cursor:default;color:#7190b3;text-transform:uppercase;font-size:11px;font-weight:800;letter-spacing:1.2px;margin-top:18px;padding-bottom:3px}.card{box-shadow:0 8px 24px rgba(0,0,0,.14)}.section-head{display:flex;align-items:center;justify-content:space-between}.section-head h3{margin:0}.badge{font-size:11px;font-weight:800;letter-spacing:.7px;padding:5px 9px;border-radius:999px;background:#1b304a;color:#9eb5d1}.badge.running{background:#173f68;color:#71b8ff}.badge.success{background:#174632;color:#79e0a9}.badge.failed{background:#522331;color:#ff9eaa}.vh-check-stack{display:flex;flex-direction:column;gap:10px;margin:14px 0}.vh-check-row{display:flex!important;align-items:flex-start;gap:10px;width:100%;box-sizing:border-box;margin:0!important;padding:12px 14px;border:1px solid #355e8a;border-radius:10px;background:#0b1d34;color:#eef7ff;font-size:17px;font-weight:700;line-height:1.35}.vh-check-row input{margin-top:4px;transform:scale(1.15);accent-color:#38d39f}.vh-check-row span{display:block}.action-row{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:12px 0}.notice{clear:both;margin:12px 0}.work-grid{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:8px;margin-top:12px}.work-stat{background:#0b192b;border:1px solid #203957;border-radius:8px;padding:9px}.work-stat small{display:block;color:#7892b3;font-size:11px}.work-stat b{display:block;color:#eef5ff;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.data-table{width:100%;border-collapse:collapse;margin-top:10px}.data-table th,.data-table td{padding:10px;border-bottom:1px solid #233d5a;text-align:left}.data-table th{color:#9eb5d1;font-size:12px;text-transform:uppercase;letter-spacing:.5px}.status-chip{padding:4px 8px;border-radius:999px;background:#1b304a;color:#cfe2f7;font-size:12px}.status-chip.ok{background:#174632;color:#79e0a9}.status-chip.warn{background:#4a3b1b;color:#ffd37a}@media(max-width:900px){.layout{grid-template-columns:180px 1fr}.work-grid{grid-template-columns:repeat(2,minmax(120px,1fr))}}</style>'''
    css=css.replace('@media(max-width:900px)', '.selector-grid{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:8px;margin:8px 0}.selector-grid select{width:100%}@media(max-width:900px)')
    page=page.replace('</head>',css+'</head>',1)
    script='''<script>(function(){function bp(t){document.getElementById('batchPlanOut').textContent=t}function filters(){return{video_ids:$('ids').value,exclude_youtube_categories:$('skipEntertainment').checked?['Entertainment']:[],exclude_keywords:$('skipKeywords').value}}function jobText(j){let r=j.result||{},g=r.github_publish||{},lines=[(j.label||j.action||'Group Similar Videos')+' — '+(j.status||'WORKING'),'Phase: '+(j.phase||'Starting'),'Current: '+(j.current_file||j.current_video||'Preparing'),'Progress: '+((j.processed||0)+' / '+(j.total||'?'))];if(j.current_percent)lines.push('Percent: '+j.current_percent);if(j.current_status||j.message)lines.push('Status: '+(j.current_status||j.message));if(j.current_speed||j.current_eta)lines.push('Speed/ETA: '+(j.current_speed||'')+(j.current_eta?' ETA '+j.current_eta:''));let text=lines.join('\\n');if(r&&Object.keys(r).length){const paths=[['Local package folder',r.folder||r.local_package_folder],['Single ChatGPT upload JSON',r.upload_file],['Planner catalog CSV',r.catalog_csv],['Batch summary CSV',r.batch_summary_csv],['Batch validation CSV',r.batch_validation_csv],['Skipped no-transcript CSV',r.skipped_no_transcript_csv],['Convenience ZIP',r.upload_zip],['PUBLIC GITHUB FOLDER',g.folder_url||r.folder_url],['GitHub repository path',g.repository_path||r.repository_path],['GitHub commit',g.commit_url||r.commit_url]].filter(x=>x[1]);if(paths.length)text+='\\n\\nCreated file locations:\\n'+paths.map(x=>x[0]+': '+x[1]).join('\\n');let fileUrls=(g.file_urls||r.file_urls||[]);if(fileUrls.length)text+='\\n\\nPublic GitHub files:\\n'+fileUrls.join('\\n');text+='\\n\\nFull result:\\n'+JSON.stringify(r,null,2)}return text}function watchInline(jobId){let timer=null;async function tick(){try{const x=await api('/api/job-detail?id='+encodeURIComponent(jobId),{cache:'no-store'}),j=x.job||{};bp(jobText(j));if(['SUCCESS','WARN','FAILED','CANCELLED'].includes(j.status)){clearInterval(timer);loadOverview();if(window.loadHistory)loadHistory();if(window.loadCoverage)loadCoverage()}}catch(e){bp('Progress check failed: '+e)}}tick();timer=setInterval(tick,1000)}async function queue(action,payload){let x=await api('/api/job-start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:action,payload:payload})});if(x.ok&&x.job_id){bp((x.message||'Started')+'\\nPhase: Starting\\nCurrent: Preparing\\nProgress: 0 / ?');watchInline(x.job_id)}else bp(x.message||JSON.stringify(x,null,2));return x}window.publishLatestGithub=async function(kind){if(!confirm('Upload the latest local '+kind+' package folder to the public GitHub repository?'))return;return await queue('chatgpt_publish_latest',{kind:kind})};window.recheckBadTranscripts=async function(force){return await queue('transcript_recheck_bad',{force:!!force})};window.previewPlannerSkips=async function(){let x=await api('/api/chatgpt-processing/planner-preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(filters())});bp(JSON.stringify(x,null,2))};window.createBatchPlanner=async function(){let p=filters();p.verify_transcript_availability=$('verifyTranscriptAvailability').checked;p.recheck_bad_transcripts=$('recheckBadTranscriptsBeforeGrouping')?.checked===true;p.github_publish=$('githubPublishPlanner')?.checked===true;return await queue('chatgpt_batch_plan_create',p)};window.importBatchPlan=async function(){let f=document.getElementById('batchPlanFile')?.files[0];if(!f){bp('Select the returned planner JSON first.');return}let x=await api('/api/chatgpt-processing/import-batch-plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:f.name,result_json:await f.text()})});bp(JSON.stringify(x,null,2));if(x.valid&&$('plannerPackageId'))$('plannerPackageId').value=x.package_id};window.createFromBatchPlan=async function(){let id=$('plannerPackageId')?.value.trim();if(!id){bp('Import and validate the planner JSON first.');return}await queue('chatgpt_grouped_packages',{planner_package_id:id,features:[...document.querySelectorAll('.features input:checked')].map(x=>x.value),automatic_batch_size:$('automaticBatchSize')?.checked!==false,github_publish:$('githubPublishBatches')?.checked===true,allow_recreate_processed:$('allowRecreateProcessedBatches')?.checked===true,reset_processed_locks_before_grouping:$('resetProcessedLocksBatches')?.checked===true,refresh_library_before_grouping:$('refreshLibraryBeforeGrouping')?.checked!==false,compact_chatgpt_package:$('compactChatgptPackage')?.checked!==false,batch_size:30,no_transcript_batch_size:50})};async function refreshWork(){try{let x=await api('/api/jobs?limit=10'),items=x.items||[],j=items.find(a=>['RUNNING','QUEUED'].includes(a.status))||items[0],e=$('currentWork'),b=$('workBadge');if(!e)return;if(!j){e.textContent='No command is running.';b.textContent='IDLE';b.className='badge';return}let st=(j.status||'').toLowerCase();b.textContent=j.status||'WORKING';b.className='badge '+st;e.innerHTML='<div class="work-grid"><div class="work-stat"><small>Command</small><b>'+((j.label||j.action||'Task'))+'</b></div><div class="work-stat"><small>Phase</small><b>'+((j.phase||'Working'))+'</b></div><div class="work-stat"><small>Current</small><b>'+((j.current_file||j.current_video||'Preparing'))+'</b></div><div class="work-stat"><small>Progress</small><b>'+((j.processed||0)+' / '+(j.total||'?'))+'</b></div></div><div style="margin-top:10px;color:var(--vh-muted)">'+(j.current_status||j.message||'')+((j.current_speed||j.current_eta)?' · '+(j.current_speed||'')+' '+(j.current_eta?'· ETA '+j.current_eta:''):'')+'</div>'}catch(e){}}window.refreshWork=refreshWork;window.loadHistory=async function(){let x=await api('/api/chatgpt-processing/history'),a=x.items||x.requests||[];$('historyOut').outerHTML='<div id="historyOut"><table class="data-table"><thead><tr><th>Package</th><th>Mode</th><th>Status</th><th>Created</th></tr></thead><tbody>'+((Array.isArray(a)?a:Object.entries(a).map(([k,v])=>({package_id:k,status:v}))).map(r=>'<tr><td>'+((r.package_id||r.request_id||'—'))+'</td><td>'+((r.mode||'—'))+'</td><td><span class="status-chip '+((r.status||'').toLowerCase())+'">'+((r.status||'UNKNOWN'))+'</span></td><td>'+((r.created_at||'—'))+'</td></tr>').join('')||'<tr><td colspan="4">No requests recorded.</td></tr>')+'</tbody></table></div>'};window.loadCoverage=async function(){let f=$('coverageFeature')?.value||'',x=await api('/api/chatgpt-processing/coverage?feature='+encodeURIComponent(f)),a=x.items||x.coverage||[];if(!Array.isArray(a))a=Object.entries(a).map(([k,v])=>({video_id:k,status:v}));$('coverageOut').outerHTML='<div id="coverageOut"><table class="data-table"><thead><tr><th>Video ID</th><th>Feature</th><th>Status</th><th>Package</th></tr></thead><tbody>'+((a.map(r=>'<tr><td>'+((r.video_id||'—'))+'</td><td>'+((r.feature_id||r.feature||f||'—'))+'</td><td><span class="status-chip '+((r.status||'').toLowerCase())+'">'+((r.status||'UNKNOWN'))+'</span></td><td>'+((r.package_id||'—'))+'</td></tr>').join(''))||'<tr><td colspan="4">No coverage records.</td></tr>')+'</tbody></table></div>'};setInterval(refreshWork,1000);refreshWork()})();</script>'''
    page=page.replace("verify_transcript_availability:$('verifyTranscriptAvailability').checked,features:f", "verify_transcript_availability:$('verifyTranscriptAvailability').checked,github_publish:$('githubPublish')?.checked===true,features:f")
    clip_script='''<script>let duplicateGroup=null;function loadDuplicateGroup(){try{duplicateGroup=JSON.parse($('duplicatePlan').value);let ids=duplicateGroup.video_ids||[];$('duplicateReview').innerHTML='<label>Canonical VIDEO_ID</label><select id="canonicalDuplicate">'+ids.map(v=>'<option>'+v+'</option>').join('')+'</select><table class="data-table"><thead><tr><th>VIDEO_ID</th><th>Reviewed decision</th></tr></thead><tbody>'+ids.map(v=>'<tr><td>'+v+'</td><td><select class="duplicateChoice" data-video="'+v+'"><option value="keep">Keep</option><option value="archive">Archive</option><option value="mark_delete">Mark delete</option></select></td></tr>').join('')+'</tbody></table>'}catch(e){$('duplicateOut').textContent='Invalid duplicate JSON: '+e}}async function saveDuplicateReview(){if(!duplicateGroup){loadDuplicateGroup();if(!duplicateGroup)return}let choices=[...document.querySelectorAll('.duplicateChoice')].map(x=>({video_id:x.dataset.video,decision:x.value})),canonical_video_id=$('canonicalDuplicate').value;choices.forEach(x=>{if(x.video_id===canonical_video_id)x.decision='keep'});let r=await api('/api/chatgpt-processing/duplicate-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({group:duplicateGroup,canonical_video_id,choices})});$('duplicateOut').textContent=JSON.stringify(r,null,2)}async function validateClipPlan(handoff){let plan;try{plan=JSON.parse($('clipPlanJson').value)}catch(e){$('clipPlanOut').textContent='Invalid JSON: '+e;return}const path=handoff?'/api/chatgpt-processing/clip-plan-handoff':'/api/chatgpt-processing/clip-plan-validate';const x=await api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({plan})});if(x.clips){$('clipPlanOut').outerHTML='<div id="clipPlanOut"><table class="data-table"><thead><tr><th>Include</th><th>Order</th><th>VIDEO_ID</th><th>Start</th><th>End</th><th>Duration</th></tr></thead><tbody>'+x.clips.map(c=>'<tr><td>'+(c.included?'Yes':'No')+'</td><td>'+c.order+'</td><td>'+c.video_id+'</td><td>'+c.start+'</td><td>'+c.end+'</td><td>'+c.duration+'</td></tr>').join('')+'</tbody></table>'+(x.errors||[]).map(e=>'<div class="notice">'+e+'</div>').join('')+(handoff&&x.saved?'<p>Reviewed plan saved for manual Clip Studio handoff: '+x.saved+'</p>':'')+'</div>'}else $('clipPlanOut').textContent=JSON.stringify(x,null,2);if(handoff&&x.ok&&x.clip_studio_route)location.href=x.clip_studio_route}</script>'''
    page=page.replace("if(x.ok&&window.watchCreate)window.watchCreate(x.job_id)","if(x.ok&&x.job_id)setTimeout(()=>window.watchPlannerJob&&window.watchPlannerJob(x.job_id),0)")
    reset_script='''<script>async function retryFailedPackages(){const out=document.getElementById('retryFailedOut');const x=await api('/api/job-start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'chatgpt_retry_failed',payload:{}})});out.textContent=x.message||JSON.stringify(x,null,2)}async function rebuildLibraryReports(){const out=document.getElementById('libraryReportsOut');const x=await api('/api/job-start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'library_rebuild_exports',payload:{}})});out.textContent=x.message||JSON.stringify(x,null,2)}async function resetPackageHistory(){const text=document.getElementById('resetPackageHistoryText')?.value||'';const out=document.getElementById('resetPackageHistoryOut');if(text!=='RESET PACKAGE HISTORY'){out.textContent='Type RESET PACKAGE HISTORY exactly.';return}if(!confirm('Reset Request History, Feature Coverage, and Overview counters? Package folders and applied intelligence will be kept.'))return;const x=await api('/api/chatgpt-processing/reset-history',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm_text:text})});out.textContent=JSON.stringify(x,null,2);if(x.ok){loadOverview();if(window.loadHistory)loadHistory();if(window.loadCoverage)loadCoverage()}}</script>'''
    planner_output_script='''<script>window.openExchangeFolder=async function(folder){const x=await api('/api/open-folder',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({folder})});if(!x.ok)alert(x.message||'Could not open folder')};window.watchPlannerJob=async function(jobId){const out=document.getElementById('batchPlanOut');if(!out)return;let timer=null;async function tick(){try{const x=await api('/api/job-detail?id='+encodeURIComponent(jobId),{cache:'no-store'}),j=x.job||{},r=j.result||{};let lines=[(j.label||'Group Similar Videos')+' — '+(j.status||'WORKING'),'Phase: '+(j.phase||'Starting'),'Current: '+(j.current_file||j.current_video||'Preparing'),'Progress: '+((j.processed||0)+' / '+(j.total||'?'))];if(j.current_percent)lines.push('Percent: '+j.current_percent);if(j.current_status||j.message)lines.push('Status: '+(j.current_status||j.message));if(j.current_speed||j.current_eta)lines.push('Speed/ETA: '+(j.current_speed||'')+(j.current_eta?' ETA '+j.current_eta:''));let text=lines.join('\\n');if(['SUCCESS','WARN','FAILED','CANCELLED'].includes(j.status)){clearInterval(timer);const paths=[['Folder',r.folder],['Single ChatGPT upload JSON',r.upload_file],['Planner catalog CSV',r.catalog_csv],['Batch summary CSV',r.batch_summary_csv],['Batch validation CSV',r.batch_validation_csv],['Skipped no-transcript CSV',r.skipped_no_transcript_csv],['Convenience ZIP',r.upload_zip]].filter(x=>x[1]);if(paths.length)text+='\\n\\nCreated file locations:\\n'+paths.map(x=>x[0]+': '+x[1]).join('\\n');text+='\\n\\n'+JSON.stringify(r,null,2)}out.textContent=text}catch(e){out.textContent='Progress check failed: '+e}}await tick();timer=setInterval(tick,1000)}</script>'''
    planner_output_script=planner_output_script.replace("r=j.result||{};", "r=j.result||{},g=r.github_publish||{};")
    planner_output_script=planner_output_script.replace("['Folder',r.folder]", "['Local package folder',r.folder]")
    planner_output_script=planner_output_script.replace("['Convenience ZIP',r.upload_zip]", "['Convenience ZIP',r.upload_zip],['PUBLIC GITHUB FOLDER',g.folder_url],['GitHub repository path',g.repository_path],['GitHub commit',g.commit_url]")
    planner_output_script=planner_output_script.replace("text+='\\n\\n'+JSON.stringify(r,null,2)", "if(g.file_urls&&g.file_urls.length)text+='\\n\\nPublic GitHub files:\\n'+g.file_urls.join('\\n');text+='\\n\\nFull result:\\n'+JSON.stringify(r,null,2)")
    page=page.replace("if(j.result)out(line(j)+'\\n\\n'+JSON.stringify(j.result,null,2));loadOverview()", "if(j.result){let r=j.result,g=r.github_publish||{},paths=[['Local package folder',r.folder],['ChatGPT upload JSON',r.upload_file],['PUBLIC GITHUB FOLDER',g.folder_url],['GitHub repository path',g.repository_path],['GitHub commit',g.commit_url]].filter(x=>x[1]);out(line(j)+(paths.length?'\\n\\nCreated file locations:\\n'+paths.map(x=>x[0]+': '+x[1]).join('\\n'):'')+(g.file_urls&&g.file_urls.length?'\\n\\nPublic GitHub files:\\n'+g.file_urls.join('\\n'):'')+'\\n\\nFull result:\\n'+JSON.stringify(r,null,2))}loadOverview()")
    zip_import_script='''<script>async function importResultZip(){const f=document.getElementById('resultZip')?.files[0],out=document.getElementById('zipImportOut');if(!f){out.textContent='Select one returned ZIP file first.';return}if(f.size>100*1024*1024){out.textContent='ZIP exceeds the 100 MB safety limit.';return}out.textContent='Reading and validating '+f.name+'…';const bytes=new Uint8Array(await f.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));const x=await api('/api/chatgpt-processing/import-zip',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:f.name,zip_base64:btoa(binary)})});out.textContent=JSON.stringify(x,null,2);if(x.ok){loadOverview();if(window.loadHistory)loadHistory();if(window.loadCoverage)loadCoverage()}}async function importGithubResults(){const out=document.getElementById('githubImportOut');out.textContent='Pulling authorized GitHub repository and validating returned files...';const x=await api('/api/chatgpt-processing/import-github',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({archive_processed:document.getElementById('githubArchiveProcessed')?.checked!==false})});out.textContent=JSON.stringify(x,null,2);if(x.ok){loadOverview();if(window.loadHistory)loadHistory();if(window.loadCoverage)loadCoverage()}}</script>'''
    return page.replace('</body>',script+clip_script+reset_script+planner_output_script+zip_import_script+'</body>')

def chatgpt_processing_page_html_v10():
    # Add an optional OpenAI Responses API path without removing manual exchange.
    page=chatgpt_processing_page_html_v9()
    page=page.replace("Manual Exchange Command Center","Manual Exchange + OpenAI API",1)
    page=page.replace(
        '<div class="card"><h3>Quick actions</h3>',
        '''<div class="card" id="openaiApiCard"><h3>Optional OpenAI API transcript processing</h3>
        <p>Use the same validated VideoHoarder package contract, but submit each video separately through the OpenAI Responses API. The API key is read from an environment variable and is never stored by VideoHoarder. Results are imported into the normal validation/review queue and are <b>never applied automatically</b>.</p>
        <div id="openaiApiStatus" class="notice">Checking OpenAI API readiness...</div>
        <label>Existing package ID</label><input id="openaiPackageId" style="width:100%" placeholder="vh_full_intelligence_...">
        <p><button onclick="loadOpenAIStatus()">Refresh API status</button> <button class="primary" onclick="submitExistingOpenAI()">Process existing package via API</button> <button class="primary" onclick="createAndSubmitOpenAI()">Create current selection + process via API</button></p>
        <pre id="openaiApiOut"></pre></div><div class="card"><h3>Quick actions</h3>''',
        1,
    )
    script = r'''<script>(function(){
function oaOut(t){const e=document.getElementById('openaiApiOut');if(e)e.textContent=t}
window.loadOpenAIStatus=async function(){try{const x=await api('/api/chatgpt-processing/openai-status',{cache:'no-store'}),e=document.getElementById('openaiApiStatus');if(e)e.innerHTML='<b>'+(x.ready?'READY':'NOT READY')+'</b> - '+(x.message||'')+'<br>Model: '+(x.model||'')+' | Reasoning: '+(x.reasoning_effort||'')+' | Key source: '+(x.api_key_env||'OPENAI_API_KEY')+' | Responses stored by provider: '+(x.store_responses?'yes':'no')}catch(err){oaOut('Could not read API status: '+err)}};
async function watchOpenAIJob(jobId){let timer=null;async function tick(){try{const x=await api('/api/job-detail?id='+encodeURIComponent(jobId),{cache:'no-store'}),j=x.job||{},r=j.result||{};let t=(j.label||'OpenAI API')+' - '+(j.status||'WORKING')+'\nPhase: '+(j.phase||j.stage||'Starting')+'\nCurrent: '+(j.current_file||'Preparing')+'\nProgress: '+(j.processed||0)+' / '+(j.total||'?')+'\n'+(j.current_status||j.message||'');if(['SUCCESS','WARN','FAILED','CANCELLED'].includes(j.status)){if(timer)clearInterval(timer);t+='\n\n'+JSON.stringify(r,null,2)}oaOut(t)}catch(err){oaOut('Progress check failed: '+err)}}await tick();timer=setInterval(tick,1000)}
window.submitExistingOpenAI=async function(){const packageId=(document.getElementById('openaiPackageId')?.value||'').trim();if(!packageId){oaOut('Enter an existing package ID first.');return}oaOut('Queueing OpenAI API processing...');const x=await api('/api/chatgpt-processing/openai-submit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({package_id:packageId})});if(!x.ok){oaOut(x.message||JSON.stringify(x,null,2));return}watchOpenAIJob(x.job_id)};
window.createAndSubmitOpenAI=async function(){const f=[...document.querySelectorAll('.features input:checked')].map(x=>x.value),mode=document.getElementById('mode')?.value||'MASTER';if(mode==='SMART_QUALITY'){oaOut('Create + API uses one package at a time. Choose MASTER/FOCUSED/etc., or create SMART_QUALITY packages first and process an existing package ID.');return}const payload={mode:mode,video_ids:document.getElementById('ids')?.value||'',folderScope:document.getElementById('folderScope')?.value||'',topicScope:document.getElementById('topicScope')?.value||'',categoryScope:document.getElementById('categoryScope')?.value||'',verify_transcript_availability:document.getElementById('verifyTranscriptAvailability')?.checked!==false,features:f};oaOut('Creating package and queueing isolated API processing...');const x=await api('/api/chatgpt-processing/openai-create-submit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!x.ok){oaOut(x.message||JSON.stringify(x,null,2));return}watchOpenAIJob(x.job_id)};
setTimeout(()=>window.loadOpenAIStatus&&window.loadOpenAIStatus(),50);
})();</script>'''
    return page.replace('</body>',script+'</body>')

def chatgpt_processing_page_html():
    return chatgpt_processing_page_html_v10()
    # Legacy embedded page retained below for source compatibility.
    feature_options=''.join(f'<label><input type="checkbox" value="{html.escape(k)}" checked> {html.escape(k)} — {html.escape(v)}</label>' for k,v in CHATGPT_FEATURES.items())
    return '''<!doctype html><html><head><meta charset="utf-8"><style>body{margin:0;background:#081426;color:#eef5ff;font:15px Segoe UI,Arial}.top{padding:18px 24px;background:#0e2038;border-bottom:1px solid #294667;font-size:22px;font-weight:700}.layout{display:grid;grid-template-columns:220px 1fr;min-height:calc(100vh - 61px)}nav{background:#0b1a2d;border-right:1px solid #294667;padding:14px}nav button{display:block;width:100%;text-align:left;margin:5px 0;background:transparent;border:0;color:#b9cae2;padding:11px;border-radius:8px;font-size:14px}nav button:hover{background:#193354;color:#fff}main{padding:22px;max-width:1250px}.notice{background:#13325a;border:1px solid #2f649b;padding:14px;border-radius:10px;color:#d9ecff}.grid{display:grid;grid-template-columns:repeat(3,minmax(180px,1fr));gap:12px;margin:15px 0}.card{background:#0f2036;border:1px solid #294667;border-radius:12px;padding:16px}.count{font-size:30px;font-weight:700;color:#fff}.panel{display:none}.panel.active{display:block}textarea,select{width:100%;box-sizing:border-box;background:#071120;color:#fff;border:1px solid #315273;border-radius:7px;padding:9px}textarea{height:90px}button.primary{background:#1670ea;color:#fff;border:0;border-radius:8px;padding:11px 14px;font-weight:700}.features label{display:block;color:#c8d8ed;margin:7px 0}pre{white-space:pre-wrap;max-height:420px;overflow:auto;background:#071120;padding:12px;border-radius:8px}</style></head><body><div class="top">◇ ChatGPT Processing <span style="font-size:13px;color:#9eb5d1">Manual Exchange Command Center</span></div><div class="layout"><nav>'''+''.join(f'<button onclick="show(\'{x}\')">{label}</button>' for x,label in [('overview','Overview'),('create','Create Package'),('history','Request History'),('coverage','Feature Coverage'),('import','Import & Validate'),('review','Review & Apply'),('duplicates','Duplicates'),('clips','Clip Plans'),('maintenance','Maintenance')])+'''</nav><main><section id="overview" class="panel active"><div class="notice"><b>Manual exchange safety:</b> VideoHoarder never uploads data to ChatGPT. It creates local packages only; you upload them manually and manually select returned JSON for import.</div><div id="counters" class="grid"></div><div class="card"><h3>Six-step manual flow</h3>Select → Review evidence → Create package → Upload manually → Import & validate → Review & apply.</div><div class="card"><h3>Quick actions</h3><button class="primary" onclick="show('create')">Create package</button> <button class="primary" onclick="show('history')">View history</button> <button class="primary" onclick="show('coverage')">Feature coverage</button></div></section><section id="create" class="panel"><h2>Create Package</h2><div class="card"><label>Mode</label><select id="mode"><option>MASTER</option><option>FOCUSED</option><option>TAXONOMY</option><option>SAME_TOPIC</option><option>FEATURE_ENRICHMENT</option></select><label>VIDEO_IDs (optional; blank selects eligible active videos)</label><textarea id="ids"></textarea><div class="features">'''+feature_options+'''</div><button class="primary" onclick="createPackage()">Create local manual package</button><pre id="createOut"></pre></div></section><section id="history" class="panel"><h2>Request History</h2><pre id="historyOut"></pre></section><section id="coverage" class="panel"><h2>Feature Coverage</h2><select id="coverageFeature"><option value="">All features</option>'''+''.join(f'<option value="{html.escape(k.split(".")[0])}">{html.escape(k)}</option>' for k in CHATGPT_FEATURES)+'''</select> <button class="primary" onclick="loadCoverage()">Refresh matrix</button><pre id="coverageOut"></pre></section><section id="import" class="panel"><h2>Import & Validate</h2><div class="notice">Manual only. Select a returned JSON in the existing ChatGPT Exchange area, then validate it before any apply. No changes are applied automatically.</div></section><section id="review" class="panel"><h2>Review & Apply</h2><div class="notice">Use the existing reviewed rename, category-move preview, metadata, taxonomy, report refresh and undo systems. No physical rename or folder move happens automatically.</div></section><section id="duplicates" class="panel"><h2>Duplicates</h2><div class="notice">Duplicate suggestions are manual. Choose a canonical video and manually keep, archive, mark delete, or delete. No automatic deletion.</div></section><section id="clips" class="panel"><h2>Clip Plans</h2><div class="notice">ChatGPT clip plans are suggestions only. Review and manually send a valid plan to existing Clip Studio; no automatic cut or merge.</div></section><section id="maintenance" class="panel"><h2>Maintenance</h2><div class="notice">Use existing package-integrity, comment-intelligence, legacy sync and audit tools. All operations remain local and traceable.</div></section></main></div><script>const $=x=>document.getElementById(x);async function api(u,o){return await fetch(u,o).then(r=>r.json())}function show(id){document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));$(id).classList.add('active');if(id==='overview')loadOverview();if(id==='history')loadHistory();if(id==='coverage')loadCoverage()}async function loadOverview(){let x=await api('/api/chatgpt-processing/overview'),c=x.counters||{};$('counters').innerHTML=[['Package sets',c.package_sets||0],['Videos with intelligence',c.videos_with_intelligence||0],['Feature updates',c.feature_updates||0]].map(v=>`<div class="card"><div>${v[0]}</div><div class="count">${v[1]}</div></div>`).join('')}async function createPackage(){let f=[...document.querySelectorAll('.features input:checked')].map(x=>x.value);let x=await api('/api/chatgpt-processing/create',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:$('mode').value,video_ids:$('ids').value,features:f})});$('createOut').textContent=JSON.stringify(x,null,2);loadOverview()}async function loadHistory(){$('historyOut').textContent=JSON.stringify(await api('/api/chatgpt-processing/history'),null,2)}async function loadCoverage(){$('coverageOut').textContent=JSON.stringify(await api('/api/chatgpt-processing/coverage?feature='+encodeURIComponent($('coverageFeature').value)),null,2)}loadOverview()</script></body></html>'''

