def ask_use_ollama_for_run():
    """
    Explicit per-run Ollama choice.
    Returns:
      True  -> enable local LLM/Ollama
      False -> disable local LLM/Ollama
      None  -> cancel
    """
    print("")
    print("Use Ollama / Local LLM for this run?")
    print("1 = Yes")
    print("2 = No")
    print("0 = Cancel")
    choice=input("Choose: ").strip()

    if choice=="1":
        return True
    if choice=="2":
        return False
    return None


def run_download_with_ollama_choice(smart_resume=False):
    use_ollama=ask_use_ollama_for_run()
    if use_ollama is None:
        print("Cancelled.")
        return

    old_use_llm=RUNTIME.get("use_llm")
    old_resume=RUNTIME.get("smart_resume")
    old_resume_mode=RUNTIME.get("resume_mode")

    RUNTIME["use_llm"]=bool(use_ollama)
    RUNTIME["smart_resume"]=bool(smart_resume)
    if smart_resume:
        RUNTIME["resume_mode"]="smart"

    print("")
    print(f"Ollama / Local LLM: {'ENABLED' if use_ollama else 'DISABLED'}")
    if smart_resume:
        print("Smart Resume: ENABLED")

    try:
        result=download_stage()
        print_all_downloads_done_banner()
        return result
    finally:
        if old_use_llm is None:
            RUNTIME.pop("use_llm",None)
        else:
            RUNTIME["use_llm"]=old_use_llm

        if old_resume is None:
            RUNTIME.pop("smart_resume",None)
        else:
            RUNTIME["smart_resume"]=old_resume

        if old_resume_mode is None:
            RUNTIME.pop("resume_mode",None)
        else:
            RUNTIME["resume_mode"]=old_resume_mode



def smart_resume_queue_txt_path():
    p=BASE/"logs"/"smart_resume_queue.txt"
    p.parent.mkdir(parents=True,exist_ok=True)
    return p


def transcript_retry_state_path():
    p=BASE/"data"/"database"/"transcript_retry_state.json"
    p.parent.mkdir(parents=True,exist_ok=True)
    return p


def load_transcript_retry_state():
    p=transcript_retry_state_path()
    if not p.exists():
        return {}
    try:
        obj=json.loads(p.read_text(encoding="utf-8"))
        return obj if isinstance(obj,dict) else {}
    except Exception:
        return {}


def save_transcript_retry_state(state):
    transcript_retry_state_path().write_text(
        json.dumps(state,ensure_ascii=False,indent=2),
        encoding="utf-8"
    )


def transcript_retry_count(video_id):
    state=load_transcript_retry_state()
    rec=state.get(str(video_id),{})
    try:
        return int(rec.get("attempts") or 0)
    except Exception:
        return 0


def increment_transcript_retry(video_id, reason=""):
    state=load_transcript_retry_state()
    vid=str(video_id)
    rec=state.get(vid,{})
    attempts=int(rec.get("attempts") or 0)+1
    state[vid]={
        "attempts":attempts,
        "last_reason":str(reason or ""),
        "updated_at":time.strftime("%Y-%m-%d %H:%M:%S")
    }
    save_transcript_retry_state(state)
    return attempts


def clear_transcript_retry(video_id):
    state=load_transcript_retry_state()
    if str(video_id) in state:
        state.pop(str(video_id),None)
        save_transcript_retry_state(state)


def has_usable_transcript(video_id):
    folder=locate_existing_folder(video_id)
    if folder:
        folder=Path(folder)
        data=support_dir(folder)
        for pat in ("*.transcript.txt","*.transcript_timestamped.txt","*.transcript_clean.txt","*.srt","*.vtt"):
            for p in data.glob(pat):
                try:
                    if p.is_file() and p.stat().st_size>0 and transcript_has_useful_speech(p.read_text(encoding="utf-8",errors="replace")):
                        return True
                except Exception:
                    pass

    for root in (temp_transcript_root(),temp_short_video_root()):
        tdir=root/str(video_id)
        if tdir.exists():
            for pat in ("*.timestamped.txt","*.clean.txt","*.srt","*.vtt","*.txt"):
                for p in tdir.glob(pat):
                    try:
                        if p.is_file() and p.stat().st_size>0 and transcript_has_useful_speech(p.read_text(encoding="utf-8",errors="replace")):
                            return True
                    except Exception:
                        pass
    return False


def smart_resume_queue_items():
    """
    Smart Resume driven entirely by Video-ID artifact inventory.

    Queue:
      1. media missing -> download
      2. transcript missing with retry count < 2 -> transcript retry
    Ignore other optional missing artifacts.
    """
    con=db_connect()
    rows=con.execute(
        "SELECT video_id,url,original_title,clean_title,channel FROM videos WHERE COALESCE(current_present,1)=1 AND COALESCE(deleted_from_library,0)=0 ORDER BY rowid"
    ).fetchall()
    con.close()

    items=[]

    for vid,url,orig,clean,channel in rows:
        title=clean or orig or ""
        inv=artifact_inventory(vid)

        if not inv["media"]:
            items.append({
                "video_id":vid,
                "url":url or "",
                "title":title,
                "channel":channel or "",
                "action":"DOWNLOAD_VIDEO",
                "reason":"VIDEO MEDIA MISSING",
                "transcript_attempts":transcript_retry_count(vid)
            })
            continue

        if inv["timestamped_transcript"] or inv["clean_transcript"] or inv["subtitle"]:
            clear_transcript_retry(vid)
            mark_failed_video_retry_status(vid,"RESOLVED")
            continue

        attempts=transcript_retry_count(vid)
        if attempts < 2:
            items.append({
                "video_id":vid,
                "url":url or "",
                "title":title,
                "channel":channel or "",
                "action":"RETRY_TRANSCRIPT",
                "reason":f"TRANSCRIPT MISSING - ATTEMPT {attempts+1}/2",
                "transcript_attempts":attempts
            })
        else:
            mark_failed_video_retry_status(vid,"RESOLVED")

    return items


def rebuild_smart_resume_queue_txt():
    items=smart_resume_queue_items()
    p=smart_resume_queue_txt_path()
    lines=[]

    if not items:
        lines=["No Smart Resume items.", "", "Queue includes only: video media missing OR transcript missing with fewer than 2 attempts."]
    else:
        for i,item in enumerate(items,1):
            lines.extend([
                f"{i}. Video ID: {item['video_id']}",
                f"URL: {item['url']}",
                f"Title: {item['title']}",
                f"Channel: {item['channel']}",
                f"Action: {item['action']}",
                f"Reason: {item['reason']}",
                "-"*80
            ])

    p.write_text("\n".join(lines)+"\n",encoding="utf-8")
    return p,items


def show_smart_resume_queue():
    p,items=rebuild_smart_resume_queue_txt()
    print("")
    print("===== SMART RESUME QUEUE =====")
    if not items:
        print("No items require Smart Resume.")
    else:
        for i,item in enumerate(items,1):
            print(f"{i}. {item['video_id']} | {item['action']} | {item['title']}")
            print(f"   {item['reason']}")
    print(f"Queue file: {p}")


def reconcile_existing_smart_resume_state():
    """
    Apply strict Smart Resume policy to existing DB/failure state.
    If video exists:
      - transcript present => resolve
      - transcript missing and attempts >=2 => resolve/ignore
      - transcript missing and attempts <2 => queue it
    If video missing => queue it.
    """
    p,items=rebuild_smart_resume_queue_txt()
    queued={x["video_id"] for x in items}

    con=db_connect()
    vids=[r[0] for r in con.execute("SELECT video_id FROM videos WHERE COALESCE(current_present,1)=1 AND COALESCE(deleted_from_library,0)=0").fetchall()]
    con.close()

    resolved=0
    for vid in vids:
        if vid not in queued:
            mark_failed_video_retry_status(vid,"RESOLVED")
            resolved+=1

    rebuild_failed_videos_txt()
    print("Smart Resume existing-state reconciliation complete.")
    print("Only missing-video and transcript-retry items remain queued.")
    print(f"Queued   : {len(items)}")
    print(f"Resolved : {resolved}")
    print(f"Queue    : {p}")
    return p

def smart_resume_artifact_status(video_id):
    """
    Return only queue-relevant state.

    COMPLETE  = video exists and transcript exists, or transcript attempts exhausted
    RETRY     = video exists, transcript missing, attempts < 2
    DOWNLOAD  = video media missing
    """
    vid=str(video_id or "").strip()

    con=db_connect()
    row=con.execute(
        "SELECT local_folder,local_video FROM videos WHERE video_id=?",
        (vid,)
    ).fetchone()
    con.close()

    folder=locate_existing_folder(vid)
    if folder is None and row and row[0] and Path(row[0]).exists():
        folder=Path(row[0])

    media=None
    if folder:
        media=find_any_media(folder)
    if not media and row and row[1] and Path(row[1]).exists():
        media=Path(row[1])

    media_ok=False
    try:
        media_ok=bool(media and Path(media).exists() and Path(media).stat().st_size>0)
    except Exception:
        media_ok=False

    if not media_ok:
        return {
            "video_id":vid,
            "action":"DOWNLOAD",
            "reason":"Video media missing",
            "folder":str(folder or "")
        }

    if has_usable_transcript(vid):
        clear_transcript_retry(vid)
        mark_failed_video_retry_status(vid,"RESOLVED")
        return {
            "video_id":vid,
            "action":"COMPLETE",
            "reason":"Video and transcript available",
            "folder":str(folder or "")
        }

    attempts=transcript_retry_count(vid)
    if attempts < 2:
        return {
            "video_id":vid,
            "action":"RETRY",
            "reason":f"Transcript missing - attempt {attempts+1}/2",
            "folder":str(folder or "")
        }

    mark_failed_video_retry_status(vid,"RESOLVED")
    return {
        "video_id":vid,
        "action":"COMPLETE",
        "reason":"Video downloaded; transcript unavailable after 2 attempts; ignored",
        "folder":str(folder or "")
    }


def smart_resume_full_library_audit():
    """Audit every SQLite VIDEO_ID and classify it as SKIP / REPAIR / DOWNLOAD."""
    con=db_connect()
    rows=con.execute("SELECT video_id,original_title FROM videos ORDER BY rowid").fetchall()
    con.close()

    counts={"SKIP":0,"REPAIR":0,"DOWNLOAD":0}
    details=[]
    for vid,title in rows:
        st=smart_resume_artifact_status(vid)
        raw=str(st.get("action") or "DOWNLOAD").upper()
        action="SKIP" if raw=="COMPLETE" else ("REPAIR" if raw=="RETRY" else "DOWNLOAD")
        counts[action]+=1
        inv=artifact_inventory(vid)
        artifact_flags={
            "Media":bool(inv.get("media")),
            "Subtitle":bool(inv.get("subtitle")),
            "Timestamped Transcript":bool(inv.get("timestamped_transcript")),
            "Clean Transcript":bool(inv.get("clean_transcript")),
            "HTML Report":bool(inv.get("html_report")),
            "Info JSON":bool(inv.get("info_json")),
        }
        details.append({"video_id":vid,"title":title or "","action":action,"reason":st.get("reason") or "","folder":st.get("folder") or "","artifacts":artifact_flags})
        print("")
        print(f"{action} {vid} | {title or ''}")
        if st.get("folder"): print(f"  Folder : {st.get('folder')}")
        print(f"  Reason : {st.get('reason') or ''}")
        for name,ok in artifact_flags.items(): print(f"    {'OK' if ok else 'MISSING':7} {name}")

    print("")
    print("Smart Resume full-library artifact audit")
    print(f"SKIP    : {counts['SKIP']}")
    print(f"REPAIR  : {counts['REPAIR']}")
    print(f"DOWNLOAD: {counts['DOWNLOAD']}")
    return {"ok":True,"counts":counts,"videos":len(rows),"details":details}


