def rebuild_all_html_reports_with_approved_titles():
    con=db_connect()
    rows=con.execute(
        "SELECT video_id,local_folder FROM videos WHERE downloaded=1 ORDER BY rowid"
    ).fetchall()
    con.close()

    rebuilt=skipped=failed=0

    for vid,folder in rows:
        if not folder or not Path(folder).exists():
            skipped+=1
            continue
        try:
            title=resolved_approved_title(vid)
            rebuild_report_after_rename(
                vid,
                Path(folder),
                title
            )
            rebuilt+=1
        except Exception as ex:
            failed+=1
            log(
                f"Rebuild HTML failed {vid}: "
                f"{type(ex).__name__}: {ex}"
            )

    print("")
    print("Rebuild All HTML Reports complete")
    print(f"Rebuilt : {rebuilt}")
    print(f"Skipped : {skipped}")
    print(f"Failed  : {failed}")
    return rebuilt,skipped,failed


