def phase5_doc_hash(doc):
    base="|".join([
        str(doc.get("video_id","")),
        str(doc.get("title","")),
        str(doc.get("downloaded_at","")),
        str(doc.get("summary_text",""))[:10000],
        str(doc.get("intelligence_text",""))[:5000],
        str(doc.get("transcript_text",""))[:10000],
        "|".join(doc.get("topics") or []),
    ])
    return hashlib.sha256(base.encode("utf-8",errors="ignore")).hexdigest()


def phase5_search_snippet(doc,query,max_chars=240):
    text=str(doc.get("search_text") or "")
    q=str(query or "").strip().lower()
    if not text or not q:
        return ""
    low=text.lower()
    pos=low.find(q)
    if pos<0:
        toks=phase5_tokens(q)
        for tok in toks:
            pos=low.find(tok)
            if pos>=0: break
    if pos<0:
        return ""
    start=max(0,pos-max_chars//2)
    end=min(len(text),start+max_chars)
    snippet=re.sub(r"\s+"," ",text[start:end]).strip()
    if start>0: snippet="…"+snippet
    if end<len(text): snippet+="…"
    return snippet


def phase5_duplicate_topic_groups(docs,min_group=2):
    groups=defaultdict(list)
    for d in docs:
        for topic in d.get("topics") or []:
            groups[topic].append(d)
    return {
        topic:items for topic,items in groups.items()
        if len(items)>=min_group
    }


def phase5_best_video_by_topic(docs):
    best={}
    for d in docs:
        for topic in d.get("topics") or []:
            cur=best.get(topic)
            key=(int(d.get("user_rating") or 0),int(d.get("worth_watching_score") or 0),str(d.get("downloaded_at") or ""))
            if cur is None:
                best[topic]=d
            else:
                curkey=(int(cur.get("user_rating") or 0),int(cur.get("worth_watching_score") or 0),str(cur.get("downloaded_at") or ""))
                if key>curkey: best[topic]=d
    return best


def phase5_maintenance_stats(docs):
    stats={
        "failed":0,"staging":0,"missing_summary":0,"missing_transcript":0,
        "pending_delete":0,"archived":0,"favorites":0,"unwatched":0
    }
    try:
        p=failed_videos_csv_path()
        if p.exists():
            with open(p,"r",encoding="utf-8-sig",newline="") as f:
                stats["failed"]=sum(1 for _ in csv.DictReader(f))
    except Exception: pass
    try:
        sr=staging_root()
        stats["staging"]=sum(1 for p in sr.iterdir() if p.is_dir()) if sr.exists() else 0
    except Exception: pass

    for d in docs:
        if not d.get("summary_text"): stats["missing_summary"]+=1
        if not (d.get("transcript_text") or ""): stats["missing_transcript"]+=1
        if int(d.get("archived") or 0): stats["archived"]+=1
        if int(d.get("favorite") or 0): stats["favorites"]+=1
        if not int(d.get("watched") or 0): stats["unwatched"]+=1
        try:
            f=Path(d.get("local_folder") or "")
            if f.exists() and (f/".delete").exists(): stats["pending_delete"]+=1
        except Exception: pass
    return stats


