def phase5_build_topic_pages():
    docs=phase5_load_search_index()
    root,search_dir,topics_dir,channels_dir,related_dir=phase5_dirs()

    if topics_dir.exists():
        shutil.rmtree(topics_dir)
    topics_dir.mkdir(parents=True,exist_ok=True)

    buckets=defaultdict(list)
    for d in docs:
        for topic in d.get("topics") or []:
            if str(topic).strip():
                buckets[str(topic).strip()].append(d)

    css="""body{font-family:Segoe UI,Arial;margin:24px;background:#f6f8fb;color:#1f2937}
    a{color:#1d4ed8;text-decoration:none}.card{background:#fff;padding:14px;margin:12px 0;
    border-radius:10px;box-shadow:0 1px 5px rgba(0,0,0,.08)}.meta{color:#64748b;font-size:.9rem}"""

    master=[
        "<html><head><meta charset='utf-8'><style>"+css+"</style></head><body>",
        "<h1>Cross-Video Topic Index</h1>"
    ]

    for topic in sorted(buckets,key=str.lower):
        items=sorted(
            buckets[topic],
            key=lambda d:(d.get("worth_watching_score",0),d.get("upload_date","")),
            reverse=True
        )
        fname=safe_name(topic)[:100]+".html"
        master.append(
            f"<div class='card'><a href='{htmlmod.escape(fname)}'><b>{htmlmod.escape(topic)}</b></a> "
            f"({len(items)} videos)</div>"
        )

        page=[
            "<html><head><meta charset='utf-8'><style>"+css+"</style></head><body>",
            f"<h1>{htmlmod.escape(topic)}</h1>"
        ]
        for d in items:
            title=htmlmod.escape(str(d.get("title") or d["video_id"]))
            report=d.get("report_html")
            if report and Path(report).exists():
                try:
                    title_html=f"<a href='{htmlmod.escape(Path(report).resolve().as_uri())}'>{title}</a>"
                except Exception:
                    title_html=title
            else:
                title_html=title

            thumb_html=""
            if d.get("thumbnail") and Path(d["thumbnail"]).exists():
                try:
                    thumb_html=f"<img src='{htmlmod.escape(Path(d['thumbnail']).resolve().as_uri())}' style='width:180px;max-width:100%;border-radius:8px;margin-bottom:8px'>"
                except Exception:
                    thumb_html=""

            page.append(
                "<div class='card'>"
                +thumb_html+
                f"<div><b>{title_html}</b></div>"
                f"<div class='meta'>{htmlmod.escape(d.get('upload_date',''))} · "
                f"{htmlmod.escape(d.get('channel',''))} · {htmlmod.escape(d.get('category','Other'))} · "
                f"Worth Watching {d.get('worth_watching_score',0)}/100</div>"
                "</div>"
            )
        page.append("</body></html>")
        (topics_dir/fname).write_text("\n".join(page),encoding="utf-8")

    master.append("</body></html>")
    out=topics_dir/"index.html"
    out.write_text("\n".join(master),encoding="utf-8")
    print(f"Topic index: {out}")
    return out


def phase5_related_for_video(video_id,limit=8):
    docs=phase5_load_search_index()
    by_id={d["video_id"]:d for d in docs}
    base=by_id.get(str(video_id))
    if not base:
        return []

    base_topics=set(phase5_tokens(" ".join(base.get("topics") or [])))
    base_tokens=set((base.get("token_counts") or {}).keys())
    scored=[]

    for d in docs:
        if d["video_id"]==base["video_id"]:
            continue
        topics=set(phase5_tokens(" ".join(d.get("topics") or [])))
        toks=set((d.get("token_counts") or {}).keys())

        topic_overlap=len(base_topics & topics)
        union=len(base_tokens | toks) or 1
        lexical=len(base_tokens & toks)/union
        channel_bonus=0.15 if d.get("channel")==base.get("channel") else 0
        score=topic_overlap*2.5 + lexical*10 + channel_bonus

        if score>0.3:
            scored.append((score,d))

    scored.sort(key=lambda x:(x[0],x[1].get("worth_watching_score",0)),reverse=True)
    return scored[:limit]


def phase5_build_related_video_files():
    docs=phase5_load_search_index()
    related_dir=phase5_dirs()[4]
    if related_dir.exists():
        shutil.rmtree(related_dir)
    related_dir.mkdir(parents=True,exist_ok=True)

    for d in docs:
        hits=phase5_related_for_video(d["video_id"],8)
        payload={
            "video_id":d["video_id"],
            "title":d["title"],
            "related":[
                {
                    "score":round(score,3),
                    "video_id":x["video_id"],
                    "title":x["title"],
                    "channel":x["channel"],
                    "report_html":x.get("report_html",""),
                    "worth_watching_score":x.get("worth_watching_score",0)
                }
                for score,x in hits
            ]
        }
        (related_dir/f"{d['video_id']}.related.json").write_text(
            json.dumps(payload,ensure_ascii=False,indent=2),
            encoding="utf-8"
        )

    print(f"Related-video files: {related_dir}")
    return related_dir


def phase5_build_channel_reports():
    docs=phase5_load_search_index()
    channels_dir=phase5_dirs()[3]
    if channels_dir.exists():
        shutil.rmtree(channels_dir)
    channels_dir.mkdir(parents=True,exist_ok=True)

    buckets=defaultdict(list)
    for d in docs:
        buckets[d.get("channel") or "Unknown"].append(d)

    css="""body{font-family:Segoe UI,Arial;margin:24px;background:#f6f8fb;color:#1f2937}
    .card{background:white;padding:14px;border-radius:10px;margin:10px 0}
    .meta{color:#64748b}.tag{display:inline-block;background:#e2e8f0;padding:4px 8px;
    margin:3px;border-radius:12px}"""

    master=["<html><head><meta charset='utf-8'><style>"+css+"</style></head><body>",
            "<h1>Channel Knowledge Reports</h1>"]

    for channel,items in sorted(buckets.items(),key=lambda x:x[0].lower()):
        topic_counts=Counter()
        for d in items:
            topic_counts.update(d.get("topics") or [])
        avg=round(sum(d.get("worth_watching_score",0) for d in items)/max(1,len(items)),1)
        fname=safe_name(channel)[:100]+".html"

        master.append(
            f"<div class='card'><a href='{htmlmod.escape(fname)}'><b>{htmlmod.escape(channel)}</b></a> "
            f"· {len(items)} videos · avg Worth Watching {avg}/100</div>"
        )

        page=[
            "<html><head><meta charset='utf-8'><style>"+css+"</style></head><body>",
            f"<h1>{htmlmod.escape(channel)}</h1>",
            f"<p>{len(items)} videos · Average Worth Watching: {avg}/100</p>",
            "<h2>Major Topics</h2><div>"
        ]
        for topic,count in topic_counts.most_common(25):
            page.append(f"<span class='tag'>{htmlmod.escape(str(topic))} ({count})</span>")
        page.append("</div><h2>Videos</h2>")

        for d in sorted(items,key=lambda x:x.get("upload_date",""),reverse=True):
            thumb_html=""
            if d.get("thumbnail") and Path(d["thumbnail"]).exists():
                try:
                    thumb_html=f"<img src='{htmlmod.escape(Path(d['thumbnail']).resolve().as_uri())}' style='width:180px;max-width:100%;border-radius:8px;margin-bottom:8px'><br>"
                except Exception:
                    thumb_html=""
            page.append(
                "<div class='card'>"
                +thumb_html+
                f"<b>{htmlmod.escape(d.get('title',''))}</b><br>"
                f"<span class='meta'>{htmlmod.escape(d.get('upload_date',''))} · "
                f"{htmlmod.escape(d.get('category','Other'))} · "
                f"Worth Watching {d.get('worth_watching_score',0)}/100</span>"
                "</div>"
            )
        page.append("</body></html>")
        (channels_dir/fname).write_text("\n".join(page),encoding="utf-8")

    master.append("</body></html>")
    out=channels_dir/"index.html"
    out.write_text("\n".join(master),encoding="utf-8")
    print(f"Channel reports: {out}")
    return out


def phase5_build_all():
    print("===== PHASE 5 - KNOWLEDGE & SEARCH =====")

    # 1. Incremental searchable corpus + Excel-readable CSV.
    docs=phase5_build_search_index(incremental=True)

    # 2. Cross-video content products.
    phase5_build_topic_pages()
    phase5_build_related_video_files()
    phase5_build_channel_reports()

    # 3. Rebuild only HTML reports whose taxonomy changed.
    report_rebuilt,report_skipped,report_failed=smart_rebuild_reports_for_taxonomy()
    print(
        f"Taxonomy HTML reports: rebuilt={report_rebuilt}, "
        f"skipped={report_skipped}, failed={report_failed}"
    )

    # 4. Taxonomy quality/statistics/integrity audits.
    phase5_export_taxonomy_audits()
    integrity_path,integrity_issues=phase5_integrity_audit()
    print(f"Integrity audit: {integrity_path} | issues={integrity_issues}")

    # 5. Browser dashboard + root project copy.
    dashboard=phase5_build_dashboard()

    # 4. Duplicate-topic and best-video exports.
    try:
        dup=phase5_duplicate_topic_groups(docs,2)
        best=phase5_best_video_by_topic(docs)
        knowledge_root=phase5_dirs()[0]

        with open(
            knowledge_root/"phase5_duplicate_topics.csv",
            "w",newline="",encoding="utf-8-sig"
        ) as f:
            w=csv.writer(f)
            w.writerow(["Topic","Video Count","Video IDs"])
            for topic,items in sorted(
                dup.items(),
                key=lambda x:len(x[1]),
                reverse=True
            ):
                w.writerow([
                    topic,
                    len(items),
                    " | ".join(x["video_id"] for x in items)
                ])

        with open(
            knowledge_root/"phase5_best_by_topic.csv",
            "w",newline="",encoding="utf-8-sig"
        ) as f:
            w=csv.writer(f)
            w.writerow([
                "Topic","Video ID","Title",
                "Personal Rating","Worth Watching"
            ])
            for topic,d in sorted(best.items()):
                w.writerow([
                    topic,
                    d["video_id"],
                    d["title"],
                    d.get("user_rating",0),
                    d.get("worth_watching_score",0)
                ])
    except Exception as ex:
        print(f"Phase 5 stats warning: {type(ex).__name__}: {ex}")

    # 5. Build summary/audit.
    audit=BASE/"maintenance"/"audits"/"phase5_knowledge_summary.csv"
    audit.parent.mkdir(parents=True,exist_ok=True)

    topics=set()
    channels=set()
    categories=set()
    for d in docs:
        topics.update(d.get("topics") or [])
        channels.add(d.get("channel") or "")
        categories.add(d.get("category") or "Other")

    with open(audit,"w",newline="",encoding="utf-8-sig") as f:
        w=csv.writer(f)
        w.writerow([
            "Videos Indexed","Topics","Channels","Categories",
            "Dashboard","Built At"
        ])
        w.writerow([
            len(docs),
            len(topics),
            len(channels),
            len(categories),
            str(dashboard),
            time.strftime("%Y-%m-%d %H:%M:%S")
        ])

    print("")
    print("Phase 5 complete")
    print(f"Videos indexed : {len(docs)}")
    print(f"Dashboard      : {dashboard}")
    print(f"Search CSV     : {phase5_search_csv_path()}")
    print(f"Audit          : {audit}")
    return True


