def phase6_dirs():
    root=BASE/"data"/"knowledge"/"phase6"
    chunks=root/"chunks"
    audits=root/"audits"
    research=root/"research"
    cache=root/"cache"
    for p in [root,chunks,audits,research,cache]:
        p.mkdir(parents=True,exist_ok=True)
    return root,chunks,audits,research,cache


def phase6_chunk_index_path():
    return phase6_dirs()[1]/"chunk_index.jsonl"


def phase6_chunk_csv_path():
    return phase6_dirs()[1]/"chunk_index.csv"


def phase6_manifest_path():
    return phase6_dirs()[1]/"chunk_manifest.json"


def phase6_chunk_id(video_id,start,end,index):
    raw=f"{video_id}|{start}|{end}|{index}"
    return hashlib.sha1(raw.encode("utf-8",errors="ignore")).hexdigest()[:20]


def phase6_parse_timestamp(value):
    s=str(value or "").strip()
    if not s:
        return 0
    parts=s.split(":")
    try:
        nums=[int(float(x)) for x in parts]
    except Exception:
        return 0
    if len(nums)==3:
        return nums[0]*3600+nums[1]*60+nums[2]
    if len(nums)==2:
        return nums[0]*60+nums[1]
    if len(nums)==1:
        return nums[0]
    return 0


def phase6_format_timestamp(seconds):
    try:
        sec=max(0,int(seconds))
    except Exception:
        sec=0
    h=sec//3600
    m=(sec%3600)//60
    s=sec%60
    return f"{h:02d}:{m:02d}:{s:02d}"


def phase6_video_source_hash(doc):
    parts=[
        str(doc.get("video_id") or ""),
        str(doc.get("title") or ""),
        str(doc.get("downloaded_at") or ""),
        str(doc.get("taxonomy_hash") or ""),
        str(doc.get("report_html") or ""),
        str(doc.get("transcript_original") or ""),
        str(doc.get("transcript_clean") or ""),
        str(doc.get("chatgpt_summary") or ""),
    ]
    for p in [doc.get("transcript_original"),doc.get("transcript_clean"),doc.get("chatgpt_summary")]:
        try:
            fp=Path(p or "")
            if fp.exists():
                st=fp.stat()
                parts.extend([str(st.st_size),str(int(st.st_mtime))])
        except Exception:
            pass
    return hashlib.sha256("|".join(parts).encode("utf-8",errors="ignore")).hexdigest()


def phase6_load_sections_for_video(video_id):
    vid=str(video_id or "").strip()
    folder=locate_existing_folder(vid)
    summary_obj,summary_path=load_chatgpt_summary_for_video(vid)
    sections=[]

    if summary_obj:
        try:
            norm=normalize_chatgpt_result_video(summary_obj)
            sections=norm.get("sections") or []
            if not isinstance(sections,list):
                sections=[]
        except Exception:
            sections=[]

    if not sections:
        try:
            p=temp_paths(vid)
            if p.get("chapters") and p["chapters"].exists():
                obj=json.loads(p["chapters"].read_text(encoding="utf-8",errors="replace"))
                if isinstance(obj,list):
                    sections=obj
        except Exception:
            pass

    return sections,folder


def phase6_chunk_video(doc,max_chars=2200):
    vid=doc.get("video_id")
    sections,folder=phase6_load_sections_for_video(vid)
    chunks=[]
    idx=0

    def add_chunk(start,end,title,text,kind="section"):
        nonlocal idx
        clean=re.sub(r"\s+"," ",str(text or "")).strip()
        if not clean:
            return
        start_sec=phase6_parse_timestamp(start)
        end_sec=phase6_parse_timestamp(end)
        if end_sec<=start_sec:
            end_sec=start_sec+max(30,min(300,len(clean)//12))
        idx+=1
        chunks.append({
            "chunk_id":phase6_chunk_id(vid,start_sec,end_sec,idx),
            "video_id":vid,
            "title":doc.get("title",""),
            "channel":doc.get("channel",""),
            "category":doc.get("category","Other"),
            "subcategory":doc.get("subcategory","General"),
            "topics":doc.get("topics") or [],
            "chunk_index":idx,
            "kind":kind,
            "section_title":str(title or "").strip(),
            "start_seconds":start_sec,
            "end_seconds":end_sec,
            "start":phase6_format_timestamp(start_sec),
            "end":phase6_format_timestamp(end_sec),
            "text":clean[:max_chars],
            "report_html":doc.get("report_html",""),
            "local_video":doc.get("local_video",""),
            "downloaded_at":doc.get("downloaded_at",""),
            "worth_watching_score":doc.get("worth_watching_score",0),
            "user_rating":doc.get("user_rating",0),
        })

    for sec in sections:
        if not isinstance(sec,dict):
            continue
        start=sec.get("start") or sec.get("start_time") or "00:00:00"
        end=sec.get("end") or sec.get("end_time") or ""
        stitle=sec.get("chapter_title") or sec.get("title") or sec.get("group_title") or ""
        pieces=[]
        for key in [
            "main_idea","overview","detailed_summary","summary","source_text",
            "key_points","takeaways","instructions","claims","relevance"
        ]:
            v=sec.get(key)
            if isinstance(v,list):
                pieces.extend(str(x) for x in v if str(x).strip())
            elif v:
                pieces.append(str(v))
        add_chunk(start,end,stitle," ".join(pieces),"section")

    # Fallback: timestamped transcript if no structured sections.
    if not chunks:
        transcript_path=doc.get("transcript_original") or doc.get("transcript_clean")
        try:
            p=Path(transcript_path or "")
            if p.exists():
                lines=p.read_text(encoding="utf-8",errors="replace").splitlines()
                current_start=0
                buf=[]
                chunk_no=0
                ts_re=re.compile(r"(?<!\d)(\d{1,2}:\d{2}:\d{2}|\d{1,3}:\d{2})(?!\d)")
                for line in lines:
                    m=ts_re.search(line)
                    if m:
                        secv=phase6_parse_timestamp(m.group(1))
                        if buf and (len(" ".join(buf))>1000 or secv-current_start>=180):
                            chunk_no+=1
                            add_chunk(current_start,secv,f"Transcript Block {chunk_no}"," ".join(buf),"transcript")
                            buf=[]
                        if not buf:
                            current_start=secv
                        line=ts_re.sub("",line).strip(" -|\t")
                    if line.strip():
                        buf.append(line.strip())
                if buf:
                    chunk_no+=1
                    add_chunk(current_start,current_start+180,f"Transcript Block {chunk_no}"," ".join(buf),"transcript")
        except Exception:
            pass

    # Final fallback to summary/context.
    if not chunks:
        summary=doc.get("summary_text") or doc.get("intelligence_text") or ""
        if summary:
            words=re.sub(r"\s+"," ",summary).strip()
            for i in range(0,len(words),max_chars):
                add_chunk(0,0,"Summary",words[i:i+max_chars],"summary")

    return chunks


def phase6_build_chunk_index(incremental=True):
    docs=phase5_load_search_index()
    if not docs:
        docs=phase5_build_search_index(incremental=True)

    existing_by_video=defaultdict(list)
    manifest={}
    if incremental and phase6_chunk_index_path().exists():
        try:
            with open(phase6_chunk_index_path(),"r",encoding="utf-8") as f:
                for line in f:
                    if line.strip():
                        c=json.loads(line)
                        existing_by_video[c.get("video_id")].append(c)
        except Exception:
            existing_by_video=defaultdict(list)

    if incremental and phase6_manifest_path().exists():
        try:
            manifest=json.loads(
                phase6_manifest_path().read_text(encoding="utf-8")
            )
        except Exception:
            manifest={}

    all_chunks=[]
    new_manifest={}
    rebuilt=reused=failed=0

    for i,doc in enumerate(docs,1):
        vid=doc.get("video_id")
        try:
            source_hash=phase6_video_source_hash(doc)
            new_manifest[vid]={"source_hash":source_hash}

            if incremental and manifest.get(vid,{}).get("source_hash")==source_hash and existing_by_video.get(vid):
                all_chunks.extend(existing_by_video[vid])
                reused+=1
            else:
                chunks=phase6_chunk_video(doc)
                all_chunks.extend(chunks)
                rebuilt+=1
                new_manifest[vid]["chunk_count"]=len(chunks)

            if i%100==0:
                print(
                    f"Phase 6 chunks {i}/{len(docs)} | "
                    f"rebuilt={rebuilt} reused={reused} failed={failed}"
                )
        except Exception as ex:
            failed+=1
            log(f"Phase 6 chunk build failed {vid}: {type(ex).__name__}: {ex}")

    all_chunks=phase6_enrich_chunks_with_intelligence(all_chunks)

    with open(phase6_chunk_index_path(),"w",encoding="utf-8") as f:
        for c in all_chunks:
            f.write(json.dumps(c,ensure_ascii=False)+"\n")

    fields=[
        "Chunk ID","Video ID","Title","Channel","Category","Subcategory",
        "Topics","Kind","Section Title","Start","End","Text",
        "Worth Watching","Personal Rating","Report"
    ]
    with open(phase6_chunk_csv_path(),"w",newline="",encoding="utf-8-sig") as f:
        w=csv.DictWriter(f,fieldnames=fields)
        w.writeheader()
        for c in all_chunks:
            w.writerow({
                "Chunk ID":c["chunk_id"],"Video ID":c["video_id"],
                "Title":c["title"],"Channel":c["channel"],
                "Category":c["category"],"Subcategory":c["subcategory"],
                "Topics":" | ".join(c["topics"]),
                "Kind":c["kind"],"Section Title":c["section_title"],
                "Start":c["start"],"End":c["end"],"Text":c["text"],
                "Worth Watching":c["worth_watching_score"],
                "Personal Rating":c["user_rating"],
                "Report":c["report_html"]
            })

    phase6_manifest_path().write_text(
        json.dumps(new_manifest,indent=2,ensure_ascii=False),
        encoding="utf-8"
    )

    print(
        f"Phase 6 chunk index: chunks={len(all_chunks)} "
        f"rebuilt={rebuilt} reused={reused} failed={failed}"
    )
    return all_chunks


def phase6_load_chunks():
    p=phase6_chunk_index_path()
    if not p.exists():
        return phase6_build_chunk_index(incremental=True)
    out=[]
    with open(p,"r",encoding="utf-8") as f:
        for line in f:
            if line.strip():
                try: out.append(json.loads(line))
                except Exception: pass
    return phase6_enrich_chunks_with_intelligence(out)




def phase6_embedding_dir():
    p=phase6_dirs()[0]/"embeddings"
    p.mkdir(parents=True,exist_ok=True)
    return p

def phase6_embedding_cache_path():
    return phase6_embedding_dir()/"chunk_embeddings.jsonl"

def phase6_embedding_manifest_path():
    return phase6_embedding_dir()/"embedding_manifest.json"

def phase6_embedding_backend():
    try:
        import sentence_transformers  # noqa: F401
        return "sentence_transformers"
    except Exception:
        return "hashing"

def phase6_hash_embedding(text_value,dim=384):
    toks=phase5_tokens(text_value)
    if not toks:
        return [0.0]*dim
    vec=[0.0]*dim
    feats=list(toks)
    feats.extend(toks[i]+"_"+toks[i+1] for i in range(len(toks)-1))
    for feat in feats:
        h=int(hashlib.sha1(feat.encode("utf-8",errors="ignore")).hexdigest()[:12],16)
        idx=h % dim
        sign=1.0 if ((h>>4)&1)==0 else -1.0
        vec[idx]+=sign
    norm=math.sqrt(sum(x*x for x in vec)) or 1.0
    return [x/norm for x in vec]

_PHASE6_ST_MODEL=None

def phase6_sentence_transformer_model():
    global _PHASE6_ST_MODEL
    if _PHASE6_ST_MODEL is not None:
        return _PHASE6_ST_MODEL if _PHASE6_ST_MODEL is not False else None
    try:
        from sentence_transformers import SentenceTransformer
        _PHASE6_ST_MODEL=SentenceTransformer("all-MiniLM-L6-v2")
        return _PHASE6_ST_MODEL
    except Exception:
        _PHASE6_ST_MODEL=False
        return None

def phase6_active_embedding_identity():
    """Identity of the backend/model that would create embeddings right now."""
    model=phase6_sentence_transformer_model() if phase6_embedding_backend()=="sentence_transformers" else None
    if model:
        try:
            dim=int(model.get_sentence_embedding_dimension() or 384)
        except Exception:
            dim=384
        return embedding_identity("sentence_transformers",dim,model=SENTENCE_TRANSFORMER_MODEL,implementation="sentence-transformers")
    return embedding_identity("hashing",384,model=HASHING_EMBEDDING_VERSION,implementation=HASHING_EMBEDDING_VERSION)

def phase6_embedding_identity_for_vector(backend,vector):
    dim=len(vector or [])
    if str(backend or "") == "sentence_transformers":
        return embedding_identity("sentence_transformers",dim,model=SENTENCE_TRANSFORMER_MODEL,implementation="sentence-transformers")
    return embedding_identity("hashing",dim,model=HASHING_EMBEDDING_VERSION,implementation=HASHING_EMBEDDING_VERSION)

def phase6_embed_text(text_value):
    if phase6_embedding_backend()=="sentence_transformers":
        model=phase6_sentence_transformer_model()
        if model:
            try:
                vec=model.encode(
                    [str(text_value or "")],
                    normalize_embeddings=True,
                    show_progress_bar=False
                )[0]
                return [float(x) for x in vec],"sentence_transformers"
            except Exception:
                pass
    return phase6_hash_embedding(text_value),"hashing"

def phase6_cosine(a,b):
    if not a or not b or len(a)!=len(b):
        return 0.0
    return sum(float(x)*float(y) for x,y in zip(a,b))

def phase6_chunk_embedding_text(chunk):
    return " ".join([
        str(chunk.get("title") or ""),
        str(chunk.get("section_title") or ""),
        str(chunk.get("category") or ""),
        str(chunk.get("subcategory") or ""),
        " ".join(chunk.get("topics") or []),
        str(chunk.get("text") or "")
    ])

def phase6_build_embeddings(incremental=True):
    chunks=phase6_load_chunks()
    manifest={}
    existing={}
    desired_identity=phase6_active_embedding_identity()

    if incremental and phase6_embedding_manifest_path().exists():
        try:
            manifest=json.loads(
                phase6_embedding_manifest_path().read_text(encoding="utf-8")
            )
        except Exception:
            manifest={}

    compatible=embedding_manifest_compatible(manifest,desired_identity)
    manifest_chunks=manifest.get("chunks",{}) if compatible else {}

    if incremental and compatible and phase6_embedding_cache_path().exists():
        try:
            with open(phase6_embedding_cache_path(),"r",encoding="utf-8") as f:
                for line in f:
                    if line.strip():
                        obj=json.loads(line)
                        if obj.get("identity_fingerprint")==desired_identity.get("fingerprint"):
                            existing[obj["chunk_id"]]=obj
        except Exception:
            existing={}

    out=[]
    new_chunks={}
    rebuilt=reused=failed=0
    actual_identity=desired_identity

    for i,c in enumerate(chunks,1):
        try:
            cid=c["chunk_id"]
            embed_text=phase6_chunk_embedding_text(c)
            source_hash=hashlib.sha256(
                embed_text.encode("utf-8",errors="ignore")
            ).hexdigest()
            new_chunks[cid]=source_hash

            if incremental and manifest_chunks.get(cid)==source_hash and cid in existing:
                out.append(existing[cid])
                reused+=1
            else:
                vector,backend=phase6_embed_text(embed_text)
                vector_identity=phase6_embedding_identity_for_vector(backend,vector)
                # If the preferred SentenceTransformer cannot encode and falls
                # back to hashing, make that fallback the manifest identity so
                # future runs do not keep trying to reuse incompatible vectors.
                if rebuilt==0 and reused==0:
                    actual_identity=vector_identity
                if vector_identity.get("fingerprint") != actual_identity.get("fingerprint"):
                    # A mixed-backend cache is unsafe. Rebuild the current item
                    # with deterministic hashing so the resulting file has one
                    # identity throughout.
                    vector=phase6_hash_embedding(embed_text)
                    backend="hashing"
                    vector_identity=phase6_embedding_identity_for_vector(backend,vector)
                    actual_identity=vector_identity
                    if reused:
                        # Existing vectors from another identity must not survive.
                        return phase6_build_embeddings(incremental=False)
                out.append({
                    "chunk_id":cid,
                    "video_id":c.get("video_id"),
                    "backend":backend,
                    "identity_fingerprint":vector_identity.get("fingerprint"),
                    "vector":vector
                })
                rebuilt+=1

            if i%250==0:
                print(
                    f"Phase 6 embeddings {i}/{len(chunks)} | "
                    f"rebuilt={rebuilt} reused={reused} failed={failed}"
                )
        except Exception as ex:
            failed+=1
            log(f"Phase 6 embedding failed {c.get('chunk_id')}: {type(ex).__name__}: {ex}")

    # A legacy/mismatched manifest never authorizes vector reuse.  If the first
    # rebuilt vector established a fallback identity, ensure every cached row
    # is from that same identity before writing the new manifest.
    if out and any(x.get("identity_fingerprint")!=actual_identity.get("fingerprint") for x in out):
        return phase6_build_embeddings(incremental=False)

    with open(phase6_embedding_cache_path(),"w",encoding="utf-8") as f:
        for obj in out:
            f.write(json.dumps(obj,ensure_ascii=False)+"\n")

    new_manifest={
        "schema_version":2,
        "identity":actual_identity,
        "chunks":new_chunks,
    }
    phase6_embedding_manifest_path().write_text(
        json.dumps(new_manifest,indent=2),
        encoding="utf-8"
    )

    print(
        f"Phase 6 embeddings: backend={actual_identity.get('backend')} "
        f"rebuilt={rebuilt} reused={reused} failed={failed}"
    )
    return out

def phase6_load_embeddings():
    p=phase6_embedding_cache_path()
    expected=phase6_active_embedding_identity()
    manifest={}
    try:
        if phase6_embedding_manifest_path().exists():
            manifest=json.loads(phase6_embedding_manifest_path().read_text(encoding="utf-8"))
    except Exception:
        manifest={}
    if (not p.exists()) or (not embedding_manifest_compatible(manifest,expected)):
        phase6_build_embeddings(incremental=True)
        try:
            manifest=json.loads(phase6_embedding_manifest_path().read_text(encoding="utf-8"))
        except Exception:
            manifest={}
    allowed=(manifest.get("identity") or {}).get("fingerprint") if isinstance(manifest,dict) else None
    out={}
    try:
        with open(p,"r",encoding="utf-8") as f:
            for line in f:
                if line.strip():
                    obj=json.loads(line)
                    if allowed and obj.get("identity_fingerprint")==allowed:
                        out[obj["chunk_id"]]=obj
    except Exception:
        pass
    return out

def phase6_semantic_forms(term):
    """
    Lightweight local semantic expansion for retrieval.
    Keeps search fast and deterministic without Ollama.
    """
    t=str(term or "").strip().lower()
    if not t:
        return set()

    forms={t}

    # spelling variants
    spelling={
        "grey":"gray","gray":"grey",
        "greying":"graying","graying":"greying",
        "colour":"color","color":"colour",
        "fibre":"fiber","fiber":"fibre"
    }
    if t in spelling:
        forms.add(spelling[t])

    # simple morphology/stemming variants
    if t.endswith("ing") and len(t)>5:
        stem=t[:-3]
        forms.add(stem)
        forms.add(stem+"e")
    if t.endswith("ed") and len(t)>4:
        stem=t[:-2]
        forms.add(stem)
        forms.add(stem+"e")
    if t.endswith("ies") and len(t)>4:
        forms.add(t[:-3]+"y")
    if t.endswith("s") and len(t)>3:
        forms.add(t[:-1])
    else:
        forms.add(t+"s")

    # curated concept synonyms for common library domains.
    semantic={
        "grey":{"gray","greying","graying","white","whitening"},
        "gray":{"grey","greying","graying","white","whitening"},
        "greying":{"grey","gray","graying","whitening"},
        "graying":{"gray","grey","greying","whitening"},
        "hair":{"hairs","scalp","haircare","hair-care"},
        "weight":{"obesity","fat","slimming"},
        "fat":{"weight","obesity","adipose"},
        "diabetes":{"blood-sugar","glucose","sugar"},
        "sugar":{"glucose","blood-sugar","diabetes"},
        "ai":{"artificial-intelligence","llm","machine-learning"},
        "llm":{"large-language-model","ai"},
        "mobile":{"phone","smartphone","handset"},
        "phone":{"mobile","smartphone"},
        "cancer":{"tumor","tumour","oncology"},
        "tumor":{"tumour","cancer"},
        "tumour":{"tumor","cancer"},
        "digestion":{"digestive","gut","stomach"},
        "ayurveda":{"ayurvedic"},
    }
    forms.update(semantic.get(t,set()))

    return {x for x in forms if x}


def phase6_expand_query_terms(query):
    toks=phase5_tokens(query)
    noise={
        "what","why","how","does","do","did","can","could","would","should",
        "is","are","was","were","be","been","being","the","a","an","to","of",
        "in","on","for","from","with","and","or","my","your","this","that",
        "these","those","become","becoming","prevent","help","helps"
    }
    toks=[t for t in toks if t not in noise]
    groups=[]
    # Treat common natural-language variants as ONE intent concept, not unrelated words.
    if "hair" in toks and any(x in toks for x in {"white","grey","gray","greying","graying","premature"}):
        groups.append(sorted({"hair","grey","gray","greying","graying","white","whitening","premature"}))
        toks=[t for t in toks if t not in {"hair","white","grey","gray","greying","graying","premature","whitening","early"}]
    for t in toks:
        forms=set()
        for f in phase6_semantic_forms(t): forms.update(phase5_tokens(f))
        groups.append(sorted(forms or {t}))
    return groups

def phase6_token_group_match(group, token_set):
    return any(x in token_set for x in group)



def phase6_section_type(chunk):
    textv=" ".join([str(chunk.get("section_title") or ""),str(chunk.get("text") or "")]).lower()
    promo_terms={"sponsor","sponsored","discount","coupon","buy now","order now","link in description","special offer","product by","use code","checkout","check out","affiliate","promotion"}
    outro_terms={"subscribe","like this video","share this video","join button","follow me","thanks for watching","thank you for watching","see you in the next video"}
    intro_terms={"welcome to","in this video","today i am going to","today we will","before we start"}
    if any(x in textv for x in promo_terms): return "promo"
    if any(x in textv for x in outro_terms): return "outro"
    if any(x in textv for x in intro_terms): return "intro"
    return "main_content"

def phase6_match_reason(chunk,groups):
    intent={x for g in groups for x in g}
    section=set(phase5_tokens(chunk.get("section_title","")))
    topics=set(phase5_tokens(" ".join(chunk.get("topics") or [])))
    hierarchy=set(phase5_tokens(f"{chunk.get('category','')} {chunk.get('subcategory','')}"))
    title=set(phase5_tokens(chunk.get("title","")))
    textset=set(phase5_tokens(chunk.get("text","")))
    intel=set(phase5_tokens(chunk.get("chatgpt_search_intelligence","")))
    reasons=[]
    if intent & intel: reasons.append("ChatGPT intelligence")
    if intent & section: reasons.append("section title")
    if intent & topics: reasons.append("tags/topics")
    if intent & hierarchy: reasons.append("category/subcategory")
    if intent & title: reasons.append("video title")
    if not reasons and intent & textset: reasons.append("transcript only")
    st=phase6_section_type(chunk)
    if st!="main_content": reasons.append(st)
    return ", ".join(reasons) if reasons else "semantic similarity"

def phase6_chunk_search(query,limit=30,category="",channel="",video_id="",dedupe_videos=True,require_all_terms=False):
    raw_query=str(query or "").strip()
    if not phase5_tokens(raw_query): return []
    groups=phase6_expand_query_terms(raw_query)
    if not groups: return []
    chunks=phase6_load_chunks(); embeddings=phase6_load_embeddings()
    expanded=" ".join(sorted({x for g in groups for x in g}))
    qvec,qbackend=phase6_embed_text(expanded)
    qidentity=phase6_embedding_identity_for_vector(qbackend,qvec)
    candidates=[]
    for c in chunks:
        if category and c.get("category")!=category: continue
        if channel and c.get("channel")!=channel: continue
        if video_id and c.get("video_id")!=video_id: continue
        fields={
            "title":set(phase5_tokens(c.get("title",""))),
            "section":set(phase5_tokens(c.get("section_title",""))),
            "topics":set(phase5_tokens(" ".join(c.get("topics") or []))),
            "hier":set(phase5_tokens(f"{c.get('category','')} {c.get('subcategory','')}")),
            "text":set(phase5_tokens(c.get("text",""))),
            "intel":set(phase5_tokens(c.get("chatgpt_search_intelligence","")))
        }
        allset=set().union(*fields.values())
        matches=[phase6_token_group_match(g,allset) for g in groups]
        if require_all_terms and len(groups)>1 and not all(matches): continue
        lexical=0.0; matched=0
        for g in groups:
            hit=False
            for q in g:
                if q in fields['intel']: lexical+=38; hit=True
                if q in fields['section']: lexical+=34; hit=True
                if q in fields['topics']: lexical+=30; hit=True
                if q in fields['hier']: lexical+=26; hit=True
                if q in fields['title']: lexical+=20; hit=True
                if q in fields['text']: lexical+=4; hit=True
            if hit: matched+=1
        emb=embeddings.get(c.get('chunk_id')) or {}
        sim=0.0
        if (
            emb.get('vector')
            and len(emb['vector'])==len(qvec)
            and emb.get('identity_fingerprint')==qidentity.get('fingerprint')
        ):
            sim=max(0.0,phase6_cosine(qvec,emb['vector']))
        backend=emb.get('backend') or qbackend
        # Strong domain signal: if query intent clearly maps to taxonomy/section/topics, reward it.
        intent_tokens={x for g in groups for x in g}
        domain_hits=len(intent_tokens & (fields['intel']|fields['section']|fields['topics']|fields['hier']))
        domain_bonus=min(35.0,domain_hits*9.0)
        # Incidental transcript-only hits are weak; prevents 'curry' cooking pages outranking hair intent.
        transcript_only=bool(intent_tokens & fields['text']) and not bool(intent_tokens & (fields['intel']|fields['intel']|fields['section']|fields['topics']|fields['hier']|fields['title']))
        mismatch_penalty=18.0 if transcript_only else 0.0
        threshold=0.14 if backend=='sentence_transformers' else 0.07
        if matched==0 and sim<threshold: continue
        section_type=phase6_section_type(c)
        content_penalty={"main_content":0.0,"intro":10.0,"outro":18.0,"promo":28.0}.get(section_type,0.0)
        score=min(70.0,lexical/3.0)+sim*30.0+domain_bonus-mismatch_penalty-content_penalty
        score+=min(4.0,float(c.get('worth_watching_score',0))/25.0)
        relevance_class='INCIDENTAL' if section_type in {'promo','outro','intro'} or score<18 else ('DIRECT' if domain_hits>0 and score>=32 else 'RELATED')
        r=dict(c); r.update({
            'relevance_class':relevance_class,
            'retrieval_score':round(score,2),'lexical_score':round(lexical,2),
            'semantic_similarity':round(sim,4),'embedding_backend':backend,
            'semantic_match_count':matched,'query_groups':groups,
            'section_type':section_type,'match_reason':phase6_match_reason(c,groups),
            'snippet':phase5_search_snippet({'search_text':c.get('text','')},raw_query,300) or ' '.join(phase5_tokens(c.get('text',''))[:55])
        })
        candidates.append(r)
    candidates.sort(key=lambda x:(x['retrieval_score'],x['semantic_similarity'],x['lexical_score']),reverse=True)
    if not dedupe_videos: return candidates[:limit]
    grouped={}; order=[]
    for h in candidates:
        vid=h.get('video_id')
        if vid not in grouped:
            h=dict(h); h['additional_matches']=[]; h['matching_chunk_count']=1; grouped[vid]=h; order.append(vid)
        else:
            grouped[vid]['matching_chunk_count']+=1
            if len(grouped[vid]['additional_matches'])<5:
                grouped[vid]['additional_matches'].append({k:h.get(k) for k in ['chunk_id','section_title','start','end','start_seconds','end_seconds','retrieval_score','semantic_similarity','snippet']})
    return [grouped[v] for v in order[:limit]]

def phase6_search_only_interactive():
    query=input("Ask/Search your library: ").strip()
    if not query:
        return
    hits=phase6_chunk_search(query,25)
    if not hits:
        print("No relevant evidence found.")
        return

    print("")
    print("===== PHASE 6 SEARCH-ONLY RESULTS =====")
    for i,h in enumerate(hits,1):
        print(
            f"{i}. [{h['retrieval_score']}] "
            f"{h.get('title','')} | {h.get('channel','')}"
        )
        print(
            f"   {h.get('start','')} - {h.get('end','')} | "
            f"{h.get('section_title','')}"
        )
        if h.get("matching_chunk_count",1)>1:
            print(
                f"   Matching sections in this video: "
                f"{h.get('matching_chunk_count')}"
            )
        if h.get("snippet"):
            print(f"   {h['snippet']}")
        print(f"   Video ID: {h.get('video_id')}")
        print("")


def phase6_health_audit():
    chunks=phase6_load_chunks()
    docs=phase5_load_search_index()

    by_video=Counter(c.get("video_id") for c in chunks)
    missing=[]
    for d in docs:
        vid=d.get("video_id")
        if by_video.get(vid,0)==0:
            missing.append([
                vid,d.get("title",""),d.get("channel",""),
                d.get("category",""),d.get("subcategory","")
            ])

    root,chunks_dir,audits,research,cache=phase6_dirs()

    out=audits/"phase6_chunk_health.csv"
    with open(out,"w",newline="",encoding="utf-8-sig") as f:
        w=csv.writer(f)
        w.writerow(["Metric","Value"])
        w.writerow(["Videos in Phase 5",len(docs)])
        w.writerow(["Videos with chunks",len(by_video)])
        w.writerow(["Total chunks",len(chunks)])
        w.writerow(["Videos missing chunks",len(missing)])
        w.writerow(["Generated At",time.strftime("%Y-%m-%d %H:%M:%S")])

    missing_out=audits/"phase6_missing_chunks.csv"
    with open(missing_out,"w",newline="",encoding="utf-8-sig") as f:
        w=csv.writer(f)
        w.writerow(["Video ID","Title","Channel","Category","Subcategory"])
        w.writerows(missing)

    print(f"Phase 6 audit: {out}")
    print(f"Videos missing chunks: {len(missing)}")
    return out,missing_out


def phase6_build_all():
    print("===== PHASE 6A - RETRIEVAL FOUNDATION =====")
    chunks=phase6_build_chunk_index(incremental=True)
    phase6_build_embeddings(incremental=True)
    phase6_health_audit()
    print("")
    print("Phase 6A complete")
    print(f"Chunks indexed: {len(chunks)}")
    print(f"Chunk index   : {phase6_chunk_index_path()}")
    print(f"Chunk CSV     : {phase6_chunk_csv_path()}")
    return True




def phase6_collections_dir():
    p=phase6_dirs()[0]/"collections"; p.mkdir(parents=True,exist_ok=True); return p

def phase6_collections_path(): return phase6_collections_dir()/"collections.json"
def phase6_intelligence_dir():
    p=phase6_dirs()[0]/"chatgpt_intelligence"; p.mkdir(parents=True,exist_ok=True); return p

def phase6_load_collections():
    p=phase6_collections_path()
    if not p.exists(): return []
    try: return json.loads(p.read_text(encoding="utf-8"))
    except Exception: return []

def phase6_save_collections(items):
    phase6_collections_path().write_text(json.dumps(items,indent=2,ensure_ascii=False),encoding="utf-8")

def phase6_upsert_collection(name,video_ids,query="",topic=""):
    topic=re.sub(r"\s+"," ",str(topic or name or "")).strip()
    name=re.sub(r"\s+"," ",str(name or "")).strip()
    vids=list(dict.fromkeys(str(v) for v in (video_ids or []) if str(v).strip()))
    if not name or not vids: return False,"Collection name and at least one video are required",None
    items=phase6_load_collections(); now=time.strftime("%Y-%m-%d %H:%M:%S")
    found=next((x for x in items if str(x.get('name','')).lower()==name.lower()),None)
    if found:
        found['video_ids']=list(dict.fromkeys((found.get('video_ids') or [])+vids)); found['updated_at']=now
        if query: found['query']=query
        if topic: found['topic']=topic
        obj=found
    else:
        obj={'collection_id':'COL-'+hashlib.sha1((name+now).encode()).hexdigest()[:10],'name':name,'topic':topic,'query':query,'video_ids':vids,'created_at':now,'updated_at':now}
        items.append(obj)
    phase6_save_collections(items); return True,f"Saved collection '{name}' with {len(obj['video_ids'])} videos",obj


def phase6_find_transcript_for_video(video_id):
    docs={d.get('video_id'):d for d in phase5_load_search_index()}
    d=docs.get(str(video_id)) or {}
    for key in ['transcript_original','transcript_clean']:
        try:
            raw=str(d.get(key) or "").strip()
            if not raw:
                continue
            p=Path(raw)
            if p.is_file():
                return p
        except Exception:
            pass

    # DB fallback is important when the Phase 5 index predates the transcript.
    try:
        con=db_connect()
        cols=video_table_columns()
        wanted=[c for c in ["transcript_original","transcript_clean","transcript_detailed"] if c in cols]
        row=con.execute(
            "SELECT "+",".join(f'"{c}"' for c in wanted)+" FROM videos WHERE video_id=?",
            (str(video_id),)
        ).fetchone() if wanted else None
        con.close()
        if row:
            for raw in row:
                raw=str(raw or "").strip()
                if not raw:
                    continue
                p=Path(raw)
                if p.is_file():
                    return p
    except Exception:
        pass

    # Fallback to indexed chunks so existing videos can still be exported
    # immediately, but do not return Path('') / a directory as a transcript.
    return None


def phase6_collection_package(collection_id,focused=False):
    coll=next((x for x in phase6_load_collections() if x.get('collection_id')==collection_id),None)
    if not coll: return None
    docs={d.get('video_id'):d for d in phase5_load_search_index()}; chunks=phase6_load_chunks()
    safe=safe_name(coll.get('name') or collection_id)[:70]
    out=phase6_collections_dir()/f"{safe} - {'FOCUSED' if focused else 'FULL'} - CHATGPT_PACKAGE.txt"
    lines=[
      'CHATGPT VIDEO LIBRARY INTELLIGENCE PACKAGE','='*88,f"COLLECTION: {coll.get('name','')}",f"FOCUS TOPIC: {phase6_collection_topic(coll)}",f"SOURCE SEARCH: {coll.get('query','')}",f"VIDEOS: {len(coll.get('video_ids') or [])}",'',
      'REQUIRED OUTPUTS','-'*88,
      'Create ONE comprehensive synthesis across all supplied videos, not separate repetitive summaries.',
      'Return both: (A) a detailed human-readable report and (B) a machine-readable JSON object.',
      'Human report: Executive Summary; Combined Detailed Findings; Common Themes; Unique Insights; Agreements/Disagreements; Steps/Procedures; Examples; Numbers/Timings/Dosages/Configuration Values; Claims; Warnings/Limitations; Best Takeaways; Source Video + Timestamp references.',
      'JSON keys: topic, approved_english_title, category, subcategory, canonical_tags, concepts, entities, questions_answered, search_phrases, synonyms, sections, key_findings, procedures, examples, numbers_and_values, warnings, claims, agreements, disagreements, unique_insights, related_topics, not_about, source_mapping, video_updates.',
      'video_updates MUST contain one object per source video with: video_id, approved_english_title, category, subcategory, primary_topic, canonical_tags, concepts, questions_answered, search_phrases, synonyms, not_about, transcript_status, classification_basis, classification_confidence.',
      'Always copy VIDEO_ID exactly. This is how the local program knows which physical video folder and database row the classification belongs to.',
      'If TRANSCRIPT_STATUS is MISSING, classify only from title/channel/description/tags/metadata; set classification_basis=metadata_only and do NOT invent transcript details.',
      'Generate many natural-language questions this content can answer and useful alternate search phrases. These will be imported into local Search V2.',
      'Do not add outside facts unless placed under a clearly separate outside_context field/section. Preserve disagreements and distinguish video claims from verified facts.',
      'For every substantive finding cite [Video N @ HH:MM:SS].','',
      'SAVE THE JSON ONLY (no markdown fences) separately as: chatgpt_library_intelligence_result.json','='*88,'']
    for n,vid in enumerate(coll.get('video_ids') or [],1):
        d=docs.get(vid) or {}; lines += [f"VIDEO {n}",f"VIDEO_ID: {vid}",f"TITLE: {d.get('title','')}",f"CHANNEL: {d.get('channel','')}",f"CATEGORY: {d.get('category','')} / {d.get('subcategory','')}",f"TAGS: {', '.join(d.get('topics') or [])}",
            f"DESCRIPTION: {canonical_clean_description(vid,d.get('description') or '')[:8000]}",
            f"TRANSCRIPT_STATUS: {'AVAILABLE' if phase6_find_transcript_for_video(vid) else 'MISSING'}",
            '-'*88]
        p=phase6_find_transcript_for_video(vid)
        if p and not focused:
            lines.append(p.read_text(encoding='utf-8',errors='replace'))
        else:
            vc=[c for c in chunks if c.get('video_id')==vid]
            if focused and phase6_collection_topic(coll):
                hits=phase6_chunk_search(phase6_collection_topic(coll),limit=20,video_id=vid,dedupe_videos=False,require_all_terms=False)
                if hits:
                    direct=[]; related=[]; excluded=[]
                    for h in hits:
                        st=h.get('section_type') or phase6_section_type(h)
                        reason=str(h.get('match_reason') or '')
                        score=float(h.get('retrieval_score') or 0)
                        if st in {'promo','outro','intro'} or score < 18:
                            excluded.append(h); continue
                        if any(x in reason for x in ['section title','tags/topics','category/subcategory','video title','ChatGPT intelligence']) and score>=32:
                            h['relevance_class']='DIRECT'; direct.append(h)
                        elif score>=22:
                            h['relevance_class']='RELATED'; related.append(h)
                        else:
                            excluded.append(h)
                    vc=direct+related
                    lines += [f"DIRECT SECTIONS: {len(direct)}",f"RELATED SECTIONS: {len(related)}",f"EXCLUDED INCIDENTAL/PROMO: {len(excluded)}",'' ]
            for c in vc:
                lines.append(f"[{c.get('relevance_class','DIRECT')}] [{c.get('start','')} - {c.get('end','')}] {c.get('section_title','')}")
                if c.get('match_reason'): lines.append(f"WHY MATCHED: {c.get('match_reason')}")
                lines.append(str(c.get('text') or '')); lines.append('')
        comment_intel=phase6_comments_for_chatgpt(vid,focused=focused)
        if comment_intel:
            lines += ['', 'AUDIENCE COMMENT INTELLIGENCE','-'*88,
                'The following are locally filtered meaningful viewer comments. Treat viewer comments as audience-generated claims/questions/experiences, not verified facts.',
                comment_intel,'']
        else:
            lines += ['', 'AUDIENCE COMMENT INTELLIGENCE: NOT AVAILABLE', '']
        lines += ['', '='*88, '']
    out.write_text('\n'.join(lines),encoding='utf-8'); return out


def phase6_category_folder_name(category):
    name=safe_name(str(category or "Uncategorized")).strip()
    return name or "Uncategorized"

def phase6_category_channel_root(category,channel):
    p=DOWNLOADS/phase6_category_folder_name(category)/channel_folder_name(channel)
    p.mkdir(parents=True,exist_ok=True)
    return p


def phase6_update_db_paths_after_move(video_id,old_folder,new_folder):
    con=db_connect()
    cols=video_table_columns()
    path_cols=[x for x in [
        "local_folder","local_video","subtitle_file","transcript_original",
        "transcript_clean","transcript_detailed","report_html",
        "comments_file","comments_transcript_file","comments_meaningful_file","comments_meaningful_json","video_identity_file","chatgpt_summary_file"
    ] if x in cols]
    if not path_cols:
        con.close()
        return
    row=con.execute(
        "SELECT "+",".join(f'"{c}"' for c in path_cols)+" FROM videos WHERE video_id=?",
        (video_id,)
    ).fetchone()
    if row:
        updates={}
        old_s=str(old_folder)
        new_s=str(new_folder)
        for col,val in zip(path_cols,row):
            if val:
                sv=str(val)
                if sv.lower().startswith(old_s.lower()):
                    updates[col]=new_s+sv[len(old_s):]
        if "local_folder" in path_cols:
            updates["local_folder"]=new_s
        if updates:
            sql="UPDATE videos SET "+",".join(f'"{k}"=?' for k in updates)+" WHERE video_id=?"
            con.execute(sql,tuple(updates.values())+(video_id,))
            con.commit()
    con.close()


def phase6_reorganize_video_by_category(video_id,category):
    folder=locate_existing_folder(video_id)
    if not folder:
        return False,"Folder not found"
    folder=Path(folder)
    con=db_connect()
    row=con.execute("SELECT channel FROM videos WHERE video_id=?",(video_id,)).fetchone()
    con.close()
    channel=(row[0] if row else "") or "Unknown Channel"
    target_parent=phase6_category_channel_root(category,channel)
    target=target_parent/folder.name
    try:
        if folder.resolve()==target.resolve():
            return True,"Already organized"
    except Exception:
        pass
    if target.exists():
        marker=target/"_data"/".video_id"
        try:
            if marker.exists() and marker.read_text(encoding="utf-8",errors="ignore").strip()==str(video_id):
                phase6_update_db_paths_after_move(video_id,folder,target)
                return True,"Target already contains this video"
        except Exception:
            pass
        target=target_parent/(folder.name+" ["+safe_name(str(video_id))+"]")
    old_parent=folder.parent
    target_parent.mkdir(parents=True,exist_ok=True)
    shutil.move(str(folder),str(target))
    phase6_update_db_paths_after_move(video_id,folder,target)
    try:
        if old_parent.exists() and old_parent!=DOWNLOADS and not any(old_parent.iterdir()):
            old_parent.rmdir()
            gp=old_parent.parent
            if gp.exists() and gp!=DOWNLOADS and not any(gp.iterdir()):
                gp.rmdir()
    except Exception:
        pass
    return True,f"Moved to {target}"

def phase6_extract_video_updates(obj):
    updates=[]
    if not isinstance(obj,dict):
        return updates
    vu=obj.get("video_updates")
    if isinstance(vu,list):
        updates.extend(phase6_normalize_chatgpt_video_update(x) for x in vu if isinstance(x,dict) and x.get("video_id"))
    if obj.get("video_id"):
        updates.append(phase6_normalize_chatgpt_video_update(obj))
    return updates

def phase6_normalize_chatgpt_video_update(update):
    """Adapt v3 feature-shaped ChatGPT results into the older flat apply fields."""
    if not isinstance(update,dict):return {}
    out=dict(update)
    features=out.get("features") if isinstance(out.get("features"),dict) else {}
    title=features.get("title_en.v1") if isinstance(features.get("title_en.v1"),dict) else {}
    taxonomy=features.get("taxonomy.v3") if isinstance(features.get("taxonomy.v3"),dict) else {}
    if title and not str(out.get("approved_english_title") or "").strip():
        out["approved_english_title"]=str(title.get("title") or title.get("short_title") or "").strip()
    if taxonomy:
        for src,dest in [
            ("category","category"),
            ("subcategory","subcategory"),
            ("primary_topic","primary_topic"),
        ]:
            if taxonomy.get(src) and not str(out.get(dest) or "").strip():out[dest]=taxonomy.get(src)
        if taxonomy.get("canonical_tags") and not out.get("canonical_tags"):out["canonical_tags"]=taxonomy.get("canonical_tags")
        if taxonomy.get("keywords") and not out.get("tags"):out["tags"]=taxonomy.get("keywords")
    return out


def phase6_apply_video_update(update,move_folder=True):
    vid=str(update.get("video_id") or "").strip()
    if not vid:return False,"video_id missing"
    cols=video_table_columns();mapping={}
    title=str(update.get("approved_english_title") or "").strip()
    if title and "clean_title" in cols:mapping["clean_title"]=title[:120]
    category=str(update.get("category") or update.get("primary_category") or "").strip()
    if category:
        if "category" in cols:mapping["category"]=category
        if "primary_category" in cols:mapping["primary_category"]=category
    sub=str(update.get("subcategory") or "").strip()
    if sub and "subcategory" in cols:mapping["subcategory"]=sub
    topic=str(update.get("primary_topic") or update.get("topic") or "").strip()
    if topic:
        if "main_topic" in cols:mapping["main_topic"]=topic
        if "primary_topic" in cols:mapping["primary_topic"]=topic
    tags=update.get("canonical_tags") or update.get("tags") or []
    if isinstance(tags,str):tags=[x.strip() for x in re.split(r"[,|;]",tags) if x.strip()]
    tags=list(dict.fromkeys(str(x).strip() for x in tags if str(x).strip()))
    if tags:
        if "tags" in cols:mapping["tags"]=", ".join(tags)
        if "topics_json" in cols:mapping["topics_json"]=json.dumps(tags,ensure_ascii=False)
    con=db_connect()
    if not con.execute("SELECT 1 FROM videos WHERE video_id=?",(vid,)).fetchone():
        con.close();return False,f"{vid}: database row not found"
    if mapping:
        setparts=[f'"{k}"=?' for k in mapping];vals=list(mapping.values())
        if "taxonomy_updated_at" in cols:setparts.append('"taxonomy_updated_at"=?');vals.append(time.strftime("%Y-%m-%d %H:%M:%S"))
        con.execute("UPDATE videos SET "+",".join(setparts)+" WHERE video_id=?",tuple(vals+[vid]));con.commit()
    con.close()
    if move_folder and category:
        try:
            ok,msg=phase6_reorganize_video_by_category(vid,category)
            if not ok:return False,f"{vid}: taxonomy updated but folder move failed: {msg}"
            return True,f"{vid}: taxonomy updated; {msg}"
        except Exception as ex:return False,f"{vid}: taxonomy updated but folder move failed: {type(ex).__name__}: {ex}"
    return True,f"{vid}: taxonomy updated"



def phase6_apply_chatgpt_video_updates(records,move_folders=True,return_ids=False):
    updates=[]
    for obj in records:updates.extend(phase6_extract_video_updates(obj))
    applied=0;messages=[];success_ids=[];failed_ids=[];seen=set()
    for u in updates:
        vid=str(u.get("video_id") or "").strip()
        if not vid or vid in seen:continue
        seen.add(vid);ok,msg=phase6_apply_video_update(u,move_folder=move_folders);messages.append(msg)
        if ok:applied+=1;success_ids.append(vid)
        else:failed_ids.append(vid)
    return (applied,messages,success_ids,failed_ids) if return_ids else (applied,messages)



def phase6_move_preview_path():return phase6_dirs()[0]/"taxonomy_move_preview.json"
def phase6_move_history_path():return phase6_dirs()[0]/"taxonomy_move_history.json"
def phase6_category_channel_target(category,channel):return DOWNLOADS/phase6_category_folder_name(category)/channel_folder_name(channel)

def phase6_preview_category_moves(records=None):
    records=phase6_load_intelligence() if records is None else records
    updates=[]
    for obj in records:updates.extend(phase6_extract_video_updates(obj))
    con=db_connect();channels={str(r[0]):(r[1] or "Unknown Channel") for r in con.execute("SELECT video_id,channel FROM videos").fetchall()};con.close()
    items=[];seen=set()
    for u in updates:
        vid=str(u.get("video_id") or "").strip()
        if not vid or vid in seen:continue
        seen.add(vid);cat=str(u.get("category") or u.get("primary_category") or "").strip()
        if not cat:items.append({"video_id":vid,"status":"NO_CATEGORY","source":"","target":"","category":""});continue
        folder=locate_existing_folder(vid)
        if not folder:items.append({"video_id":vid,"status":"MISSING_SOURCE","source":"","target":"","category":cat});continue
        source=Path(folder);target=phase6_category_channel_target(cat,channels.get(vid,"Unknown Channel"))/source.name
        try:same=source.resolve()==target.resolve()
        except Exception:same=str(source).lower()==str(target).lower()
        status="SAME" if same else "MOVE"
        if not same and target.exists():
            marker=target/"_data"/".video_id"
            try:same_target=marker.exists() and marker.read_text(encoding="utf-8",errors="ignore").strip()==vid
            except Exception:same_target=False
            status="SAME" if same_target else "CONFLICT"
        items.append({"video_id":vid,"title":str(u.get("approved_english_title") or ""),"category":cat,"source":str(source),"target":str(target),"status":status})
    obj={"created_at":time.strftime("%Y-%m-%d %H:%M:%S"),"items":items,"counts":dict(Counter(x["status"] for x in items))}
    phase6_move_preview_path().write_text(json.dumps(obj,indent=2,ensure_ascii=False),encoding="utf-8");return obj

def phase6_apply_previewed_moves():
    p=phase6_move_preview_path()
    if not p.exists():return {"ok":False,"message":"No move preview exists. Preview first."}
    preview=json.loads(p.read_text(encoding="utf-8"));moves=[];failures=[];messages=[]
    for item in preview.get("items") or []:
        if item.get("status")=="SAME":continue
        if item.get("status")!="MOVE":failures.append(f"{item.get('video_id')}: {item.get('status')}");continue
        vid=item.get("video_id");before=locate_existing_folder(vid);ok,msg=phase6_reorganize_video_by_category(vid,item.get("category"));messages.append(msg)
        if ok:
            after=locate_existing_folder(vid)
            if before and after and str(before)!=str(after):moves.append({"video_id":vid,"old":str(before),"new":str(after),"category":item.get("category")})
        else:failures.append(msg)
    hp=phase6_move_history_path()
    try:history=json.loads(hp.read_text(encoding="utf-8")) if hp.exists() else []
    except Exception:history=[]
    entry={"history_id":"MOVE-"+time.strftime("%Y%m%d%H%M%S")+"-"+uuid.uuid4().hex[:6],"applied_at":time.strftime("%Y-%m-%d %H:%M:%S"),"moves":moves,"failures":failures,"undone":False}
    history.append(entry);hp.write_text(json.dumps(history[-50:],indent=2,ensure_ascii=False),encoding="utf-8")
    return {"ok":not failures,"moved":len(moves),"failed":len(failures),"messages":messages,"failures":failures,"history_id":entry["history_id"]}

def phase6_undo_last_organization():
    hp=phase6_move_history_path()
    if not hp.exists():return {"ok":False,"message":"No organization history found."}
    history=json.loads(hp.read_text(encoding="utf-8"));entry=next((x for x in reversed(history) if not x.get("undone")),None)
    if not entry:return {"ok":False,"message":"No organization operation available to undo."}
    restored=[];failed=[]
    for m in reversed(entry.get("moves") or []):
        old=Path(m.get("old") or "");new=Path(m.get("new") or "");vid=str(m.get("video_id") or "")
        try:
            if not new.exists():failed.append(f"{vid}: organized folder missing");continue
            if old.exists():failed.append(f"{vid}: original path already exists");continue
            old.parent.mkdir(parents=True,exist_ok=True);shutil.move(str(new),str(old));phase6_update_db_paths_after_move(vid,new,old);restored.append(vid)
            try:
                parent=new.parent
                if parent.exists() and parent!=DOWNLOADS and not any(parent.iterdir()):
                    parent.rmdir()
                    gp=parent.parent
                    if gp.exists() and gp!=DOWNLOADS and not any(gp.iterdir()):gp.rmdir()
            except Exception:pass
        except Exception as ex:failed.append(f"{vid}: {type(ex).__name__}: {ex}")
    entry["undone"]=True;entry["undone_at"]=time.strftime("%Y-%m-%d %H:%M:%S");entry["undo_failures"]=failed;hp.write_text(json.dumps(history,indent=2,ensure_ascii=False),encoding="utf-8")
    return {"ok":not failed,"restored":len(restored),"failed":len(failed),"failures":failed}

def phase6_import_taxonomy_result_file(path,archive=True):
    p=Path(path)
    if not p.exists():return {"ok":False,"message":"Result file not found."}
    try:records=phase6_read_result_records(p)
    except Exception as ex:return {"ok":False,"message":f"Cannot read result: {type(ex).__name__}: {ex}"}
    validation=phase6_validate_video_updates(records)
    if validation["valid_count"]==0:return {"ok":False,"message":"No valid video_updates found.","validation":validation}
    final=phase6_archive_result_file(p) if archive else p
    stored=phase6_store_intelligence_records(records)
    valid_records=[{"video_updates":validation["valid_updates"]}]
    applied,messages,success_ids,failed_ids=phase6_apply_chatgpt_video_updates(valid_records,move_folders=False,return_ids=True)
    if success_ids:phase6_mark_taxonomy_processed(success_ids)
    preview=phase6_preview_category_moves(valid_records)
    return {"ok":applied>0,"message":f"Imported {stored} record(s); taxonomy applied to {applied} valid video(s). Review move preview before moving folders.","path":str(final),"validation":validation,"applied":applied,"successful_video_ids":success_ids,"failed_video_ids":failed_ids,"messages":messages,"move_preview":preview}

def phase6_taxonomy_export_dir():
    p=phase6_dirs()[0]/"taxonomy_exports"
    p.mkdir(parents=True,exist_ok=True)
    return p

def phase6_taxonomy_status_path():
    return phase6_dirs()[0]/"taxonomy_processed.json"

def phase6_taxonomy_processed_ids():
    p=phase6_taxonomy_status_path()
    if not p.exists(): return set()
    try:
        return set(str(x) for x in json.loads(p.read_text(encoding="utf-8")).get("processed_video_ids",[]))
    except Exception:
        return set()

def phase6_mark_taxonomy_processed(video_ids):
    ids=phase6_taxonomy_processed_ids()|{str(x) for x in video_ids if x}
    phase6_taxonomy_status_path().write_text(
        json.dumps({"processed_video_ids":sorted(ids),"updated_at":time.strftime("%Y-%m-%d %H:%M:%S")},indent=2),
        encoding="utf-8"
    )


def phase6_taxonomy_video_payload(doc,chunks_by_video):
    vid=str(doc.get("video_id") or "")
    chunks=chunks_by_video.get(vid,[])
    transcript="\n\n".join(f"[{c.get('start','')} - {c.get('end','')}] {c.get('section_title','')}\n{c.get('text','')}" for c in chunks).strip()
    p=phase6_find_transcript_for_video(vid)
    if not transcript and p:
        try:transcript=p.read_text(encoding="utf-8",errors="replace").strip()
        except Exception:transcript=""
    transcript=transcript[:18000];available=bool(transcript)
    comment_intel=phase6_comments_for_chatgpt(vid,focused=True)
    return {"video_id":vid,"original_title":doc.get("original_title") or doc.get("title") or "",
        "current_approved_title":doc.get("title") or "","channel":doc.get("channel") or "",
        "description":canonical_clean_description(vid,doc.get("description") or "")[:8000],"upload_date":doc.get("upload_date") or "",
        "downloaded_at":doc.get("downloaded_at") or "","current_category":doc.get("category") or "",
        "current_subcategory":doc.get("subcategory") or "","current_tags":doc.get("topics") or [],
        "transcript_status":"AVAILABLE" if available else "MISSING","transcript_or_sections":transcript if available else "",
        "classification_basis_required":"transcript_or_sections" if available else "metadata_only",
        "meaningful_viewer_comments":comment_intel[:12000],
        "viewer_comments_note":"Viewer comments are audience-generated content and are not verified facts."}


def phase6_export_taxonomy_packages(mode="unclassified",batch_size=25,limit=0,channel="",category=""):
    docs=[d for d in phase5_load_search_index() if not int(d.get("archived") or 0)]
    if not docs:
        try:
            phase5_build_search_index(incremental=True)
            docs=[d for d in phase5_load_search_index() if not int(d.get("archived") or 0)]
        except Exception:
            docs=[]
    processed=phase6_taxonomy_processed_ids()
    con=db_connect();packaged={str(r[0]) for r in con.execute("SELECT video_id FROM videos WHERE COALESCE(chatgpt_package_status,'')='EXPORTED'").fetchall()};con.close()
    mode=str(mode or "unclassified").lower()
    if mode=="unclassified":
        docs=[d for d in docs if str(d.get("video_id")) not in processed and str(d.get("video_id")) not in packaged]
    elif mode=="new":
        cutoff=datetime.now()-timedelta(days=7); keep=[]
        for d in docs:
            try:
                dt=datetime.strptime(str(d.get("downloaded_at") or "")[:19],"%Y-%m-%d %H:%M:%S")
                if dt>=cutoff: keep.append(d)
            except Exception: pass
        docs=keep
    elif mode=="channel" and channel:
        docs=[d for d in docs if str(d.get("channel") or "").lower()==str(channel).lower()]
    elif mode=="category" and category:
        docs=[d for d in docs if str(d.get("category") or "").lower()==str(category).lower()]
    elif mode=="test":
        docs=docs[:max(1,int(limit or 5))]
    if limit and mode!="test": docs=docs[:int(limit)]

    chunks_by_video=defaultdict(list)
    for c in phase6_load_chunks():
        chunks_by_video[str(c.get("video_id") or "")].append(c)

    batch_size=max(1,min(100,int(batch_size or 25)))
    outdir=phase6_taxonomy_export_dir(); stamp=time.strftime("%Y%m%d_%H%M%S"); files=[]
    instruction={
        "task":"Classify and enrich every video independently for Video Library Manager.",
        "critical_rules":[
            "Return JSON only, no markdown fences.",
            "Return one video_updates object per input video.",
            "Copy video_id EXACTLY from input.",
            "Use stable English category/subcategory names suitable for thousands of videos.",
            "Canonicalize spelling, singular/plural and synonymous tags.",
            "If transcript_status is MISSING, use only supplied metadata and do not invent transcript details.",
            "approved_english_title must be clear, non-clickbait and <=80 characters.",
            "classification_confidence must be 0 to 1."
        ],
        "required_output":{"video_updates":[{
            "video_id":"EXACT INPUT VIDEO_ID","approved_english_title":"","category":"","subcategory":"",
            "primary_topic":"","canonical_tags":[],"concepts":[],"questions_answered":[],
            "search_phrases":[],"synonyms":[],"not_about":[],"transcript_status":"AVAILABLE|MISSING",
            "classification_basis":"transcript_or_sections|metadata_only","classification_confidence":0.0
        }]}
    }
    total_batches=(len(docs)+batch_size-1)//batch_size if docs else 0
    for bi in range(0,len(docs),batch_size):
        batch=docs[bi:bi+batch_size]
        payload={"package_type":"VIDEO_LIBRARY_TAXONOMY_BATCH","batch_number":bi//batch_size+1,
                 "total_batches":total_batches,"mode":mode,"instructions":instruction,
                 "videos":[phase6_taxonomy_video_payload(d,chunks_by_video) for d in batch]}
        p=outdir/f"ChatGPT_Taxonomy_{stamp}_Batch_{bi//batch_size+1:03d}.json"
        p.write_text(json.dumps(payload,indent=2,ensure_ascii=False),encoding="utf-8"); files.append(p)
        package_id=p.stem
        con=db_connect();con.executemany("UPDATE videos SET chatgpt_package_status='EXPORTED',chatgpt_package_id=?,chatgpt_packaged_at=? WHERE video_id=?",[(package_id,time.strftime("%Y-%m-%d %H:%M:%S"),str(d.get("video_id"))) for d in batch]);con.commit();con.close()
    manifest=outdir/f"ChatGPT_Taxonomy_{stamp}_MANIFEST.json"
    manifest.write_text(json.dumps({"created_at":time.strftime("%Y-%m-%d %H:%M:%S"),"mode":mode,
        "videos":len(docs),"batch_size":batch_size,"files":[p.name for p in files],
        "result_filename":"chatgpt_library_intelligence_result.json","result_drop_location":str(BASE)},indent=2),encoding="utf-8")
    return {"ok":True,"videos":len(docs),"batches":len(files),"files":[str(p) for p in files],
            "manifest":str(manifest),"folder":str(outdir)}


def phase6_import_taxonomy_result_from_root():
    candidates=phase6_chatgpt_inbox_candidates()
    taxonomy=[];ignored=[]
    for p in candidates:
        det=chatgpt_detect_file_type(p)
        if "Taxonomy" in str(det.get("type") or "") or "Library Intelligence" in str(det.get("type") or ""):
            try:
                recs=phase6_read_result_records(p)
                if any(phase6_extract_video_updates(x) for x in recs if isinstance(x,dict)):
                    taxonomy.append(p)
                else:ignored.append(str(p))
            except Exception:ignored.append(str(p))
        else:ignored.append(str(p))
    if not taxonomy:
        return {"ok":False,"message":f"No video taxonomy/library-intelligence result with video_updates found beside START.bat: {BASE}","ignored":ignored}
    results=[]
    for p in taxonomy:
        try:results.append(phase6_import_taxonomy_result_file(p,archive=True))
        except Exception as ex:results.append({"ok":False,"file":str(p),"message":f"{type(ex).__name__}: {ex}"})
    return {"ok":any(x.get("ok") for x in results),"files":len(results),"results":results,"ignored":ignored}


def phase6_read_result_records(path):
    p=Path(path)
    if p.suffix.lower()==".jsonl":
        out=[]
        for line in p.read_text(encoding="utf-8-sig",errors="replace").splitlines():
            if line.strip():out.append(json.loads(line))
        return out
    obj=json.loads(p.read_text(encoding="utf-8-sig"))
    return obj if isinstance(obj,list) else [obj]

def phase6_validate_video_updates(records):
    updates=[]
    for obj in records:updates.extend(phase6_extract_video_updates(obj))
    con=db_connect();db_ids={str(r[0]) for r in con.execute("SELECT video_id FROM videos WHERE COALESCE(current_present,1)=1 AND COALESCE(deleted_from_library,0)=0").fetchall()};con.close()
    errors=[];warnings=[];valid=[];seen=set()
    for i,u in enumerate(updates,1):
        vid=str(u.get("video_id") or "").strip()
        if not vid:errors.append(f"Update {i}: video_id missing");continue
        if vid in seen:warnings.append(f"{vid}: duplicate update ignored");continue
        seen.add(vid)
        if vid not in db_ids:errors.append(f"{vid}: not found in local database");continue
        if not str(u.get("category") or u.get("primary_category") or "").strip():errors.append(f"{vid}: category missing");continue
        if str(u.get("transcript_status") or "").upper()=="MISSING" and u.get("classification_basis") not in {None,"","metadata_only"}:warnings.append(f"{vid}: missing transcript but basis={u.get('classification_basis')}")
        valid.append(u)
    return {"ok":bool(valid) and not errors,"valid_updates":valid,"valid_count":len(valid),"error_count":len(errors),"warning_count":len(warnings),"errors":errors,"warnings":warnings}

def phase6_store_intelligence_records(records):
    out=phase6_intelligence_dir()/"library_intelligence.jsonl";existing={}
    if out.exists():
        for line in out.read_text(encoding="utf-8").splitlines():
            try:
                x=json.loads(line);existing[str(x.get("video_id") or x.get("collection_id") or x.get("topic") or hashlib.sha1(line.encode()).hexdigest())]=x
            except Exception:pass
    count=0
    for x in records:
        if not isinstance(x,dict):continue
        y=dict(x);key=y.get("video_id") or y.get("collection_id") or y.get("topic") or f"record-{time.time_ns()}-{count}"
        y["imported_at"]=time.strftime("%Y-%m-%d %H:%M:%S");existing[str(key)]=y;count+=1
    with open(out,"w",encoding="utf-8") as f:
        for x in existing.values():f.write(json.dumps(x,ensure_ascii=False)+"\n")
    return count

def phase6_archive_result_file(path):
    p=Path(path);dest=phase6_intelligence_dir()/p.name
    try:
        if p.resolve().parent==phase6_intelligence_dir().resolve():return p
    except Exception:pass
    if dest.exists():dest=phase6_intelligence_dir()/(p.stem+"_"+time.strftime("%Y%m%d_%H%M%S")+p.suffix)
    shutil.move(str(p),str(dest));return dest


def phase6_import_chatgpt_intelligence(path=None,move_folders=False,mark_processed=False):
    p=Path(path) if path else ((phase6_root_inbox_dir()/"chatgpt_library_intelligence_result.json") if (phase6_root_inbox_dir()/"chatgpt_library_intelligence_result.json").exists() else phase6_intelligence_dir()/"chatgpt_library_intelligence_result.json")
    if not p.exists():return False,f"Put ChatGPT JSON beside START.bat ({phase6_root_inbox_dir()}) OR here: {phase6_intelligence_dir()}",0
    try:records=phase6_read_result_records(p)
    except Exception as ex:return False,f"Invalid JSON/JSONL: {ex}",0
    count=phase6_store_intelligence_records(records)
    applied,messages,success_ids,failed_ids=phase6_apply_chatgpt_video_updates(records,move_folders=move_folders,return_ids=True)
    if mark_processed and success_ids:phase6_mark_taxonomy_processed(success_ids)
    return True,f"Imported {count} intelligence record(s). Applied {applied} video update(s). Failed {len(failed_ids)}.",count


def phase6_load_intelligence():
    p=phase6_intelligence_dir()/"library_intelligence.jsonl"; out=[]
    if p.exists():
        for line in p.read_text(encoding='utf-8').splitlines():
            try: out.append(json.loads(line))
            except Exception: pass
    return out

def phase6_enrich_chunks_with_intelligence(chunks):
    intel=phase6_load_intelligence(); byvid=defaultdict(list)
    for x in intel:
        if x.get('video_id'): byvid[str(x['video_id'])].append(x)
        for vu in x.get('video_updates') or []:
            if isinstance(vu,dict) and vu.get('video_id'):
                merged=dict(x)
                merged.update(vu)
                byvid[str(vu['video_id'])].append(merged)
        for sm in x.get('source_mapping') or []:
            if isinstance(sm,dict) and sm.get('video_id'): byvid[str(sm['video_id'])].append(x)
    for c in chunks:
        extra=[]
        for x in byvid.get(str(c.get('video_id')),[]):
            for k in ['questions_answered','search_phrases','synonyms','concepts','entities','related_topics','not_about']:
                v=x.get(k) or []; extra.extend(v if isinstance(v,list) else [v])
        c['chatgpt_search_intelligence']=' '.join(str(x) for x in extra if x)
    return chunks



def phase6_collection_topic(coll):
    return str((coll or {}).get("topic") or (coll or {}).get("name") or "").strip()

def phase6_resolve_collection(value):
    items=phase6_load_collections()
    raw=str(value or "").strip()
    if not raw:return None
    if raw.isdigit():
        n=int(raw)
        if 1<=n<=len(items): return items[n-1]
    low=raw.lower()
    return next((x for x in items if str(x.get("collection_id","")).lower()==low),None) or next((x for x in items if str(x.get("name","")).lower()==low),None)

def phase6_collection_summary_page():
    items=phase6_load_collections()
    out=phase6_collections_dir()/"collections_home.html"
    data=json.dumps(items,ensure_ascii=False)
    html="""<!doctype html><meta charset='utf-8'><title>Topic Collections</title>
<style>body{font-family:Arial,sans-serif;margin:24px;background:#f6f7f9;color:#18202a}.top{position:sticky;top:0;background:#f6f7f9;padding:10px 0;z-index:2}input{padding:10px;width:min(700px,90%);font-size:16px}.card{background:white;border:1px solid #ddd;border-radius:10px;padding:12px;margin:8px 0}.meta{color:#667;font-size:13px}</style>
<div class='top'><h1>Topic Collections</h1><input id='q' placeholder='Search collections...' oninput='render()'><div class='meta'><span id='count'></span></div></div><div id='list'></div>
<script>const D=__DATA__;
function esc(s){return String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function render(){let q=document.getElementById('q').value.toLowerCase().trim();let a=D.filter(x=>!q||JSON.stringify(x).toLowerCase().includes(q));document.getElementById('count').textContent=a.length+' of '+D.length+' collections';document.getElementById('list').innerHTML=a.map(x=>`<div class="card"><b>${esc(x.name)}</b><div class="meta">ID: ${esc(x.collection_id)} · ${(x.video_ids||[]).length} videos</div><div>Topic: ${esc(x.topic||x.name||'')}</div><div class="meta">Source search: ${esc(x.query||'')}</div></div>`).join('')} render();</script>"""
    out.write_text(html.replace("__DATA__",data),encoding="utf-8")
    return out

def phase6_root_inbox_dir():
    return BASE

def phase6_chatgpt_inbox_candidates():
    root=phase6_root_inbox_dir(); found=[]
    for n in ["chatgpt_library_intelligence_result.json","chatgpt_tag_cleanup_result.jsonl","chatgpt_library_intelligence_result.jsonl"]:
        p=root/n
        if p.exists():found.append(p)
    for p in root.glob("chatgpt*.*"):
        if p.suffix.lower() in {".json",".jsonl"} and p not in found:found.append(p)
    return found

def phase6_pickup_chatgpt_results():
    dest=phase6_intelligence_dir(); moved=[]
    for p in phase6_chatgpt_inbox_candidates():
        target=dest/p.name
        if target.exists():target=dest/(p.stem+"_"+time.strftime("%Y%m%d_%H%M%S")+p.suffix)
        shutil.move(str(p),str(target)); moved.append(target)
    return moved

def phase6_get_collection(collection_id):
    return next((x for x in phase6_load_collections() if x.get("collection_id")==collection_id),None)

def phase6_rename_collection(collection_id,new_name):
    items=phase6_load_collections(); coll=next((x for x in items if x.get("collection_id")==collection_id),None)
    if not coll:return False,"Collection not found"
    new_name=re.sub(r"\s+"," ",str(new_name or "")).strip()
    if not new_name:return False,"New name is required"
    coll["name"]=new_name; coll["updated_at"]=time.strftime("%Y-%m-%d %H:%M:%S"); phase6_save_collections(items)
    return True,f"Renamed to {new_name}"

def phase6_remove_videos_from_collection(collection_id,video_ids):
    items=phase6_load_collections(); coll=next((x for x in items if x.get("collection_id")==collection_id),None)
    if not coll:return False,"Collection not found"
    remove={str(x) for x in (video_ids or [])}; before=len(coll.get("video_ids") or [])
    coll["video_ids"]=[v for v in (coll.get("video_ids") or []) if str(v) not in remove]
    coll["updated_at"]=time.strftime("%Y-%m-%d %H:%M:%S"); phase6_save_collections(items)
    return True,f"Removed {before-len(coll['video_ids'])} video(s)"

def phase6_delete_collection(collection_id):
    items=phase6_load_collections(); new=[x for x in items if x.get("collection_id")!=collection_id]
    if len(new)==len(items):return False,"Collection not found"
    phase6_save_collections(new); return True,"Collection deleted"

def phase6_collection_estimate(collection_id,focused=False):
    coll=phase6_get_collection(collection_id)
    if not coll:return {"ok":False,"message":"Collection not found"}
    chunks=phase6_load_chunks(); chars=0
    for vid in coll.get("video_ids") or []:
        if focused:
            hits=phase6_chunk_search(coll.get("query") or coll.get("name"),limit=30,video_id=vid,dedupe_videos=False,require_all_terms=False)
            chars+=sum(len(str(x.get("text") or "")) for x in hits)
        else:
            p=phase6_find_transcript_for_video(vid)
            if p:
                try:chars+=p.stat().st_size
                except Exception:pass
            else:
                chars+=sum(len(str(c.get("text") or "")) for c in chunks if c.get("video_id")==vid)
    return {"ok":True,"videos":len(coll.get("video_ids") or []),"approx_chars":chars,"approx_words":round(chars/6),"approx_mb":round(chars/1024/1024,2)}

