def phase6_ai_settings_path():
    return phase6_dirs()[0]/"ai_settings.json"


def phase6_default_ai_settings():
    return {
        "ollama_url":"http://127.0.0.1:11434",
        "fast_model":"qwen2.5:3b",
        "deep_model":"qwen2.5:7b",
        "keep_alive":"30m",
        "fast_chunks":10,
        "deep_chunks":24,
        "num_ctx_fast":8192,
        "num_ctx_deep":16384,
        "temperature":0.2,
        "timeout_seconds":180
    }


def phase6_load_ai_settings():
    p=phase6_ai_settings_path()
    defaults=phase6_default_ai_settings()
    if not p.exists():
        p.write_text(json.dumps(defaults,indent=2),encoding="utf-8")
        return defaults
    try:
        obj=json.loads(p.read_text(encoding="utf-8"))
        defaults.update(obj if isinstance(obj,dict) else {})
    except Exception:
        pass
    return defaults


def phase6_save_ai_settings(settings):
    phase6_ai_settings_path().write_text(
        json.dumps(settings,indent=2,ensure_ascii=False),
        encoding="utf-8"
    )


def phase6_http_json(url,payload=None,timeout=30):
    data=None
    headers={"Content-Type":"application/json"}
    if payload is not None:
        data=json.dumps(payload).encode("utf-8")
    req=urllib.request.Request(url,data=data,headers=headers)
    with urllib.request.urlopen(req,timeout=timeout) as r:
        return json.loads(r.read().decode("utf-8","replace"))


def phase6_ollama_status():
    s=phase6_load_ai_settings()
    base=s["ollama_url"].rstrip("/")
    try:
        obj=phase6_http_json(base+"/api/tags",timeout=5)
        models=[x.get("name","") for x in obj.get("models",[]) if x.get("name")]
        return True,models,""
    except Exception as ex:
        return False,[],f"{type(ex).__name__}: {ex}"


def phase6_answer_cache_dir():
    p=phase6_dirs()[4]/"answers"
    p.mkdir(parents=True,exist_ok=True)
    return p


def phase6_answer_cache_key(question,mode,model,evidence_ids,evidence=None,settings=None):
    """Return a cache key that changes when evidence or generation semantics change."""
    if evidence is None:
        evidence=[{"chunk_id":str(x or "")} for x in (evidence_ids or [])]
    if settings is None:
        settings=phase6_load_ai_settings()
    return answer_cache_identity(
        question=question,mode=mode,model=model,evidence=evidence,settings=settings
    )["cache_key"]

def phase6_build_evidence(question,mode="fast"):
    settings=phase6_load_ai_settings()
    limit=(
        int(settings.get("fast_chunks",10))
        if mode=="fast"
        else int(settings.get("deep_chunks",24))
    )
    hits=phase6_chunk_search(
        question,
        limit=max(limit*2,20),
        dedupe_videos=False,
        require_all_terms=False
    )

    # Keep evidence diverse: cap repeated sections from same video.
    picked=[]
    by_video=Counter()
    for h in hits:
        vid=h.get("video_id")
        if by_video[vid]>=3:
            continue
        picked.append(h)
        by_video[vid]+=1
        if len(picked)>=limit:
            break
    return picked


def phase6_evidence_prompt(question,evidence,mode="fast"):
    blocks=[]
    for i,h in enumerate(evidence,1):
        blocks.append(
            f"""[SOURCE {i}]
VIDEO_ID: {h.get('video_id','')}
TITLE: {h.get('title','')}
CHANNEL: {h.get('channel','')}
TIME: {h.get('start','')} - {h.get('end','')}
SECTION: {h.get('section_title','')}
CATEGORY: {h.get('category','')} / {h.get('subcategory','')}
TEXT:
{h.get('text','')}
"""
        )

    depth=(
        "Be concise and prioritize the strongest evidence."
        if mode=="fast"
        else
        "Be comprehensive: synthesize agreements, differences, unique points, and uncertainty."
    )

    return f"""You are the AI assistant for a private video library.

QUESTION:
{question}

RULES:
- Answer ONLY from the evidence below.
- Do not add outside facts.
- If evidence is insufficient, say: "Insufficient evidence in this video library."
- Distinguish what videos claim from established fact.
- Every substantive point must cite one or more source numbers in square brackets, e.g. [1] or [2][5].
- Preserve disagreements instead of forcing consensus.
- {depth}
- End with a short "Best Sources" section listing the most useful source numbers.

EVIDENCE:
{chr(10).join(blocks)}
"""


def phase6_ollama_generate(question,mode="fast",use_cache=True):
    settings=phase6_load_ai_settings()
    model=(
        settings.get("fast_model","qwen2.5:3b")
        if mode=="fast"
        else settings.get("deep_model","qwen2.5:7b")
    )
    evidence=phase6_build_evidence(question,mode)
    if not evidence:
        return {
            "ok":True,
            "answer":"Insufficient evidence in this video library.",
            "evidence":[],
            "cached":False,
            "model":model,
            "mode":mode
        }

    evidence_ids=[h.get("chunk_id") for h in evidence]
    cache_identity=answer_cache_identity(
        question=question,mode=mode,model=model,evidence=evidence,settings=settings
    )
    cache_key=cache_identity["cache_key"]
    cache_file=phase6_answer_cache_dir()/(cache_key+".json")

    if use_cache and cache_file.exists():
        try:
            obj=json.loads(cache_file.read_text(encoding="utf-8"))
            obj["cached"]=True
            return obj
        except Exception:
            pass

    online,models,error=phase6_ollama_status()
    if not online:
        return {
            "ok":False,
            "message":"Ollama is offline or unreachable: "+error,
            "evidence":evidence,
            "model":model,
            "mode":mode
        }

    prompt=phase6_evidence_prompt(question,evidence,mode)
    num_ctx=(
        int(settings.get("num_ctx_fast",8192))
        if mode=="fast"
        else int(settings.get("num_ctx_deep",16384))
    )

    payload={
        "model":model,
        "prompt":prompt,
        "stream":False,
        "keep_alive":settings.get("keep_alive","30m"),
        "options":{
            "temperature":float(settings.get("temperature",0.2)),
            "num_ctx":num_ctx
        }
    }

    started=time.time()
    try:
        response=phase6_http_json(
            settings["ollama_url"].rstrip("/")+"/api/generate",
            payload,
            timeout=int(settings.get("timeout_seconds",180))
        )
        elapsed=round(time.time()-started,2)
        answer=str(response.get("response") or "").strip()
        obj={
            "ok":True,
            "question":question,
            "answer":answer,
            "evidence":evidence,
            "cached":False,
            "model":model,
            "mode":mode,
            "elapsed_seconds":elapsed,
            "created_at":time.strftime("%Y-%m-%d %H:%M:%S"),
            "cache_identity":cache_identity,
            "prompt_version":ANSWER_PROMPT_VERSION
        }
        cache_file.write_text(
            json.dumps(obj,indent=2,ensure_ascii=False),
            encoding="utf-8"
        )
        return obj
    except Exception as ex:
        return {
            "ok":False,
            "message":f"{type(ex).__name__}: {ex}",
            "evidence":evidence,
            "model":model,
            "mode":mode
        }


def phase6_clear_answer_cache():
    p=phase6_answer_cache_dir()
    count=0
    for f in p.glob("*.json"):
        try:
            f.unlink()
            count+=1
        except Exception:
            pass
    print(f"Cleared cached AI answers: {count}")
    return count


