def video_support_path_audit(video_id):
    con=db_connect()
    row=con.execute(
        "SELECT local_folder,clean_title,original_title,upload_date,channel FROM videos WHERE video_id=?",
        (str(video_id),)
    ).fetchone()
    con.close()

    if not row:
        print(f"Video ID not found: {video_id}")
        return False

    folder=row[0] or str(video_folder_path(
        row[1] or row[2] or video_id,
        row[3] or "",
        row[4] or "",
        video_id
    ))

    print("")
    print("===== VIDEO SUPPORT PATH AUDIT =====")
    print(f"Video ID: {video_id}")
    print(f"Folder length {len(folder)}: {folder}")
    names=[
        f"{video_id}.transcript.txt",
        f"{video_id}.en.vtt",
        f"{video_id}.srt",
        "ERROR.txt",
        f"{video_id}.info.json"
    ]
    for name in names:
        p=Path(folder)/"_data"/name
        print(f"{len(str(p)):3} | {p}")
    return True


def folder_title_length_audit():
    """
    Audit existing managed video folders against:
      - title portion <= 50 characters
      - full path <= Windows safe path budget
    """
    con=db_connect()
    rows=con.execute(
        "SELECT video_id,local_folder FROM videos ORDER BY rowid"
    ).fetchall()
    con.close()

    problems=[]
    checked=0

    for vid,folder in rows:
        if not folder:
            continue
        p=Path(folder)
        if not p.exists():
            continue

        checked+=1
        title_part=re.sub(
            r"^\d{4}-\d{2}-\d{2}\s+-\s+",
            "",
            p.name
        )

        if (
            len(title_part)>MAX_VIDEO_TITLE_CHARS
            or len(str(p))>WINDOWS_SAFE_PATH_BUDGET
        ):
            problems.append(
                (vid,len(title_part),len(str(p)),str(p))
            )

    print("")
    print("===== FOLDER TITLE / WINDOWS PATH AUDIT =====")
    print(f"Checked: {checked}")

    if not problems:
        print(
            "PASS: all existing folder title portions are within "
            f"{MAX_VIDEO_TITLE_CHARS} characters and paths are within "
            f"{WINDOWS_SAFE_PATH_BUDGET} characters."
        )
        return True

    for vid,title_len,path_len,path in problems:
        print(
            f"{vid} | title={title_len} | path={path_len} | {path}"
        )

    print(f"Problems: {len(problems)}")
    return False

def windows_long_path_audit():
    """
    Find managed files/directories whose paths are likely to exceed classic
    Windows API limits.
    """
    threshold=235
    hits=[]

    for base in [DOWNLOADS,BASE/"tmp",BASE/"data",BASE/"maintenance"]:
        if not Path(base).exists():
            continue
        try:
            for p in Path(base).rglob("*"):
                plen=len(str(p))
                if plen>threshold:
                    hits.append((plen,str(p)))
        except Exception:
            pass

    hits.sort(reverse=True)

    print("")
    print("===== WINDOWS LONG PATH AUDIT =====")
    if not hits:
        print(f"PASS: no managed paths longer than {threshold} characters.")
        return True

    print(f"Found {len(hits)} path(s) longer than {threshold} characters.")
    for plen,p in hits[:50]:
        print(f"{plen:3} | {p}")
    if len(hits)>50:
        print(f"... plus {len(hits)-50} more")
    return False

def v25_path_compatibility_audit():
    """
    Report stale legacy files still sitting at project root after migration.
    """
    legacy_names=[
        "video_library.db",
        "video_library.rebuilt.db",
        "video_list.csv",
        "video_list_with_chatgpt_titles.csv",
        "rename_review_results.csv",
        "library_health.csv",
        "library_health_summary.json",
        "phase0_core_audit.csv",
        "phase2_integrity_audit.csv",
        "phase3_summary_quality.csv",
        "phase4_content_intelligence.csv",
        "package_history.csv",
        "app.log",
        "config.json",
        "app.py"
    ]
    found=[]
    for name in legacy_names:
        p=BASE/name
        if p.exists():
            found.append(p)

    print("")
    print("===== PATH COMPATIBILITY AUDIT =====")
    if not found:
        print("PASS: no stale legacy root data/app files found.")
        return True

    print("WARN: legacy root files still present:")
    for p in found:
        print(" ",p)
    print("Run Repair / Health / Maintenance -> Phase 1 -> Migrate Root Files.")
    return False



def original_title_reference_audit():
    """
    Runtime-facing audit for marker compatibility.
    Reports video folders where no marker exists; does not fail downloads.
    """
    con=db_connect()
    rows=con.execute(
        "SELECT video_id,original_title,local_folder FROM videos ORDER BY rowid"
    ).fetchall()
    con.close()

    missing=[]
    for vid,orig,db_folder in rows:
        folder=locate_existing_folder(vid)
        if folder is None and db_folder and Path(db_folder).exists():
            folder=Path(db_folder)
        if not folder:
            continue
        marker=find_original_title_marker(folder)
        if marker is None:
            missing.append((vid,str(folder),orig or ""))

    print("")
    print("===== ORIGINAL-TITLE REFERENCE AUDIT =====")
    if not missing:
        print("PASS: every existing video folder has an original-title marker or fallback.")
        return True

    for vid,folder,orig in missing:
        print(f"MISSING {vid} | {folder}")
    print(f"Missing markers: {len(missing)}")
    print("These are non-fatal in FIX17.")
    return False

def original_title_marker_audit():
    con=db_connect()
    rows=con.execute(
        "SELECT video_id,original_title,local_folder FROM videos ORDER BY rowid"
    ).fetchall()
    con.close()

    missing=0
    empty=0
    ok=0

    for vid,orig,db_folder in rows:
        folder=locate_existing_folder(vid)
        if folder is None and db_folder and Path(db_folder).exists():
            folder=Path(db_folder)
        if folder is None:
            continue

        marker=find_original_title_marker(folder)
        if not marker:
            missing+=1
            print(f"MISSING {vid}: no .original-title marker")
            continue

        value=read_original_title_marker(folder,"")
        if not value:
            empty+=1
            print(f"EMPTY {vid}: {marker}")
        else:
            ok+=1

    print("")
    print("Original-title marker audit")
    print(f"OK      : {ok}")
    print(f"Missing : {missing}")
    print(f"Empty   : {empty}")

def v25_static_integrity_check():
    checks=[]

    def add(name,ok,detail=""):
        checks.append((name,"PASS" if ok else "FAIL",detail))

    add("Project app.py", (BASE/"app"/"app.py").exists(), str(BASE/"app"/"app.py"))
    add("Config", (BASE/"app"/"config.json").exists(), str(BASE/"app"/"config.json"))
    add("urls.txt at root", URLS.exists(), str(URLS))
    add("api_key.txt at root", (BASE/"api_key.txt").exists(), str(BASE/"api_key.txt"))
    add("Database directory", DB.parent.exists(), str(DB.parent))
    add("Phase2 package folder", phase2_chatgpt_dirs()[0].exists(), str(phase2_chatgpt_dirs()[0]))
    add("Phase2 results folder", phase2_chatgpt_dirs()[1].exists(), str(phase2_chatgpt_dirs()[1]))
    add("Auto post-ChatGPT pipeline", CFG.get("auto_post_chatgpt_pipeline",False), "")
    add("Dashboard auto launch disabled", not CFG.get("dashboard_auto_launch",False), "")
    add("No stale legacy root files", v25_path_compatibility_audit(), "")

    print("")
    print("===== V25 STATIC INTEGRITY CHECK =====")
    for name,status,detail in checks:
        print(f"{status:<4} | {name} | {detail}")
    return all(status=="PASS" for _,status,_ in checks)

