def main():
    def stop_handler(sig,frame):
        global STOP
        STOP=True
        set_state(message="Stop requested; finishing current operation")
    signal.signal(signal.SIGINT,stop_handler)
    ensure_project_layout()
    migrate_legacy_root_files()
    DOWNLOADS.mkdir(exist_ok=True)
    try:
        migrate_legacy_deleted_history_to_guard()
    except Exception as ex:
        log(f"Deleted-history startup migration warning: {ex}")

    args={str(a).lower() for a in sys.argv[1:]}
    if "--self-test" in args or "--diagnostics" in args:
        print("="*72)
        print(f"VIDEO LIBRARY MANAGER {APP_VERSION} - DIAGNOSTICS")
        print("="*72)
        result=full_app_diagnostics()
        print(json.dumps(result,indent=2,default=web_json_default))
        return

    if args.intersection({"--web","--browser","--dashboard"}):
        srv=start_dashboard()
        port=int(srv.server_address[1])
        print("="*72)
        print(f"VIDEO LIBRARY MANAGER {APP_VERSION}")
        print(f"Browser dashboard: http://127.0.0.1:{port}")
        print(f"App workspace    : http://127.0.0.1:{port}/app")
        print(f"Knowledge Center : http://127.0.0.1:{port}/knowledge")
        print(f"Library root     : {BASE}")
        print(f"Database         : {DB}")
        print("Press Ctrl+C to stop.")
        print("="*72,flush=True)
        try:
            while True:time.sleep(1)
        except KeyboardInterrupt:
            try:srv.shutdown()
            except Exception:pass
        return
    menu()

if __name__=="__main__":
    main()
